    const peers = (layout?.sideChats || []).filter(s => s.kind === target.kind);
    const idx = peers.length > 1 ? peers.findIndex(s => sameRouteId(s.id, target.id)) : -1;
    return idx >= 0 ? `${base} ${idx + 1}` : base;
