        '#ag-topbar-ws-controls{display:inline-flex !important;flex-direction:row !important;flex-wrap:nowrap !important;align-items:center !important;gap:2px !important;height:24px !important;padding:2px !important;width:max-content !important;min-width:max-content !important;max-width:none !important;flex-shrink:0 !important;white-space:nowrap !important;overflow:visible !important;box-sizing:border-box !important;border-radius:6px !important;background:rgba(255,255,255,0.04) !important;border:1px solid rgba(255,255,255,0.10) !important;color:#d4d4d8 !important;font:11px/1 system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI","Microsoft YaHei UI",sans-serif !important;z-index:2147483580 !important;-webkit-app-region:no-drag !important;pointer-events:auto !important;user-select:none !important;}',
        '#ag-topbar-ws-controls[hidden]{display:none !important;}',
