          const origBasis = ls.getAttribute('data-ag-ws-orig-lbasis') || '';
          const origW = ls.getAttribute('data-ag-ws-orig-lw') || '';
          const origMinW = ls.getAttribute('data-ag-ws-orig-lminw') || '';
          const origMaxW = ls.getAttribute('data-ag-ws-orig-lmaxw') || '';
          const origOvf = ls.getAttribute('data-ag-ws-orig-lovf') || '';
