          ls.removeAttribute?.('data-ag-ws-orig-lflex');
          ls.removeAttribute?.('data-ag-ws-orig-lgrow');
          ls.removeAttribute?.('data-ag-ws-orig-lshrink');
          ls.removeAttribute?.('data-ag-ws-orig-lbasis');
          ls.removeAttribute?.('data-ag-ws-orig-lw');
          ls.removeAttribute?.('data-ag-ws-orig-lminw');
          ls.removeAttribute?.('data-ag-ws-orig-lmaxw');
          ls.removeAttribute?.('data-ag-ws-orig-lovf');
