          const origAcMinW = ch.getAttribute('data-ag-ws-orig-acminw') || '';
          const origAcMaxW = ch.getAttribute('data-ag-ws-orig-acmaxw') || '';
          const origAcFlex = ch.getAttribute('data-ag-ws-orig-acflex') || '';
          const origAcGrow = ch.getAttribute('data-ag-ws-orig-acgrow') || '';
          const origAcShrink = ch.getAttribute('data-ag-ws-orig-acshrink') || '';
          const origAcBasis = ch.getAttribute('data-ag-ws-orig-acbasis') || '';
          const origAcBox = ch.getAttribute('data-ag-ws-orig-acbox') || '';
          const origAcOvf = ch.getAttribute('data-ag-ws-orig-acovf') || '';
