    if (!keepPinnedDock && !auxEl && !pinnedAuxDockActive) {
      removePinnedAuxFallbackDock();
    }
    const closedNow = !auxEl && (keepPinnedDock ? !findNativeAuxSidebarContainer() : !findAuxSidebarContainer());
    const savedRows = Array.from(trackedWorkspaceRows);
    if (typeof document?.querySelectorAll === 'function') {
      try {
        for (const r of Array.from(document.querySelectorAll('[data-ag-ws-row-styled="true"]') || [])) {
          if (r && !savedRows.includes(r)) savedRows.push(r);
        }
      } catch { }
    }
    restoreAuxHostSiblings(auxEl, { sidePanelClosed: closedNow });
    cleanupMultiSessionPaneArtifacts({ forceClearSizing: true });
    // 兜底还原任何残留的原生页签正文遮罩，杜绝切至单浏览器或分栏时宿主内容区保持 visibility:hidden 黑屏
    if (!preserveNativeOcclusion && typeof document?.querySelectorAll === 'function') {
      try {
        for (const occ of Array.from(document.querySelectorAll('[data-ag-aux-native-occluded="true"]') || [])) {
          occ?.removeAttribute?.('data-ag-aux-native-occluded');
        }
      } catch { }
    }
