    lastConservedWorkspaceGeom = {
      totalW: dragCtx.totalW,
      nativeSepW: dragCtx.nativeSepW,
      auxSepW: dragCtx.auxSepW,
      sessionsW,
      auxW: safeAuxW,
      pluginW: safePlugW,
      browserW: dragCtx.isTriPane ? safeBrwW : 0,
      minSess,
      minPlug,
      minBrw: dragCtx.isTriPane ? minBrw : 0,
      sumW,
      overflowPx: Math.max(0, sumW - dragCtx.totalW),
      isTriPane: dragCtx.isTriPane,
      auxOrder: dragCtx.order,
      hasWorkspaceRow: Boolean(dragCtx.slotsInfo?.workspaceRow),
      leftSlotCount: dragCtx.slotsInfo?.leftSlots?.length || 0,
      hiddenNativeOuterSplitterCount: trackedHiddenNativeSplitters.size
    };

