    const slotsInfo = auxEl ? resolveWorkspaceHorizontalSlots(auxEl) : null;
    const availW = slotsInfo ? slotsInfo.totalW : measureWorkspaceAvailableWidth(auxEl);
    const nativeSepW = slotsInfo ? slotsInfo.nativeSepW : 0;
    const isTriPaneMode = opts.triPane === true || (auxViewTab === 'both' && opts.triPane !== false);
