  async function invokeModulesApi(action, name, enable, opts = {}) {
    const ipcFn = (action === 'status' && typeof window.contextMeterAPI?.getModulesStatus === 'function')
      ? () => window.contextMeterAPI.getModulesStatus()
      : ((action === 'toggle' && typeof window.contextMeterAPI?.toggleModule === 'function')
        ? () => window.contextMeterAPI.toggleModule(name, enable, opts)
        : null);
    const liveRoute = action === 'status' ? '/modules-status' : '/toggle-module';
    const liveBody = action === 'status' ? {} : { name, enable, opts };
    if (!ipcFn && !hasLiveHttpBridge()) {
      return { ok: false, error: t('msg.noHostBridge'), unavailable: true };
    }
    try {
      const out = await callBackendWithPriority({
        ipcCall: ipcFn,
        liveRoute,
        liveBody
      });
      return out.result || { ok: false, error: t('msg.noHostBridge'), unavailable: true };
    } catch (e) {
      return { ok: false, error: e?.message || t('msg.noHostBridge') };
    }
  }

  async function refreshUnlockStatus() {
    const thisSeq = ++unlockReqSeq;
    try {
      const currentObservedBudget = (state.latest?.budget && state.latest.budget > 0)
        ? state.latest.budget
        : undefined;
      const res = await invokeUnlockApi('status', { currentBudget: currentObservedBudget });
      if (thisSeq !== unlockReqSeq) return;

      if (!res || !res.ok || !res.data) {
        unlockStatusFetchError = true;
        currentUnlockStatus = null;
        syncRecommendedCheckboxes();
        if (unlockStatusDesc) unlockStatusDesc.textContent = t('status.client.unavailable');
        renderCompactSessionCard();
        renderClientStatusBar();
        if (!isContextSettingsView && activeContextTab === 'models') renderModelSettingsTab();
        return;
      }

      unlockStatusFetchError = false;
      const data = res.data;
      currentUnlockStatus = data;
      syncRecommendedCheckboxes();
      lastPartialReason = data.partialMatchReason || data.error || '';
      if (typeof data.hostSupportsRestart === 'boolean') {
        hostSupportsRestart = data.hostSupportsRestart;
      }
      if (data.status === 'patched_pending_restart') {
        needsRestartAfterApply = true;
      } else if (data.status === 'patched_loaded' || data.status === 'not_patched') {
        needsRestartAfterApply = false;
      }

      // 重启后校验核对
      if (pendingRestartVerification) {
        if (data.runtimeEvidence?.restartDetected === true) {
          if (data.status === 'patched_loaded' && doesClientMatchVerification(data, pendingRestartVerification)) {
            restartMismatchNotice = '';
          } else {
            restartMismatchNotice = t('models.status.restartMismatch', { actual: describeClientModeValue(data) });
          }
          pendingRestartVerification = null;
          void saveSettingsPayloadBridge({ uiPreferences: { restartVerification: null } });
        }
      }

      const statusInfo = mapUnlockDisplayStatus(data);
      if (unlockStatusDesc) {
        unlockStatusDesc.textContent = t('models.status.line', { badge: statusInfo.badge, mode: describeClientModeValue(data) });
      }
      if (unlockMetaMode) {
        unlockMetaMode.textContent = `${describeClientModeValue(data)}（${statusInfo.badge}）`;
      }
      if (unlockMetaTarget) {
        unlockMetaTarget.textContent = data.arch ? t('models.meta.targetDesktopArch', { arch: data.arch }) : t('models.meta.targetDesktop');
      }
      if (unlockMetaArch) unlockMetaArch.textContent = data.arch || t('models.meta.archUnknown');
      if (unlockMetaBackup) {
        unlockMetaBackup.textContent = data.hasBackup
          ? (data.backupStaleReason ? t('models.meta.backupStale') : t('models.meta.backupReady'))
          : t('models.meta.backupNone');
      }

      if (btnApplyUnlock) {
        const writableStatuses = new Set(['not_patched', 'patched_runtime_unconfirmed', 'patched_pending_restart', 'patched_loaded']);
        const archSupported = data.isPlatformSupported !== false && (!data.arch || data.arch === 'x86-64' || data.arch === 'arm64');
        if (writableStatuses.has(data.status) && archSupported) {
          btnApplyUnlock.disabled = false;
          btnApplyUnlock.textContent = t('models.btn.saveApply');
        } else if (data.status === 'partial_match') {
          btnApplyUnlock.disabled = true;
          btnApplyUnlock.textContent = t('models.btn.partialBlocked');
        } else if (data.status === 'failed') {
          btnApplyUnlock.disabled = false;
          btnApplyUnlock.textContent = t('models.btn.retryApply');
        } else {
          btnApplyUnlock.disabled = true;
          btnApplyUnlock.textContent = t('models.btn.unsupported');
        }
      }

      if (btnRestoreUnlock) {
        btnRestoreUnlock.disabled = !(
          (data.hasBackup && data.backupValidForCurrentBinary !== false) ||
          data.hasMatchingGate3BSidecar ||
          (data.status && data.status !== 'not_patched' && data.status !== 'unsupported')
        );
      }

      if (data.status === 'partial_match' && unlockResultBox && (!unlockResultBox.style.display || unlockResultBox.style.display === 'none')) {
        showUnlockResultBox(
          false,
          t('models.card.partialFailDetail', { reason: translateBackendText(lastPartialReason) || '' }),
          { showRetry: true }
        );
      }

      if (!ctxDraftDirty && !resolveProductPreferenceState(getSelectedProductObj()).pref) {
        loadDraftFromSelectedModel(false);
      } else {
        renderCompactSessionCard();
        renderClientStatusBar();
        if (!isContextSettingsView && activeContextTab === 'models') renderModelSettingsTab();
      }
      if (typeof syncEnhanceInteractiveDisabledState === 'function') {
        syncEnhanceInteractiveDisabledState();
      }
    } catch {
      if (thisSeq !== unlockReqSeq) return;
      unlockStatusFetchError = true;
      currentUnlockStatus = null;
      renderCompactSessionCard();
      renderClientStatusBar();
    }
  }

  btnRefreshUnlock?.addEventListener('click', () => {
    void refreshUnlockStatus();
  });

  function yieldForSettingsPaint() {
    if (typeof requestAnimationFrame === 'function') {
      return new Promise((resolve) => requestAnimationFrame(resolve));
    }
    if (typeof MessageChannel === 'function') {
      return new Promise((resolve) => {
        const mc = new MessageChannel();
        mc.port1.onmessage = () => resolve();
        mc.port2.postMessage(null);
      });
    }
    return Promise.resolve();
  }

  btnApplyUnlock?.addEventListener('click', async () => {
    if (isUnlocking) return;
    if (ctxResetNoticeEl) ctxResetNoticeEl.hidden = true;
    const saved = await saveCurrentProductDraft();
    if (saved.stale) return;
    if (!saved.ok) {
      showUnlockResultBox(false, saved.error);
      return;
    }

    isUnlocking = true;
    if (btnApplyUnlock) btnApplyUnlock.disabled = true;
    if (btnRestoreUnlock) btnRestoreUnlock.disabled = true;
    showUnlockResultBox(true, t('mod.processing'));
    needsRestartAfterApply = false;
    restartMismatchNotice = '';

    try {
      await yieldForSettingsPaint();
      // ELV-41: 底座统一应用为动态透传模式 (mov esi, edx)，使各模型设置能够独立生效，绝不把单一模型的数值固化进二进制
      const res = await invokeUnlockApi('apply', {
        mode: 'dynamic',
        limitTokens: null,
        serviceLimit: state.latest?.serviceLimit || undefined
      });
      if (!res || !res.ok) {
        needsRestartAfterApply = false;
        showUnlockResultBox(false, buildFriendlyWriteError(res?.error), { showRetry: true });
        return;
      }
      if (res.needsRestart === true) {
        needsRestartAfterApply = true;
        showUnlockResultBox(true, t('msg.appliedRestart'), { needsRestart: true });
      } else if (res.alreadyMatched) {
        needsRestartAfterApply = false;
        showUnlockResultBox(true, '底座引擎已处于动态跟随状态。当前模型设置已保存，下一次发送时尝试应用。');
      } else {
        needsRestartAfterApply = false;
        showUnlockResultBox(true, '已应用底座配置。当前模型设置已保存，下一次发送时尝试应用。');
      }
    } catch (e) {
      needsRestartAfterApply = false;
      showUnlockResultBox(false, buildFriendlyWriteError(e?.message), { showRetry: true });
    } finally {
      isUnlocking = false;
      if (btnApplyUnlock) btnApplyUnlock.disabled = false;
      if (btnRestoreUnlock) btnRestoreUnlock.disabled = false;
      await refreshUnlockStatus();
      if (!needsRestartAfterApply && currentUnlockStatus?.status === 'patched_pending_restart') {
        needsRestartAfterApply = true;
        renderClientStatusBar();
      }
    }
  });

  let isRestartInProgress = false;

  async function executeClientRestart(fromModal = false) {
    if (isRestartInProgress) return;
    isRestartInProgress = true;
    if (btnModalRestartConfirm) btnModalRestartConfirm.disabled = true;
    if (btnRestartConfirmGo) btnRestartConfirmGo.disabled = true;

    // 记录重启前的观测快照（不保存草稿）
    try {
      const obsObj = budgetTracker ? { ...budgetTracker.exportAllObservationsByProduct() } : {};
      for (const [mid, val] of observedByModelId.entries()) obsObj[mid] = val;
      preRestartSnapshot = { requestedAt: new Date().toISOString(), observations: obsObj };
      localStorage?.setItem(CTX_PRE_RESTART_OBS_KEY, JSON.stringify(preRestartSnapshot));
    } catch { }

    const feedbackEl = fromModal ? modalRestartFeedback : (modalRestartFeedback || ctxRestartFeedback);
    if (feedbackEl) {
      feedbackEl.textContent = t('client.restart.triggering');
      feedbackEl.hidden = false;
    }

    const res = await invokeRestartHostApi();
    if (!res || res.supported === false) {
      hostSupportsRestart = false;
      if (feedbackEl) {
        feedbackEl.textContent = t('client.restart.hostNotSupported');
        feedbackEl.hidden = false;
      }
      isRestartInProgress = false;
      if (btnModalRestartConfirm) btnModalRestartConfirm.disabled = false;
      if (btnRestartConfirmGo) btnRestartConfirmGo.disabled = false;
      renderClientStatusBar();
      return;
    }
    if (res.ok === false) {
      if (feedbackEl) {
        feedbackEl.textContent = t('client.restart.failed', { err: translateBackendText(res.error) || t('msg.unknownErr') });
        feedbackEl.hidden = false;
      }
      isRestartInProgress = false;
      if (btnModalRestartConfirm) btnModalRestartConfirm.disabled = false;
      if (btnRestartConfirmGo) btnRestartConfirmGo.disabled = false;
      return;
    }

    if (feedbackEl) {
      feedbackEl.textContent = t('models.restart.restarting');
      feedbackEl.hidden = false;
    }
    if (restartTimeoutTimer) clearTimeout(restartTimeoutTimer);
    restartTimeoutTimer = setTimeout(() => {
      if (!state.disposed && feedbackEl) {
        feedbackEl.textContent = t('models.restart.notExited');
        feedbackEl.hidden = false;
      }
      isRestartInProgress = false;
      if (btnModalRestartConfirm) btnModalRestartConfirm.disabled = false;
      if (btnRestartConfirmGo) btnRestartConfirmGo.disabled = false;
    }, 15000);
  }

  function disposeModalTopHost() {
    try {
      if (modalTopHost) {
        modalTopHost.remove?.();
      }
    } catch { }
    modalTopHost = null;
    modalTopShadow = null;
  }

  function ensureGlobalRestartModalTopLayer() {
    if (!globalRestartModal || typeof document === 'undefined' || !document.body) return;
    if (typeof document.createElement !== 'function') return;
    try {
      const activePortal = typeof document.querySelector === 'function'
        ? (document.querySelector('[data-base-ui-portal] .settings-modal-container')?.closest?.('[data-base-ui-portal]')
          || document.querySelector('.settings-modal-backdrop')?.closest?.('[data-base-ui-portal]')
          || null)
        : null;
      const targetParent = activePortal || document.body;
      if (!modalTopHost || !modalTopShadow) {
        const candidate = document.createElement('div');
        if (!candidate || typeof candidate.attachShadow !== 'function') return;
        const cShadow = candidate.attachShadow({ mode: 'open' });
        if (!cShadow || cShadow === shadow) return;
        candidate.id = MODAL_TOP_HOST_ID;
        candidate.setAttribute?.('data-ag-modal-top-layer', 'true');
        if (candidate.style) {
          candidate.style.cssText = 'position:fixed!important;inset:0!important;width:0!important;height:0!important;margin:0!important;padding:0!important;border:0!important;background:transparent!important;overflow:visible!important;pointer-events:none!important;z-index:2147483647!important;';
        }
        const srcStyle = shadow.querySelector?.('style')?.textContent || '';
        const stEl = document.createElement('style');
        if (stEl) {
          stEl.textContent = srcStyle;
          cShadow.appendChild?.(stEl);
        }
        cShadow.appendChild?.(globalRestartModal);
        modalTopHost = candidate;
        modalTopShadow = cShadow;
        earlyDisposeHooks.push(disposeModalTopHost);
      }
      if (modalTopHost.parentElement !== targetParent) {
        targetParent.appendChild?.(modalTopHost);
      }
      try {
        modalTopHost.inert = false;
        modalTopHost.removeAttribute?.('inert');
        modalTopHost.removeAttribute?.('aria-hidden');
        syncHostSettingsThemeAttrs(modalTopHost);
      } catch { }
    } catch { }
  }

  /**
   * 当在宿主 Settings 内点击自定义颜色色块时，将插件自带颜色选取器提升到顶层 Portal Shadow，
   * 确保在宿主设置弹窗上方可见且视觉完全跟随插件深浅主题与宿主 Accent。
   */
  function ensureColorPickerTopLayer() {
    const pop = el('color-picker-popover');
    if (!pop || typeof document === 'undefined' || !document.body) return;
    const settingsModalOpenNow = Boolean(hostSettingsModalOpen || document.querySelector?.('.settings-modal-container'));
    if (!settingsModalOpenNow) {
      if (modalTopShadow && pop.parentNode === modalTopShadow && shadow) {
        try { shadow.appendChild?.(pop); } catch { }
      }
      return;
    }
    try {
      ensureGlobalRestartModalTopLayer();
      if (modalTopShadow && pop.parentNode !== modalTopShadow) {
        modalTopShadow.appendChild?.(pop);
      }
      if (pop.style) {
        pop.style.pointerEvents = 'auto';
      }
      if (modalTopHost) syncHostSettingsThemeAttrs(modalTopHost);
    } catch { }
  }

  function openClientRestartConfirmFlow() {
    if (isRestartInProgress || globalRestartModal?.open) return;
    if (!hostSupportsRestart) {
      showUnlockResultBox(true, t('client.restart.hostNotSupported'), { needsRestart: true });
      const upStatusEl = el('up-pop-status');
      const upPop = el('update-popover');
      if (upStatusEl && upPop && upPop.style.display === 'block') {
        upStatusEl.style.display = 'block';
        upStatusEl.textContent = t('client.restart.hostNotSupported');
      }
      renderQuotaBoard?.();
      return;
    }
    if (globalRestartModal) {
      ensureGlobalRestartModalTopLayer();
      const titleEl = el('modal-restart-title');
      const textEl = el('modal-restart-text');
      if (titleEl) titleEl.textContent = t('models.restartConfirm.title');
      if (textEl) textEl.textContent = t('models.restartConfirm.text');
      if (btnModalRestartCancel) btnModalRestartCancel.textContent = t('models.restartConfirm.cancel');
      if (btnModalRestartConfirm) {
        btnModalRestartConfirm.textContent = t('models.restartConfirm.go');
        btnModalRestartConfirm.disabled = false;
      }
      if (modalRestartFeedback) {
        modalRestartFeedback.textContent = '';
        modalRestartFeedback.hidden = true;
      }
      globalRestartModal.hidden = false;
      try {
        if (typeof globalRestartModal.showModal === 'function' && !globalRestartModal.open) {
          globalRestartModal.showModal();
        }
      } catch { }
      try {
        btnModalRestartConfirm?.focus?.();
        setTimeout(() => {
          if (!state.disposed && globalRestartModal && !globalRestartModal.hidden) {
            try { btnModalRestartConfirm?.focus?.(); } catch { }
          }
        }, 0);
      } catch { }
      return;
    }
    if (ctxRestartConfirm) {
      ctxRestartConfirm.hidden = false;
      if (ctxRestartFeedback) ctxRestartFeedback.hidden = true;
    }
  }

  btnRestartHost?.addEventListener('click', openClientRestartConfirmFlow);
  btnUnlockResultRestart?.addEventListener('click', openClientRestartConfirmFlow);
  btnUnlockResultRetry?.addEventListener('click', () => {
    if (unlockResultBox) unlockResultBox.style.display = 'none';
    void refreshUnlockStatus();
  });

  function closeClientRestartConfirm() {
    if (!globalRestartModal) return;
    try {
      if (globalRestartModal.open && typeof globalRestartModal.close === 'function') {
        globalRestartModal.close();
      }
    } catch { }
    globalRestartModal.hidden = true;
  }

  btnModalRestartCancel?.addEventListener('click', (e) => {
    e?.stopPropagation?.();
    closeClientRestartConfirm();
  });
  globalRestartModal?.addEventListener('click', (e) => {
    e?.stopPropagation?.();
    if (e.target === globalRestartModal) closeClientRestartConfirm();
  });
  globalRestartModal?.addEventListener('cancel', (e) => {
    e?.preventDefault?.();
    e?.stopPropagation?.();
    closeClientRestartConfirm();
  });
  earlyDisposeHooks.push(closeClientRestartConfirm);

  btnModalRestartConfirm?.addEventListener('click', (e) => {
    e?.stopPropagation?.();
    void executeClientRestart(true);
  });

  btnRestartCancel?.addEventListener('click', () => {
    if (ctxRestartConfirm) ctxRestartConfirm.hidden = true;
  });

  btnRestartConfirmGo?.addEventListener('click', () => executeClientRestart(false));

  btnRestoreUnlock?.addEventListener('click', async () => {
    if (isUnlocking) return;
    isUnlocking = true;
    if (btnRestoreUnlock) btnRestoreUnlock.disabled = true;
    if (btnApplyUnlock) btnApplyUnlock.disabled = true;
    showUnlockResultBox(true, t('mod.processing'));

    try {
      await yieldForSettingsPaint();
      const res = await invokeUnlockApi('restore');
      if (!res || !res.ok) {
        showUnlockResultBox(false, buildFriendlyWriteError(res?.error || t('msg.restoreFail')), { showRetry: true });
        return;
      }
      needsRestartAfterApply = true;
      showUnlockResultBox(true, t('msg.restoredRestart'), { needsRestart: true });
    } catch (e) {
      showUnlockResultBox(false, buildFriendlyWriteError(e?.message), { showRetry: true });
    } finally {
      isUnlocking = false;
      if (btnRestoreUnlock) btnRestoreUnlock.disabled = false;
      if (btnApplyUnlock) btnApplyUnlock.disabled = false;
      await refreshUnlockStatus();
    }
  });

  // -----------------------------------------------------------------------
  // 速度对比分页与纯 SVG 图表渲染
  // -----------------------------------------------------------------------
  function isValidSpeedSampleSafe(c) {
    if (typeof isValidSpeedSample === 'function') return isValidSpeedSample(c);
    return Boolean(c && c.status === 'final' && !c.estimated && Number(c.outputTokens) > 0 && Number(c.durationSec) > 0 && Number(c.tps) > 0);
  }

  function mergeAvailableSpeedCalls() {
    const byId = new Map();
    const hist = Array.isArray(ANTIGRAVITY_TOKEN_DATA.speedRecords) ? ANTIGRAVITY_TOKEN_DATA.speedRecords : [];
    for (const r of hist) {
      if (r && r.callId) byId.set(r.callId, r);
    }
    const cur = Array.isArray(state.sessionCalls) ? state.sessionCalls : [];
    for (const r of cur) {
      if (!r || !r.callId) continue;
      const prev = byId.get(r.callId);
      if (!prev || (!isValidSpeedSampleSafe(prev) && isValidSpeedSampleSafe(r)) || Number(r.outputTokens || 0) > Number(prev.outputTokens || 0)) {
        byId.set(r.callId, r);
      }
    }
    return Array.from(byId.values());
  }

  function createSvgEl(tag, attrs = {}) {
    const doc = typeof document !== 'undefined' ? document : null;
    if (!doc) return null;
    const node = typeof doc.createElementNS === 'function'
      ? doc.createElementNS('http://www.w3.org/2000/svg', tag)
      : (typeof doc.createElement === 'function' ? doc.createElement(tag) : null);
    if (!node) return null;
    for (const [k, v] of Object.entries(attrs)) {
      if (v != null && typeof node.setAttribute === 'function') node.setAttribute(k, String(v));
    }
    return node;
  }

  function renderSpeedBarChart(groups) {
    const svg = el('speed-bar-svg');
    const wrap = el('speed-bar-chart-wrap');
    const emptyEl = el('speed-bar-empty');
    const tooltip = el('speed-bar-tooltip');
    const titleEl = el('speed-bar-title');

    const metricTitleMap = { tps: t('speed.barTitle.tps'), ttft: t('speed.barTitle.ttft'), duration: t('speed.barTitle.duration') };
    if (titleEl) titleEl.textContent = metricTitleMap[speedMetric] || t('speed.barTitle.tps');

    if (!groups.length) {
      if (emptyEl) emptyEl.hidden = false;
      if (wrap) wrap.hidden = true;
      return;
    }
    if (emptyEl) emptyEl.hidden = true;
    if (wrap) wrap.hidden = false;
    if (!svg || typeof svg.replaceChildren !== 'function') return;

    const width = 420;
    const rowH = 34;
    const padTop = 8;
    const padBottom = 10;
    const labelW = 148;
    const valW = 86;
    const barAreaW = width - labelW - valW - 12;
    const height = padTop + padBottom + groups.length * rowH;

    svg.setAttribute('viewBox', `0 0 ${width} ${height}`);
    svg.setAttribute('width', String(width));
    svg.setAttribute('height', String(height));

    const getVal = g => speedMetric === 'ttft' ? g.medianTtft : speedMetric === 'duration' ? g.medianDuration : g.medianTps;
    const maxVal = Math.max(...groups.map(g => getVal(g) || 0), 0.1);

    const nodes = [];
    groups.forEach((g, idx) => {
      const y = padTop + idx * rowH;
      const val = getVal(g) || 0;
      const w = Math.max(4, (val / maxVal) * barAreaW);
      const displayLabel = formatProductDisplayWithEffort(g.productLabel, g.effort);
      const unitStr = speedMetric === 'tps' ? `${val} tok/s` : t('speed.unitSec', { val });

      const rowGrp = createSvgEl('g', { style: 'cursor:pointer' });
      const bgHit = createSvgEl('rect', { x: 0, y, width, height: rowH - 4, rx: 4, fill: 'transparent' });
      const dot = createSvgEl('circle', {
        cx: 7,
        cy: y + 14,
        r: 3.5,
        fill: VENDOR_DOT_COLORS[g.vendor] || '#8a8a94'
      });
      const lbl = createSvgEl('text', {
        x: 15,
        y: y + 18,
        fill: 'var(--ag-text-primary, #ececef)',
        'font-size': '10.5'
      });
      if (lbl) lbl.textContent = displayLabel.length > 20 ? displayLabel.slice(0, 19) + '…' : displayLabel;

      const track = createSvgEl('rect', {
        x: labelW,
        y: y + 7,
        width: barAreaW,
        height: 14,
        rx: 3,
        fill: 'var(--ag-track-bg, rgba(255,255,255,0.08))'
      });
      const bar = createSvgEl('rect', {
        x: labelW,
        y: y + 7,
        width: w.toFixed(1),
        height: 14,
        rx: 3,
        fill: VENDOR_DOT_COLORS[g.vendor] || 'var(--ag-custom-speed, #38bdf8)',
        opacity: g.lowSample ? '0.45' : '0.92'
      });
      const valTxt = createSvgEl('text', {
        x: labelW + barAreaW + 6,
        y: y + 18,
        fill: g.lowSample ? 'var(--ag-text-muted, #8a8a94)' : 'var(--ag-text-secondary, #c8c8d0)',
        'font-size': '10'
      });
      if (valTxt) valTxt.textContent = `${unitStr}${g.lowSample ? ` ${t('speed.lowSample')}` : ''}`;

      if (rowGrp) {
        if (bgHit) rowGrp.appendChild(bgHit);
        if (dot) rowGrp.appendChild(dot);
        if (lbl) rowGrp.appendChild(lbl);
        if (track) rowGrp.appendChild(track);
        if (bar) rowGrp.appendChild(bar);
        if (valTxt) rowGrp.appendChild(valTxt);
        rowGrp.addEventListener?.('mouseenter', () => {
          if (!tooltip) return;
          const rangeTxt = g.minTs && g.maxTs
            ? `${formatMonthDayTime(g.minTs)} ~ ${formatMonthDayTime(g.maxTs)}`
            : '—';
          tooltip.innerHTML =
            `<strong>${displayLabel}</strong><br>` +
            `${t('speed.tip.samples', { n: g.count, low: g.lowSample ? t('models.card.lowSampleParen') : '' })}<br>` +
            `${t('speed.tip.timeRange', { range: rangeTxt })}<br>` +
            `${t('speed.tip.medOut', { val: fmt(g.medianOutputTokens) })}<br>` +
            `${t('speed.tip.medIn', { val: fmt(g.medianInputTokens) })}`;
          tooltip.hidden = false;
          if (tooltip.style) {
            tooltip.style.top = `${Math.max(4, y - 4)}px`;
            tooltip.style.right = '8px';
          }
        });
        rowGrp.addEventListener?.('mouseleave', () => {
          if (tooltip) tooltip.hidden = true;
        });
        rowGrp.addEventListener?.('click', () => {
          selectedSpeedExactModelId = g.modelExactId;
          renderSpeedComparisonTab();
        });
        nodes.push(rowGrp);
      }
    });
    svg.replaceChildren(...nodes);
  }

  function renderSpeedLineChart(selectedGroup) {
    const svg = el('speed-line-svg');
    const wrap = el('speed-line-chart-wrap');
    const emptyEl = el('speed-line-empty');
    const tooltip = el('speed-line-tooltip');

    const samples = (selectedGroup?.samples || []).slice(-200).filter(s => s && s.tps > 0);
    if (!samples.length) {
      if (emptyEl) emptyEl.hidden = false;
      if (wrap) wrap.hidden = true;
      return;
    }
    if (emptyEl) emptyEl.hidden = true;
    if (wrap) wrap.hidden = false;
    if (!svg || typeof svg.replaceChildren !== 'function') return;

    const width = 420;
    const height = 148;
    const padL = 38;
    const padR = 14;
    const padT = 14;
    const padB = 24;
    const plotW = width - padL - padR;
    const plotH = height - padT - padB;

    svg.setAttribute('viewBox', `0 0 ${width} ${height}`);
    svg.setAttribute('width', String(width));
    svg.setAttribute('height', String(height));

    const maxTps = Math.max(...samples.map(s => Number(s.tps) || 0), 10);
    const minTps = Math.max(0, Math.min(...samples.map(s => Number(s.tps) || 0)) * 0.8);
    const spanTps = Math.max(1, maxTps - minTps);

    const nodes = [];
    // Y 轴参考线与刻度
    [0, 0.5, 1].forEach(ratio => {
      const y = padT + plotH * (1 - ratio);
      const val = Math.round(minTps + spanTps * ratio);
      const grid = createSvgEl('line', {
        x1: padL, y1: y.toFixed(1), x2: width - padR, y2: y.toFixed(1),
        stroke: 'var(--ag-border-subtle, rgba(255,255,255,0.08))', 'stroke-width': 1
      });
      const txt = createSvgEl('text', {
        x: padL - 5, y: (y + 3).toFixed(1), 'text-anchor': 'end',
        fill: 'var(--ag-text-muted, #8a8a94)', 'font-size': '9.5'
      });
      if (txt) txt.textContent = String(val);
      if (grid) nodes.push(grid);
      if (txt) nodes.push(txt);
    });

    const pts = samples.map((s, idx) => {
      const x = samples.length === 1 ? padL + plotW / 2 : padL + (idx / (samples.length - 1)) * plotW;
      const y = padT + plotH * (1 - ((Number(s.tps) - minTps) / spanTps));
      return { x, y, sample: s };
    });

    if (pts.length >= 2) {
      const dAttr = pts.map((p, i) => `${i === 0 ? 'M' : 'L'} ${p.x.toFixed(1)} ${p.y.toFixed(1)}`).join(' ');
      const path = createSvgEl('path', {
        d: dAttr, fill: 'none',
        stroke: VENDOR_DOT_COLORS[selectedGroup.vendor] || 'var(--ag-custom-speed, #38bdf8)',
        'stroke-width': 1.8
      });
      if (path) nodes.push(path);
    }

    pts.forEach((pt, idx) => {
      const circle = createSvgEl('circle', {
        cx: pt.x.toFixed(1),
        cy: pt.y.toFixed(1),
        r: 3.5,
        fill: VENDOR_DOT_COLORS[selectedGroup.vendor] || 'var(--ag-custom-speed, #38bdf8)',
        stroke: 'var(--ag-bg-panel, #181818)',
        'stroke-width': 1.2,
        style: 'cursor:pointer'
      });
      if (circle) {
        circle.addEventListener?.('mouseenter', () => {
          if (!tooltip) return;
          const s = pt.sample;
          const originTxt = s.origin === 'speed-test' ? t('speed.originProbe') : t('speed.origin.chat');
          const ttftTxt = s.ttftSec != null ? t('speed.unitSec', { val: s.ttftSec }) : t('speed.unknown');
          tooltip.innerHTML =
            `<strong>${t('speed.tip.tpsLine', { idx: idx + 1, tps: s.tps })}</strong><br>` +
            `${t('speed.tip.time', { val: formatMonthDayTime(s.ts || s.createdAt) || '—' })}<br>` +
            `${t('speed.tip.output', { val: fmt(s.outputTokens) })}<br>` +
            `${t('speed.tip.ttft', { val: ttftTxt })}<br>` +
            `${t('speed.tip.origin', { val: originTxt })}`;
          tooltip.hidden = false;
          if (tooltip.style) {
            tooltip.style.top = '6px';
            tooltip.style.right = '8px';
          }
        });
        circle.addEventListener?.('mouseleave', () => {
          if (tooltip) tooltip.hidden = true;
        });
        nodes.push(circle);
      }
    });

    const firstLbl = createSvgEl('text', { x: padL, y: height - 6, fill: 'var(--ag-text-muted, #8a8a94)', 'font-size': '9.5' });
    if (firstLbl) firstLbl.textContent = formatMonthDayTime(samples[0].ts || samples[0].createdAt) || '#1';
    const lastLbl = createSvgEl('text', { x: width - padR, y: height - 6, 'text-anchor': 'end', fill: 'var(--ag-text-muted, #8a8a94)', 'font-size': '9.5' });
    if (lastLbl && samples.length > 1) lastLbl.textContent = formatMonthDayTime(samples[samples.length - 1].ts || samples[samples.length - 1].createdAt) || `#${samples.length}`;
    if (firstLbl) nodes.push(firstLbl);
    if (lastLbl) nodes.push(lastLbl);

    svg.replaceChildren(...nodes);
  }

  let lastSpeedGroups = [];

  // =========================================================================
  // 速度对比页（原型移植）：PK 对比台 + 多系列走势 + 全量排行
  // =========================================================================
  let speedPkSelection = [];
  let speedPkUserCleared = false;
  let speedPkInitialized = false;
  let speedRankSort = 'tps';
  let speedRankQuery = '';

  const SPEED_SERIES_COLORS = ['accent', 'c2', 'c3', 'c4', 'c5', 'c6', 'c7', 'c8'];

  const speedSeriesColor = (index) => `var(--spd-${SPEED_SERIES_COLORS[index % SPEED_SERIES_COLORS.length]})`;

  let speedAlgorithm = 'median';

  const speedResolvedMetrics = (group) => {
    const empty = { tps: null, ttft: null, duration: null };
    if (!group) return empty;
    const samples = Array.isArray(group.samples) ? group.samples : [];
    const meanOf = (pick) => {
      const list = samples.map(pick).map(Number).filter(v => Number.isFinite(v) && v > 0);
      return list.length ? list.reduce((a, b) => a + b, 0) / list.length : null;
    };
    const medianTps = Number.isFinite(group.medianTps) ? group.medianTps : null;
    const medianTtft = Number.isFinite(group.medianTtft) ? group.medianTtft : null;
    const medianDuration = Number.isFinite(group.medianDuration) ? group.medianDuration : null;
    let tps = medianTps;
    let ttft = medianTtft;
    let duration = medianDuration;
    if (speedAlgorithm === 'mean') {
      tps = meanOf(s => s.tps);
      if (!Number.isFinite(tps)) tps = medianTps;
      ttft = meanOf(s => s.ttftSec);
      if (!Number.isFinite(ttft)) ttft = medianTtft;
      duration = meanOf(s => s.durationSec);
      if (!Number.isFinite(duration)) duration = medianDuration;
    } else if (speedAlgorithm === 'composite') {
      // 综合效率：500 token 等效输出速率 500 / (TTFT + 500 / tok_s)，无 TTFT 时优雅回退
      if (Number.isFinite(medianTps) && medianTps > 0) {
        tps = (Number.isFinite(medianTtft) && medianTtft > 0)
          ? 500 / (medianTtft + 500 / medianTps)
          : medianTps;
      }
    }
    return { tps, ttft, duration };
  };

  const speedMetricValue = (group) => {
    if (!group) return null;
    const resolved = speedResolvedMetrics(group);
    if (speedMetric === 'ttft') return Number.isFinite(resolved.ttft) ? resolved.ttft : null;
    if (speedMetric === 'duration') return Number.isFinite(resolved.duration) ? resolved.duration : null;
    return Number.isFinite(resolved.tps) ? resolved.tps : null;
  };

  const speedMetricUnit = () => (speedAlgorithm === 'composite' || speedMetric === 'tps' ? 'tok/s' : 's');

  const speedSampleValue = (sample) => {
    if (!sample) return null;
    if (speedMetric === 'ttft') return Number.isFinite(Number(sample.ttftSec)) && Number(sample.ttftSec) > 0 ? Number(sample.ttftSec) : null;
    if (speedMetric === 'duration') return Number.isFinite(Number(sample.durationSec)) && Number(sample.durationSec) > 0 ? Number(sample.durationSec) : null;
    const tps = Number(sample.tps);
    if (!(Number.isFinite(tps) && tps > 0)) return null;
    if (speedAlgorithm === 'composite') {
      const ttft = Number(sample.ttftSec);
      if (Number.isFinite(ttft) && ttft > 0) return 500 / (ttft + 500 / tps);
    }
    return tps;
  };

  const formatSpeedMetricValue = (value) => {
    if (!Number.isFinite(value)) return '—';
    return speedMetric === 'tps' ? Number(value).toFixed(1) : `${Number(value).toFixed(2)}s`;
  };

  const speedEffortShortLabel = (effort) => {
    const raw = String(effort || '').trim();
    if (!raw) return '';
    const zh = formatEffortZh(raw) || '';
    // formatEffortZh 形如「中（Medium）」，速度对比页严格零括号，只取中文短档位
    return String(zh).split(/[（(]/)[0].trim();
  };

  const stripTrailingBracket = (text) => String(text || '').replace(/\s*[（(][^（()）]*[)）]\s*$/, '').trim();

  /**
   * 速度对比页专用模型显示名：严格零中英文括号，档位用中点连接
   */
  const speedDisplayName = (group) => {
    if (!group) return '';
    const raw = String(group.productLabel || group.modelLabel || group.modelExactId || '').trim();
    const base = stripTrailingBracket(raw);
    const shortEffort = speedEffortShortLabel(group.effort);
    const composed = [base, shortEffort].filter(Boolean).join(' · ');
    return composed.replace(/[（()）]/g, '').replace(/\s{2,}/g, ' ').trim();
  };

  const resolveSpeedCurrentModelId = () => {
    const latest = state.latest || state.scan?.latest || null;
    const raw = latest?.modelExactId || latest?.modelLabel || latest?.model || '';
    return String(raw || '').trim().toLowerCase();
  };

  const ensureSpeedPkSelection = (groups) => {
    const validIds = new Set((groups || []).map(g => g.modelExactId));
    speedPkSelection = speedPkSelection.filter(id => validIds.has(id));
    if (speedPkSelection.length) return speedPkSelection;
    // 用户主动清空或逐个删光后绝不自动回填，只有首次未初始化才给默认 3 款
    if (speedPkUserCleared) return speedPkSelection;
    const currentId = resolveSpeedCurrentModelId();
    const picked = [];
    const currentGroup = groups.find(g => g.modelExactId === currentId);
    if (currentGroup) picked.push(currentGroup.modelExactId);
    for (const g of groups) {
      if (picked.length >= 3) break;
      if (!picked.includes(g.modelExactId)) picked.push(g.modelExactId);
    }
    speedPkSelection = picked.slice(0, 3);
    speedPkInitialized = true;
    return speedPkSelection;
  };

  const renderSpeedPkChips = (groups) => {
    const wrap = el('speed-pk-chips');
    if (!wrap) return;
    wrap.replaceChildren();
    const picked = ensureSpeedPkSelection(groups);
    picked.forEach((id, index) => {
      const group = groups.find(g => g.modelExactId === id);
      if (!group) return;
      const chip = document.createElement('span');
      chip.className = 'ctx-speed-chip';
      chip.setAttribute('data-pk-id', id);
      const dot = document.createElement('span');
      dot.className = 'ctx-speed-chip-dot';
      dot.style.background = speedSeriesColor(index);
      const label = document.createElement('span');
      label.className = 'ctx-speed-chip-label';
      label.textContent = speedDisplayName(group);
      const xBtn = document.createElement('button');
      xBtn.type = 'button';
      xBtn.className = 'ctx-speed-chip-x';
      xBtn.textContent = '×';
      xBtn.setAttribute('aria-label', t('speed.hero.clear'));
      xBtn.addEventListener('click', (ev) => {
        ev?.stopPropagation?.();
        speedPkUserCleared = true;
speedPkSelection = speedPkSelection.filter(v => v !== id);
        renderSpeedProto();
      });
      chip.appendChild(dot);
      chip.appendChild(label);
      chip.appendChild(xBtn);
      wrap.appendChild(chip);
    });
  };

  function renderSpeedPkCards(groups) {
    const grid = el('speed-pk-cards');
    const picked = ensureSpeedPkSelection(groups);
    const pickedGroups = picked.map(id => groups.find(g => g.modelExactId === id)).filter(Boolean);
    const countEl = el('speed-pk-count');
    if (countEl) countEl.textContent = String(pickedGroups.length);
    if (!grid) return;
    grid.replaceChildren();
    if (!pickedGroups.length) {
      const empty = document.createElement('div');
      empty.className = 'ctx-speed-empty-cell';
      empty.textContent = t('speed.empty');
      grid.appendChild(empty);
      return;
    }
    const values = pickedGroups.map(speedMetricValue);
    const nums = values.filter(v => Number.isFinite(v) && v > 0);
    const bestValue = nums.length
      ? (speedMetric === 'tps' ? Math.max(...nums) : Math.min(...nums))
      : null;
    const ttftBest = (() => {
      const list = pickedGroups.map(g => g.medianTtft).filter(v => Number.isFinite(v) && v > 0);
      return list.length ? Math.min(...list) : null;
    })();
    const currentId = resolveSpeedCurrentModelId();

    pickedGroups.forEach((group, index) => {
      const value = values[index];
      const isActive = group.modelExactId === currentId;
      const card = document.createElement('div');
      card.className = 'ctx-speed-pk-card';
      card.setAttribute('data-pk-id', group.modelExactId);
      card.setAttribute('data-pk-rank', String(index));
      if (isActive) card.setAttribute('data-pk-active', 'true');

      const top = document.createElement('div');
      top.className = 'ctx-speed-pk-top';
      // 冠军按当前指标动态判定：tps 越大越快，ttft / duration 越小越快；绝不把 current 硬编码成最快
      const championId = (() => {
        const scored = pickedGroups
          .map((g, i) => ({ id: g.modelExactId, v: values[i] }))
          .filter(x => Number.isFinite(x.v));
        if (!scored.length) return null;
        scored.sort((a, b) => (speedMetric === 'tps' ? b.v - a.v : a.v - b.v));
        return scored[0].id;
      })();
      const isChampion = championId != null && group.modelExactId === championId;
      if (isChampion) {
        const badge = document.createElement('span');
        badge.className = 'ctx-speed-pk-badge';
        badge.textContent = isActive ? t('speed.hero.fastest') : t('speed.hero.champion');
        top.appendChild(badge);
        const base = document.createElement('span');
        base.className = 'ctx-speed-pk-base';
        base.textContent = t('speed.hero.base', { x: '1.00' });
        top.appendChild(base);
      } else {
        if (isActive) {
          const cur = document.createElement('span');
          cur.className = 'ctx-speed-pk-rank';
          cur.textContent = t('speed.hero.current');
          top.appendChild(cur);
        }
        const rank = document.createElement('span');
        rank.className = 'ctx-speed-pk-rank';
        rank.textContent = t('speed.hero.rankN', { n: index + 1 });
        top.appendChild(rank);
        const delta = document.createElement('span');
        delta.className = 'ctx-speed-pk-rank';
        if (Number.isFinite(value) && Number.isFinite(bestValue) && bestValue > 0) {
          const pct = Math.abs(((value - bestValue) / bestValue) * 100);
          const slower = speedMetric === 'tps' ? value < bestValue : value > bestValue;
          delta.textContent = slower
            ? t('speed.hero.slower', { pct: pct.toFixed(1) })
            : t('speed.hero.faster', { pct: pct.toFixed(1) });
        } else {
          delta.textContent = '—';
        }
        top.appendChild(delta);
      }
      card.appendChild(top);

      const name = document.createElement('div');
      name.className = 'ctx-speed-pk-name';
      name.textContent = speedDisplayName(group);
      name.title = speedDisplayName(group);
      card.appendChild(name);

      const sub = document.createElement('div');
      sub.className = 'ctx-speed-pk-sub';
      const vendorText = String(group.vendor || '').trim();
      const effortText = String(group.effort || '').trim();
      sub.textContent = [vendorText, effortText].filter(Boolean).join(' · ') || String(group.productKey || '');
      card.appendChild(sub);

      const valueEl = document.createElement('div');
      valueEl.className = 'ctx-speed-pk-value';
      valueEl.textContent = formatSpeedMetricValue(value);
      const unit = document.createElement('span');
      unit.className = 'ctx-speed-pk-unit';
      unit.textContent = speedMetricUnit();
      valueEl.appendChild(unit);
      card.appendChild(valueEl);

      const bar = document.createElement('div');
      bar.className = 'ctx-speed-pk-bar';
      const fill = document.createElement('div');
      fill.className = 'ctx-speed-pk-bar-fill';
      const ratio = Number.isFinite(value) && Number.isFinite(bestValue) && Math.max(...nums, 0) > 0
        ? (speedMetric === 'tps'
          ? Math.max(0.04, Math.min(1, value / Math.max(...nums)))
          : Math.max(0.04, Math.min(1, Math.max(...nums) > 0 ? (1 - value / Math.max(...nums)) : 0.04)))
        : 0.04;
      fill.style.width = `${Math.round(ratio * 100)}%`;
      fill.style.background = speedSeriesColor(index);
      bar.appendChild(fill);
      card.appendChild(bar);

      const metrics = document.createElement('div');
      metrics.className = 'ctx-speed-pk-metrics';
      const addMetricRow = (labelKey, valueText, extraNode) => {
        const row = document.createElement('div');
        row.className = 'ctx-speed-pk-metric';
        const lbl = document.createElement('span');
        lbl.textContent = t(labelKey);
        const val = document.createElement('b');
        val.textContent = valueText;
        if (extraNode) val.appendChild(extraNode);
        row.appendChild(lbl);
        row.appendChild(val);
        metrics.appendChild(row);
      };
      const ttftExtra = (Number.isFinite(ttftBest) && Number.isFinite(group.medianTtft) && group.medianTtft === ttftBest)
        ? (() => {
          const pill = document.createElement('span');
          pill.className = 'ctx-speed-tag ctx-speed-tag-accent';
          pill.textContent = ` · ${t('speed.hero.firstBest')}`;
          return pill;
        })()
        : null;
      addMetricRow('speed.hero.ttft', Number.isFinite(group.medianTtft) ? `${Number(group.medianTtft).toFixed(1)}s` : '—', ttftExtra);
      addMetricRow('speed.hero.medianOut', Number.isFinite(group.medianOutputTokens) ? `${Math.round(group.medianOutputTokens).toLocaleString()} tok` : '—');
      const sampleExtra = group.lowSample
        ? (() => {
          const pill = document.createElement('span');
          pill.className = 'ctx-speed-pill-low';
          pill.textContent = ` · ${t('speed.hero.lowSample', { n: group.count })}`;
          return pill;
        })()
        : null;
      addMetricRow('speed.hero.samples',
        group.lowSample ? '' : t('speed.hero.sampleCount', { n: group.count }),
        sampleExtra);
      card.appendChild(metrics);

      card.addEventListener('click', () => {
        if (speedPkSelection.includes(group.modelExactId)) return;
        speedPkSelection = [...speedPkSelection, group.modelExactId];
        renderSpeedProto();
      });
      grid.appendChild(card);
    });
  }

  function speedTrendLegendSuffixes(groups) {
    const byName = new Map();
    for (const group of groups) {
      const name = speedDisplayName(group);
      if (!byName.has(name)) byName.set(name, []);
      byName.get(name).push(group.modelExactId);
    }
    const suffixes = new Map();
    const used = new Set(byName.keys());
    for (const [name, ids] of byName) {
      if (ids.length < 2) continue;
      const tails = ids.map(id => id.replace(/[（）()]/g, '').split(/[-_:/]+/).pop().slice(-16));
      ids.slice().sort().forEach((id, index) => {
        const tail = tails[ids.indexOf(id)];
        let suffix = tail && tails.indexOf(tail) === tails.lastIndexOf(tail) ? tail : `#${index + 1}`;
        while (used.has(`${name} · ${suffix}`)) suffix += ` · #${index + 1}`;
        used.add(`${name} · ${suffix}`);
        suffixes.set(id, ` · ${suffix}`);
      });
    }
    return suffixes;
  }

  const SPEED_MINUTE_MS = 60000;
  const SPEED_HOUR_MS = 60 * SPEED_MINUTE_MS;
  const speedLocalDay = (timestamp) => {
    const ts = timestamp - new Date(timestamp).getTimezoneOffset() * SPEED_MINUTE_MS;
    return Math.floor(ts / 86400000);
  };
  const speedLocalHour = (ts) => {
    const date = new Date(ts);
    return ts - date.getMinutes() * SPEED_MINUTE_MS - date.getSeconds() * 1000 - date.getMilliseconds();
  };

  function buildSpeedTrend(picked) {
    const days = new Set();
    let first = Infinity;
    let last = -Infinity;
    const series = picked.map((group, index) => {
      const points = [];
      for (const sample of group.samples || []) {
        const ts = Number(sample.ts);
        const val = speedSampleValue(sample);
        if (!(ts > 0 && Number.isFinite(ts) && Number.isFinite(val))) continue;
        days.add(speedLocalDay(ts));
        first = Math.min(first, ts);
        last = Math.max(last, ts);
        points.push({ ts, val });
      }
      return { group, color: speedSeriesColor(index), points };
    }).filter(entry => entry.points.length);
    const granularity = last - first > 90 * 86400000 ? 'week'
      : days.size > 2 ? 'day' : last - first >= SPEED_HOUR_MS ? 'hour' : 'sample';
    const bucketKey = granularity === 'week' ? (ts => Math.floor((speedLocalDay(ts) + 3) / 7) * 7 - 3)
      : granularity === 'day' ? speedLocalDay : speedLocalHour;
    for (const entry of series) {
      if (granularity !== 'sample') {
        const buckets = new Map();
        for (const { ts, val } of entry.points) {
          const key = bucketKey(ts);
          if (!buckets.has(key)) buckets.set(key, []);
          buckets.get(key).push(val);
        }
        entry.points = Array.from(buckets, ([ts, values]) => {
          const val = speedAlgorithm === 'mean'
            ? values.reduce((sum, value) => sum + value, 0) / values.length
            : computeMedian(values);
          return { ts, val };
        });
      }
      entry.points.sort((a, b) => a.ts - b.ts);
      if (entry.points.length >= 4) {
        const sortedVals = entry.points.map(point => point.val).sort((a, b) => a - b);
        const index = Math.min(sortedVals.length - 1, Math.floor(sortedVals.length * 0.95));
        const cap = sortedVals[index];
        for (const pt of entry.points) {
          if (pt.val > cap) pt.val = cap;
        }
      }
    }
    return { granularity, series };
  }

  function speedTrendTimeAxis(granularity, min, max, maxTicks) {
    const span = max - min;
    const unit = granularity === 'week' ? 7 : granularity === 'day' ? 1 : SPEED_HOUR_MS;
    const step = granularity === 'sample'
      ? ([1000, 2000, 5000, 10000, 15000, 30000, 60000, 120000, 300000, 600000]
        .find(interval => interval >= span / (maxTicks - 1)) || 900000)
      : Math.max(1, Math.ceil(span / unit / (maxTicks - 1))) * unit;
    const count = Math.max(3, Math.ceil(span / step) + 1);
    const ticks = Array.from({ length: count }, (_, index) => min + step * index);
    const twoDigits = (value) => String(value).padStart(2, '0');
    const dateLabel = (month, day) => `${twoDigits(month + 1)}-${twoDigits(day)}`;
    const today = speedLocalDay(Date.now());
    const format = (ts, full = false) => {
      if (granularity === 'day' || granularity === 'week') {
        const date = new Date(ts * 86400000);
        return ts === today ? t('speed.trend.today') : dateLabel(date.getUTCMonth(), date.getUTCDate());
      }
      const date = new Date(ts);
      const time = `${twoDigits(date.getHours())}:${twoDigits(date.getMinutes())}`;
      const withSeconds = granularity === 'sample' && (step < SPEED_MINUTE_MS || full);
      const clock = withSeconds ? `${time}:${twoDigits(date.getSeconds())}` : time;
      return full ? `${dateLabel(date.getMonth(), date.getDate())} · ${clock}` : clock;
    };
    return { ticks, end: ticks[ticks.length - 1], format };
  }

  function renderSpeedTrendLegend(series, suffixes) {
    const legend = el('speed-trend-legend');
    const titleEl = el('speed-trend-title');
    if (titleEl) {
      const key = speedMetric === 'ttft'
        ? 'speed.trend.titleTtft'
        : (speedMetric === 'duration' ? 'speed.trend.titleDuration' : 'speed.trend.title');
      titleEl.textContent = t(key);
    }
    if (!legend) return;
    legend.replaceChildren();
    for (const { group, color } of series) {
      const item = document.createElement('span');
      item.className = 'ctx-speed-legend-item';
      const line = document.createElement('span');
      line.className = 'ctx-speed-legend-line';
      line.style.background = color;
      const text = document.createElement('span');
      text.textContent = speedDisplayName(group);
      text.textContent += suffixes.get(group.modelExactId) || '';
      item.appendChild(line);
      item.appendChild(text);
      legend.appendChild(item);
    }
  }

  function renderSpeedMultiSeriesChart(series, granularity, suffixes) {
    const svg = el('speed-line-svg');
    const wrap = el('speed-line-chart-wrap');
    if (!svg || !wrap) return;
    // 测试沙箱没有 createElementNS，保留既有单模型折线图节点，避免破坏既有断言
    if (typeof document?.createElementNS !== 'function') return;
    wrap.hidden = !series.length;
    const W = Math.max(220, wrap.clientWidth || 520);
    const H = 200, PAD_L = 40, PAD_R = 32, PAD_T = 12, PAD_B = 27;
    svg.setAttribute('viewBox', `0 0 ${W} ${H}`);
    svg.setAttribute('preserveAspectRatio', 'none');
    svg.replaceChildren();
    const emptyEl = el('speed-line-empty');
    if (emptyEl) emptyEl.hidden = series.length > 0;
    const foot = el('speed-trend-foot');
    foot?.replaceChildren();
    const tooltip = el('speed-line-tooltip');
    if (tooltip) {
      tooltip.hidden = true;
      svg.onpointermove = null;
      svg.onpointerleave = null;
    }
    if (!series.length) return;

    let rawMin = Infinity;
    let rawMax = -Infinity;
    const timestamps = new Set();
    for (const { points } of series) {
      for (const { ts, val } of points) {
        timestamps.add(ts);
        rawMin = Math.min(rawMin, val);
        rawMax = Math.max(rawMax, val);
      }
    }
    const sortedTimes = Array.from(timestamps).sort((a, b) => a - b);
    const minTs = sortedTimes[0];
    const plotW = W - PAD_L - PAD_R;
    const axis = speedTrendTimeAxis(granularity, minTs, sortedTimes[sortedTimes.length - 1],
      Math.max(3, Math.min(7, Math.floor(plotW / 57) + 1)));
    const span = Math.max(rawMax - rawMin, 1);
    // Y 轴下限严格锁死 0，绝不出现负数刻度
    const yMin = Math.max(0, rawMin - span * 0.15);
    const yMax = Math.max(yMin + 1, rawMax + span * 0.15);
    const xOf = ts => PAD_L + ((ts - minTs) / (axis.end - minTs)) * plotW;
    const yOf = v => PAD_T + (1 - (v - yMin) / Math.max(1e-6, yMax - yMin)) * (H - PAD_T - PAD_B);

    // 网格与 Y 轴刻度
    for (let i = 0; i <= 3; i++) {
      const v = yMin + ((yMax - yMin) * i) / 3;
      const y = yOf(v);
      svg.appendChild(createSvgEl('line', { x1: PAD_L, x2: W - PAD_R, y1: y, y2: y, class: 'ctx-speed-gridline' }));
      const label = createSvgEl('text', { x: PAD_L - 7, y: y + 3, 'text-anchor': 'end', class: 'ctx-speed-y-tick' });
      label.textContent = speedMetric === 'tps' ? v.toFixed(0) : v.toFixed(1);
      svg.appendChild(label);
    }

    for (const ts of axis.ticks) {
      const x = xOf(ts);
      svg.appendChild(createSvgEl('line', { x1: x, x2: x, y1: H - PAD_B, y2: H - PAD_B + 5, class: 'ctx-speed-gridline' }));
      const label = createSvgEl('text', { x, y: H - 8, 'text-anchor': 'middle', class: 'ctx-speed-x-tick' });
      label.textContent = axis.format(ts);
      svg.appendChild(label);
    }

    series.forEach(({ points, color }, index) => {
      svg.appendChild(createSvgEl('polyline', {
        fill: 'none', stroke: color, 'stroke-width': index === 0 ? 2 : 1.5,
        'stroke-linejoin': 'round', 'stroke-linecap': 'round',
        'stroke-dasharray': index >= SPEED_SERIES_COLORS.length ? '4 3' : null,
        points: points.map(p => `${xOf(p.ts).toFixed(1)},${yOf(p.val).toFixed(1)}`).join(' ')
      }));
      const marks = points.length <= 16 ? points : points.slice(-1);
      for (const point of marks) {
        svg.appendChild(createSvgEl('circle', { cx: xOf(point.ts), cy: yOf(point.val), r: 2.5, fill: color }));
      }
    });

    if (tooltip) {
      const byTime = new Map();
      for (const { group, color, points } of series) {
        const label = speedDisplayName(group) + (suffixes.get(group.modelExactId) || '');
        for (const point of points) {
          if (!byTime.has(point.ts)) byTime.set(point.ts, []);
          byTime.get(point.ts).push({ label, color, val: point.val });
        }
      }
      svg.onpointermove = (ev) => {
        const rect = svg.getBoundingClientRect();
        if (!rect.width) return;
        const offset = ev.clientX - rect.left;
        const ratioX = (offset * W / rect.width - PAD_L) / plotW;
        const ts = minTs + ratioX * (axis.end - minTs);
        let nearest = minTs;
        for (let index = 1; index < sortedTimes.length; index++) {
          const time = sortedTimes[index];
          if (Math.abs(time - ts) >= Math.abs(nearest - ts)) break;
          nearest = time;
        }
        const stamp = document.createElement('strong');
        stamp.textContent = axis.format(nearest, true);
        tooltip.replaceChildren(stamp);
        for (const { label, color, val } of byTime.get(nearest)) {
          const row = document.createElement('div');
          row.className = 'ctx-speed-tooltip-row';
          const swatch = document.createElement('i');
          swatch.style.background = color;
          const name = document.createElement('span');
          name.textContent = label;
          const value = document.createElement('b');
          value.textContent = formatSpeedMetricValue(val);
          row.append(swatch, name, value);
          tooltip.appendChild(row);
        }
        tooltip.hidden = false;
        tooltip.style.left = `${Math.round(Math.max(4, Math.min(rect.width - tooltip.offsetWidth - 4, offset)))}px`;
        tooltip.style.top = '6px';
      };
      svg.onpointerleave = () => { tooltip.hidden = true; };
    }

    if (foot) {
      const note = document.createElement('span');
      note.textContent = t(`speed.trend.granularity.${granularity}`);
      foot.appendChild(note);
      const primary = series[0];
      if (primary && primary.points.length >= 2) {
        const vals = primary.points.map(p => p.val);
        const mean = vals.reduce((a, b) => a + b, 0) / vals.length;
        const variance = vals.reduce((a, b) => a + (b - mean) ** 2, 0) / vals.length;
        const cv = mean > 0 ? Math.sqrt(variance) / mean : 0;
        const stability = Math.max(0, Math.min(100, 100 - cv * 100));
        const stable = document.createElement('span');
        stable.textContent = `${String(primary.group.productLabel || '').split('·')[0].trim()} ${t('speed.trend.stability')} · ${stability.toFixed(1)}%`;
        foot.appendChild(stable);
      }
    }
  }

  function renderSpeedRankRows(groups) {
    const rowsWrap = el('speed-rank-rows');
    if (!rowsWrap) return;
    rowsWrap.replaceChildren();
    const countEl = el('speed-rank-count');
    if (countEl) countEl.textContent = t('speed.rank.countTotal', { n: groups.length });

    const query = String(speedRankQuery || '').trim().toLowerCase();
    let list = groups.filter((g) => {
      if (!query) return true;
      const hay = [g.productLabel, g.modelLabel, g.modelExactId, g.vendor, g.effort, g.productKey]
        .filter(Boolean).join(' ').toLowerCase();
      return hay.includes(query);
    });
    const sorters = {
      tps: (a, b) => (Number(b.medianTps) || -1) - (Number(a.medianTps) || -1),
      ttft: (a, b) => (Number.isFinite(a.medianTtft) ? a.medianTtft : Infinity) - (Number.isFinite(b.medianTtft) ? b.medianTtft : Infinity),
      samples: (a, b) => (Number(b.count) || 0) - (Number(a.count) || 0)
    };
    list = list.slice().sort(sorters[speedRankSort] || sorters.tps);

    if (!list.length) {
      const empty = document.createElement('div');
      empty.className = 'ctx-speed-empty-cell';
      empty.textContent = t('speed.rank.empty');
      rowsWrap.appendChild(empty);
      return;
    }
    const maxTps = list.reduce((m, g) => Math.max(m, Number(g.medianTps) || 0), 0) || 1;
    const currentId = resolveSpeedCurrentModelId();

    for (const group of list) {
      const row = document.createElement('div');
      row.className = 'ctx-speed-rank-row';
      row.setAttribute('data-rank-id', group.modelExactId);

      const pickWrap = document.createElement('div');
      pickWrap.className = 'ctx-speed-rank-pick';
      const check = document.createElement('input');
      check.type = 'checkbox';
      check.className = 'ctx-speed-rank-check';
      check.checked = speedPkSelection.includes(group.modelExactId);
      check.setAttribute('aria-label', t('speed.rank.colPick'));
      check.addEventListener('change', () => {
        if (check.checked) {
          if (!speedPkSelection.includes(group.modelExactId)) {
            speedPkSelection = [...speedPkSelection, group.modelExactId];
          }
        } else {
          speedPkUserCleared = true;
          speedPkSelection = speedPkSelection.filter(v => v !== group.modelExactId);
        }
        renderSpeedProto();
      });
      const dot = document.createElement('span');
      dot.className = 'ctx-speed-rank-dot';
      const dotIdx = speedPkSelection.indexOf(group.modelExactId);
      dot.style.background = dotIdx >= 0 ? speedSeriesColor(dotIdx) : 'var(--spd-muted)';
      pickWrap.appendChild(check);
      pickWrap.appendChild(dot);
      row.appendChild(pickWrap);

      const modelWrap = document.createElement('div');
      modelWrap.className = 'ctx-speed-rank-model';
      const nameEl = document.createElement('span');
      nameEl.className = 'ctx-speed-rank-name';
      nameEl.textContent = speedDisplayName(group);
      modelWrap.appendChild(nameEl);
      const tags = document.createElement('div');
      tags.className = 'ctx-speed-rank-tags';
      const pushTag = (text, accent) => {
        if (!text) return;
        const tag = document.createElement('span');
        tag.className = accent ? 'ctx-speed-tag ctx-speed-tag-accent' : 'ctx-speed-tag';
        tag.textContent = text;
        tags.appendChild(tag);
      };
      pushTag(group.vendor || '', false);
      if (group.lowSample) pushTag(t('speed.hero.lowSample', { n: group.count }), false);
      if (group.modelExactId === currentId) pushTag(t('speed.rank.current').replace('· ', ''), true);
      modelWrap.appendChild(tags);
      row.appendChild(modelWrap);

      const distWrap = document.createElement('div');
      distWrap.className = 'ctx-speed-rank-dist';
      const bar = document.createElement('div');
      bar.className = 'ctx-speed-rank-bar';
      const fill = document.createElement('div');
      fill.className = 'ctx-speed-rank-bar-fill';
      fill.style.width = `${Math.max(3, Math.round(((Number(group.medianTps) || 0) / maxTps) * 100))}%`;
      fill.style.background = speedSeriesColor(Math.max(0, speedPkSelection.indexOf(group.modelExactId)));
      bar.appendChild(fill);
      const num = document.createElement('span');
      num.className = 'ctx-speed-rank-num';
      num.textContent = Number.isFinite(group.medianTps) ? Number(group.medianTps).toFixed(1) : '—';
      distWrap.appendChild(bar);
      distWrap.appendChild(num);
      row.appendChild(distWrap);

      const metricWrap = document.createElement('div');
      metricWrap.className = 'ctx-speed-rank-metric';
      const tpsText = document.createElement('span');
      tpsText.className = 'ctx-speed-rank-num';
      tpsText.textContent = Number.isFinite(group.medianTps) ? `${Number(group.medianTps).toFixed(1)} tok/s` : '—';
      const ttftText = document.createElement('span');
      ttftText.className = 'ctx-speed-rank-ttft';
      ttftText.textContent = `TTFT ${Number.isFinite(group.medianTtft) ? `${Number(group.medianTtft).toFixed(1)}s` : '—'}`;
      const sampleTag = document.createElement('span');
      sampleTag.className = group.lowSample ? 'ctx-speed-pill-low' : 'ctx-speed-tag';
      sampleTag.textContent = group.lowSample
        ? t('speed.hero.lowSample', { n: group.count })
        : t('speed.hero.samples') + ` ${group.count}`;
      metricWrap.appendChild(tpsText);
      metricWrap.appendChild(ttftText);
      metricWrap.appendChild(sampleTag);
      row.appendChild(metricWrap);

      rowsWrap.appendChild(row);
    }
  }

  function renderSpeedProto() {
    const groups = Array.isArray(lastSpeedGroups) ? lastSpeedGroups : [];
    const byId = new Map(groups.map(group => [group.modelExactId, group]));
    const picked = ensureSpeedPkSelection(groups).map(id => byId.get(id));
    const { series, granularity } = buildSpeedTrend(picked);
    const suffixes = speedTrendLegendSuffixes(groups);
    renderSpeedPkChips(groups);
    renderSpeedPkCards(groups);
    renderSpeedTrendLegend(series, suffixes);
    renderSpeedRankRows(groups);
    renderSpeedMultiSeriesChart(series, granularity, suffixes);
  }

  function resetSpeedFilters() {
    speedRankQuery = '';
    speedRankSort = 'tps';
    speedPkUserCleared = false;
    speedPkSelection = [];
    const search = el('speed-rank-search');
    if (search) search.value = '';
    const sortWrap = el('speed-rank-sort');
    if (sortWrap) {
      for (const btn of Array.from(sortWrap.children || [])) {
        const on = btn.getAttribute?.('data-rank-sort') === 'tps';
        btn.classList?.toggle?.('active', on);
        btn.setAttribute?.('aria-pressed', on ? 'true' : 'false');
      }
    }
    speedRangeDays = '7';
    speedDateRange = null;
    speedOriginFilter = 'all';
    speedMetric = 'tps';
    speedAlgorithm = 'median';
    const dateErrorEl = el('speed-date-error');
    if (dateErrorEl) dateErrorEl.hidden = true;
    const syncSegActive = (map, activeId) => {
      for (const id of Object.keys(map)) {
        const btn = el(id);
        if (!btn) continue;
        const on = id === activeId;
        btn.classList?.toggle?.('active', on);
        btn.setAttribute?.('aria-pressed', on ? 'true' : 'false');
      }
    };
    syncSegActive(SPEED_RANGE_MAP, 'speed-range-7d');
    syncSegActive(SPEED_ORIGIN_MAP, 'speed-origin-all');
    syncSegActive(SPEED_METRIC_MAP, 'speed-metric-tps');
    syncSegActive(SPEED_ALGO_MAP, 'speed-algo-median');
    renderSpeedComparisonTab();
  }

  function exportSpeedCsv() {
    const groups = Array.isArray(lastSpeedGroups) ? lastSpeedGroups : [];
    if (!groups.length) return;
    const header = ['model', 'samples', 'medianTps', 'medianTtft', 'medianDuration', 'medianOutputTokens', 'lowSample'];
    const lines = [header.join(',')].concat(groups.map(g => [
      `"${String(g.productLabel || g.modelExactId || '').replace(/"/g, '""')}"`,
      g.count,
      Number.isFinite(g.medianTps) ? g.medianTps : '',
      Number.isFinite(g.medianTtft) ? g.medianTtft : '',
      Number.isFinite(g.medianDuration) ? g.medianDuration : '',
      Number.isFinite(g.medianOutputTokens) ? g.medianOutputTokens : '',
      g.lowSample ? 'true' : 'false'
    ].join(',')));
    const csv = lines.join('\n');
    try {
      const blob = new Blob([`\uFEFF${csv}`], { type: 'text/csv;charset=utf-8' });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = `speed-${speedRangeDays}d.csv`;
      a.style.display = 'none';
      (document.body || document.documentElement)?.appendChild?.(a);
      a.click?.();
      a.remove?.();
      setTimeout(() => { try { URL.revokeObjectURL(url); } catch { } }, 4000);
    } catch {
      try { void navigator?.clipboard?.writeText?.(csv); } catch { }
    }
    showSpeedToast(t('speed.rank.exportOk', { n: groups.length }));
  }

  function showSpeedToast(text) {
    showTransientActionToast(text, { tone: 'info', durationMs: TRANSIENT_TOAST_TOTAL_MS });
  }

  function renderSpeedComparisonTab() {
    const rangeForm = el('speed-custom-dates');
    if (rangeForm) rangeForm.hidden = speedRangeDays !== 'custom';
    const customButton = el('speed-range-custom');
    if (customButton) setPillActive(customButton, speedRangeDays === 'custom');
    const mergedCalls = mergeAvailableSpeedCalls();
    const bounds = speedRangeDays === 'custom' ? parseSpeedDateRange?.(speedDateRange) : null;
    const groups = typeof summarizeSpeedByModel === 'function'
      ? summarizeSpeedByModel(mergedCalls, {
        days: speedRangeDays,
        calendarDays: true,
        fullHistory: true,
        ...(bounds || {}),
        origin: speedOriginFilter,
        metric: speedMetric,
        cascadeModelConfigs: state.cascadeModelConfigs || state.scan?.cascadeModelConfigs || []
      })
      : [];
    lastSpeedGroups = groups;

    renderSpeedBarChart(groups);

    if (!selectedSpeedExactModelId || !groups.some(g => g.modelExactId === selectedSpeedExactModelId)) {
      selectedSpeedExactModelId = groups[0]?.modelExactId || null;
    }
    const chosenGroup = groups.find(g => g.modelExactId === selectedSpeedExactModelId) || null;
    const speedDropLabel = el('speed-model-dropdown-label');
    if (speedDropLabel) {
      if (chosenGroup) {
        speedDropLabel.textContent = formatProductDisplayWithEffort(chosenGroup.productLabel, chosenGroup.effort);
      } else {
        speedDropLabel.textContent = t('speed.lineNoModel');
      }
    }

    if (!speedModelDropdownCtrl && typeof initDropdownController === 'function' && el('speed-model-dropdown-wrap')) {
      speedModelDropdownCtrl = initDropdownController({
        wrapId: 'speed-model-dropdown-wrap',
        triggerId: 'speed-model-dropdown-trigger',
        labelId: 'speed-model-dropdown-label',
        menuId: 'speed-model-dropdown-menu',
        emptyLabel: () => t('speed.lineNoModel'),
        searchPlaceholder: () => t('dropdown.speedSearch'),
        emptyText: () => t('dropdown.speedEmpty'),
        getSelectedValue: () => selectedSpeedExactModelId || '',
        onSelect: (opt) => {
          const val = opt?.value || '';
          if (!val) return;
          selectedSpeedExactModelId = val;
          renderSpeedComparisonTab();
        },
        getOptions: () => lastSpeedGroups.map(g => {
          return {
            value: g.modelExactId,
            label: formatProductDisplayWithEffort(g.productLabel, g.effort),
            displayRight: t('speed.samples', { n: g.count })
          };
        })
      });
    } else if (speedModelDropdownCtrl && typeof speedModelDropdownCtrl.refresh === 'function') {
      speedModelDropdownCtrl.refresh();
    }

    if (typeof document.createElementNS !== 'function') renderSpeedLineChart(chosenGroup);
    // 原型化 PK 台 / 多系列走势 / 全量排行
    try { renderSpeedProto(); } catch { }
  }

