        var viewTop = hostRect && hostRect.height > 0 ? Math.max(hostRect.top, 0) : 0;
        var viewRight = hostRect && hostRect.width > 0 ? hostRect.right : (typeof window !== 'undefined' ? window.innerWidth : 1200);
