  async function invokeHostInstallPathApi(action, payload = {}) {
    try {
      const reqBody = { action, ...(payload || {}) };
      if (typeof window?.contextMeterAPI?.hostInstallPath === 'function') {
        return await window.contextMeterAPI.hostInstallPath(reqBody);
      }
      if (hasLiveHttpBridge()) {
        return await callLiveHttpRoute('/host-install-path', reqBody);
      }
      return { ok: false, error: 'host_install_path_api_unavailable' };
    } catch (err) {
      return { ok: false, error: err?.message || String(err) };
    }
  }

  async function refreshHostInstallPathStatus() {
    if (isHostInstallPathBusy) return currentHostInstallPathState;
    const res = await invokeHostInstallPathApi('get', {});
    if (res && res.ok) {
      currentHostInstallPathState = res;
      if (!hostInstallPathDirty) {
        hostInstallPathDraft = String(res.customPath || '');
      }
      syncHostSettingsUi();
    }
    return currentHostInstallPathState;
  }

  async function runHostInstallPathAction(action, payload = {}) {
    if (isHostInstallPathBusy) return null;
    isHostInstallPathBusy = true;
    hostInstallPathFeedback = { text: '', tone: 'idle' };
    syncHostSettingsUi();
    try {
      const res = await invokeHostInstallPathApi(action, payload);
      if (action === 'browse') {
        if (res?.ok && !res.cancelled && res.selectedPath) {
          hostInstallPathDraft = String(res.selectedPath);
          hostInstallPathDirty = true;
          if (res.inspection && !res.inspection.ok) {
            hostInstallPathFeedback = { text: t('ns.installPath.saveFail', { reason: res.inspection.reason || res.inspection.error || t('msg.unknownErr') }), tone: 'error' };
          }
        }
        return res;
      }
      if (res?.ok) {
        currentHostInstallPathState = res;
        hostInstallPathDraft = String(res.customPath || '');
        hostInstallPathDirty = false;
        hostInstallPathFeedback = {
          text: action === 'clear' ? t('ns.installPath.clearedOk') : t('ns.installPath.savedOk'),
          tone: 'ok'
        };
        showNativeSettingsToast(hostInstallPathFeedback.text);
        void refreshHostGuardStatus();
      } else {
        hostInstallPathFeedback = {
          text: t('ns.installPath.saveFail', { reason: res?.error || res?.reason || t('msg.unknownErr') }),
          tone: 'error'
        };
      }
      return res;
    } finally {
      isHostInstallPathBusy = false;
      syncHostSettingsUi();
    }
  }

