  function syncRendererTaskQuotaLifecycle(routeId = null) {
    try {
      const tracker = ensureRendererTaskQuotaTracker();
      if (!tracker) return null;
      const cid = String(routeId || state.route || '').trim();
      if (!cid) return null;
      const nowMs = Date.now();
      const isActiveRun = Boolean(state.generating || state.livePendingRequest?.cascadeId === cid);
      const currentTaskId = activeTaskQuotaIdByRoute.get(cid) || null;
      if (isActiveRun) {
        const nextTaskId = currentTaskId || `${cid}::${state.latestCallId || nowMs}`;
        activeTaskQuotaIdByRoute.set(cid, nextTaskId);
        if (typeof tracker.beginTask === 'function') {
          return tracker.beginTask({
            taskId: nextTaskId,
            sessionId: cid,
            accountScopeKey: quotaState?.accountScopeKey || null,
            modelId: state.latest?.model || state.selectedModelId || null,
            nowMs
          });
        }
      } else if (currentTaskId && typeof tracker.getTaskObservation === 'function') {
        const obs = tracker.getTaskObservation(currentTaskId, nowMs);
        if (obs && obs.taskStatus === 'running' && typeof tracker.finishTask === 'function') {
          return tracker.finishTask(currentTaskId, { taskStatus: 'completed', nowMs });
        }
        return obs;
      }
    } catch { }
    return null;
  }

