      const obs = (trackedTaskId && typeof tracker.getTaskObservation === 'function' ? tracker.getTaskObservation(trackedTaskId, Date.now()) : null)
        || (Array.isArray(state.scan?.taskQuotaSnapshots) ? state.scan.taskQuotaSnapshots[0] : null);
      if (!obs) return '';
