  function resolveSessionFourViewsCopy(lang) {
    const raw = String(lang || currentPanelLanguage || 'zh-CN');
    if (raw === 'zh-TW' || /^zh[-_](tw|hk|mo|hant)/i.test(raw)) return SESSION_FOUR_VIEWS_I18N['zh-TW'];
    if (/^en/i.test(raw)) return SESSION_FOUR_VIEWS_I18N.en;
    return SESSION_FOUR_VIEWS_I18N['zh-CN'];
  }

  function normalizeSessionViewTabKey(raw) {
    const k = String(raw || 'chat').trim().toLowerCase();
    if (k === 'trace') return 'trace';
    if (k === 'context') return 'context';
    if (k === 'collab' || k === 'squad') return 'collab';
    return 'chat';
  }

