  function findSessionFourViewsAnchor() {
    if (typeof document === 'undefined' || typeof document.querySelectorAll !== 'function') return null;
    let rawConvViews = [];
    try { rawConvViews = Array.from(document.querySelectorAll('[data-testid="conversation-view"]')); } catch { return null; }
    const convViews = rawConvViews
      .filter((v) => v && v.isConnected && !isNodeInsideAuxOrSystemControls(v));
    if (!convViews.length) return null;
    const convView = convViews.find((v) => v.getAttribute('data-focused') === 'true') || convViews[0];
    const parent = convView.parentElement;
    if (!parent || isNodeInsideAuxOrSystemControls(parent)) return null;
    const headerEl = parent.querySelector?.(':scope > [data-testid="conversation-header"], :scope > .conv-header')
      || (convView.previousElementSibling && !convView.previousElementSibling.hasAttribute?.('data-om-session-tabs') && !convView.previousElementSibling.hasAttribute?.('data-om-session-views-stage')
        ? convView.previousElementSibling
        : null);
    const cascadeAttr = String(convView.getAttribute('data-cascade-id') || '').trim();
    const activeNavItem = document.querySelector?.('.left-nav-item.active[data-session-id]');
    const navSessionId = String(activeNavItem?.getAttribute?.('data-session-id') || '').trim();
    const routeKey = cascadeAttr || navSessionId || String(state.route || convView.getAttribute('data-pane-id') || 'default');
    return { parent, headerEl, convView, routeKey };
  }

  function saveConversationScrollPositions(convView) {
    if (!convView) return;
    sessionViewSavedScrolls.clear();
    const candidates = [convView];
    try {
      const msgEl = convView.querySelector?.('#conv-messages');
      if (msgEl) candidates.push(msgEl);
      for (const node of Array.from(convView.querySelectorAll?.('*') || [])) {
        if (node === msgEl) continue;
        if (node && (node.scrollTop > 0 || node.scrollLeft > 0 || (node.scrollHeight > node.clientHeight + 2))) {
          candidates.push(node);
        }
      }
    } catch { }
    for (const node of candidates) {
      if (!node) continue;
      sessionViewSavedScrolls.set(node, {
        scrollTop: Number(node.scrollTop || 0),
        scrollLeft: Number(node.scrollLeft || 0)
      });
    }
  }

  function restoreConversationScrollPositions(convView) {
    const applyAll = () => {
      for (const [node, pos] of sessionViewSavedScrolls.entries()) {
        if (!node || !node.isConnected) continue;
        try {
          if (typeof pos.scrollTop === 'number') node.scrollTop = pos.scrollTop;
          if (typeof pos.scrollLeft === 'number') node.scrollLeft = pos.scrollLeft;
        } catch { }
      }
    };
    if (convView) {
      try { convView.removeAttribute('data-om-session-chat-hidden'); } catch { }
    }
    if (sessionViewHiddenConvEl && sessionViewHiddenConvEl !== convView) {
      try { sessionViewHiddenConvEl.removeAttribute('data-om-session-chat-hidden'); } catch { }
    }
    sessionViewHiddenConvEl = null;
    applyAll();
    if (!state.disposed && typeof requestAnimationFrame === 'function') {
      const rafId = requestAnimationFrame(() => {
        if (!state.disposed && activeSessionViewTab === 'chat') applyAll();
      });
      activeDisposers.add(() => { try { cancelAnimationFrame?.(rafId); } catch { } });
    }
  }

  function buildSessionFourViewsPayload() {
    const d = state.latest || {};
    const rawTl = state.sessionTimeline || null;
    const calls = Array.isArray(state.sessionCalls) && state.sessionCalls.length
      ? state.sessionCalls
      : (Array.isArray(state.allTurns) ? state.allTurns : []);
    const activeCall = calls.length > 0 ? calls[calls.length - 1] : null;
    const effSession = typeof buildEffectiveSessionForComposition === 'function' ? buildEffectiveSessionForComposition() : null;
    const activeContextTokens = d?.actual ?? d?.contextUsed ?? d?.postCompactEstimate ?? d?.estimate ?? activeCall?.contextWindowTokens ?? activeCall?.contextTokens ?? activeCall?.inputTokens ?? null;
    const limitVal = d?.budget ?? d?.contextLimit ?? d?.serviceLimit ?? null;
    let breakdown = null;
    try {
      if (effSession && typeof buildSessionCompositionBreakdown === 'function') {
        breakdown = buildSessionCompositionBreakdown(effSession, { actual: activeContextTokens, budget: limitVal }, {
          budgetTokens: limitVal
        });
      }
    } catch { }

    // 若 timeline 未单独提供，基于真实 sessionCalls/allTurns 归一化合成只读视图快照（零假数据）
    let derivedTrace = rawTl?.executionTrace || null;
    let derivedTurns = Array.isArray(rawTl?.turns) && rawTl.turns.length ? rawTl.turns : [];
    let derivedFiles = Array.isArray(rawTl?.fileActivity) && rawTl.fileActivity.length
      ? rawTl.fileActivity
      : (Array.isArray(rawTl?.fileOperations) ? rawTl.fileOperations : []);
    let derivedCommands = Array.isArray(rawTl?.commandExecutions) && rawTl.commandExecutions.length
      ? rawTl.commandExecutions
      : (Array.isArray(rawTl?.commands) ? rawTl.commands : []);

    if (calls.length > 0) {
      if (!derivedTrace || !Array.isArray(derivedTrace.nodes) || !derivedTrace.nodes.length) {
        const nodes = [];
        let minStart = Infinity;
        let maxEnd = 0;
        calls.forEach((c, idx) => {
          if (!c) return;
          const turnIdx = Number(c.turnIndex ?? (idx + 1));
          const stepIdx = Number(c.stepIndex ?? (idx + 1));
          const startMs = Number(c.startedAtMs || c.timestamp || (Date.now() - (calls.length - idx) * 10000));
          const durMs = Number(c.durationMs || ((Number(c.durationSec || 0)) * 1000) || 1200);
          const endMs = Number(c.endedAtMs || (startMs + durMs));
          if (startMs < minStart) minStart = startMs;
          if (endMs > maxEnd) maxEnd = endMs;
          if (c.userSummary || c.preview) {
            nodes.push({
              id: `${c.callId || 'c'}-user-${idx}`,
              stepIndex: stepIdx,
              turnIndex: turnIdx,
              category: 'user',
              label: 'user',
              summary: String(c.userSummary || c.preview),
              detail: String(c.userSummary || c.preview),
              status: 'ok',
              startMs,
              endMs: startMs + Math.min(200, Math.round(durMs * 0.1)),
              durationSec: Math.min(0.2, durMs / 10000),
              tokens: Number(c.inputTokens || 0),
              agentRole: 'main'
            });
          }
          nodes.push({
            id: c.callId || `call-${idx}`,
            stepIndex: stepIdx,
            turnIndex: turnIdx,
            category: 'assistant',
            label: c.actualModel || c.model || 'model',
            modelLabel: c.actualModel || c.model || '',
            summary: String(c.assistantSummary || `${c.outputTokens || 0} tok`),
            detail: String(c.assistantSummary || ''),
            outputSummary: String(c.assistantSummary || ''),
            status: c.status === 'error' ? 'error' : 'ok',
            startMs,
            endMs,
            durationSec: Math.round(durMs / 10) / 100,
            tokens: Number(c.outputTokens || 0),
            inputTokens: Number(c.inputTokens || 0),
            outputTokens: Number(c.outputTokens || 0),
            cacheReadTokens: Number(c.cacheReadTokens ?? c.cacheTokens ?? 0),
            agentRole: c.agentRole || 'main'
          });
          if (Array.isArray(c.toolCalls)) {
            c.toolCalls.forEach((tc, ti) => {
              if (!tc) return;
              const tcDurMs = Number(tc.durationMs || 120);
              const tcStart = startMs + Math.min(durMs, (ti + 1) * 150);
              nodes.push({
                id: `${c.callId || 'c'}-tool-${ti}`,
                stepIndex: stepIdx,
                turnIndex: turnIdx,
                category: 'tool',
                label: tc.name || tc.program || 'tool',
                summary: String(tc.command || tc.target || tc.name || 'tool'),
                argsSummary: String(tc.args || tc.command || tc.target || ''),
                outputSummary: String(tc.output || (tc.exitCode != null ? `exit ${tc.exitCode}` : '')),
                detail: String(tc.args || tc.command || ''),
                status: tc.exitCode && tc.exitCode !== 0 ? 'error' : 'ok',
                startMs: tcStart,
                endMs: tcStart + tcDurMs,
                durationSec: Math.round(tcDurMs / 10) / 100,
                tokens: 0,
                agentRole: 'main'
              });
            });
          }
        });
        derivedTrace = {
          nodes,
          totalSpanSec: maxEnd > minStart ? Math.max(0.5, Math.round((maxEnd - minStart) / 10) / 100) : 1
        };
      }

      if (!derivedTurns.length) {
        derivedTurns = calls.map((c, idx) => ({
          turnIndex: Number(c.turnIndex ?? (idx + 1)),
          stepIndex: Number(c.stepIndex ?? (idx + 1)),
          preview: String(c.userSummary || c.preview || ''),
          userSummary: String(c.userSummary || c.preview || ''),
          assistantSummary: String(c.assistantSummary || ''),
          timestamp: Number(c.startedAtMs || c.endedAtMs || c.timestamp || Date.now()),
          inputTokens: Number(c.inputTokens || 0),
          outputTokens: Number(c.outputTokens || 0),
          cacheReadTokens: Number(c.cacheReadTokens ?? c.cacheTokens ?? 0),
          contextTokens: Number(c.contextWindowTokens ?? c.contextTokens ?? c.inputTokens ?? 0),
          contextWindowTokens: Number(c.contextWindowTokens ?? c.contextTokens ?? c.inputTokens ?? 0),
          durationSec: Number(c.durationSec ?? ((Number(c.durationMs || 0)) / 1000)),
          ttftSec: Number(c.ttftSec ?? ((Number(c.ttftMs || 0)) / 1000)),
          tps: c.tps != null ? Number(c.tps) : null,
          model: c.actualModel || c.model || '',
          toolCalls: Array.isArray(c.toolCalls) ? c.toolCalls : [],
          calls: [c]
        }));
      }

      if (!derivedFiles.length) {
        const fList = [];
        for (const c of calls) {
          for (const fa of (Array.isArray(c?.fileActivities) ? c.fileActivities : [])) {
            if (fa) fList.push({ ...fa, turnIndex: c.turnIndex, stepIndex: c.stepIndex, timestamp: c.endedAtMs || c.startedAtMs });
          }
        }
        derivedFiles = fList;
      }

      if (!derivedCommands.length) {
        const cmdList = [];
        for (const c of calls) {
          for (const tc of (Array.isArray(c?.toolCalls) ? c.toolCalls : [])) {
            if (tc && (tc.command || tc.name === 'run_command')) {
              cmdList.push({
                command: tc.command || tc.args || '',
                program: tc.program || String(tc.command || '').trim().split(/\s+/)[0] || 'cmd',
                durationMs: Number(tc.durationMs || 0),
                exitCode: tc.exitCode ?? 0,
                status: tc.exitCode && tc.exitCode !== 0 ? 'failed' : 'ok',
                turnIndex: c.turnIndex,
                stepIndex: c.stepIndex,
                timestamp: c.endedAtMs || c.startedAtMs
              });
            }
          }
        }
        derivedCommands = cmdList;
      }
    }

    const tl = rawTl
      ? {
        ...rawTl,
        executionTrace: derivedTrace || rawTl.executionTrace || null,
        turns: derivedTurns.length ? derivedTurns : (rawTl.turns || []),
        fileActivity: derivedFiles.length ? derivedFiles : (rawTl.fileActivity || []),
        commandExecutions: derivedCommands.length ? derivedCommands : (rawTl.commandExecutions || [])
      }
      : (calls.length
        ? {
          executionTrace: derivedTrace,
          turns: derivedTurns,
          calls,
          fileActivity: derivedFiles,
          commandExecutions: derivedCommands,
          sessionStats: state.sessionStats || null,
          agentCollabHub: null
        }
        : null);

    const modelName = activeCall?.actualModel || activeCall?.model || d?.model || state.scan?.model || '';
    const sessionTitle = String(document.getElementById?.('conv-title')?.textContent || d?.title || state.scan?.title || '').trim();
    const langTag = currentPanelLanguage || 'zh-CN';
    const isLight = isLightWorkspaceThemeNow();
    const baseData = {
      route: state.route || sessionViewsActiveRouteKey || '',
      sessionTitle,
      timeline: tl,
      tl,
      breakdown,
      sessionStats: state.sessionStats || tl?.sessionStats || null,
      sessionCalls: calls,
      calls,
      turns: derivedTurns,
      activeCall,
      latest: d,
      scan: state.scan || null,
      executionTrace: derivedTrace,
      agentCollabHub: tl?.agentCollabHub || tl?.agentFleetSummary || null,
      agentFleetSummary: tl?.agentFleetSummary || tl?.agentCollabHub || null,
      contextEvents: tl?.contextEvents || [],
      fileActivity: derivedFiles,
      commandExecutions: derivedCommands,
      timingSummary: tl?.timingSummary || null,
      cacheSummary: tl?.cacheSummary || null,
      sessionTokenTotals: tl?.sessionTokenTotals || null,
      contextUsed: activeContextTokens,
      contextBudget: limitVal,
      model: modelName,
      modelLabel: modelName,
      version: typeof METER_DISPLAY_VERSION === 'string' ? METER_DISPLAY_VERSION : 'v0.9.3'
    };
    const mergedData = sessionViewsMockDataOverrideForTest
      ? { ...baseData, ...sessionViewsMockDataOverrideForTest }
      : baseData;
    const dataSig = JSON.stringify({
      route: mergedData.route,
      lang: langTag,
      theme: isLight ? 'light' : 'dark',
      callsLen: Array.isArray(mergedData.sessionCalls) ? mergedData.sessionCalls.length : 0,
      traceNodes: Array.isArray(mergedData.executionTrace?.nodes) ? mergedData.executionTrace.nodes.length : 0,
      used: mergedData.contextUsed ?? null,
      budget: mergedData.contextBudget ?? null,
      subagents: Array.isArray(mergedData.agentCollabHub?.subagents) ? mergedData.agentCollabHub.subagents.length : 0,
      hasMock: Boolean(sessionViewsMockDataOverrideForTest)
    });
    const opts = {
      lang: langTag,
      active: activeSessionViewTab !== 'chat',
      theme: isLight ? 'light' : 'dark',
      version: mergedData.version,
      model: mergedData.model,
      modelLabel: mergedData.modelLabel,
      budget: mergedData.contextBudget,
      onOpenSettings: () => { try { hostSettingsCtrl?.openHostSettingsPage?.({ page: 'settings' }); } catch { } },
      onOpenBudget: () => { try { hostSettingsCtrl?.openHostSettingsPage?.({ page: 'settings', section: 'budget' }); } catch { } },
      onOpenContextDetails: () => { try { openDetailedContextView?.({ trigger: 'session-tab' }); } catch { } },
      onRefresh: () => { try { render(); } catch { } }
    };
    return { data: mergedData, opts, dataSig };
  }

  function resolveSessionViewRendererFn(tabKey) {
    const win = typeof window !== 'undefined' ? window : {};
    if (tabKey === 'trace') {
      if (typeof renderExecutionTraceInto === 'function') return renderExecutionTraceInto;
      if (typeof win.renderExecutionTraceInto === 'function') return win.renderExecutionTraceInto;
      if (typeof win.AGExecutionTrace?.renderExecutionTraceInto === 'function') return win.AGExecutionTrace.renderExecutionTraceInto;
    } else if (tabKey === 'context') {
      if (typeof renderContextInspectorInto === 'function') return renderContextInspectorInto;
      if (typeof win.renderContextInspectorInto === 'function') return win.renderContextInspectorInto;
      if (typeof win.AGContextInspector?.renderContextInspectorInto === 'function') return win.AGContextInspector.renderContextInspectorInto;
    } else if (tabKey === 'collab') {
      if (typeof renderAgentCollabInto === 'function') return renderAgentCollabInto;
      if (typeof win.renderAgentCollabInto === 'function') return win.renderAgentCollabInto;
      if (typeof win.AGAgentCollabHub?.renderAgentCollabInto === 'function') return win.AGAgentCollabHub.renderAgentCollabInto;
    }
    return null;
  }

  function renderSessionViewPane(tabKey, { force = false } = {}) {
    if (!['trace', 'context', 'collab'].includes(tabKey)) return null;
    const container = sessionViewContainers[tabKey];
    if (!container) return null;
    const { data, opts, dataSig } = buildSessionFourViewsPayload();
    if (!force && sessionViewRenderedDataSig[tabKey] === dataSig && sessionViewHandles[tabKey]) {
      try { sessionViewHandles[tabKey]?.setActive?.(true); } catch { }
      return sessionViewHandles[tabKey];
    }
    if (sessionViewHandles[tabKey] && typeof sessionViewHandles[tabKey].update === 'function') {
      try {
        sessionViewHandles[tabKey].update(data, { ...opts, active: true });
        sessionViewHandles[tabKey].setActive?.(true);
        sessionViewRenderedDataSig[tabKey] = dataSig;
        return sessionViewHandles[tabKey];
      } catch { }
    }
    try { sessionViewHandles[tabKey]?.cleanup?.(); } catch { }
    sessionViewHandles[tabKey] = null;
    const fn = resolveSessionViewRendererFn(tabKey);
    if (typeof fn === 'function') {
      try {
        const handle = fn(container, data, { ...opts, active: true }) || {};
        sessionViewHandles[tabKey] = handle;
        sessionViewRenderedDataSig[tabKey] = dataSig;
        try { handle.setActive?.(true); } catch { }
        return handle;
      } catch { }
    }
    const copy = resolveSessionFourViewsCopy(opts.lang);
    container.replaceChildren();
    const emptyEl = document.createElement('div');
    emptyEl.className = 'om-st-fallback-empty';
    emptyEl.textContent = copy.emptyView;
    container.appendChild(emptyEl);
    sessionViewRenderedDataSig[tabKey] = dataSig;
    return null;
  }

  function closeSessionTabsMoreMenu() {
    sessionTabsMoreOpen = false;
    if (!sessionTabsHostEl) return;
    const menu = sessionTabsHostEl.querySelector('.om-st-more-menu');
    const btn = sessionTabsHostEl.querySelector('.om-st-more-btn');
    if (menu) menu.hidden = true;
    if (btn) btn.setAttribute('aria-expanded', 'false');
  }

  function syncSessionTabsUiSelection() {
    if (!sessionTabsHostEl) return;
    const copy = resolveSessionFourViewsCopy(currentPanelLanguage);
    const tablist = sessionTabsHostEl.querySelector('.om-st-tablist');
    if (tablist) tablist.setAttribute('aria-label', copy.tabsAria);
    for (const btn of Array.from(sessionTabsHostEl.querySelectorAll('.om-st-tab'))) {
      const k = btn.getAttribute('data-om-tab');
      const sel = k === activeSessionViewTab;
      btn.setAttribute('aria-selected', sel ? 'true' : 'false');
      btn.setAttribute('data-active', sel ? 'true' : 'false');
      btn.setAttribute('tabindex', sel ? '0' : '-1');
      if (k && copy[k]) btn.textContent = copy[k];
    }
    const moreBtn = sessionTabsHostEl.querySelector('.om-st-more-btn');
    if (moreBtn) {
      moreBtn.setAttribute('aria-label', copy.moreAria);
      moreBtn.title = copy.moreAria;
    }
    const mRef = sessionTabsHostEl.querySelector('[data-om-more-action="refresh"]');
    const mDet = sessionTabsHostEl.querySelector('[data-om-more-action="details"]');
    const mSet = sessionTabsHostEl.querySelector('[data-om-more-action="settings"]');
    if (mRef) mRef.textContent = copy.menuRefresh;
    if (mDet) mDet.textContent = copy.menuDetails;
    if (mSet) mSet.textContent = copy.menuSettings;
  }

  function switchSessionViewTab(nextTabRaw, opts = {}) {
    const nextTab = normalizeSessionViewTabKey(nextTabRaw);
    const prevTab = activeSessionViewTab;
    closeSessionTabsMoreMenu();
    const anchor = findSessionFourViewsAnchor();
    if (!sessionFourViewsEnabled) {
      activeSessionViewTab = 'chat';
      restoreConversationScrollPositions(anchor?.convView || sessionViewHiddenConvEl);
      return { tab: 'chat', mounted: false };
    }
    if (prevTab !== 'chat' && prevTab !== nextTab) {
      try { sessionViewHandles[prevTab]?.setActive?.(false); } catch { }
    }
    if (prevTab === 'chat' && nextTab !== 'chat' && anchor?.convView) {
      saveConversationScrollPositions(anchor.convView);
    }
    activeSessionViewTab = nextTab;
    syncSessionTabsUiSelection();
    if (nextTab === 'chat') {
      if (sessionViewsStageEl) sessionViewsStageEl.hidden = true;
      for (const k of ['trace', 'context', 'collab']) {
        if (sessionViewContainers[k]) sessionViewContainers[k].hidden = true;
      }
      restoreConversationScrollPositions(anchor?.convView || sessionViewHiddenConvEl);
    } else {
      if (anchor?.convView) {
        sessionViewHiddenConvEl = anchor.convView;
        anchor.convView.setAttribute('data-om-session-chat-hidden', 'true');
      }
      if (sessionViewsStageEl) sessionViewsStageEl.hidden = false;
      for (const k of ['trace', 'context', 'collab']) {
        if (sessionViewContainers[k]) sessionViewContainers[k].hidden = k !== nextTab;
      }
      renderSessionViewPane(nextTab, { force: Boolean(opts.forceRender) });
    }
    return getSessionFourViewsState();
  }

  function resetSessionViewsForConversationSwitch(nextRouteKey) {
    const anchor = findSessionFourViewsAnchor();
    for (const k of ['trace', 'context', 'collab']) {
      try { sessionViewHandles[k]?.setActive?.(false); } catch { }
      try { sessionViewHandles[k]?.cleanup?.(); } catch { }
      sessionViewHandles[k] = null;
      sessionViewRenderedDataSig[k] = '';
      try { sessionViewContainers[k]?.replaceChildren?.(); } catch { }
      if (sessionViewContainers[k]) sessionViewContainers[k].hidden = true;
    }
    if (sessionViewsStageEl) sessionViewsStageEl.hidden = true;
    activeSessionViewTab = 'chat';
    sessionViewsActiveRouteKey = String(nextRouteKey || '');
    sessionViewSavedScrolls.clear();
    if (anchor?.convView) {
      try { anchor.convView.removeAttribute('data-om-session-chat-hidden'); } catch { }
    }
    if (sessionViewHiddenConvEl) {
      try { sessionViewHiddenConvEl.removeAttribute('data-om-session-chat-hidden'); } catch { }
      sessionViewHiddenConvEl = null;
    }
    syncSessionTabsUiSelection();
  }

  function unmountSessionFourViews() {
    const anchor = findSessionFourViewsAnchor();
    for (const k of ['trace', 'context', 'collab']) {
      try { sessionViewHandles[k]?.setActive?.(false); } catch { }
      try { sessionViewHandles[k]?.cleanup?.(); } catch { }
      sessionViewHandles[k] = null;
      sessionViewRenderedDataSig[k] = '';
      sessionViewContainers[k] = null;
    }
    activeSessionViewTab = 'chat';
    sessionTabsMoreOpen = false;
    restoreConversationScrollPositions(anchor?.convView || sessionViewHiddenConvEl);
    sessionViewSavedScrolls.clear();
    try { sessionTabsHostEl?.remove?.(); } catch { }
    sessionTabsHostEl = null;
    try { sessionViewsStageEl?.remove?.(); } catch { }
    sessionViewsStageEl = null;
    try {
      if (typeof document !== 'undefined') {
        for (const n of Array.from(document.querySelectorAll('[data-om-session-tabs], [data-om-session-views-stage]'))) {
          n.remove?.();
        }
        for (const h of Array.from(document.querySelectorAll('[data-om-session-chat-hidden]'))) {
          h.removeAttribute?.('data-om-session-chat-hidden');
        }
      }
    } catch { }
  }

  function setSessionFourViewsEnabled(enabled, opts = {}) {
    const next = Boolean(enabled);
    sessionFourViewsEnabled = next;
    try {
      if (typeof localStorage !== 'undefined') localStorage.setItem('ag_session_four_views_enabled', next ? 'true' : 'false');
    } catch { }
    if (!next) {
      unmountSessionFourViews();
    } else {
      syncSessionFourViewsHost();
    }
    try { renderContextSettingsUI?.(); } catch { }
    try { hostSettingsCtrl?.sync?.(); } catch { }
    if (opts.persist !== false && (typeof window?.contextMeterAPI?.saveSettings === 'function' || hasLiveHttpBridge())) {
      void saveSettingsPayloadBridge({
        sessionFourViewsEnabled: next,
        uiPreferences: { sessionFourViewsEnabled: next }
      });
    }
    return sessionFourViewsEnabled;
  }

  function syncSessionFourViewsHost() {
    if (!sessionFourViewsEnabled || state.disposed || isHostMarketplaceActive()) {
      unmountSessionFourViews();
      return;
    }
    const anchor = findSessionFourViewsAnchor();
    if (!anchor || !anchor.parent || !anchor.convView) return;

    ensureSessionViewsHostStyle();

    if (!sessionTabsHostEl) {
      try {
        for (const stale of Array.from(document.querySelectorAll('[data-om-session-tabs], [data-om-session-views-stage]'))) {
          stale.remove?.();
        }
      } catch { }
      const copy = resolveSessionFourViewsCopy(currentPanelLanguage);
      const bar = document.createElement('div');
      bar.id = 'ag-om-session-tabs';
      bar.setAttribute('data-om-session-tabs', 'true');
      bar.setAttribute('data-ag-ws-owned', 'true');

      const tablist = document.createElement('div');
      tablist.className = 'om-st-tablist';
      tablist.setAttribute('role', 'tablist');
      tablist.setAttribute('aria-label', copy.tabsAria);

      const tabDefs = ['chat', 'trace', 'context', 'collab'];
      for (const k of tabDefs) {
        const btn = document.createElement('button');
        btn.type = 'button';
        btn.className = 'om-st-tab';
        btn.setAttribute('role', 'tab');
        btn.setAttribute('data-om-tab', k);
        btn.setAttribute('data-view-key', k);
        btn.setAttribute('aria-selected', k === activeSessionViewTab ? 'true' : 'false');
        btn.setAttribute('data-active', k === activeSessionViewTab ? 'true' : 'false');
        btn.setAttribute('tabindex', k === activeSessionViewTab ? '0' : '-1');
        btn.textContent = copy[k];
        btn.addEventListener('click', (ev) => {
          ev.stopPropagation?.();
          switchSessionViewTab(k);
        });
        tablist.appendChild(btn);
      }

      tablist.addEventListener('keydown', (ev) => {
        if (ev.key !== 'ArrowRight' && ev.key !== 'ArrowLeft') return;
        ev.preventDefault?.();
        const curIdx = tabDefs.indexOf(activeSessionViewTab);
        const nextIdx = (curIdx + (ev.key === 'ArrowRight' ? 1 : -1) + tabDefs.length) % tabDefs.length;
        switchSessionViewTab(tabDefs[nextIdx]);
        tablist.querySelector?.(`[data-om-tab="${tabDefs[nextIdx]}"]`)?.focus?.();
      });

      const moreWrap = document.createElement('div');
      moreWrap.className = 'om-st-more-wrap';
      const moreBtn = document.createElement('button');
      moreBtn.type = 'button';
      moreBtn.className = 'om-st-more-btn';
      moreBtn.setAttribute('data-om-tab-more', 'true');
      moreBtn.setAttribute('aria-haspopup', 'menu');
      moreBtn.setAttribute('aria-expanded', 'false');
      moreBtn.setAttribute('aria-label', copy.moreAria);
      moreBtn.title = copy.moreAria;
      moreBtn.textContent = '…';

      const moreMenu = document.createElement('div');
      moreMenu.className = 'om-st-more-menu';
      moreMenu.setAttribute('role', 'menu');
      moreMenu.hidden = true;
      const menuSpecs = [
        ['refresh', copy.menuRefresh, () => {
          if (activeSessionViewTab !== 'chat') renderSessionViewPane(activeSessionViewTab, { force: true });
          else render();
        }],
        ['details', copy.menuDetails, () => { openDetailedContextView?.({ trigger: 'session-tab-more' }); }],
        ['settings', copy.menuSettings, () => { hostSettingsCtrl?.openHostSettingsPage?.({ page: 'settings' }); }]
      ];
      for (const [act, label, handler] of menuSpecs) {
        const item = document.createElement('button');
        item.type = 'button';
        item.className = 'om-st-more-item';
        item.setAttribute('role', 'menuitem');
        item.setAttribute('data-om-more-action', act);
        item.textContent = label;
        item.addEventListener('click', (ev) => {
          ev.stopPropagation?.();
          closeSessionTabsMoreMenu();
          try { handler(); } catch { }
        });
        moreMenu.appendChild(item);
      }
      moreBtn.addEventListener('click', (ev) => {
        ev.stopPropagation?.();
        sessionTabsMoreOpen = !sessionTabsMoreOpen;
        moreMenu.hidden = !sessionTabsMoreOpen;
        moreBtn.setAttribute('aria-expanded', sessionTabsMoreOpen ? 'true' : 'false');
      });
      moreWrap.appendChild(moreBtn);
      moreWrap.appendChild(moreMenu);
      bar.appendChild(tablist);
      bar.appendChild(moreWrap);
      sessionTabsHostEl = bar;

      const stage = document.createElement('div');
      stage.id = 'ag-om-session-views-stage';
      stage.setAttribute('data-om-session-views-stage', 'true');
      stage.setAttribute('data-ag-ws-owned', 'true');
      stage.hidden = true;
      for (const k of ['trace', 'context', 'collab']) {
        const pane = document.createElement('div');
        pane.id = `ag-om-session-view-${k}`;
        pane.setAttribute('data-om-session-view', k);
        pane.hidden = true;
        stage.appendChild(pane);
        sessionViewContainers[k] = pane;
      }
      sessionViewsStageEl = stage;

      if (!sessionViewsGlobalListenersBound && typeof document !== 'undefined') {
        sessionViewsGlobalListenersBound = true;
        const onDocClick = (ev) => {
          if (sessionTabsMoreOpen && sessionTabsHostEl && !sessionTabsHostEl.contains?.(ev?.target)) {
            closeSessionTabsMoreMenu();
          }
          const navBtn = ev?.target?.closest?.('.left-nav-item[data-session-id], [data-testid="new-chat-button"]');
          if (navBtn && sessionFourViewsEnabled && !state.disposed) {
            const nextSid = String(navBtn.getAttribute?.('data-session-id') || '').trim();
            if (nextSid && nextSid !== sessionViewsActiveRouteKey) {
              resetSessionViewsForConversationSwitch(nextSid);
            } else {
              setTimeout(() => { if (!state.disposed) syncSessionFourViewsHost(); }, 40);
            }
          }
        };
        const onDocKey = (ev) => {
          if (ev?.key === 'Escape' && sessionTabsMoreOpen) closeSessionTabsMoreMenu();
        };
        document.addEventListener('click', onDocClick, true);
        document.addEventListener('keydown', onDocKey);
        const cleanupListeners = () => {
          document.removeEventListener('click', onDocClick, true);
          document.removeEventListener('keydown', onDocKey);
          sessionViewsGlobalListenersBound = false;
        };
        activeDisposers.add(cleanupListeners);
        earlyDisposeHooks.push(cleanupListeners);
      }
    }

    // 锚定位置：会话标题正下方、消息列表（conversation-view）正上方
    if (sessionTabsHostEl.parentElement !== anchor.parent || sessionTabsHostEl.nextSibling !== sessionViewsStageEl) {
      try {
        anchor.parent.insertBefore(sessionTabsHostEl, anchor.convView);
      } catch { }
    }
    if (sessionViewsStageEl && (sessionViewsStageEl.parentElement !== anchor.parent || sessionViewsStageEl.nextSibling !== anchor.convView)) {
      try {
        anchor.parent.insertBefore(sessionViewsStageEl, anchor.convView);
      } catch { }
    }

    if (sessionViewsActiveRouteKey && anchor.routeKey && anchor.routeKey !== sessionViewsActiveRouteKey) {
      resetSessionViewsForConversationSwitch(anchor.routeKey);
    } else if (!sessionViewsActiveRouteKey) {
      sessionViewsActiveRouteKey = anchor.routeKey || 'default';
    }

    syncHostSettingsThemeAttrs?.();
    syncSessionTabsUiSelection();
    if (activeSessionViewTab !== 'chat') {
      renderSessionViewPane(activeSessionViewTab, { force: false });
    }
  }

  function getSessionFourViewsState() {
    const anchor = findSessionFourViewsAnchor();
    const convView = anchor?.convView || null;
    const msgEl = convView?.querySelector?.('#conv-messages') || null;
    return {
      enabled: sessionFourViewsEnabled,
      mounted: Boolean(sessionTabsHostEl && sessionTabsHostEl.isConnected),
      activeTab: activeSessionViewTab,
      routeKey: sessionViewsActiveRouteKey,
      tabsConnected: Boolean(sessionTabsHostEl && sessionTabsHostEl.isConnected),
      stageVisible: Boolean(sessionViewsStageEl && !sessionViewsStageEl.hidden),
      chatHidden: Boolean(convView && convView.getAttribute('data-om-session-chat-hidden') === 'true'),
      chatScrollTop: msgEl ? Number(msgEl.scrollTop || 0) : null,
      renderedTabs: Object.keys(sessionViewRenderedDataSig).filter((k) => Boolean(sessionViewRenderedDataSig[k]))
    };
  }

  function simulateConversationSwitchForTest(nextSessionId, opts = {}) {
    const nextId = String(nextSessionId || `session-${Date.now()}`);
    const anchor = findSessionFourViewsAnchor();
    if (anchor?.convView) {
      anchor.convView.setAttribute('data-cascade-id', nextId);
    }
    if (opts.title) {
      const titleEl = document.getElementById('conv-title') || anchor?.headerEl?.querySelector?.('.conv-title');
      if (titleEl) titleEl.textContent = String(opts.title);
    }
    state.route = nextId;
    resetSessionViewsForConversationSwitch(nextId);
    syncSessionFourViewsHost();
    return getSessionFourViewsState();
  }

  ensureRendererTaskQuotaTracker();
  syncReqSortDropdownMount();
  syncInsightsAndOrchestratorViews();
  function updateRingAndBubble(d, session, pct, danger, stale, incomplete, dispArg, isCompactingNow) {
    const ringFill = el('ring-fill');
    const tipTitle = el('ctx-tip-title');
    const tipPct = el('ctx-tip-pct');
    const tipDetail = el('ctx-tip-detail');

    // 区分常态颜色与高占用告警状态
    let occupancy = 'normal';
    if (danger || (pct != null && pct >= 90)) {
      occupancy = 'danger';
    } else if ((pct != null && pct >= 75) || stale) {
      occupancy = 'warn';
    }
    host.setAttribute('data-occupancy', occupancy);

    // 1. 圆环进度与未知容量状态表达（未知容量绝不画成 0% 或 100%）
    if (ringFill) {
      if (d?.exceeded) {
        ringFill.setAttribute('data-ring-state', 'exceeded');
        ringFill.setAttribute('stroke-dasharray', `${RING_CIRCUMFERENCE.toFixed(2)} ${RING_CIRCUMFERENCE.toFixed(2)}`);
        ringFill.style.opacity = '1';
      } else if (pct != null) {
        ringFill.setAttribute('data-ring-state', 'determinate');
        if (pct <= 0) {
          ringFill.setAttribute('stroke-dasharray', `0 ${RING_CIRCUMFERENCE.toFixed(2)}`);
          ringFill.style.opacity = '0';
        } else {
          const arcLen = Math.max(1.8, (Math.min(100, pct) / 100) * RING_CIRCUMFERENCE);
          ringFill.setAttribute('stroke-dasharray', `${arcLen.toFixed(2)} ${RING_CIRCUMFERENCE.toFixed(2)}`);
          ringFill.style.opacity = '1';
        }
      } else {
        // 容量未知 / 仅估算 / 尚未就绪：使用均匀虚线环段表示非确定比例，不画成 0% 空环或 100% 满环
        ringFill.setAttribute('data-ring-state', d?.estimated ? 'estimated' : 'unknown');
        ringFill.setAttribute('stroke-dasharray', '3.2 4.97');
        ringFill.style.opacity = '0.55';
      }
    }

    // 同步悬浮圆球实时状态机与进度环
    if (typeof syncFloatingOrbState === 'function') syncFloatingOrbState();

    // 2. 悬停信息气泡三层文案（标题 — 使用比例 — 用量与容量）
    if (!tipTitle || !tipPct || !tipDetail) return;

    const disp = dispArg || resolveDisplayStatus(d, session);
    if (disp.isError || disp.kind === 'canceled') {
      tipTitle.textContent = disp.tipTitle;
      tipPct.textContent = disp.tipPct;
      tipDetail.textContent = disp.tipDetail;
    } else if (isCompactingNow) {
      tipTitle.textContent = t('tip.title.compacting');
      tipPct.textContent = t('tip.pct.compacting');
      if (d?.actual != null && d?.budget) {
        tipDetail.textContent = t('tip.detail.usedOfBudget', { used: fmtBubbleToken(d.actual), budget: fmtBubbleToken(d.budget), inc: '' });
      } else if (d?.compacted && d?.postCompactEstimate != null && d?.budget) {
        tipDetail.textContent = t('tip.detail.compacted', { used: fmtBubbleToken(d.postCompactEstimate), budget: fmtBubbleToken(d.budget) });
      } else {
        tipDetail.textContent = t('tip.detail.waitBg');
      }
    } else if (stale && d?.actual != null && d?.budget) {
      const usedRound = Math.min(100, Math.max(0, Math.round((d.actual / d.budget) * 100)));
      const remRound = Math.max(0, 100 - usedRound);
      tipTitle.textContent = t('tip.title.stale');
      tipPct.textContent = t('tip.pct.staleVal', { used: usedRound, rem: remRound });
      tipDetail.textContent = t('tip.detail.usedOfBudget', { used: fmtBubbleToken(d.actual), budget: fmtBubbleToken(d.budget), inc: '' });
    } else if (stale) {
      tipTitle.textContent = t('tip.title.stale');
      tipPct.textContent = t('tip.pct.staleUnknown');
      tipDetail.textContent = session?.total
        ? t('tip.detail.sessionEst', { low: fmtBubbleToken(session.total.low), high: fmtBubbleToken(session.total.high) })
        : t('tip.detail.waitBg');
    } else if (d?.compacted && d?.postCompactEstimate != null && d?.budget) {
      const rawPct = pct != null ? pct : (d.postCompactEstimate / d.budget) * 100;
      const usedRound = rawPct > 0 && rawPct < 1 ? 1 : Math.min(100, Math.max(0, Math.round(rawPct)));
      const remRound = Math.max(0, 100 - usedRound);
      tipTitle.textContent = t('tip.title.compacted');
      tipPct.textContent = t('tip.pct.compacted', { used: usedRound, rem: remRound });
      tipDetail.textContent = t('tip.detail.compacted', {
        used: fmtBubbleToken(d.postCompactEstimate),
        budget: fmtBubbleToken(d.budget)
      });
    } else if (d?.compacted && d?.postCompactEstimate != null && !d?.budget) {
      tipTitle.textContent = t('tip.title.compacted');
      tipPct.textContent = t('tip.pct.noBudget');
      tipDetail.textContent = t('tip.detail.compactedNoBudget', { used: fmtBubbleToken(d.postCompactEstimate) });
    } else if (d?.actual != null && d?.budget) {
      const rawPct = pct != null ? pct : (d.actual / d.budget) * 100;
      const usedRound = rawPct > 0 && rawPct < 1 ? 1 : Math.min(100, Math.max(0, Math.round(rawPct)));
      const remRound = Math.max(0, 100 - usedRound);
      if (rawPct >= 90) {
        tipTitle.textContent = t('tip.title.high90');
        tipPct.textContent = t('tip.pct.high90', { used: usedRound, rem: remRound });
      } else if (rawPct >= 75) {
        tipTitle.textContent = t('tip.title.high75');
        tipPct.textContent = t('tip.pct.high75', { used: usedRound, rem: remRound });
      } else {
        tipTitle.textContent = t('tip.title.normal');
        tipPct.textContent = t('tip.pct.normal', { used: usedRound, rem: remRound });
      }
      tipDetail.textContent = t('tip.detail.usedOfBudget', {
        used: fmtBubbleToken(d.actual),
        budget: fmtBubbleToken(d.budget),
        inc: incomplete ? t('tip.detail.incSuffix') : ''
      });
    } else if (d?.actual != null && !d?.budget) {
      tipTitle.textContent = t('tip.title.normal');
      tipPct.textContent = t('tip.pct.noBudget');
      tipDetail.textContent = t('tip.detail.usedNoBudget', { used: fmtBubbleToken(d.actual) });
    } else if (d?.estimated || d?.estimate != null) {
      tipTitle.textContent = t('tip.title.est');
      tipPct.textContent = t('tip.pct.estOnly');
      const budgetPart = d.budget ? t('tip.detail.estBudgetPart', { budget: fmtBubbleToken(d.budget) }) : t('tip.detail.estNoBudgetPart');
      tipDetail.textContent = t('tip.detail.estUsed', { used: fmtBubbleToken(d.estimate), budget: budgetPart });
    } else if (session?.total) {
      tipTitle.textContent = t('tip.title.est');
      tipPct.textContent = t('tip.pct.waitStats');
      tipDetail.textContent = t('tip.detail.sessionCum', { low: fmtBubbleToken(session.total.low), high: fmtBubbleToken(session.total.high) });
    } else {
      tipTitle.textContent = t('tip.title.normal');
      tipPct.textContent = t('tip.pct.notReady');
      tipDetail.textContent = t('tip.detail.readingSession');
    }

    if (state.tooltipOpen) positionContextTooltip();
  }

  function stopLiveWaitTickTimer() {
    if (state.liveWaitTickTimer) {
      clearInterval(state.liveWaitTickTimer);
      state.liveWaitTickTimer = null;
    }
  }

  function clearLivePendingRequestWait() {
    state.livePendingRequest = null;
    stopLiveWaitTickTimer();
    if (!state.disposed && typeof syncFloatingOrbState === 'function') syncFloatingOrbState();
  }
  earlyDisposeHooks.push(clearLivePendingRequestWait);

  function resolveSpeedEvaluationInput() {
    if (state.speedOverrideForTest && typeof state.speedOverrideForTest === 'object') {
      return state.speedOverrideForTest;
    }
    const isRemoteSession = Boolean(
      state.scan?.session?.isRemote === true ||
      state.latest?.isRemote === true ||
      state.latest?.status === 'remote_unavailable' ||
      /remote|cloud/i.test(String(state.scan?.session?.locationKind || ''))
    );
    const hasLocalSpeedData = Boolean(
      state.latest?.speed?.ttft != null ||
      state.latest?.speed?.duration != null ||
      state.latest?.speed?.streamingTps != null ||
      state.latest?.speed?.tps != null ||
      (resolveLatestSessionCallRecord() && (
        resolveLatestSessionCallRecord().ttftSec != null ||
        resolveLatestSessionCallRecord().durationSec != null ||
        resolveLatestSessionCallRecord().outputTokens > 0
      ))
    );
    if (isRemoteSession && !hasLocalSpeedData) {
      if (state.livePendingRequest && state.route && state.livePendingRequest.cascadeId === state.route) {
        state.livePendingRequest = null;
        stopLiveWaitTickTimer();
      }
      return {
        phase: 'remote_unavailable',
        status: 'remote_unavailable',
        outcomeStatus: 'remote_unavailable',
        isRemote: true
      };
    }
    if (state.livePendingRequest && state.route && state.livePendingRequest.cascadeId === state.route) {
      if (state.livePendingRequest.stage === 'queued') {
        return {
          phase: 'queued',
          status: 'queued',
          outcomeStatus: 'queued',
          elapsedSec: null
        };
      }
      const refDisp = Number(state.livePendingRequest.dispatchedAtMs || state.livePendingRequest.startedAtMs || 0);
      const elapsedSec = refDisp > 0 ? Math.max(0, (Date.now() - refDisp) / 1000) : 0;
      return {
        phase: 'waiting',
        status: 'waiting',
        elapsedSec
      };
    }
    const d = state.latest;
    if (!d) return { phase: 'idle', status: 'idle' };
    const latestRec = resolveLatestSessionCallRecord();
    const sameActiveCall = latestRec && (!d.speed || !latestRec.outputTokens || Math.abs(Number(latestRec.outputTokens) - Number(d.speed?.outputTokens || 0)) <= 50 || latestRec.status === 'streaming');
    const trackedSamples = (latestRec && state.streamSampleTracker?.byCallId?.get?.(latestRec.callId)) || null;

    if (d.status === 'canceled' || d.errorClassification?.kind === 'canceled') {
      return {
        phase: 'canceled',
        status: 'canceled',
        outcomeStatus: 'canceled',
        ttftSec: d.speed?.ttft ?? null,
        totalDurationSec: d.speed?.duration ?? null,
        outputTokens: d.speed?.outputTokens ?? null,
        error: d.error || ''
      };
    }
    if (d.exceeded || d.network || d.error || ['failed', 'quota_exhausted', 'rate_limited', 'auth_error', 'service_unavailable'].includes(d.status)) {
      return {
        phase: 'failed',
        status: d.status || 'failed',
        outcomeStatus: d.status || 'failed',
        ttftSec: d.speed?.ttft ?? null,
        totalDurationSec: d.speed?.duration ?? null,
        outputTokens: d.speed?.outputTokens ?? null,
        error: d.error || ''
      };
    }
    if (latestRec && latestRec.status === 'streaming' && latestRec.outputTokens > 0) {
      return {
        phase: 'streaming',
        status: 'streaming',
        ttftSec: latestRec.ttftSec ?? d.speed?.ttft ?? null,
        streamingSec: latestRec.streamingSec ?? d.speed?.streamingSec ?? trackedSamples?.elapsedStreamSec ?? null,
        totalDurationSec: latestRec.durationSec ?? d.speed?.duration ?? null,
        streamSpeed: latestRec.streamingTps ?? d.speed?.streamingTps ?? null,
        overallTps: latestRec.tps ?? d.speed?.tps ?? null,
        outputTokens: latestRec.outputTokens ?? d.speed?.outputTokens ?? 0,
        totalInputTokens: latestRec.totalInputTokens ?? d.input ?? null,
        chunkCount: trackedSamples?.chunks ?? latestRec.chunkCount ?? null,
        chunkIntervalsMs: trackedSamples?.intervalsMs ?? latestRec.chunkIntervalsMs ?? null
      };
    }
    if (d.speed) {
      return {
        phase: 'final',
        status: 'final',
        ttftSec: d.speed.ttft ?? null,
        streamingSec: d.speed.streamingSec ?? null,
        totalDurationSec: d.speed.duration ?? null,
        streamSpeed: d.speed.streamingTps ?? d.speed.streamSpeed ?? null,
        overallTps: d.speed.tps ?? null,
        outputTokens: d.speed.outputTokens ?? null,
        totalInputTokens: d.speed.totalInputTokens ?? d.input ?? null,
        chunkCount: (sameActiveCall && trackedSamples?.chunks) || (sameActiveCall && latestRec?.chunkCount) || null,
        chunkIntervalsMs: (sameActiveCall && trackedSamples?.intervalsMs) || (sameActiveCall && latestRec?.chunkIntervalsMs) || null
      };
    }
    if (latestRec && (latestRec.ttftSec != null || latestRec.durationSec != null || latestRec.outputTokens > 0)) {
      return {
        phase: latestRec.status === 'streaming' ? 'streaming' : 'final',
        status: latestRec.status,
        ttftSec: latestRec.ttftSec ?? null,
        streamingSec: latestRec.streamingSec ?? null,
        totalDurationSec: latestRec.durationSec ?? null,
        streamSpeed: latestRec.streamingTps ?? null,
        overallTps: latestRec.tps ?? null,
        outputTokens: latestRec.outputTokens ?? null,
        totalInputTokens: latestRec.totalInputTokens ?? null,
        chunkCount: trackedSamples?.chunks ?? latestRec.chunkCount ?? null,
        chunkIntervalsMs: trackedSamples?.intervalsMs ?? latestRec.chunkIntervalsMs ?? null
      };
    }
    return { phase: 'idle', status: 'idle' };
  }

  function updateLiveSpeedTracker(routeId, row, summary, callInfo) {
    if (!routeId || !row || !summary?.speed) {
      state.liveSpeed = null;
      return { isActivelyStreaming: false };
    }
    const cm = row.chatModel || {};
    const sp = summary.speed;
    const callKey = callInfo?.callId || cm.usage?.responseId || String(row.stepIndices?.[0] ?? row.stepIndex ?? 'latest');
    const curOut = Number(sp.outputTokens || 0);
    const curStreamSec = sp.streamingSec != null ? Number(sp.streamingSec) : null;
    const explicitStreaming = Boolean(row.isStreaming === true || row.status === 'streaming');
    const explicitFinal = Boolean(row.status === 'final' || row.status === 'completed' || cm.finishReason || row.finishReason || row.done === true);

    const prev = state.liveSpeed && state.liveSpeed.routeId === routeId && state.liveSpeed.callKey === callKey
      ? state.liveSpeed
      : null;
    const dOut = prev ? (curOut - prev.prevOut) : 0;
    const dStream = (prev && curStreamSec != null && prev.prevStreamSec != null) ? (curStreamSec - prev.prevStreamSec) : 0;
    const isGrowing = dOut > 0 || dStream > 0;

    let emaTps = prev ? prev.emaTps : null;
    if (sp.phase === 'warming') {
      emaTps = null;
    } else if (!explicitFinal && isGrowing && dStream >= 0.25 && dOut >= 4) {
      const instTps = dOut / dStream;
      const anchor = sp.streamingTps || emaTps || instTps;
      const clamped = anchor > 0 ? Math.min(Math.max(instTps, anchor * 0.35), anchor * 2.5) : instTps;
      const base = emaTps ?? sp.streamingTps ?? clamped;
      emaTps = Number((base * 0.55 + clamped * 0.45).toFixed(1));
    } else if (explicitFinal || (!explicitStreaming && prev && !isGrowing)) {
      emaTps = null;
    }

    const isActivelyStreaming = Boolean(
      !explicitFinal && (explicitStreaming || sp.phase === 'warming' || isGrowing)
    );
    state.liveSpeed = {
      routeId,
      callKey,
      prevOut: curOut,
      prevStreamSec: curStreamSec,
      emaTps,
      isActivelyStreaming
    };
    return { isActivelyStreaming };
  }

  function applyElv91PillTone(badgeEl, evalRes) {
    if (!badgeEl || !evalRes?.badge) return;
    const sev = evalRes.badge.severity || 'neutral';
    const cls = (sev === 'good' || sev === 'fast' || sev === 'rapid' || sev === 'epic')
      ? 'pill-good'
      : (sev === 'warn' ? 'pill-warn' : ((sev === 'danger' || sev === 'critical') ? 'pill-danger' : 'pill-muted'));
    badgeEl.className = `key-pill ${cls}`;
    badgeEl.style.color = evalRes.badge.color || '';
    badgeEl.textContent = `${evalRes.badge.glyph ? evalRes.badge.glyph + ' ' : ''}${evalRes.badge.text}`;
  }

  function collectSessionCallsForSpeed() {
    const merged = new Map();
    const addList = (arr) => {
      if (!Array.isArray(arr)) return;
      for (const c of arr) {
        if (!c || typeof c !== 'object') continue;
        const k = c.callId || `__anon_${merged.size}`;
        const prev = merged.get(k);
        merged.set(k, prev ? { ...prev, ...c } : c);
      }
    };
    addList(state.scan?.recentGeneratorCalls);
    if (state.scan?.latestCallRecord) addList([state.scan.latestCallRecord]);
    addList(state.sessionCalls);
    return Array.from(merged.values());
  }

  function getSessionAverageSpeed(evalRes = null) {
    if (typeof summarizeSessionSpeed !== 'function') return null;
    const isMock = Boolean(state.speedOverrideForTest && typeof state.speedOverrideForTest === 'object');
    const sp = state.latest?.speed || null;
    const fb = evalRes && (evalRes.streamSpeed != null || evalRes.overallTps != null)
      ? {
        streamSpeed: evalRes.streamSpeed,
        overallTps: evalRes.overallTps,
        outputTokens: evalRes.outputTokens,
        totalDurationSec: sp?.duration ?? null,
        streamingSec: sp?.streamingSec ?? null,
        isSampleSparse: Boolean(evalRes.isSampleSparse)
      }
      : sp;
    const calls = isMock ? [] : collectSessionCallsForSpeed();
    const raw = summarizeSessionSpeed(calls, fb);
    if (!raw) return null;
    // Issue #114: 严格统一分子、分母、步数与偏好口径，避免拿累计流式速度配端到端总耗时
    const wantE2e = speedDisplayMode === 'e2e';
    const useStreaming = !wantE2e && raw.avgStreamTps != null && (raw.totalStreamingSec != null || raw.isFallback);
    const activeTps = useStreaming ? raw.avgStreamTps : (raw.avgOverallTps ?? raw.avgTps);
    const activeDurationSec = useStreaming
      ? (raw.totalStreamingSec ?? raw.totalDurationSec ?? null)
      : (raw.totalDurationSec ?? null);
    const activeCount = useStreaming
      ? (raw.streamCount > 0 ? raw.streamCount : raw.count)
      : raw.count;
    return {
      ...raw,
      avgTps: activeTps,
      activeMetricMode: useStreaming ? 'streaming' : 'e2e',
      activeDurationSec,
      activeCount
    };
  }

  function updateSpeedBadgeHoverTitle(evalRes, avgSp) {
    const speedBadge = el('badge-speed');
    if (!speedBadge) return;
    const sp = state.latest?.speed || null;
    if (avgSp?.avgTps != null) {
      const latestStream = evalRes?.streamSpeed ?? sp?.streamingTps ?? null;
      const latestOverall = evalRes?.overallTps ?? sp?.tps ?? null;
      const latestPrimary = speedDisplayMode === 'e2e' ? (latestOverall ?? latestStream) : (latestStream ?? latestOverall);
      const latestPart = latestPrimary != null
        ? t('badge.speedLatestPart', {
          tps: latestOverall ?? latestPrimary,
          streaming: latestStream ? t('badge.speedStreamingPart', { tps: latestStream }) : '',
          duration: sp?.duration || evalRes?.durationFormatted || '—',
          ttft: sp?.ttft || evalRes?.ttftFormatted || '—',
          streamSec: sp?.streamingSec || '—',
          output: fmt(evalRes?.outputTokens ?? sp?.outputTokens ?? 0)
        })
        : '';
      const modeLbl = avgSp.activeMetricMode === 'e2e' ? t('ns.speedMode.e2e') : t('ns.speedMode.streaming');
      speedBadge.title = `${modeLbl} · ` + t('badge.speedTitleDetail', {
        avgTps: avgSp.avgTps,
        count: avgSp.activeCount ?? avgSp.count,
        totalOut: fmt(avgSp.totalOutputTokens),
        totalDur: avgSp.activeDurationSec ?? avgSp.totalDurationSec ?? '—',
        latestPart
      });
    } else if (evalRes?.phase === 'waiting' || state.requestBusy) {
      speedBadge.title = t('badge.speedTitleWait');
    } else {
      speedBadge.title = t('badge.speedTitleIdle');
    }
  }

  function syncTimingDiagFoldUi() {
    const fold = el('ctx-timing-diag-fold');
    const btn = el('btn-ctx-timing-diag-toggle');
    const open = Boolean(state.timingDiagExpanded);
    state.speedBreakdownOpen = open;
    if (fold) fold.hidden = !open;
    if (btn) {
      btn.setAttribute?.('aria-expanded', open ? 'true' : 'false');
      btn.textContent = open ? t('session.timing.diagToggleClose') : t('session.timing.diagToggleOpen');
    }
  }

  function renderSpeedExperienceInPlace(evalRes) {
    if (!evalRes) return;
    syncTimingDiagFoldUi();
    const isEn = currentPanelLanguage === 'en';
    const isTw = currentPanelLanguage === 'zh-TW';
    const activeColor = evalRes.badge?.color || '';
    const avgSp = getSessionAverageSpeed(evalRes);

    const bSpeed = el('badge-speed');
    const speedAmount = el('speed-amount');
    const waitSvgWrap = el('badge-speed-wait-svg');
    const overflowSpeedVal = el('overflow-speed-val');
    const topBolt = el('badge-speed-icon');
    const cardBolt = el('speed-summary-bolt');
    if (topBolt) topBolt.style.color = activeColor;
    if (cardBolt) cardBolt.style.color = activeColor;
    if (topBolt && evalRes.badge?.glyph) topBolt.textContent = evalRes.badge.glyph;
    if (cardBolt && evalRes.badge?.glyph) cardBolt.textContent = evalRes.badge.glyph;

    const isCompact = state.layoutMode === 'compact';
    const shortSampleText = t('session.speed.shortSampleBadge');
    if (evalRes.phase === 'queued') {
      bSpeed?.setAttribute?.('data-speed-phase', 'queued');
      if (waitSvgWrap) waitSvgWrap.hidden = true;
      if (speedAmount) speedAmount.textContent = isCompact ? '…' : t('composer.runtime.reason.queued');
      if (overflowSpeedVal) overflowSpeedVal.textContent = t('composer.runtime.reason.queued');
      if (bSpeed) {
        bSpeed.title = evalRes.comment;
        bSpeed.setAttribute?.('aria-label', evalRes.comment);
      }
    } else if (evalRes.phase === 'waiting') {
      // ELV-93: 等待态顶栏纯 SVG 沙漏动效，去除每秒文字变化导致的横向抖动
      bSpeed?.setAttribute?.('data-speed-phase', 'waiting');
      if (waitSvgWrap) waitSvgWrap.hidden = false;
      if (speedAmount) speedAmount.textContent = '';
      if (overflowSpeedVal) overflowSpeedVal.textContent = `${evalRes.elapsedFormatted || '0s'}`;
      if (bSpeed) {
        const waitTip = t('badge.speedWaitTitle', { elapsed: evalRes.elapsedFormatted || '0s' });
        bSpeed.title = waitTip;
        bSpeed.setAttribute?.('aria-label', waitTip);
      }
    } else if (evalRes.phase === 'remote_unavailable') {
      bSpeed?.setAttribute?.('data-speed-phase', 'remote_unavailable');
      if (waitSvgWrap) waitSvgWrap.hidden = true;
      if (speedAmount) speedAmount.textContent = isCompact ? '—' : '— tok/s';
      if (overflowSpeedVal) overflowSpeedVal.textContent = '— tok/s';
      if (bSpeed) {
        bSpeed.title = evalRes.comment;
        bSpeed.setAttribute?.('aria-label', evalRes.comment);
      }
    } else {
      bSpeed?.removeAttribute?.('data-speed-phase');
      if (waitSvgWrap) waitSvgWrap.hidden = true;
      bSpeed?.setAttribute?.('aria-label', t('badge.speed.aria'));
      if (speedAmount) {
        if (evalRes.isSampleSparse) {
          speedAmount.textContent = shortSampleText;
          if (overflowSpeedVal) overflowSpeedVal.textContent = shortSampleText;
        } else if (avgSp?.avgTps != null) {
          speedAmount.textContent = isCompact ? `${avgSp.avgTps}` : `${avgSp.avgTps} tok/s`;
          if (overflowSpeedVal) overflowSpeedVal.textContent = `${avgSp.avgTps} tok/s`;
        } else if (evalRes.streamSpeed != null) {
          speedAmount.textContent = isCompact ? `${evalRes.streamSpeed}` : `${evalRes.streamSpeed} tok/s`;
          if (overflowSpeedVal) overflowSpeedVal.textContent = `${evalRes.streamSpeed} tok/s`;
        } else if (evalRes.overallTps != null) {
          speedAmount.textContent = isCompact ? `${evalRes.overallTps}` : `${evalRes.overallTps} tok/s`;
          if (overflowSpeedVal) overflowSpeedVal.textContent = `${evalRes.overallTps} tok/s`;
        } else {
          speedAmount.textContent = isCompact ? '--' : '-- tok/s';
          if (overflowSpeedVal) overflowSpeedVal.textContent = '-- tok/s';
        }
      }
      updateSpeedBadgeHoverTitle(evalRes, avgSp);
    }

    const spBadge = el('speed-badge');
    const spAvgVal = el('speed-avg-val');
    const spVal = el('speed-val');
    const spDur = el('speed-duration');
    const spTtft = el('speed-ttft');
    const spTokens = el('speed-tokens');
    const spSub = el('speed-sub-label');
    const spTakeaway = el('speed-takeaway');
    const spBreakdownDet = el('speed-breakdown-details');
    const spBreakdownGrid = el('speed-breakdown-grid');

    const spMockTag = el('speed-mock-tag');
    if (spMockTag) {
      spMockTag.hidden = !(state.speedOverrideForTest && typeof state.speedOverrideForTest === 'object');
      if (!spMockTag.hidden) spMockTag.textContent = t('session.speed.mockTag');
    }
    if (spBadge) applyElv91PillTone(spBadge, evalRes);
    if (spAvgVal) {
      if (avgSp?.avgTps != null) {
        spAvgVal.textContent = `${avgSp.avgTps} tok/s`;
        const overallPart = (avgSp.avgOverallTps != null && Math.abs(avgSp.avgOverallTps - avgSp.avgTps) >= 0.5)
          ? t('session.speed.avgOverallPart', { overallTps: avgSp.avgOverallTps })
          : '';
        spAvgVal.title = t('session.speed.avgTip', {
          avgTps: avgSp.avgTps,
          overallPart,
          count: avgSp.count,
          totalTok: fmt(avgSp.totalOutputTokens),
          totalDur: avgSp.totalDurationSec ?? '—'
        });
      } else {
        spAvgVal.textContent = '—';
        spAvgVal.title = '';
      }
    }
    if (spVal) {
      if (evalRes.phase === 'queued') {
        spVal.textContent = evalRes.shortTitle || t('composer.runtime.reason.queued');
      } else if (evalRes.phase === 'waiting') {
        spVal.textContent = isEn ? 'Waiting' : '等待首字';
      } else if (evalRes.phase === 'remote_unavailable') {
        spVal.textContent = evalRes.shortTitle || '—';
      } else if (evalRes.isSampleSparse) {
        spVal.textContent = shortSampleText;
      } else if (evalRes.streamSpeed != null) {
        spVal.textContent = `${evalRes.streamSpeed} tok/s`;
      } else if (evalRes.overallTps != null) {
        spVal.textContent = `${evalRes.overallTps} tok/s`;
      } else {
        spVal.textContent = '—';
      }
    }
    if (spDur) spDur.textContent = evalRes.durationFormatted || '—';
    if (spTtft) spTtft.textContent = evalRes.ttftFormatted || '—';
    if (spTokens) spTokens.textContent = evalRes.outputTokens != null ? `${fmt(evalRes.outputTokens)} tok` : '—';

    if (spSub) {
      if (evalRes.subLabel && evalRes.phase !== 'idle') {
        spSub.hidden = false;
        spSub.textContent = evalRes.subLabel;
      } else {
        spSub.hidden = true;
        spSub.textContent = '';
      }
    }
    if (spTakeaway) {
      const avgNote = (evalRes.phase === 'final' && evalRes.overallTps != null && (evalRes.isSampleSparse || (evalRes.streamSpeed != null && Math.abs(evalRes.overallTps - evalRes.streamSpeed) >= 5)))
        ? (isEn ? ` (Overall avg ${evalRes.overallTps} tok/s)` : (isTw ? `（整體均速 ${evalRes.overallTps} tok/s）` : `（整体均速 ${evalRes.overallTps} tok/s）`))
        : '';
      const sessionAvgNote = avgSp?.avgTps != null
        ? t('speed.takeaway.avgInline', { avgTps: avgSp.avgTps, count: avgSp.count })
        : '';
      spTakeaway.textContent = `${evalRes.comment || ''}${avgNote}${sessionAvgNote}`;
    }

    const canShowBreakdown = evalRes.phase === 'final' || evalRes.phase === 'streaming';
    const breakdownVisible = Boolean(canShowBreakdown && (state.timingDiagExpanded || state.speedBreakdownOpen));
    if (spBreakdownDet) {
      spBreakdownDet.style.display = breakdownVisible ? 'block' : 'none';
    }
    if (spBreakdownGrid && breakdownVisible) {
      spBreakdownGrid.replaceChildren();
      const unk = t('session.latestCall.unknownVal');
      const eText = evalRes.efficiency?.available
        ? `${evalRes.efficiency.score} ${isEn ? 'pts' : '分'} · ${evalRes.efficiency.tier?.title || evalRes.efficiency.grade}`
        : (evalRes.efficiency?.skippedReason === 'insufficient_sample' ? t('session.speed.scoreSkippedSparse') : t('session.speed.scoreSkippedMissing'));
      const stabText = evalRes.stability?.isStable
        ? t('session.speed.stabilityOk', { n: evalRes.stability.chunks, cv: evalRes.stability.intervalCv })
        : (evalRes.stability?.reason === 'high_variance'
          ? t('session.speed.stabilityHighVar', { n: evalRes.stability.chunks, cv: evalRes.stability.intervalCv })
          : t('session.speed.stabilityUnverified'));
      const fmtTierComment = (tier, elapsed) => (tier && tier.comment) ? String(tier.comment).replace('{elapsed}', elapsed || '—') : '';
      const streamCellVal = evalRes.isSampleSparse
        ? `${shortSampleText}${evalRes.shortWindowEstimateSpeed != null ? ` (${evalRes.shortWindowEstimateSpeed} tok/s)` : ''}`
        : (evalRes.speedTier ? `${evalRes.streamSpeed} tok/s · ${evalRes.speedTier.title}` : unk);
      const cells = [
        {
          k: t('session.speed.breakdown.eScore'),
          v: eText,
          color: evalRes.efficiency?.tier?.color || null,
          note: evalRes.efficiency?.tier?.comment || ''
        },
        {
          k: t('session.speed.breakdown.ttft'),
          v: evalRes.ttftTier ? `${evalRes.ttftFormatted} · ${evalRes.ttftTier.title}${evalRes.ttftRatioPct != null ? ` (${evalRes.ttftRatioPct}%)` : ''}` : unk,
          color: evalRes.ttftTier?.color || null,
          note: fmtTierComment(evalRes.ttftTier, evalRes.ttftFormatted)
        },
        {
          k: t('session.speed.breakdown.stream'),
          v: streamCellVal,
          color: evalRes.isSampleSparse ? null : (evalRes.speedTier?.color || null),
          note: evalRes.isSampleSparse ? t('session.speed.shortWindowNote') : (evalRes.speedTier?.comment || '')
        },
        {
          k: t('session.speed.breakdown.duration'),
          v: evalRes.durationTier ? `${evalRes.durationFormatted} · ${evalRes.durationTier.title}` : unk,
          color: evalRes.durationTier?.color || null,
          note: evalRes.durationTier?.comment || ''
        },
        { k: t('session.speed.breakdown.overall'), v: evalRes.overallTps != null ? `${evalRes.overallTps} tok/s` : unk, color: null, note: '' },
        {
          k: t('session.speed.breakdown.sessionAvg'),
          v: avgSp?.avgTps != null ? `${avgSp.avgTps} tok/s` : unk,
          color: null,
          note: avgSp?.avgTps != null
            ? (isEn
              ? `${avgSp.count} turn(s) · ${fmt(avgSp.totalOutputTokens)} tok / ${avgSp.totalDurationSec ?? '—'}s`
              : (isTw
                ? `共 ${avgSp.count} 輪 · 累計 ${fmt(avgSp.totalOutputTokens)} tok / ${avgSp.totalDurationSec ?? '—'}s`
                : `共 ${avgSp.count} 轮 · 累计 ${fmt(avgSp.totalOutputTokens)} tok / ${avgSp.totalDurationSec ?? '—'}s`))
            : ''
        },
        { k: t('session.speed.breakdown.stability'), v: stabText, color: evalRes.stability?.isStable ? '#10B981' : null, note: '' }
      ];
      if (evalRes.isSampleSparse && evalRes.shortWindowEstimateSpeed != null) {
        cells.splice(3, 0, {
          k: t('session.speed.shortWindowEst'),
          v: `${evalRes.shortWindowEstimateSpeed} tok/s`,
          color: null,
          note: t('session.speed.shortWindowNote')
        });
      }
      if (evalRes.efficiency?.basis) {
        const b = evalRes.efficiency.basis;
        cells.push({
          k: t('session.speed.breakdown.basis'),
          v: `N=${b.N_work} · γ=${b.gamma} · w=[${b.w1}/${b.w2}/${b.w3}]`,
          color: null,
          note: ''
        });
      }
      for (const item of cells) {
        const cell = document.createElement('div');
        cell.className = 'call-detail-cell';
        const kEl = document.createElement('span');
        kEl.className = 'call-detail-k';
        kEl.textContent = item.k;
        const vEl = document.createElement('span');
        vEl.className = 'call-detail-v';
        if (item.color) {
          const dot = document.createElement('span');
          dot.className = 'tier-color-swatch';
          dot.style.backgroundColor = item.color;
          dot.setAttribute('aria-hidden', 'true');
          vEl.appendChild(dot);
          const txtEl = document.createElement('span');
          txtEl.textContent = item.v;
          vEl.appendChild(txtEl);
        } else {
          vEl.textContent = item.v;
        }
        cell.appendChild(kEl);
        cell.appendChild(vEl);
        if (item.note) {
          const noteEl = document.createElement('span');
          noteEl.className = 'call-detail-note';
          noteEl.textContent = item.note;
          cell.appendChild(noteEl);
        }
        spBreakdownGrid.appendChild(cell);
      }
    }
    state.lastSpeedEval = evalRes;
    if (typeof syncFloatingOrbState === 'function') syncFloatingOrbState();
  }

  function isPriorTurnActivelyGenerating(cascadeId) {
    const cid = cascadeId || state.route;
    if (!cid) return false;
    const latestRec = typeof resolveLatestSessionCallRecord === 'function' ? resolveLatestSessionCallRecord() : null;
    if (latestRec && latestRec.status === 'streaming') return true;
    if (state.turnState?.streaming && !state.livePendingRequest) return true;
    if (state.livePendingRequest && state.livePendingRequest.cascadeId === cid && state.livePendingRequest.stage === 'dispatched') {
      return true;
    }
    try {
      const stopBtn = typeof document !== 'undefined' && document.querySelector?.('.surface-composer button[data-testid="stop-button"], .surface-composer button[aria-label^="Stop"], .surface-composer button[aria-label^="停止"]');
      if (stopBtn) return true;
    } catch { }
    return false;
  }

  function startPendingWaitTickTimer() {
    const updateWaitOnly = () => {
      if (state.disposed || !state.livePendingRequest || state.livePendingRequest.cascadeId !== state.route) {
        stopLiveWaitTickTimer();
        return;
      }
      if (typeof evaluateGenerationExperience === 'function') {
        renderSpeedExperienceInPlace(evaluateGenerationExperience(resolveSpeedEvaluationInput(), currentPanelLanguage));
      }
    };
    updateWaitOnly();
    stopLiveWaitTickTimer();
    state.liveWaitTickTimer = setInterval(updateWaitOnly, 1000);
  }

  function startLivePendingRequestWait(cascadeId, options = {}) {
    const cid = cascadeId || state.route;
    if (!cid) return null;
    const latestRec = resolveLatestSessionCallRecord();
    const now = Number(options.nowMs) || Date.now();
    const shouldQueue = options.queued !== undefined
      ? Boolean(options.queued)
      : isPriorTurnActivelyGenerating(cid);

    if (shouldQueue) {
      state.livePendingRequest = {
        cascadeId: cid,
        stage: 'queued',
        queuedAtMs: now,
        dispatchedAtMs: null,
        startedAtMs: null,
        firstTokenAtMs: null,
        queuedFromComposerDom: Boolean(options.fromDom),
        baselineCallId: latestRec?.callId || null,
        baselineCount: state.count || 0
      };
    } else {
      state.livePendingRequest = {
        cascadeId: cid,
        stage: 'dispatched',
        queuedAtMs: null,
        dispatchedAtMs: now,
        startedAtMs: now,
        firstTokenAtMs: null,
        queuedFromComposerDom: false,
        baselineCallId: latestRec?.callId || null,
        baselineCount: state.count || 0
      };
    }
    startPendingWaitTickTimer();
    if (!state.disposed && typeof syncComposerStatusBar === 'function') syncComposerStatusBar();
    if (!state.disposed && typeof syncFloatingOrbState === 'function') syncFloatingOrbState();
    return state.livePendingRequest;
  }

  function promoteQueuedPendingRequestToDispatched(cascadeId, nowMs = Date.now()) {
    const req = state.livePendingRequest;
    const cid = cascadeId || state.route;
    if (!req || !cid || req.cascadeId !== cid || req.stage !== 'queued') return false;
    const latestRec = resolveLatestSessionCallRecord();
    const ts = Number(nowMs) || Date.now();
    req.stage = 'dispatched';
    req.dispatchedAtMs = ts;
    req.startedAtMs = ts;
    req.baselineCallId = latestRec?.callId || req.baselineCallId || null;
    req.baselineCount = state.count || req.baselineCount || 0;
    startPendingWaitTickTimer();
    if (!state.disposed && typeof syncComposerStatusBar === 'function') syncComposerStatusBar();
    if (!state.disposed && typeof syncFloatingOrbState === 'function') syncFloatingOrbState();
    return true;
  }

  function cancelOrEditQueuedPendingRequest(reason = 'canceled') {
    const req = state.livePendingRequest;
    if (!req) return false;
    if (req.stage === 'queued' || /cancel|abort|edit|rpc_cancel/i.test(String(reason))) {
      clearLivePendingRequestWait();
      if (!state.disposed && typeof evaluateGenerationExperience === 'function') {
        renderSpeedExperienceInPlace(evaluateGenerationExperience(resolveSpeedEvaluationInput(), currentPanelLanguage));
      }
      if (!state.disposed && typeof syncComposerStatusBar === 'function') syncComposerStatusBar();
      if (!state.disposed && typeof syncRequestsLiveViewIfVisible === 'function') syncRequestsLiveViewIfVisible();
      return true;
    }
    return false;
  }

  // 监听宿主输入框排队提交、撤回/取消与重编辑，避免排队或中断误产生假首字计时
  if (typeof document !== 'undefined' && typeof document.addEventListener === 'function') {
    const onComposerQueueKeydown = (e) => {
      if (state.disposed || !state.route) return;
      if (e.key === 'Escape' && state.livePendingRequest?.stage === 'queued') {
        if (e.target?.closest?.('.surface-composer')) {
          cancelOrEditQueuedPendingRequest('escape_edit');
        }
        return;
      }
      if (e.key !== 'Enter' || e.shiftKey || e.altKey || e.ctrlKey || e.metaKey || e.isComposing) return;
      const composer = e.target?.closest?.('.surface-composer');
      if (!composer || composer.closest?.('#ag-context-meter')) return;
      if (isPriorTurnActivelyGenerating(state.route) && e.target?.textContent?.trim() && !/^\/compact(?:\s|$)/i.test(e.target.textContent.trim())) {
        startLivePendingRequestWait(state.route, { queued: true, fromDom: true });
      }
    };
    const onComposerQueueClick = (e) => {
      if (state.disposed || !state.route) return;
      const btn = e.target?.closest?.('button');
      if (!btn || btn.closest?.('#ag-context-meter')) return;
      const testId = String(btn.getAttribute?.('data-testid') || '');
      const aria = String(btn.getAttribute?.('aria-label') || '');
      const txt = String(btn.textContent || '').trim();
      const composer = btn.closest?.('.surface-composer');
      if (composer && testId === 'send-button' && isPriorTurnActivelyGenerating(state.route)) {
        startLivePendingRequestWait(state.route, { queued: true, fromDom: true });
        return;
      }
      if (state.livePendingRequest?.stage === 'queued') {
        const metaStr = `${testId} ${aria} ${txt}`;
        if (/(?:stop|cancel|abort|remove|delete|edit|withdraw|停止|取消|删除|移除|编辑|撤回)/i.test(metaStr)) {
          cancelOrEditQueuedPendingRequest('dom_cancel_or_edit');
        }
      }
    };
    const onComposerQueueInput = (e) => {
      if (state.disposed || state.livePendingRequest?.stage !== 'queued' || !state.livePendingRequest.queuedFromComposerDom) return;
      const composer = e.target?.closest?.('.surface-composer');
      if (composer && !composer.closest?.('#ag-context-meter')) {
        cancelOrEditQueuedPendingRequest('dom_edit');
      }
    };
    document.addEventListener('keydown', onComposerQueueKeydown, true);
    document.addEventListener('click', onComposerQueueClick, true);
    document.addEventListener('input', onComposerQueueInput, true);
    earlyDisposeHooks.push(() => {
      try {
        document.removeEventListener('keydown', onComposerQueueKeydown, true);
        document.removeEventListener('click', onComposerQueueClick, true);
        document.removeEventListener('input', onComposerQueueInput, true);
      } catch { }
    });
  }

  function syncSpeedBadgeText() {
    if (typeof evaluateGenerationExperience === 'function') {
      const evalRes = evaluateGenerationExperience(resolveSpeedEvaluationInput(), currentPanelLanguage);
      renderSpeedExperienceInPlace(evalRes);
      return;
    }
    const sp = state.latest?.speed;
    const speedAmount = el('speed-amount');
    const overflowSpeedVal = el('overflow-speed-val');
    if (!speedAmount) return;
    const isCompact = state.layoutMode === 'compact';
    if (sp?.tps != null) {
      speedAmount.textContent = isCompact ? `${sp.tps}` : `${sp.tps} tok/s`;
      if (overflowSpeedVal) overflowSpeedVal.textContent = `${sp.tps} tok/s`;
    } else if (state.requestBusy) {
      const calcText = t('badge.speedCalc');
      speedAmount.textContent = isCompact ? '…' : calcText;
      if (overflowSpeedVal) overflowSpeedVal.textContent = calcText;
    } else {
      speedAmount.textContent = isCompact ? '--' : '-- tok/s';
      if (overflowSpeedVal) overflowSpeedVal.textContent = '-- tok/s';
    }
  }

  let lastCallCardLang = '';
  let timelineFetchController = null;
  let timelineFetchSeq = 0;

  function prefersReducedMotionNow() {
    try {
      return Boolean(typeof globalThis.matchMedia === 'function' && globalThis.matchMedia('(prefers-reduced-motion: reduce)').matches);
    } catch {
      return false;
    }
  }

  function formatCallTimeStr(call) {
    if (!call) return '—';
    const rawTs = call.timestamp || (call.created_at ? Date.parse(call.created_at) : NaN);
    if (!Number.isFinite(rawTs) || rawTs <= 0) return t('session.latestCall.unknownVal');
    try {
      return new Date(rawTs).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit', hour12: false });
    } catch {
      return new Date(rawTs).toLocaleTimeString();
    }
  }

  function formatCallModelTitle(call) {
    if (!call) return t('session.timeline.unknownModel');
    if (call.isModelUnknown) {
      if (call.rawPlaceholderId || (call.isPlaceholderOnly && (call.modelExactId || call.model))) {
        const rawId = call.rawPlaceholderId || call.modelExactId || call.model || '';
        return rawId ? t('session.latestCall.unknownMappedModel', { id: rawId }) : t('session.timeline.unknownModel');
      }
      return call.attributedModelLabel || t('session.timeline.unknownModel');
    }
    if (call.isPlaceholderOnly && !call.isRoutedModelVerified && !call.attributedModelLabel) {
      const rawId = call.rawPlaceholderId || call.modelExactId || call.model || '';
      return rawId ? t('session.latestCall.unknownMappedModel', { id: rawId }) : t('session.timeline.unknownModel');
    }
    const rawLbl = call.attributedModelLabel || call.modelLabel || (call.model && !/^model_/i.test(String(call.model)) ? String(call.model) : '');
    if (rawLbl) {
      if (typeof splitModelDisplayAndEffort === 'function') {
        const split = splitModelDisplayAndEffort(rawLbl, call.effort);
        if (split.baseLabel) return split.baseLabel;
      }
      return rawLbl;
    }
    if (call.stableModelId && !/^model_placeholder_/i.test(String(call.stableModelId))) return String(call.stableModelId);
    if (call.modelExactId && !/^model_placeholder_/i.test(String(call.modelExactId))) return String(call.modelExactId);
    if (call.model && !/^model_placeholder_/i.test(String(call.model))) return String(call.model);
    if (call.rawPlaceholderId || call.modelExactId || call.model) {
      return t('session.latestCall.unknownMappedModel', { id: call.rawPlaceholderId || call.modelExactId || call.model });
    }
    return t('session.timeline.unknownModel');
  }

  function buildCallDisplaySignature(call) {
    if (!call) return '';
    return [
      call.callId || '',
      call.outcomeStatus || call.status || '',
      call.inputTokens ?? '',
      call.cacheReadTokens ?? '',
      call.outputTokens ?? '',
      call.totalTokens ?? '',
      call.modelExactId || call.model || '',
      call.modelLabel || '',
      call.effort || '',
      call.durationSec ?? '',
      call.ttftSec ?? '',
      call.error || '',
      call.agentRole || ''
    ].join('|');
  }

  function resolveLatestSessionCallRecord() {
    if (!state.route) return null;
    const rawPool = [];
    if (Array.isArray(state.sessionCalls)) {
      for (const c of state.sessionCalls) {
        if (c) rawPool.push(c);
      }
    }
    if (Array.isArray(state.scan?.recentGeneratorCalls)) {
      for (const c of state.scan.recentGeneratorCalls) {
        if (c) rawPool.push(c);
      }
    }
    if (state.scan?.latestCallRecord) {
      rawPool.push(state.scan.latestCallRecord);
    }
    if (!rawPool.length) return null;

    const mergedById = new Map();
    const configs = state.cascadeModelConfigs || state.scan?.cascadeModelConfigs || [];
    for (const raw of rawPool) {
      const norm = typeof normalizeSessionCallRecord === 'function'
        ? normalizeSessionCallRecord(raw, { cascadeId: state.route, cascadeModelConfigs: configs })
        : raw;
      if (!norm || !norm.callId) continue;
      const prev = mergedById.get(norm.callId);
      if (!prev) {
        mergedById.set(norm.callId, norm);
        continue;
      }
      // 同一 callId 从不同源补齐耗时、精确模型或状态，不产生第二条
      mergedById.set(norm.callId, {
        ...prev,
        ...norm,
        modelExactId: norm.modelExactId || prev.modelExactId || null,
        modelLabel: norm.modelLabel || prev.modelLabel || null,
        effort: norm.effort || prev.effort || null,
        ttftSec: norm.ttftSec ?? prev.ttftSec ?? null,
        durationSec: norm.durationSec ?? prev.durationSec ?? null,
        tps: norm.tps ?? prev.tps ?? null,
        streamingTps: norm.streamingTps ?? prev.streamingTps ?? null,
        error: norm.error || prev.error || null,
        errorClassification: norm.errorClassification || prev.errorClassification || null,
        hasInputCacheFields: Boolean(norm.hasInputCacheFields || prev.hasInputCacheFields),
        inputTokens: norm.hasInputCacheFields ? norm.inputTokens : (prev.hasInputCacheFields ? prev.inputTokens : norm.inputTokens),
        cacheReadTokens: norm.hasInputCacheFields ? norm.cacheReadTokens : (prev.hasInputCacheFields ? prev.cacheReadTokens : norm.cacheReadTokens),
        totalInputTokens: norm.hasInputCacheFields ? norm.totalInputTokens : (prev.hasInputCacheFields ? prev.totalInputTokens : norm.totalInputTokens),
        outputTokens: Math.max(Number(norm.outputTokens) || 0, Number(prev.outputTokens) || 0) || norm.outputTokens,
        totalTokens: Math.max(Number(norm.totalTokens) || 0, Number(prev.totalTokens) || 0) || norm.totalTokens,
        timestamp: norm.timestamp || prev.timestamp || null,
        created_at: norm.created_at || prev.created_at || null,
        stepIndex: norm.stepIndex ?? prev.stepIndex ?? null
      });
    }

    const candidates = Array.from(mergedById.values());
    if (!candidates.length) return null;
    candidates.sort((a, b) => {
      const ta = Number(a.timestamp) || 0;
      const tb = Number(b.timestamp) || 0;
      if (ta !== tb) return ta - tb;
      const sa = a.stepIndex != null ? Number(a.stepIndex) : -1;
      const sb = b.stepIndex != null ? Number(b.stepIndex) : -1;
      if (sa !== sb) return sa - sb;
      if (a.status === 'streaming' && b.status !== 'streaming') return 1;
      if (b.status === 'streaming' && a.status !== 'streaming') return -1;
      return 0;
    });
    return candidates[candidates.length - 1];
  }

  function isElementActivelyInspected() {
    try {
      const det = el('latest-call-details');
      const tl = el('session-timeline-drawer');
      if (det && state.latestCallDetailOpen && typeof det.matches === 'function' && det.matches(':hover')) return true;
      if (tl && state.historyDrawerOpen && typeof tl.matches === 'function' && tl.matches(':hover')) return true;
      const activeEl = shadow?.activeElement || document?.activeElement;
      if (activeEl && ((det && det.contains?.(activeEl)) || (tl && tl.contains?.(activeEl)))) return true;
      const sel = shadow?.getSelection?.() || window?.getSelection?.();
      if (sel && String(sel.toString() || '').trim().length > 0 && sel.anchorNode) {
        const card = el('latest-call-card');
        if (card && card.contains?.(sel.anchorNode)) return true;
      }
    } catch { }
    return false;
  }

  function isCallCardReadingProtected(incomingCall) {
    if (!state.displayedCallRecord || !incomingCall) return false;
    if (state.pinnedCallRecord) return true;
    const differentCall = incomingCall.callId !== state.displayedCallRecord.callId;
    if (!differentCall) return false;
    if (state.latestCallDetailOpen && state.displayedCallRecord.status !== 'streaming') return true;
    if (isElementActivelyInspected()) return true;
    return false;
  }

  function resolveCallStatusDisplay(call) {
    const out = call?.outcomeStatus || call?.status || 'unknown';
    if (out === 'streaming') return { text: t('session.latestCall.statusStreaming'), cls: 'key-pill pill-warn' };
    if (out === 'canceled') return { text: t('session.latestCall.statusCanceled'), cls: 'key-pill pill-muted' };
    if (out === 'success' || out === 'final') return { text: t('session.latestCall.statusSuccess'), cls: 'key-pill pill-good' };
    if (out === 'quota_exhausted' || out === 'context_overflow' || out === 'exceeded' || out === 'network' || out === 'network_error' || out === 'rate_limit' || out === 'failed' || call?.error) {
      return { text: t('session.latestCall.statusFailed'), cls: 'key-pill pill-danger' };
    }
    return { text: t('session.latestCall.statusUnknown'), cls: 'key-pill pill-muted' };
  }

  function formatCallCachePctText(call) {
    if (!call) return t('session.latestCall.unknownVal');
    if (call.cacheStatus === 'missing' || !call.hasInputCacheFields) return t('session.latestCall.unknownVal');
    if (call.cacheStatus === 'zero_input') return t('session.latestCall.naVal');
    if (call.cacheReadPct !== null && call.cacheReadPct !== undefined) return `${call.cacheReadPct}%`;
    return t('session.latestCall.unknownVal');
  }

  function applyLatestCallRecordToDom(call, { playAnim = false } = {}) {
    const card = el('latest-call-card');
    if (!card) return;
    const statusPill = el('latest-call-status-pill');
    const agentPill = el('latest-call-agent-pill');
    const timeEl = el('latest-call-time');
    const modelEl = el('latest-call-model');
    const effortEl = el('latest-call-effort');
    const tokInline = el('latest-call-tokens-inline');
    const cacheInline = el('latest-call-cache-inline');
    const durInline = el('latest-call-duration-inline');
    const detailGrid = el('latest-call-detail-grid');
    const errorBox = el('latest-call-error-box');
    const bodyEl = el('latest-call-body');

    const st = resolveCallStatusDisplay(call);
    if (statusPill) {
      statusPill.textContent = st.text;
      statusPill.className = st.cls;
    }

    if (agentPill) {
      if (call.agentRole === 'subagent') {
        agentPill.hidden = false;
        agentPill.className = 'call-agent-badge is-subagent';
        agentPill.textContent = call.subagentType ? `${t('session.latestCall.agentSub')} · ${call.subagentType}` : t('session.latestCall.agentSub');
      } else if (call.attributionConfidence === 'unidentified') {
        agentPill.hidden = false;
        agentPill.className = 'call-agent-badge is-unknown';
        agentPill.textContent = t('session.latestCall.agentUnknown');
      } else {
        agentPill.hidden = false;
        agentPill.className = 'call-agent-badge';
        agentPill.textContent = t('session.latestCall.agentMain');
      }
    }

    if (timeEl) timeEl.textContent = formatCallTimeStr(call);
    const modelTitle = formatCallModelTitle(call);
    if (modelEl) {
      modelEl.textContent = modelTitle;
      modelEl.title = call.modelExactId ? `${modelTitle} (${call.modelExactId})` : modelTitle;
    }
    if (effortEl) {
      if (call.effort) {
        effortEl.hidden = false;
        effortEl.textContent = call.effort;
      } else {
        effortEl.hidden = true;
        effortEl.textContent = '';
      }
    }

    const unk = t('session.latestCall.unknownVal');
    const scoreInline = el('latest-call-score-inline');
    const callEval = (typeof evaluateGenerationExperience === 'function')
      ? evaluateGenerationExperience({
        phase: call.status === 'streaming' ? 'streaming' : (call.outcomeStatus === 'canceled' ? 'canceled' : (call.error ? 'failed' : 'final')),
        outcomeStatus: call.outcomeStatus,
        ttftSec: call.ttftSec,
        streamingSec: call.streamingSec,
        totalDurationSec: call.durationSec,
        streamSpeed: call.streamingTps ?? call.streamSpeed,
        overallTps: call.tps,
        outputTokens: call.outputTokens,
        totalInputTokens: call.totalInputTokens,
        chunkCount: call.chunkCount,
        chunkIntervalsMs: call.chunkIntervalsMs,
        intervalCv: call.intervalCv,
        sampleSource: call.sampleSource || null,
        isSyntheticPoll: call.isSyntheticPoll === true,
        error: call.error
      }, currentPanelLanguage)
      : null;

    if (scoreInline) {
      if (callEval && callEval.efficiency?.available) {
        scoreInline.hidden = false;
        scoreInline.textContent = `${callEval.efficiency.score}${currentPanelLanguage === 'en' ? ' pts' : '分'} · ${callEval.efficiency.grade}`;
        scoreInline.style.color = callEval.efficiency.tier?.color || '';
        scoreInline.style.borderColor = callEval.efficiency.tier?.color || '';
        scoreInline.title = callEval.shortTitle || '';
      } else if (call.eScore != null && call.eGrade) {
        scoreInline.hidden = false;
        scoreInline.textContent = `${call.eScore}${currentPanelLanguage === 'en' ? ' pts' : '分'} · ${call.eGrade}`;
        scoreInline.style.color = callEval?.badge?.color || '';
        scoreInline.style.borderColor = callEval?.badge?.color || '';
      } else {
        scoreInline.hidden = true;
        scoreInline.textContent = '—';
        scoreInline.style.color = '';
        scoreInline.style.borderColor = '';
      }
    }

    const inpStr = call.hasInputCacheFields && call.inputTokens !== null ? short(call.inputTokens) : unk;
    const outStr = call.outputTokens !== null && call.outputTokens !== undefined ? short(call.outputTokens) : unk;
    if (tokInline) tokInline.textContent = t('session.latestCall.inlineTokens', { inp: inpStr, out: outStr });
    if (cacheInline) cacheInline.textContent = t('session.latestCall.inlineCache', { val: formatCallCachePctText(call) });
    if (durInline) durInline.textContent = call.durationSec !== null && call.durationSec !== undefined
      ? (typeof formatHumanDuration === 'function' ? formatHumanDuration(call.durationSec, currentPanelLanguage) : `${call.durationSec}s`)
      : '—';

    if (detailGrid) {
      detailGrid.replaceChildren();
      const agentDesc = call.agentRole === 'subagent'
        ? `${t('session.latestCall.agentSub')}${call.subagentRole ? ` (${call.subagentRole})` : (call.subagentType ? ` (${call.subagentType})` : '')}${call.parentCascadeId ? ` · parent ${String(call.parentCascadeId).slice(0, 8)}` : ''}${call.parentStepIndex != null ? ` · step #${call.parentStepIndex}` : ` · ${t('session.latestCall.missingParentStep')}`}`
        : (call.attributionConfidence === 'unidentified' ? t('session.latestCall.agentUnknown') : t('session.latestCall.agentMain'));
      const fmtDurOrUnk = (v) => (v !== null && v !== undefined) ? (typeof formatHumanDuration === 'function' ? formatHumanDuration(v, currentPanelLanguage) : `${v}s`) : unk;
      const eDetailVal = callEval?.efficiency?.available
        ? `${callEval.efficiency.score} ${currentPanelLanguage === 'en' ? 'pts' : '分'} · ${callEval.efficiency.tier?.title || callEval.efficiency.grade}`
        : (call.eScore != null ? `${call.eScore} (${call.eGrade || '--'})` : (callEval?.efficiency?.skippedReason === 'insufficient_sample' ? t('session.speed.scoreSkippedSparse') : t('session.speed.scoreSkippedMissing')));
      const rawIdBadge = call.rawPlaceholderId ? ` (${t('session.latestCall.rawIdNote', { id: call.rawPlaceholderId })})` : '';
      const stableIdDisplay = (call.stableModelId && !/^model_placeholder_/i.test(String(call.stableModelId)))
        ? `${call.stableModelId}${rawIdBadge}`
        : ((call.modelExactId && !/^model_placeholder_/i.test(String(call.modelExactId)))
          ? `${call.modelExactId}${rawIdBadge}`
          : (call.rawPlaceholderId
            ? `${unk} (${t('session.latestCall.rawIdNote', { id: call.rawPlaceholderId })})`
            : (call.modelExactId || call.modelKey || unk)));
      const modelAndEffortDisplay = formatProductDisplayWithEffort(modelTitle, call.effort);
      const callStreamDisplay = callEval?.isSampleSparse
        ? `${t('session.speed.shortSampleBadge')}${callEval.shortWindowEstimateSpeed != null ? ` (${t('session.speed.shortWindowEst')}: ${callEval.shortWindowEstimateSpeed} tok/s)` : ''}`
        : ((call.streamingTps ?? call.streamSpeed) != null ? `${call.streamingTps ?? call.streamSpeed} tok/s${callEval?.speedTier ? ` · ${callEval.speedTier.title}` : ''}` : unk);
      const cells = [
        [t('session.latestCall.fieldTime'), formatCallTimeStr(call)],
        [t('session.latestCall.fieldStatus'), st.text],
        [t('session.latestCall.fieldModelId'), stableIdDisplay],
        [t('session.latestCall.fieldModelLabel'), modelAndEffortDisplay],
        [t('session.latestCall.fieldInput'), call.hasInputCacheFields && call.inputTokens !== null ? fmt(call.inputTokens) : unk],
        [t('session.latestCall.fieldCacheRead'), call.hasInputCacheFields && call.cacheReadTokens !== null ? fmt(call.cacheReadTokens) : unk],
        [t('session.latestCall.fieldTotalInput'), call.hasInputCacheFields && call.totalInputTokens !== null ? fmt(call.totalInputTokens) : unk],
        [t('session.latestCall.fieldOutput'), call.outputTokens !== null && call.outputTokens !== undefined
          ? `${fmt(call.outputTokens)}${call.thinkingTokens ? ` (${fmt(call.thinkingTokens)})` : ''}`
          : unk],
        [t('session.latestCall.fieldCacheRatio'), formatCallCachePctText(call)],
        [t('session.latestCall.fieldTtft'), `${fmtDurOrUnk(call.ttftSec)}${call.ttftRatioPct != null ? ` (${call.ttftRatioPct}%)` : ''}${callEval?.ttftTier ? ` · ${callEval.ttftTier.title}` : ''}`],
        [t('session.latestCall.fieldDuration'), `${fmtDurOrUnk(call.durationSec)}${callEval?.durationTier ? ` · ${callEval.durationTier.title}` : ''}`],
        [t('session.speed.streamRate'), callStreamDisplay],
        [t('session.speed.breakdown.overall'), call.tps !== null && call.tps !== undefined ? `${call.tps} tok/s` : unk],
        [t('session.speed.breakdown.eScore'), eDetailVal],
        [t('session.latestCall.fieldAgent'), agentDesc]
      ];
      for (const [k, v] of cells) {
        const cell = document.createElement('div');
        cell.className = 'call-detail-cell';
        const kEl = document.createElement('span');
        kEl.className = 'call-detail-k';
        kEl.textContent = k;
        const vEl = document.createElement('span');
        vEl.className = 'call-detail-v';
        vEl.textContent = v;
        cell.appendChild(kEl);
        cell.appendChild(vEl);
        detailGrid.appendChild(cell);
      }
    }

    if (errorBox) {
      if (call.error || st.cls.includes('pill-danger')) {
        errorBox.hidden = false;
        const reason = call.errorClassification?.reason || '';
        errorBox.textContent = [reason, call.error].filter(Boolean).join(' · ') || st.text;
      } else {
        errorBox.hidden = true;
        errorBox.textContent = '';
      }
    }

    if (bodyEl && playAnim && !prefersReducedMotionNow()) {
      if (state.callEnterAnimTimer) {
        clearTimeout(state.callEnterAnimTimer);
        state.callEnterAnimTimer = null;
      }
      bodyEl.classList?.remove?.('is-entering');
      void bodyEl.offsetWidth;
      bodyEl.classList?.add?.('is-entering');
      state.callEnterAnimTimer = setTimeout(() => {
        state.callEnterAnimTimer = null;
        bodyEl.classList?.remove?.('is-entering');
      }, 250);
    }
  }

  function syncLatestCallDetailsVisibility() {
    const det = el('latest-call-details');
    const row = el('latest-call-summary-row');
    if (det) det.style.display = state.latestCallDetailOpen ? 'block' : 'none';
    if (row) row.setAttribute?.('aria-expanded', state.latestCallDetailOpen ? 'true' : 'false');
  }

  function renderLatestCallCard({ fromUserAction = false, skipAnim = false } = {}) {
    const card = el('latest-call-card');
    if (!card) return;
    if (!state.route) {
      card.hidden = true;
      return;
    }

    const incoming = resolveLatestSessionCallRecord();
    const target = state.pinnedCallRecord || incoming;
    if (!target) {
      card.hidden = !state.historyDrawerOpen;
      return;
    }
    card.hidden = false;

    const newBanner = el('latest-call-new-banner');
    if (!fromUserAction && isCallCardReadingProtected(incoming)) {
      if (incoming && (!state.pendingLatestCallRecord || buildCallDisplaySignature(incoming) !== buildCallDisplaySignature(state.pendingLatestCallRecord))) {
        state.pendingLatestCallRecord = incoming;
      }
      if (newBanner) newBanner.hidden = false;
      if (state.pinnedCallRecord && lastCallCardLang !== currentPanelLanguage) {
        applyLatestCallRecordToDom(state.pinnedCallRecord, { playAnim: false });
        lastCallCardLang = currentPanelLanguage;
      }
      syncLatestCallDetailsVisibility();
      return;
    }

    if (newBanner) newBanner.hidden = true;
    state.pendingLatestCallRecord = null;

    const nextSig = buildCallDisplaySignature(target);
    const langChanged = lastCallCardLang !== currentPanelLanguage;
    if (nextSig === state.displayedCallSig && !langChanged) {
      syncLatestCallDetailsVisibility();
      return;
    }

    const hadPrev = Boolean(state.displayedCallRecord);
    const isRealReplacement = hadPrev && nextSig !== state.lastAnimatedCallSig && target.status !== 'streaming';
    const shouldAnimate = !skipAnim && isRealReplacement && nextSig !== state.displayedCallSig;

    state.displayedCallRecord = target;
    state.displayedCallSig = nextSig;
    if (target.status !== 'streaming') {
      state.lastAnimatedCallSig = nextSig;
    }
    lastCallCardLang = currentPanelLanguage;
    applyLatestCallRecordToDom(target, { playAnim: shouldAnimate });
    syncLatestCallDetailsVisibility();
  }

  function createDeltaBadgeEl(deltaVal, isMaxJump = false) {
    if (deltaVal === null || deltaVal === undefined || isNaN(deltaVal)) return null;
    const n = Number(deltaVal);
    const pill = document.createElement('span');
    const dirCls = n > 0 ? ' is-up' : (n < 0 ? ' is-down' : '');
    const jumpCls = isMaxJump ? ' is-jump' : '';
    pill.className = `timeline-delta-pill${dirCls}${jumpCls}`;
    const sign = n > 0 ? '+' : (n < 0 ? '-' : '');
    const jumpLabel = isMaxJump ? ` · ${t('session.timeline.maxJumpBadge')}` : '';
    pill.textContent = `Δ ${sign}${short(Math.abs(n))}${jumpLabel}`;
    return pill;
  }

  function renderTimelineInsightTabBody(tl, bodyEl) {
    if (!bodyEl) return;
    const prevBodyScroll = Number(bodyEl.scrollTop || 0);
    bodyEl.replaceChildren();
    const tab = state.timelineInsightTab || 'turns';

    if (tab === 'timing') {
      const tm = tl?.timingSummary;
      if (!tm || tm.activeWallSec <= 0) {
        const empty = document.createElement('div');
        empty.className = 'timeline-turn-meta';
        empty.textContent = t('session.timeline.timingEmpty');
        bodyEl.appendChild(empty);
        return;
      }
      const wallLine = document.createElement('div');
      wallLine.className = 'timeline-turn-meta';
      const fmtDur = (sec) => (formatHumanDuration ? formatHumanDuration(sec, currentPanelLanguage) : `${sec}s`);
      const wallTxt = tm.wallClockActiveSec > 0 ? fmtDur(tm.wallClockActiveSec) : fmtDur(tm.activeWallSec);
      const cumTxt = tm.cumulativeTaskSec > 0 ? fmtDur(tm.cumulativeTaskSec) : wallTxt;
      wallLine.textContent = (tm.hasConcurrentCalls && tm.cumulativeTaskSec > tm.wallClockActiveSec + 0.05)
        ? t('session.timing.wallVsCum', { wall: wallTxt, cum: cumTxt })
        : t('session.timeline.timingWall', { wall: wallTxt });
      bodyEl.appendChild(wallLine);

      const bar = document.createElement('div');
      bar.className = 'tl-timing-bar';
      const mkSeg = (cls, pct) => {
        const s = document.createElement('div');
        s.className = cls;
        s.style.width = `${Math.max(0, Math.min(100, Number(pct) || 0))}%`;
        return s;
      };
      bar.appendChild(mkSeg('tl-timing-seg-ttft', tm.ttftPct));
      bar.appendChild(mkSeg('tl-timing-seg-stream', tm.streamingPct));
      bar.appendChild(mkSeg('tl-timing-seg-tool', tm.toolExecPct));
      bodyEl.appendChild(bar);

      const stages = [
        { label: `${t('session.timeline.timingTtft')} (${tm.ttftCount})`, val: `${tm.totalTtftSec}s · ${tm.ttftPct}%` },
        { label: `${t('session.timeline.timingStream')} (${tm.streamingCount})`, val: `${tm.totalStreamingSec}s · ${tm.streamingPct}%` },
        { label: `${t('session.timeline.timingTool')} (${tm.toolExecCount}${tm.toolExecEstimated ? ' est.' : ''})`, val: `${tm.totalToolExecSec}s · ${tm.toolExecPct}%` }
      ];
      for (const st of stages) {
        const row = document.createElement('div');
        row.className = 'tl-insight-row';
        const l = document.createElement('span'); l.textContent = st.label;
        const r = document.createElement('span'); r.className = 'tl-tag-stat'; r.textContent = st.val;
        row.appendChild(l); row.appendChild(r);
        bodyEl.appendChild(row);
      }
      const tsDecl = document.createElement('div');
      tsDecl.className = 'timeline-turn-meta';
      tsDecl.textContent = t('session.timing.missingTsNote');
      bodyEl.appendChild(tsDecl);
      return;
    }

    if (tab === 'files') {
      const allFiles = Array.isArray(tl?.fileActivities) ? tl.fileActivities : [];
      if (allFiles.length === 0) {
        const empty = document.createElement('div');
        empty.className = 'timeline-turn-meta';
        empty.textContent = t('session.timeline.filesEmpty');
        bodyEl.appendChild(empty);
        return;
      }
      const filterRow = document.createElement('div');
      filterRow.className = 'tl-insight-filter-row';
      for (const [fKey, lblKey] of [['all', 'session.timeline.filterAll'], ['read', 'session.timeline.filterRead'], ['write', 'session.timeline.filterWrite'], ['search', 'session.timeline.filterSearch']]) {
        const chip = document.createElement('button');
        chip.type = 'button';
        chip.className = `tl-filter-chip${state.timelineFileFilter === fKey ? ' active' : ''}`;
        chip.textContent = t(lblKey);
        chip.addEventListener('click', () => { state.timelineFileFilter = fKey; renderSessionTimeline(); });
        filterRow.appendChild(chip);
      }
      const qInput = document.createElement('input');
      qInput.type = 'text';
      qInput.className = 'tl-filter-input';
      qInput.value = state.timelineFileQuery || '';
      qInput.placeholder = t('session.timeline.fileSearchPh');
      qInput.addEventListener('input', (e) => {
        state.timelineFileQuery = e.target.value || '';
        renderSessionTimeline();
      });
      filterRow.appendChild(qInput);
      bodyEl.appendChild(filterRow);

      const q = (state.timelineFileQuery || '').trim().toLowerCase();
      const filtered = allFiles.filter(f => {
        if (state.timelineFileFilter === 'read' && !(f.readCount > 0)) return false;
        if (state.timelineFileFilter === 'write' && !(f.writeCount > 0)) return false;
        if (state.timelineFileFilter === 'search' && !(f.searchCount > 0)) return false;
        if (q && !String(f.path || '').toLowerCase().includes(q) && !String(f.basename || '').toLowerCase().includes(q)) return false;
        return true;
      });
      for (const f of filtered.slice(0, 60)) {
        const row = document.createElement('div');
        row.className = 'tl-insight-row';
        const main = document.createElement('div');
        main.className = 'tl-insight-row-main';
        const nameEl = document.createElement('span');
        nameEl.className = 'tl-insight-path';
        const safePath = typeof sanitizeCompositionPreview === 'function' ? sanitizeCompositionPreview(f.path || f.basename, 110) : (f.path || f.basename);
        nameEl.textContent = f.basename || safePath;
        nameEl.title = safePath;
        main.appendChild(nameEl);

        const statEl = document.createElement('span');
        statEl.className = 'tl-tag-stat';
        const ops = [
          f.readCount ? `R${f.readCount}` : '',
          f.writeCount ? `W${f.writeCount}` : '',
          f.searchCount ? `S${f.searchCount}` : ''
        ].filter(Boolean).join(' ');
        const linesTxt = (f.addedLines || f.removedLines) ? ` +${f.addedLines}/-${f.removedLines}` : '';
        const tTxt = Array.isArray(f.turnNumbers) && f.turnNumbers.length ? ` · T${f.turnNumbers.join(',')}` : '';
        statEl.textContent = `${ops}${linesTxt}${tTxt}`;
        row.appendChild(main);
        row.appendChild(statEl);
        const targetTurn = Array.isArray(f.turnNumbers) && f.turnNumbers.length ? f.turnNumbers[f.turnNumbers.length - 1] : null;
        if (targetTurn != null || f.lastStepIndex != null) {
          row.classList.add('is-clickable');
          const jBtn = document.createElement('button');
          jBtn.type = 'button';
          jBtn.className = 'ctx-jump-step-btn';
          jBtn.textContent = targetTurn != null ? `T${targetTurn}` : `S${f.lastStepIndex}`;
          jBtn.addEventListener('click', (ev) => {
            ev?.stopPropagation?.();
            jumpToStepOrTurn({ turnIndex: targetTurn, stepIndex: f.lastStepIndex ?? null, timelineTab: 'turns' });
          });
          row.appendChild(jBtn);
        }
        bodyEl.appendChild(row);
      }
      if (prevBodyScroll > 0) bodyEl.scrollTop = prevBodyScroll;
      return;
    }

    if (tab === 'commands') {
      const allCmds = Array.isArray(tl?.commandExecutions) ? tl.commandExecutions : [];
      if (allCmds.length === 0) {
        const empty = document.createElement('div');
        empty.className = 'timeline-turn-meta';
        empty.textContent = t('session.timeline.commandsEmpty');
        bodyEl.appendChild(empty);
        return;
      }
      const topProgs = Array.isArray(tl?.commandSummary?.topPrograms) ? tl.commandSummary.topPrograms : [];
      if (topProgs.length > 0) {
        const progLine = document.createElement('div');
        progLine.className = 'timeline-turn-meta';
        progLine.style.marginBottom = '4px';
        progLine.textContent = t('session.audit.topPrograms', {
          list: topProgs.slice(0, 5).map(p => `${p.program}×${p.count}`).join(', ')
        });
        bodyEl.appendChild(progLine);
      }
      const filterRow = document.createElement('div');
      filterRow.className = 'tl-insight-filter-row';
      for (const [cKey, lblKey] of [['all', 'session.timeline.filterAll'], ['failed', 'session.timeline.filterFailed'], ['slow', 'session.timeline.filterSlow'], ['bg', 'session.timeline.filterBg']]) {
        const chip = document.createElement('button');
        chip.type = 'button';
        chip.className = `tl-filter-chip${state.timelineCmdFilter === cKey ? ' active' : ''}`;
        chip.textContent = t(lblKey);
        chip.addEventListener('click', () => { state.timelineCmdFilter = cKey; renderSessionTimeline(); });
        filterRow.appendChild(chip);
      }
      const qInput = document.createElement('input');
      qInput.type = 'text';
      qInput.className = 'tl-filter-input';
      qInput.value = state.timelineCmdQuery || '';
      qInput.placeholder = t('session.timeline.cmdSearchPh');
      qInput.addEventListener('input', (e) => {
        state.timelineCmdQuery = e.target.value || '';
        renderSessionTimeline();
      });
      filterRow.appendChild(qInput);
      bodyEl.appendChild(filterRow);

      const q = (state.timelineCmdQuery || '').trim().toLowerCase();
      const filtered = allCmds.slice().reverse().filter(c => {
        if (state.timelineCmdFilter === 'failed' && c.status !== 'failed') return false;
        if (state.timelineCmdFilter === 'slow' && !c.isSlow) return false;
        if (state.timelineCmdFilter === 'bg' && !c.isBackground) return false;
        if (q && !String(c.command || '').toLowerCase().includes(q) && !String(c.program || '').toLowerCase().includes(q)) return false;
        return true;
      });
      for (const c of filtered.slice(0, 50)) {
        const row = document.createElement('div');
        row.className = 'tl-insight-row is-clickable';
        const main = document.createElement('div');
        main.className = 'tl-insight-row-main';
        const progTag = document.createElement('span');
        progTag.className = 'timeline-delta-pill';
        progTag.textContent = c.program || 'cmd';
        const cmdEl = document.createElement('span');
        cmdEl.className = 'tl-insight-cmd';
        const safeCmd = typeof sanitizeCompositionPreview === 'function' ? sanitizeCompositionPreview(c.command, 130) : c.command;
        cmdEl.textContent = safeCmd;
        cmdEl.title = safeCmd;
        main.appendChild(progTag);
        main.appendChild(cmdEl);

        const statEl = document.createElement('span');
        statEl.className = `tl-tag-stat${c.status === 'failed' ? ' tl-tag-warn' : (c.isSlow ? ' tl-tag-slow' : (c.isBackground ? ' tl-tag-bg' : ''))}`;
        const flags = [c.status === 'failed' ? '✕' : '', c.isSlow ? 'SLOW' : '', c.isBackground ? 'BG' : ''].filter(Boolean).join(' ');
        const durTxt = c.durationSec != null ? `${c.durationSec}s` : '';
        const stepTxt = `${c.turnNumber != null ? `T${c.turnNumber} ` : ''}S${c.stepIndex ?? '?'}`;
        statEl.textContent = [flags, durTxt, stepTxt].filter(Boolean).join(' · ');
        row.appendChild(main);
        row.appendChild(statEl);
        if (c.turnNumber != null || c.stepIndex != null) {
          const jBtn = document.createElement('button');
          jBtn.type = 'button';
          jBtn.className = 'ctx-jump-step-btn';
          jBtn.textContent = c.turnNumber != null ? `T${c.turnNumber}` : `S${c.stepIndex}`;
          jBtn.addEventListener('click', (ev) => {
            ev?.stopPropagation?.();
            jumpToStepOrTurn({ turnIndex: c.turnNumber ?? null, stepIndex: c.stepIndex ?? null, timelineTab: 'turns' });
          });
          row.appendChild(jBtn);
        }
        bodyEl.appendChild(row);
      }
      if (prevBodyScroll > 0) bodyEl.scrollTop = prevBodyScroll;
      return;
    }

    if (tab === 'fleet') {
      const fleet = tl?.agentFleetSummary;
      if (!fleet || !fleet.mainAgent) {
        const empty = document.createElement('div');
        empty.className = 'timeline-turn-meta';
        empty.textContent = t('session.timeline.empty');
        bodyEl.appendChild(empty);
        return;
      }
      const note = document.createElement('div');
      note.className = 'timeline-turn-meta';
      note.textContent = t('session.timeline.fleetSummary', {
        main: short(fleet.mainOnlyTotalTokens || 0),
        fleet: short(fleet.fleetCombinedTotalTokens || 0)
      });
      bodyEl.appendChild(note);

      const mkAgentRow = (label, a, isSub = false) => {
        const row = document.createElement('div');
        row.className = 'tl-insight-row';
        const l = document.createElement('span');
        const relTag = isSub && (a.parentStepIndex == null && a.confidence === 'unknown')
          ? ` [${t('session.audit.subUnknownRel')}]`
          : (isSub && a.parentStepIndex != null ? ` @S${a.parentStepIndex}` : '');
        const mbStr = Array.isArray(a.modelBreakdown) && a.modelBreakdown.length
          ? a.modelBreakdown.map(m => `${m.modelLabel}(${m.callCount}/${short(m.totalTokens)})`).join(', ')
          : (a.models?.length ? a.models.join(', ') : '');
        l.textContent = `${label}${relTag}${mbStr ? ` · ${mbStr}` : ''}`;
        const r = document.createElement('span');
        r.className = 'tl-tag-stat';
        r.textContent = `${a.callCount} calls · ${short(a.totalTokens)} tok${a.streamingSec ? ` · ${a.streamingSec}s` : ''}`;
        row.appendChild(l);
        row.appendChild(r);
        if (isSub && a.parentStepIndex != null) {
          const jBtn = document.createElement('button');
          jBtn.type = 'button';
          jBtn.className = 'ctx-jump-step-btn';
          jBtn.textContent = `S${a.parentStepIndex}`;
          jBtn.addEventListener('click', () => jumpToStepOrTurn({ stepIndex: a.parentStepIndex, timelineTab: 'turns' }));
          row.appendChild(jBtn);
        }
        bodyEl.appendChild(row);
      };
      mkAgentRow(t('session.timeline.fleetMain'), fleet.mainAgent, false);
      for (const sa of (fleet.subagents || [])) {
        mkAgentRow(`${t('session.latestCall.agentSub')} ${sa.type || sa.role || sa.childCid}`, sa, true);
      }
      if (fleet.unlinkedCount > 0) {
        const un = document.createElement('div');
        un.className = 'timeline-turn-meta';
        un.textContent = t('session.timeline.fleetUnlinked', { n: fleet.unlinkedCount });
        bodyEl.appendChild(un);
      }
      const collabList = Array.isArray(fleet.collaborationTimeline) ? fleet.collaborationTimeline : [];
      if (collabList.length > 0) {
        const collabHdr = document.createElement('div');
        collabHdr.className = 'timeline-turn-meta';
        collabHdr.style.marginTop = '6px';
        collabHdr.textContent = t('session.timeline.fleetCollabTitle', { n: collabList.length });
        bodyEl.appendChild(collabHdr);
        for (const ev of collabList.slice(0, 35)) {
          const row = document.createElement('div');
          row.className = 'tl-insight-row is-clickable';
          const l = document.createElement('span');
          l.textContent = `S${ev.stepIndex ?? '?'} · [${ev.role || ev.kind}] ${ev.detail || ''}`;
          const r = document.createElement('span');
          r.className = 'tl-tag-stat';
          r.textContent = ev.modelLabel || ev.status || '';
          row.appendChild(l);
          row.appendChild(r);
          row.addEventListener('click', () => jumpToStepOrTurn({ stepIndex: ev.stepIndex, callId: ev.callId, timelineTab: 'turns' }));
          bodyEl.appendChild(row);
        }
      }
      const tasks = Array.isArray(fleet.taskEvents) ? fleet.taskEvents : [];
      const taskHdr = document.createElement('div');
      taskHdr.className = 'timeline-turn-meta';
      taskHdr.style.marginTop = '6px';
      taskHdr.textContent = t('session.timeline.fleetTasksTitle', { n: tasks.length });
      bodyEl.appendChild(taskHdr);
      if (tasks.length === 0) {
        const emptyTask = document.createElement('div');
        emptyTask.className = 'timeline-turn-meta';
        emptyTask.textContent = t('session.timeline.fleetTasksEmpty');
        bodyEl.appendChild(emptyTask);
      } else {
        for (const te of tasks.slice(0, 25)) {
          const row = document.createElement('div');
          row.className = 'tl-insight-row';
          const l = document.createElement('span');
          l.textContent = `S${te.stepIndex ?? '?'} · [${te.toolName}] ${te.summary || ''}`;
          const r = document.createElement('span');
          r.className = 'tl-tag-stat';
          r.textContent = te.status || 'completed';
          row.appendChild(l);
          row.appendChild(r);
          bodyEl.appendChild(row);
        }
      }
      if (prevBodyScroll > 0) bodyEl.scrollTop = prevBodyScroll;
    }
  }

  function syncTrendControlButtons() {
    const mode = state.contextTrendMode === 'delta' ? 'delta' : 'total';
    const gran = state.contextTrendGranularity === 'turn' ? 'turn' : 'step';
    setPillActive(el('ctx-trend-mode-total'), mode === 'total');
    setPillActive(el('ctx-trend-mode-delta'), mode === 'delta');
    el('ctx-trend-mode-total')?.setAttribute?.('aria-pressed', mode === 'total' ? 'true' : 'false');
    el('ctx-trend-mode-delta')?.setAttribute?.('aria-pressed', mode === 'delta' ? 'true' : 'false');
    setPillActive(el('ctx-trend-gran-step'), gran === 'step');
    setPillActive(el('ctx-trend-gran-turn'), gran === 'turn');
    el('ctx-trend-gran-step')?.setAttribute?.('aria-pressed', gran === 'step' ? 'true' : 'false');
    el('ctx-trend-gran-turn')?.setAttribute?.('aria-pressed', gran === 'turn' ? 'true' : 'false');
  }

  function syncTimelineSortAndDeltaUi() {
    const isTurnsTab = (state.timelineInsightTab || 'turns') === 'turns';
    const deltaBtnEl = el('btn-timeline-delta-mode');
    if (deltaBtnEl) {
      deltaBtnEl.setAttribute?.('aria-pressed', state.timelineDeltaOnly ? 'true' : 'false');
      deltaBtnEl.textContent = state.timelineDeltaOnly ? t('session.timeline.deltaModeOnly') : t('session.timeline.deltaModeAll');
      deltaBtnEl.hidden = !isTurnsTab;
    }
    const sortGrp = el('timeline-sort-group');
    if (sortGrp) {
      sortGrp.hidden = !isTurnsTab;
      const curSort = state.timelineSortOrder || 'newest';
      sortGrp.querySelectorAll?.('[data-tl-sort]').forEach(btn => {
        const active = btn.getAttribute('data-tl-sort') === curSort;
        btn.classList?.toggle?.('active', active);
        btn.setAttribute?.('aria-pressed', active ? 'true' : 'false');
      });
    }
  }

  function resolveTrendTimelineSource() {
    if (state.sessionTimeline && Array.isArray(state.sessionTimeline.turns) && state.sessionTimeline.turns.length > 0) {
      return state.sessionTimeline;
    }
    const liveCalls = Array.isArray(state.sessionCalls) ? state.sessionCalls : [];
    if (liveCalls.length > 0 && typeof groupSessionCallsByTurns === 'function') {
      const configs = state.cascadeModelConfigs || state.scan?.cascadeModelConfigs || [];
      return groupSessionCallsByTurns([], liveCalls, { cascadeId: state.route || '', cascadeModelConfigs: configs });
    }
    return state.sessionTimeline || null;
  }

  function findMatchingCallForTrendPoint(timelineSrc, pt) {
    if (!pt) return null;
    const allCalls = [];
    if (Array.isArray(timelineSrc?.turns)) {
      for (const turn of timelineSrc.turns) {
        if (Array.isArray(turn?.calls)) allCalls.push(...turn.calls);
      }
    }
    if (Array.isArray(state.sessionCalls)) {
      for (const c of state.sessionCalls) {
        if (c) allCalls.push(c);
      }
    }
    if (pt.callId) {
      const byId = allCalls.find(c => c && String(c.callId || '') === String(pt.callId));
      if (byId) return byId;
    }
    if (pt.stepIndex != null) {
      const byStep = allCalls.find(c => c && c.stepIndex === pt.stepIndex && (pt.turnIndex == null || c.turnIndex == null || c.turnIndex === pt.turnIndex));
      if (byStep) return byStep;
    }
    return null;
  }

  // =========================================================================
  // 4 行 Bento 当前会话分析工作台 (容器宽屏自适应 / 双轨 / 树 / 耗时并发 / 钻取)
  // =========================================================================
  const CTX_COMP_CATEGORIES = [
    { key: 'system', color: '#F472B6', labelKey: 'session.comp.cat.system', overlapped: false },
    { key: 'definitions', color: '#FACC15', labelKey: 'session.comp.cat.definitions', overlapped: false },
    { key: 'injections', color: '#F472B6', labelKey: 'session.comp.cat.injections', overlapped: true },
    { key: 'skills', color: '#F6DF45', labelKey: 'session.comp.cat.skills', overlapped: true },
    { key: 'summaries', color: '#22E09B', labelKey: 'session.comp.cat.summaries', overlapped: false },
    { key: 'user', color: '#3B82F6', labelKey: 'session.comp.cat.user', overlapped: false },
    { key: 'assistant', color: '#10B981', labelKey: 'session.comp.cat.assistant', overlapped: false },
    { key: 'thinking', color: '#22E09B', labelKey: 'session.comp.cat.thinking', overlapped: false },
    { key: 'tools', color: '#FB923C', labelKey: 'session.comp.cat.tools', overlapped: false }
  ];
  const CTX_COMP_COLOR_MAP = Object.fromEntries(CTX_COMP_CATEGORIES.map(c => [c.key, c.color]));

  var panelResizeObserver = null;
  var lastObservedPanelBox = { w: 0, h: 0 };
  function measureContextPanelContainerWidth() {
    if (Number.isFinite(Number(state.forcedPanelWidthForTest)) && Number(state.forcedPanelWidthForTest) > 0) {
      return Number(state.forcedPanelWidthForTest);
    }
    const pEl = el('panel');
    if (pEl) {
      if (typeof pEl.getBoundingClientRect === 'function') {
        const r = pEl.getBoundingClientRect();
        if (r && Number(r.width) > 0) return Number(r.width);
      }
      if (Number(pEl.clientWidth) > 0) return Number(pEl.clientWidth);
    }
    const effectiveDock = host.getAttribute?.('data-dock') || dockPosition;
    if (effectiveDock === 'aux') {
      // 优先读取插件自身 host 宽度；三栏并排时严禁误读整个 auxEl（插件+浏览器合宽）
      if (host && typeof host.getBoundingClientRect === 'function') {
        const hr = host.getBoundingClientRect();
        if (hr && Number(hr.width) > 0) return Number(hr.width);
      }
      if (auxViewTab === 'both' && Number(auxPluginSharePx) > 0) {
        return Number(auxPluginSharePx);
      }
      const auxEl = findAuxSidebarContainer();
      if (auxEl) {
        if (typeof auxEl.getBoundingClientRect === 'function') {
          const ar = auxEl.getBoundingClientRect();
          if (ar && Number(ar.width) > 0) return Number(ar.width);
        }
        if (Number(auxEl.clientWidth) > 0) return Number(auxEl.clientWidth);
      }
    }
    return 472;
  }

  function syncContextPanelContainerWidthTier(forceSync = false) {
    const pEl = el('panel');
    if (!pEl) return 'narrow';
    if (!panelResizeObserver && typeof ResizeObserver !== 'undefined') {
      try {
        panelResizeObserver = new ResizeObserver((entries) => {
          if (state.disposed || wsActiveDragging) return;
          let curW = 0;
          let curH = 0;
          for (const entry of (entries || [])) {
            curW = Math.round(entry?.contentRect?.width || pEl.clientWidth || 0);
            curH = Math.round(entry?.contentRect?.height || pEl.clientHeight || 0);
          }
          const becameNonZero = (lastObservedPanelBox.w === 0 || lastObservedPanelBox.h === 0) && curW > 0 && curH > 0;
          const widthShifted = curW > 0 && Math.abs(curW - lastObservedPanelBox.w) >= 4;
          const deferredChart = Boolean(el('ctx-trend-card')?.getAttribute?.('data-om-deferred-chart') === 'true');
          lastObservedPanelBox = { w: curW, h: curH };
          const prevTier = state.ctxWidthTier;
          const prevAuxTier = state.auxBentoTier;
          const nextTier = syncContextPanelContainerWidthTier();
          if ((becameNonZero || widthShifted || deferredChart || prevTier !== nextTier || prevAuxTier !== state.auxBentoTier) && !pEl.hidden && activeContextTab === 'session') {
            if (typeof applyCockpitLayoutToDom === 'function') applyCockpitLayoutToDom({ renderManager: false });
            if (panelTrendResizeTimer) clearTimeout(panelTrendResizeTimer);
            panelTrendResizeTimer = setTimeout(() => {
              panelTrendResizeTimer = null;
              if (!state.disposed && !wsActiveDragging && !pEl.hidden && activeContextTab === 'session') {
                renderContextTrendCard();
                if (typeof renderSessionBentoSections === 'function') renderSessionBentoSections();
              }
            }, becameNonZero || deferredChart ? 16 : 120);
          }
        });
        panelResizeObserver.observe(pEl);
        activeDisposers.add(() => {
          try { panelResizeObserver?.disconnect?.(); } catch { }
          panelResizeObserver = null;
        });
      } catch { }
    }
    // 拖拽分隔线期间延迟切换 data-ctx-width-tier / data-aux-tier，杜绝每帧触发整棵 Shadow DOM（2500+ 节点）RecalcStyle 风暴
    if (wsActiveDragging && !forceSync) {
      return state.ctxWidthTier || 'narrow';
    }
    const w = measureContextPanelContainerWidth();
    const tier = w >= 1180 ? 'xl' : (w >= 860 ? 'wide' : (w >= 560 ? 'medium' : 'narrow'));
    const auxTier = w >= 680 ? 'wide' : (w >= 440 ? 'medium' : 'narrow');
    state.ctxWidthTier = tier;
    state.auxBentoTier = auxTier;
    if (pEl.getAttribute?.('data-ctx-width-tier') !== tier) {
      pEl.setAttribute?.('data-ctx-width-tier', tier);
    }
    if (pEl.getAttribute?.('data-aux-tier') !== auxTier) {
      pEl.setAttribute?.('data-aux-tier', auxTier);
    }
    if (host?.getAttribute?.('data-aux-tier') !== auxTier) {
      host?.setAttribute?.('data-aux-tier', auxTier);
    }
    const tierBadge = el('dock-aux-tier-badge');
    if (tierBadge) {
      const badgeKey = auxTier === 'wide'
        ? 'settings.dock.auxTierWide'
        : (auxTier === 'medium' ? 'settings.dock.auxTierMedium' : 'settings.dock.auxTierNarrow');
      const nextText = t(badgeKey);
      if (tierBadge.textContent !== nextText) tierBadge.textContent = nextText;
      if (tierBadge.getAttribute?.('data-tier') !== auxTier) tierBadge.setAttribute?.('data-tier', auxTier);
    }
    return tier;
  }

  function highlightCompositionCategory(catKey) {
    state.ctxHoveredCategory = catKey || null;
    const applyCls = (containerId, attrName) => {
      const box = el(containerId);
      if (!box) return;
      const kids = Array.from(box.children || []);
      for (const ch of kids) {
        const k = ch.getAttribute?.(attrName);
        if (!k) continue;
        if (!catKey) {
          ch.classList?.remove?.('is-hovered', 'is-dimmed');
        } else if (k === catKey) {
          ch.classList?.add?.('is-hovered');
          ch.classList?.remove?.('is-dimmed');
        } else {
          ch.classList?.remove?.('is-hovered');
          ch.classList?.add?.('is-dimmed');
        }
      }
    };
    applyCls('ctx-main-segments', 'data-comp-cat');
    applyCls('ctx-subtrack-comp', 'data-comp-cat');
    applyCls('ctx-comp-legend', 'data-comp-cat');
  }

  function focusCompositionTreeCategory(catKey) {
    if (!catKey) return;
    if (!state.expandedTreeCats) state.expandedTreeCats = new Set();
    state.expandedTreeCats.add(catKey);
    state.ctxFocusedTreeCat = catKey;
    renderSessionBentoSections();
    try {
      const node = el('ctx-composition-tree-list')?.querySelector?.(`[data-tree-cat="${catKey}"]`);
      node?.scrollIntoView?.({ block: 'nearest', behavior: 'smooth' });
    } catch { }
  }

  function collectOrderedSessionCallsForCompare(timelineSrc) {
    const map = new Map();
    if (Array.isArray(timelineSrc?.turns)) {
      for (const t of timelineSrc.turns) {
        for (const c of (t?.calls || [])) {
          if (c && c.agentRole !== 'subagent') {
            const key = c.callId || `s:${c.stepIndex}:${c.timestamp}`;
            map.set(key, { ...c, turnIndex: c.turnIndex ?? t.turnIndex ?? null });
          }
        }
      }
    }
    if (Array.isArray(state.sessionCalls)) {
      for (const c of state.sessionCalls) {
        if (c && c.agentRole !== 'subagent') {
          const key = c.callId || `s:${c.stepIndex}:${c.timestamp}`;
          if (!map.has(key)) map.set(key, c);
        }
      }
    }
    return Array.from(map.values()).sort((a, b) => {
      const sa = Number.isInteger(Number(a.stepIndex)) ? Number(a.stepIndex) : Number.MAX_SAFE_INTEGER;
      const sb = Number.isInteger(Number(b.stepIndex)) ? Number(b.stepIndex) : Number.MAX_SAFE_INTEGER;
      if (sa !== sb) return sa - sb;
      return (Number(a.timestamp) || 0) - (Number(b.timestamp) || 0);
    });
  }

  function resolveSelectedAndBaselineCall() {
    const tl = resolveTrendTimelineSource();
    const calls = collectOrderedSessionCallsForCompare(tl);
    const incoming = resolveLatestSessionCallRecord();
    const activeCall = state.pinnedCallRecord || incoming || (calls.length ? calls[calls.length - 1] : null);
    const isPinned = Boolean(state.pinnedCallRecord || state.selectedTrendCallId);

    let activeIdx = -1;
    if (activeCall) {
      activeIdx = calls.findIndex(c =>
        (activeCall.callId && c.callId === activeCall.callId)
        || (activeCall.stepIndex != null && c.stepIndex === activeCall.stepIndex)
      );
    }
    if (activeIdx < 0 && calls.length > 0 && !isPinned) activeIdx = calls.length - 1;

    let baseCall = null;
    if (activeIdx > 0) {
      if (state.ctxCompareBase === 'prev_turn') {
        const curTurn = activeCall?.turnIndex ?? null;
        for (let i = activeIdx - 1; i >= 0; i--) {
          if (curTurn != null && calls[i].turnIndex != null && calls[i].turnIndex < curTurn) {
            baseCall = calls[i];
            break;
          }
        }
        if (!baseCall) baseCall = calls[activeIdx - 1];
      } else {
        baseCall = calls[activeIdx - 1];
      }
    }
    return {
      tl,
      calls,
      activeCall,
      baseCall,
      isPinned,
      targetStepIndex: (activeCall?.stepIndex !== null && activeCall?.stepIndex !== undefined && activeCall?.stepIndex !== '' && Number.isInteger(Number(activeCall.stepIndex))) ? Number(activeCall.stepIndex) : null,
      compareStepIndex: (baseCall?.stepIndex !== null && baseCall?.stepIndex !== undefined && baseCall?.stepIndex !== '' && Number.isInteger(Number(baseCall.stepIndex))) ? Number(baseCall.stepIndex) : null
    };
  }

  function jumpToStepOrTurn({ stepIndex = null, turnIndex = null, callId = null, timelineTab = null } = {}) {
    const tl = resolveTrendTimelineSource();
    const turns = Array.isArray(tl?.turns) ? tl.turns : [];
    let matchedCall = null;
    const allCalls = collectOrderedSessionCallsForCompare(tl);
    if (callId) matchedCall = allCalls.find(c => String(c.callId || '') === String(callId)) || null;
    if (!matchedCall && stepIndex != null) {
      matchedCall = allCalls.find(c => Number(c.stepIndex) === Number(stepIndex))
        || allCalls.find(c => c.stepIndex != null && Number(c.stepIndex) >= Number(stepIndex))
        || null;
    }
    if (!matchedCall && turnIndex != null) {
      const tObj = turns.find(t => Number(t.turnIndex) === Number(turnIndex));
      if (tObj && Array.isArray(tObj.calls) && tObj.calls.length) {
        matchedCall = tObj.calls[tObj.calls.length - 1];
      }
    }
    if (matchedCall) {
      state.pinnedCallRecord = matchedCall;
      state.selectedTrendCallId = matchedCall.callId || (matchedCall.stepIndex != null ? `step:${matchedCall.stepIndex}` : null);
      state.latestCallDetailOpen = true;
    } else if (stepIndex != null) {
      state.selectedTrendCallId = `step:${stepIndex}`;
    }
    if (turnIndex != null && turns.length) {
      const targetTurn = turns.find(t => Number(t.turnIndex) === Number(turnIndex));
      if (targetTurn) {
        const tk = targetTurn.turnKey || `turn-${targetTurn.turnIndex ?? 'x'}-${targetTurn.stepIndex ?? 'na'}`;
        state.expandedTurnKeys.add(tk);
      }
    }
    if (timelineTab) state.timelineInsightTab = timelineTab;
    state.historyDrawerOpen = true;
    renderContextTrendCard();
    renderLatestCallCard({ fromUserAction: true, skipAnim: true });
    renderSessionBentoSections();
    renderSessionTimeline();
    try {
      el('ctx-trend-card')?.scrollIntoView?.({ block: 'nearest', behavior: 'smooth' });
    } catch { }
  }

  function returnToLatestSessionPoint() {
    state.pinnedCallRecord = null;
    state.selectedTrendCallId = null;
    state.pendingLatestCallRecord = null;
    state.ctxFocusedTreeCat = null;
    renderContextTrendCard();
    renderLatestCallCard({ fromUserAction: true, skipAnim: true });
    renderSessionBentoSections();
    if (state.historyDrawerOpen) renderSessionTimeline();
  }

  function buildEffectiveSessionForComposition() {
    const scanSession = state.scan?.session || null;
    const tlComp = state.sessionTimeline?.compositionFromSteps || null;
    if (scanSession) {
      let next = scanSession;
      if (!scanSession.stepCompositionItems && tlComp?.stepCompositionItems) {
        next = { ...next, stepCompositionItems: tlComp.stepCompositionItems };
      }
      if (!scanSession.sequentialSlices && Array.isArray(tlComp?.sequentialSlices)) {
        next = { ...next, sequentialSlices: tlComp.sequentialSlices };
      }
      if (!scanSession.attachmentsDetail && Array.isArray(state.sessionTimeline?.attachmentsDetail)) {
        next = { ...next, attachmentsDetail: state.sessionTimeline.attachmentsDetail };
      }
      return next;
    }
    if (tlComp && !tlComp.attachmentsDetail && Array.isArray(state.sessionTimeline?.attachmentsDetail)) {
      return { ...tlComp, attachmentsDetail: state.sessionTimeline.attachmentsDetail };
    }
    return tlComp;
  }

  function renderTimingSummaryCardVisual(tl) {
    const donut = el('ctx-timing-donut');
    const concEl = el('ctx-timing-concurrency-note');
    const barEl = el('ctx-timing-stages-bar');
    const pillsEl = el('ctx-timing-stage-pills');
    const tsNoteEl = el('ctx-timing-ts-note');
    const tm = tl?.timingSummary || null;
    const sp = state.liveSpeed || state.turnState || null;

    let ttftSec = tm ? Number(tm.totalTtftSec || 0) : Number(sp?.ttft || 0);
    let streamSec = tm ? Number(tm.totalStreamingSec || 0) : Math.max(0, Number(sp?.duration || 0) - Number(sp?.ttft || 0));
    let toolSec = tm ? Number(tm.totalToolExecSec || 0) : 0;
    const sumStages = ttftSec + streamSec + toolSec;
    const wallSec = tm?.wallClockActiveSec > 0 ? Number(tm.wallClockActiveSec) : (tm?.activeWallSec > 0 ? Number(tm.activeWallSec) : sumStages);
    const cumSec = tm?.cumulativeTaskSec > 0 ? Number(tm.cumulativeTaskSec) : sumStages;

    const fmtSec = (v) => (typeof formatHumanDuration === 'function' ? formatHumanDuration(v, currentPanelLanguage) : `${Number(v || 0).toFixed(1)}s`);
    if (concEl) {
      const parts = [];
      if (wallSec > 0) {
        if (tm?.hasConcurrentCalls && cumSec > wallSec + 0.05) {
          parts.push(t('session.timing.wallVsCum', { wall: fmtSec(wallSec), cum: fmtSec(cumSec) }));
        } else {
          parts.push(t('session.timing.wallOnly', { wall: fmtSec(wallSec) }));
        }
      } else {
        parts.push('—');
      }
      if (tm?.concurrencySavedSec > 0.05 && tm?.hasConcurrentCalls) {
        parts.push(t('session.timing.savedConcurrent', { saved: fmtSec(tm.concurrencySavedSec) }));
      }
      if (tm?.isShortSample) {
        parts.push(t('session.timing.shortSample'));
      }
      concEl.textContent = parts.join(' · ');
    }

    const ttftPct = sumStages > 0 ? Math.round((ttftSec / sumStages) * 1000) / 10 : 0;
    const streamPct = sumStages > 0 ? Math.round((streamSec / sumStages) * 1000) / 10 : 0;
    const toolPct = sumStages > 0 ? Math.max(0, Math.round((100 - ttftPct - streamPct) * 10) / 10) : 0;

    if (barEl) {
      barEl.replaceChildren();
      const mkSeg = (cls, p) => {
        const s = document.createElement('div');
        s.className = cls;
        s.style.width = `${Math.max(0, Math.min(100, p))}%`;
        return s;
      };
      barEl.appendChild(mkSeg('tl-timing-seg-ttft', ttftPct));
      barEl.appendChild(mkSeg('tl-timing-seg-stream', streamPct));
      barEl.appendChild(mkSeg('tl-timing-seg-tool', toolPct));
    }

    if (pillsEl) {
      pillsEl.replaceChildren();
      const entries = [
        ['#FB923C', `${t('session.timeline.timingTtft')} ${ttftSec > 0 ? fmtSec(ttftSec) : '0s'} · ${ttftPct}%`],
        ['#3B82F6', `${t('session.timeline.timingStream')} ${streamSec > 0 ? fmtSec(streamSec) : '0s'} · ${streamPct}%`],
        ['#10B981', `${t('session.timeline.timingTool')} ${toolSec > 0 ? fmtSec(toolSec) : '0s'} · ${toolPct}%`]
      ];
      for (const [col, txt] of entries) {
        const span = document.createElement('span');
        span.style.cssText = 'display:inline-flex;align-items:center;gap:4px;';
        const dot = document.createElement('i');
        dot.style.cssText = `width:6px;height:6px;border-radius:2px;background:${col};display:inline-block;`;
        const lbl = document.createElement('span');
        lbl.textContent = txt;
        span.appendChild(dot);
        span.appendChild(lbl);
        pillsEl.appendChild(span);
      }
    }

    if (donut) {
      const r = 22;
      const circ = 2 * Math.PI * r;
      const slices = [];
      const bgCircle = createSvgEl('circle', {
        cx: '32', cy: '32', r: String(r), fill: 'none',
        stroke: 'rgba(148,163,184,0.22)', 'stroke-width': '8'
      });
      if (bgCircle) slices.push(bgCircle);
      if (sumStages > 0) {
        let offsetAcc = 0;
        for (const [col, p] of [['#FB923C', ttftPct], ['#3B82F6', streamPct], ['#10B981', toolPct]]) {
          if (p <= 0) continue;
          const dashLen = (p / 100) * circ;
          const arc = createSvgEl('circle', {
            cx: '32', cy: '32', r: String(r), fill: 'none',
            stroke: col, 'stroke-width': '8',
            'stroke-dasharray': `${dashLen.toFixed(2)} ${circ.toFixed(2)}`,
            'stroke-dashoffset': (-offsetAcc).toFixed(2),
            transform: 'rotate(-90 32 32)'
          });
          if (arc) slices.push(arc);
          offsetAcc += dashLen;
        }
      }
      const centerText = createSvgEl('text', {
        x: '32', y: '35', 'text-anchor': 'middle',
        fill: 'var(--ag-text-primary, #ececef)', 'font-size': '10', 'font-weight': '600'
      });
      if (centerText) {
        centerText.textContent = wallSec > 0 ? (wallSec >= 60 ? `${Math.round(wallSec)}s` : `${Number(wallSec.toFixed(1))}s`) : '—';
        slices.push(centerText);
      }
      if (typeof donut.replaceChildren === 'function') donut.replaceChildren(...slices);
      else {
        donut.innerHTML = '';
        slices.forEach(s => donut.appendChild?.(s));
      }
    }

    if (tsNoteEl) {
      tsNoteEl.textContent = t('session.timing.missingTsNote');
      tsNoteEl.hidden = false;
    }
  }

  function renderAuditQuickPills(tl) {
    const wrap = el('ctx-audit-quick-pills');
    if (!wrap) return;
    wrap.replaceChildren();
    const evCount = Array.isArray(tl?.contextChangeEvents) ? tl.contextChangeEvents.length : 0;
    const fileCount = Array.isArray(tl?.fileActivities) ? tl.fileActivities.length : 0;
    const cmdCount = Array.isArray(tl?.commandExecutions) ? tl.commandExecutions.length : 0;
    const fleetCount = Array.isArray(tl?.agentFleetSummary?.subagents) ? tl.agentFleetSummary.subagents.length : 0;
    const activeTab = state.timelineInsightTab || 'turns';
    const specs = [
      { key: 'turns', labelKey: 'session.audit.eventsShort', count: evCount },
      { key: 'files', labelKey: 'session.audit.filesShort', count: fileCount },
      { key: 'commands', labelKey: 'session.audit.cmdsShort', count: cmdCount },
      { key: 'fleet', labelKey: 'session.audit.fleetShort', count: fleetCount }
    ];
    for (const sp of specs) {
      const btn = document.createElement('button');
      btn.type = 'button';
      const isEmpty = sp.count === 0;
      btn.className = `ctx-audit-pill${isEmpty ? ' is-empty-collapsed' : ''}${state.historyDrawerOpen && activeTab === sp.key ? ' is-active' : ''}`;
      btn.textContent = `${t(sp.labelKey)} · ${sp.count}`;
      btn.title = isEmpty ? t('session.audit.collapsedHint', { item: t(sp.labelKey) }) : '';
      btn.addEventListener('click', () => {
        switchCockpitAuditTab(sp.key);
        renderAuditQuickPills(tl);
      });
      wrap.appendChild(btn);
    }
  }

  function getContextUsageThresholds() {
    return {
      warnThreshold: state.customWarnThreshold ?? 75,
      dangerThreshold: state.customDangerThreshold ?? 90
    };
  }

  /**
   * 阈值与分档的唯一来源：顶栏进度条与「会话总览与关键指标」#ctx-ov-pct-summary 共用。
   * 6 档：unknown（无数据） / safe <warn / moderate >=50 / warn >=warnThreshold / danger >=dangerThreshold / full >=100
   */
  const CONTEXT_USAGE_TIERS = ['unknown', 'safe', 'moderate', 'warn', 'danger', 'full'];

  function computeContextUsageTier(rawPct, thresholds = null, opts = {}) {
    const { warnThreshold, dangerThreshold } = thresholds || getContextUsageThresholds();
    if (opts.exceeded === true) return 'full';
    const pct = Number(rawPct);
    if (rawPct === null || rawPct === undefined || !Number.isFinite(pct)) return 'unknown';
    if (opts.limitValid === false) return 'unknown';
    if (pct >= 100) return 'full';
    if (pct >= Number(dangerThreshold)) return 'danger';
    if (pct >= Number(warnThreshold)) return 'warn';
    if (pct >= 50) return 'moderate';
    return 'safe';
  }

  function renderSessionRequestCosts(timeline) {
    const list = el('ctx-request-cost-rows');
    const summary = el('ctx-request-cost-summary');
    const empty = el('ctx-request-cost-empty');
    if (!list || !summary || !empty || typeof summarizeSessionRequestCosts !== 'function') return;
    const card = list.closest?.('[data-widget-id="request-cost"]');
    if (card?.hidden) return;
    const calls = state.sessionCalls?.length ? state.sessionCalls : timeline?.calls;
    const signature = [calls, currentPanelLanguage, state.route];
    if (list._costSnapshot?.every((value, index) => value === signature[index])) return;
    list._costSnapshot = signature;
    const result = summarizeSessionRequestCosts(calls);
    const money = new Intl.NumberFormat(currentPanelLanguage, { style: 'currency', currency: 'USD', maximumFractionDigits: 6 });
    const prices = result.rows.length > result.unpriced;
    empty.hidden = result.rows.length > 0;
    summary.hidden = !result.rows.length;
    list.hidden = !result.rows.length;
    summary.textContent = t('session.requestCost.total', {
      cost: prices ? money.format(result.costUSD) : '—',
      savings: prices ? money.format(result.savingsUSD) : '—',
      percent: prices ? `${(result.savingsRatio * 100).toFixed(1)}%` : '—'
    }) + (result.unpriced ? ` · ${t('session.requestCost.unpriced', { n: result.unpriced })}` : '');
    list.replaceChildren();
    let shown = 0;
    const append = () => {
      const end = Math.min(shown + 80, result.rows.length);
      for (; shown < end; shown++) {
        const row = result.rows[shown];
        const node = document.createElement('li');
        const name = document.createElement('strong');
        name.className = 'ctx-request-cost-name';
        const model = String(formatCallModelTitle(row.call) || row.call.model || '—').replace(/[（）()]/g, '');
        name.textContent = `${shown + 1} · ${model}`;
        name.title = name.textContent;
        const tokens = document.createElement('span');
        tokens.textContent = t('session.requestCost.tokens', {
          input: row.input.toLocaleString(), cache: row.cache.toLocaleString(), output: row.output.toLocaleString()
        });
        const price = document.createElement('span');
        price.textContent = t('session.requestCost.price', {
          cost: row.costUSD == null ? '—' : money.format(row.costUSD),
          savings: row.savingsUSD == null ? '—' : money.format(row.savingsUSD)
        });
        node.appendChild(name);
        node.appendChild(tokens);
        node.appendChild(price);
        list.appendChild(node);
      }
    };
    append();
    list.onscroll = () => {
      if (list.scrollHeight - list.scrollTop - list.clientHeight < 150) append();
    };
  }

  function renderSessionBentoSections(options = {}) {
    if (!el('ctx-bento-grid')) return;
    const pContext = el('panel');
    const isTest = (typeof process !== 'undefined' && Boolean(process.env?.NODE_TEST_CONTEXT)) ||
      Boolean(state.forceRenderForTest);
    if (!options?.force && !isTest && (!pContext || pContext.hidden || activeContextTab !== 'session' || isContextSettingsView)) return;
    const prevScrollTop = (pContext && typeof pContext.scrollTop === 'number') ? pContext.scrollTop : 0;
    const d = state.latest;
    const session = state.scan?.session || null;
    const { tl, activeCall, baseCall, isPinned, targetStepIndex, compareStepIndex } = resolveSelectedAndBaselineCall();
    renderSessionRequestCosts(tl);

    // 1. Row 1 会话总览与严格区分口径
    const ovTitle = el('ctx-ov-title');
    if (ovTitle) {
      const titleStr = session?.title || tl?.sessionTitle || (state.route ? state.route.slice(0, 8) : t('session.ov.noTitle'));
      ovTitle.textContent = titleStr || t('session.ov.noTitle');
      ovTitle.title = titleStr || '';
    }
    const ovModel = el('ctx-ov-model');
    if (ovModel) {
      const mName = (activeCall ? formatCallModelTitle(activeCall) : '') || d?.model || '—';
      const eff = activeCall?.effort || d?.effort || '';
      ovModel.textContent = eff && !String(mName).toLowerCase().includes(eff.toLowerCase()) ? `${mName} · ${eff}` : mName;
    }
    const ovTurnStep = el('ctx-ov-turn-step');
    if (ovTurnStep) {
      const turnN = Array.isArray(tl?.turns) && tl.turns.length > 0 ? tl.turns.length : (session?.userMessages ?? 0);
      const stepN = session?.steps ?? activeCall?.stepIndex ?? state.count ?? null;
      ovTurnStep.textContent = stepN != null
        ? t('session.ov.turnsSteps', { turns: turnN || 0, steps: stepN })
        : t('session.ov.turnsOnly', { turns: turnN || 0 });
    }

    const pinnedBanner = el('ctx-ov-pinned-banner');
    const retLatestBtn = el('btn-ctx-return-latest');
    if (retLatestBtn) retLatestBtn.hidden = !isPinned;
    if (pinnedBanner) {
      const lbl = activeCall?.stepIndex != null ? `S${activeCall.stepIndex}` : (state.selectedTrendCallId || '#');
      const pinnedTxt = isPinned ? String(t('session.ov.pinnedTag', { label: lbl }) || '').trim() : '';
      if (pinnedTxt) {
        pinnedBanner.hidden = false;
        pinnedBanner.textContent = pinnedTxt;
      } else {
        pinnedBanner.hidden = true;
        pinnedBanner.textContent = '';
      }
    }

    const activeContextTokens = isPinned && activeCall
      ? (activeCall.contextWindowTokens ?? (activeCall.hasInputCacheFields ? activeCall.totalInputTokens : null))
      : (d?.actual ?? d?.postCompactEstimate ?? d?.estimate ?? null);
    const limitVal = d?.budget || d?.serviceLimit || null;
    const isHostConfirmedWindow = Boolean(d?.serviceLimit || state.hostContextWindowUsage?.limit || (d?.actual != null && d?.budget));
    const limitSourceEl = el('ctx-ov-limit-source');
    if (limitSourceEl) {
      if (limitVal) {
        limitSourceEl.hidden = false;
        limitSourceEl.textContent = isHostConfirmedWindow ? '宿主确认窗口' : '插件配置预算';
      } else {
        limitSourceEl.hidden = true;
        limitSourceEl.textContent = '';
      }
    }
    const keyLimitEl = el('key-limit');
    if (keyLimitEl && limitVal && !d?.exceeded) {
      keyLimitEl.title = t(isHostConfirmedWindow ? 'session.ov.limitHost' : 'session.ov.limitPref', { val: short(limitVal) });
    }

    const ovCacheEl = el('ctx-ov-cache');
    if (ovCacheEl) {
      const stepHitTxt = activeCall ? formatCallCachePctText(activeCall) : '—';
      let cumHitTxt = '—';
      if (tl?.cacheSummary) {
        if (tl.cacheSummary.cacheStatus === 'zero_input') cumHitTxt = '0%';
        else if (tl.cacheSummary.cacheStatus !== 'missing' && tl.cacheSummary.cacheReadPct != null) cumHitTxt = `${tl.cacheSummary.cacheReadPct}%`;
      }
      ovCacheEl.textContent = `${stepHitTxt} / ${cumHitTxt}`;
    }

    const ovTotalEl = el('ctx-ov-total');
    if (ovTotalEl) {
      const cumTot = tl?.sessionTokenTotals?.totalTokens ?? (Array.isArray(state.sessionCalls) && state.sessionCalls.length
        ? state.sessionCalls.reduce((s, c) => s + Number(c?.totalTokens || 0), 0)
        : null);
      ovTotalEl.textContent = cumTot != null && cumTot > 0 ? short(cumTot) : (cumTot === 0 && tl?.totalCalls > 0 ? '0' : '—');
    }

    // 2. Row 2 Left: 双轨进度条与组成图例
    const effSession = buildEffectiveSessionForComposition();
    const targetSummaryForComp = {
      actual: activeContextTokens,
      budget: limitVal
    };
    const breakdown = (effSession && typeof buildSessionCompositionBreakdown === 'function')
      ? buildSessionCompositionBreakdown(effSession, targetSummaryForComp, {
        targetStepIndex: isPinned ? targetStepIndex : null,
        compareStepIndex: isPinned ? compareStepIndex : null,
        budgetTokens: limitVal
      })
      : null;

    const mainSegmentsEl = el('ctx-main-segments');
    const mainUnaccEl = el('ctx-main-unaccounted');
    const subCompEl = el('ctx-subtrack-comp');
    const subLabelEl = el('ctx-subtrack-label');
    const keySegTrack = el('key-seg-track');
    const keySegLegend = el('key-seg-legend');
    const compLegendEl = el('ctx-comp-legend');
    const ratioPill = el('ctx-comp-ratio-pill');
    const basisPill = el('ctx-comp-basis-pill');

    const { warnThreshold, dangerThreshold } = getContextUsageThresholds();

    const usedPctRaw = (activeContextTokens != null && limitVal > 0)
      ? (activeContextTokens / limitVal) * 100
      : ((d?.percent != null && Number.isFinite(Number(d.percent))) ? Number(d.percent) : null);
    const usedPctForBar = usedPctRaw != null ? Math.min(100, Math.max(0, usedPctRaw)) : null;

    let usageTier = 'unknown';
    const isExceeded = Boolean(d?.exceeded) || (usedPctRaw != null && usedPctRaw > 100);
    usageTier = computeContextUsageTier(usedPctRaw, { warnThreshold, dangerThreshold }, {
      exceeded: isExceeded,
      limitValid: limitVal > 0
    });

    const ovPctSummaryEl = el('ctx-ov-pct-summary');
    if (ovPctSummaryEl) {
      ovPctSummaryEl.setAttribute('data-usage-tier', usageTier);
      if (usedPctRaw != null && Number.isFinite(usedPctRaw) && limitVal > 0) {
        const remPct = Math.max(0, 100 - usedPctRaw);
        const tierKey = `session.ov.tier.${usageTier}`;
        ovPctSummaryEl.textContent = usageTier === 'full'
          ? `${usedPctRaw.toFixed(1)}% · ${t(tierKey)}`
          : `${usedPctRaw.toFixed(1)}% · ${t(tierKey, { pct: remPct.toFixed(1) })}`;
      } else {
        ovPctSummaryEl.textContent = '—';
      }
    }

    if (ratioPill) {
      ratioPill.textContent = usedPctForBar != null ? `${usedPctForBar.toFixed(1)}%` : '—';
    }

    const estMid = breakdown?.estimatedTotalMedian || 0;
    const unaccTok = breakdown?.unaccountedTokens || 0;
    const estExceedsActual = Boolean(breakdown?.estimateExceedsActual || (activeContextTokens != null && activeContextTokens > 0 && estMid > activeContextTokens));
    if (basisPill) {
      if (estExceedsActual && activeContextTokens != null && estMid > 0) {
        basisPill.setAttribute('data-basis', 'estimate_exceeds_actual');
        basisPill.textContent = t('session.dual.basisEstExceeds', { actual: short(activeContextTokens), est: short(estMid) });
      } else if (activeContextTokens != null && estMid > 0) {
        basisPill.setAttribute('data-basis', 'mixed');
        basisPill.textContent = t('session.dual.basisHostPlusEst', { actual: short(activeContextTokens), est: short(estMid) });
      } else if (estMid > 0) {
        basisPill.setAttribute('data-basis', 'local_estimate');
        basisPill.textContent = t('session.dual.basisEstOnly');
      } else if (activeContextTokens != null) {
        basisPill.setAttribute('data-basis', 'server_usage');
        basisPill.textContent = t('session.dual.basisHostOnly');
      } else {
        basisPill.setAttribute('data-basis', 'empty');
        basisPill.textContent = '—';
      }
    }

    const nonOverlapItems = (breakdown?.items || []).filter(it => !it.overlapped);
    const totalWindowDenom = limitVal > 0 ? limitVal : Math.max(1, activeContextTokens || estMid || 1);
    const usedDenom = Math.max(1, breakdown?.usedDenom || ((activeContextTokens != null && activeContextTokens > 0 && !estExceedsActual) ? activeContextTokens : (estMid + unaccTok)));

    if (mainSegmentsEl) {
      mainSegmentsEl.replaceChildren();
      // 主轨总宽严格遵守实报窗口比例：256K / 512K 必须为 50.00%，绝不允许估算总量 3.38M 把主轨撑成 100%
      const hasReportedRatio = activeContextTokens != null && limitVal > 0;
      const showUnaccSplit = !estExceedsActual && unaccTok > 0 && hasReportedRatio;
      const mainUsedPct = hasReportedRatio
        ? Math.min(100, Math.max(0, (activeContextTokens / limitVal) * 100))
        : (usedPctForBar != null ? usedPctForBar : Math.min(100, (estMid / totalWindowDenom) * 100));
      const mainFillPct = showUnaccSplit
        ? Math.min(mainUsedPct, Math.max(0, (estMid / totalWindowDenom) * 100))
        : mainUsedPct;
      const internalDenom = Math.max(1, estMid || activeContextTokens || 1);
      const segs = [];
      for (const it of nonOverlapItems) {
        if (!it.median || it.median <= 0) continue;
        const innerSharePct = (it.median / internalDenom) * 100;
        const block = document.createElement('div');
        block.className = 'ctx-seg-block';
        block.setAttribute('data-comp-cat', it.key);
        block.setAttribute('tabindex', '0');
        block.setAttribute('role', 'button');
        block.style.width = `${Math.max(0.4, Math.min(100, innerSharePct)).toFixed(2)}%`;
        block.style.background = CTX_COMP_COLOR_MAP[it.key] || '#94a3b8';
        const pctDisp = estExceedsActual ? it.pct : (it.pctOfUsed ?? it.pct);
        block.title = `${t(`session.comp.cat.${it.key}`)}: ${short(it.median)} · ${pctDisp}%`;
        block.setAttribute('aria-label', block.title);
        block.addEventListener('mouseenter', () => highlightCompositionCategory(it.key));
        block.addEventListener('mouseleave', () => highlightCompositionCategory(null));
        block.addEventListener('focus', () => highlightCompositionCategory(it.key));
        block.addEventListener('blur', () => highlightCompositionCategory(null));
        block.addEventListener('click', () => focusCompositionTreeCategory(it.key));
        block.addEventListener('keydown', (e) => {
          if (e.key === 'Enter' || e.key === ' ') {
            e.preventDefault();
            focusCompositionTreeCategory(it.key);
          }
        });
        segs.push(block);
      }
      mainSegmentsEl.style.width = `${Math.min(100, Math.max(0, mainFillPct)).toFixed(2)}%`;
      mainSegmentsEl.setAttribute('data-main-fill-pct', mainUsedPct.toFixed(2));
      for (const b of segs) mainSegmentsEl.appendChild(b);
    }

    if (mainUnaccEl) {
      if (!estExceedsActual && unaccTok > 0 && limitVal > 0) {
        const uPct = Math.min(100, (unaccTok / totalWindowDenom) * 100);
        mainUnaccEl.hidden = false;
        mainUnaccEl.style.width = `${Math.max(0.4, uPct).toFixed(2)}%`;
        mainUnaccEl.title = `${t('session.dual.unaccounted')}: ${short(unaccTok)}`;
      } else {
        mainUnaccEl.hidden = true;
        mainUnaccEl.style.width = '0%';
      }
    }

    // 副轨模式决策：低占用 (<25%) 默认开启「已用构成 100%」，可随时切至「缓存结构」
    const cacheTotalCheck = activeCall ? ((Number(activeCall.inputTokens) || 0) + (Number(activeCall.cacheReadTokens) || 0)) : 0;
    const effSubMode = state.ctxSubtrackMode || ((usedPctForBar !== null && usedPctForBar < 25) ? 'comp' : (cacheTotalCheck > 0 ? 'cache' : 'comp'));
    setPillActive(el('ctx-subtrack-mode-comp'), effSubMode === 'comp');
    setPillActive(el('ctx-subtrack-mode-cache'), effSubMode === 'cache');
    el('ctx-subtrack-mode-comp')?.setAttribute?.('aria-pressed', String(effSubMode === 'comp'));
    el('ctx-subtrack-mode-cache')?.setAttribute?.('aria-pressed', String(effSubMode === 'cache'));

    if (effSubMode === 'cache') {
      if (subLabelEl) subLabelEl.textContent = t('session.dual.subTitleCache');
      if (subCompEl) subCompEl.hidden = true;
      if (compLegendEl) compLegendEl.hidden = true;
      if (keySegTrack) keySegTrack.hidden = false;
      if (keySegLegend) keySegLegend.hidden = false;
      const segCall = activeCall || {};
      const segInfo = typeof computeContextSegments === 'function'
        ? computeContextSegments({
          inputTokens: segCall.inputTokens ?? 0,
          cacheCreationInputTokens: segCall.cacheCreationInputTokens ?? segCall.cache_creation_input_tokens ?? null,
          cacheReadTokens: segCall.cacheReadTokens ?? segCall.cacheTokens ?? 0,
          outputTokens: segCall.outputTokens ?? 0,
          actual: activeContextTokens ?? segCall.totalTokens ?? 0
        }, limitVal || 0)
        : null;
      if (segInfo && segInfo.usedTokens > 0) {
        if (el('key-seg-fresh')) el('key-seg-fresh').style.width = `${segInfo.freshPct}%`;
        if (el('key-seg-cache-write')) el('key-seg-cache-write').style.width = `${segInfo.cacheWritePct}%`;
        if (el('key-seg-cache-read')) el('key-seg-cache-read').style.width = `${segInfo.cacheReadPct}%`;
        if (keySegLegend) {
          keySegLegend.replaceChildren();
          const addLeg = (cHex, txt) => {
            const sp = document.createElement('span');
            sp.className = 'key-seg-legend-item';
            if (cHex) {
              const sw = document.createElement('i');
              sw.className = 'key-seg-swatch';
              sw.style.background = cHex;
              sp.appendChild(sw);
            }
            const tSpan = document.createElement('span');
            tSpan.textContent = txt;
            sp.appendChild(tSpan);
            keySegLegend.appendChild(sp);
          };
          addLeg('#38bdf8', `${t('session.dual.cacheFresh')} ${short(segInfo.freshInputTokens)}`);
          if (segInfo.hasCacheWrite && segInfo.cacheWriteTokens > 0) addLeg('#f59e0b', `${t('session.dual.cacheWrite')} ${short(segInfo.cacheWriteTokens)}`);
          addLeg('#34d399', `${t('session.dual.cacheRead')} ${short(segInfo.cacheReadTokens)}`);
        }
      } else if (keySegTrack) {
        keySegTrack.hidden = true;
      }
    } else {
      if (subLabelEl) subLabelEl.textContent = estExceedsActual ? t('session.dual.subTitleCompEst') : t('session.dual.subTitleComp');
      if (keySegTrack) keySegTrack.hidden = true;
      if (keySegLegend) keySegLegend.hidden = true;
      if (subCompEl) {
        subCompEl.hidden = false;
        subCompEl.replaceChildren();
        for (const it of nonOverlapItems) {
          if (!it.median || it.median <= 0) continue;
          const part = document.createElement('div');
          part.className = 'ctx-seg-block';
          part.setAttribute('data-comp-cat', it.key);
          part.setAttribute('tabindex', '0');
          part.setAttribute('role', 'button');
          part.style.width = `${Math.max(1, (it.median / usedDenom) * 100).toFixed(2)}%`;
          part.style.background = CTX_COMP_COLOR_MAP[it.key] || '#94a3b8';
          const pctDisp = estExceedsActual ? it.pct : (it.pctOfUsed ?? it.pct);
          part.title = `${t(`session.comp.cat.${it.key}`)}: ${short(it.median)} · ${pctDisp}%`;
          part.setAttribute('aria-label', part.title);
          part.addEventListener('mouseenter', () => highlightCompositionCategory(it.key));
          part.addEventListener('mouseleave', () => highlightCompositionCategory(null));
          part.addEventListener('focus', () => highlightCompositionCategory(it.key));
          part.addEventListener('blur', () => highlightCompositionCategory(null));
          part.addEventListener('click', () => focusCompositionTreeCategory(it.key));
          part.addEventListener('keydown', (e) => {
            if (e.key === 'Enter' || e.key === ' ') {
              e.preventDefault();
              focusCompositionTreeCategory(it.key);
            }
          });
          subCompEl.appendChild(part);
        }
        if (!estExceedsActual && unaccTok > 0) {
          const uPart = document.createElement('div');
          uPart.className = 'ctx-main-unaccounted';
          uPart.style.width = `${Math.max(1, (unaccTok / usedDenom) * 100).toFixed(2)}%`;
          uPart.title = `${t('session.dual.unaccounted')}: ${short(unaccTok)}`;
          subCompEl.appendChild(uPart);
        }
      }
      if (compLegendEl) {
        compLegendEl.hidden = false;
        compLegendEl.replaceChildren();
        const nonZeroList = [];
        const zeroList = [];
        for (const it of (breakdown?.items || [])) {
          if (it.median > 0 || it.chars > 0 || it.count > 0) nonZeroList.push(it);
          else zeroList.push(it);
        }
        const toShow = state.ctxZerosExpanded ? [...nonZeroList, ...zeroList] : nonZeroList;
        for (const it of toShow) {
          const btn = document.createElement('button');
          btn.type = 'button';
          btn.className = 'ctx-comp-leg-item';
          btn.setAttribute('data-comp-cat', it.key);
          const left = document.createElement('span');
          left.className = 'ctx-comp-leg-left';
          const dot = document.createElement('i');
          dot.className = 'key-seg-swatch';
          dot.style.background = CTX_COMP_COLOR_MAP[it.key] || '#94a3b8';
          const lbl = document.createElement('span');
          lbl.textContent = t(`session.comp.cat.${it.key}`);
          left.appendChild(dot);
          left.appendChild(lbl);

          const val = document.createElement('span');
          val.className = 'ctx-comp-leg-val';
          const pctDisp = estExceedsActual ? it.pct : (it.pctOfUsed ?? it.pct);
          val.textContent = it.median > 0 ? `${short(it.median)} · ${pctDisp}%` : '0';

          btn.appendChild(left);
          btn.appendChild(val);
          btn.addEventListener('mouseenter', () => highlightCompositionCategory(it.key));
          btn.addEventListener('mouseleave', () => highlightCompositionCategory(null));
          btn.addEventListener('focus', () => highlightCompositionCategory(it.key));
          btn.addEventListener('blur', () => highlightCompositionCategory(null));
          btn.addEventListener('click', () => focusCompositionTreeCategory(it.key));
          compLegendEl.appendChild(btn);
        }
        if (unaccTok > 0) {
          const uBtn = document.createElement('button');
          uBtn.type = 'button';
          uBtn.className = 'ctx-comp-leg-item';
          uBtn.title = t('session.dual.unaccountedTip');
          const uPct = usedDenom > 0 ? Math.round((unaccTok / usedDenom) * 1000) / 10 : 0;
          const uLeft = document.createElement('span');
          uLeft.className = 'ctx-comp-leg-left';
          const uDot = document.createElement('i');
          uDot.className = 'key-seg-swatch';
          uDot.style.background = 'repeating-linear-gradient(-45deg, #94a3b8, #94a3b8 2px, transparent 2px, transparent 4px)';
          const uLbl = document.createElement('span');
          uLbl.textContent = t('session.dual.unaccounted');
          uLeft.appendChild(uDot);
          uLeft.appendChild(uLbl);
          const uVal = document.createElement('span');
          uVal.className = 'ctx-comp-leg-val';
          uVal.textContent = `${short(unaccTok)} · ${uPct}%`;
          uBtn.appendChild(uLeft);
          uBtn.appendChild(uVal);
          compLegendEl.appendChild(uBtn);
        }
        if (zeroList.length > 0) {
          const zBtn = document.createElement('button');
          zBtn.type = 'button';
          zBtn.id = 'btn-ctx-legend-zeros';
          zBtn.className = 'ctx-comp-zeros-btn';
          zBtn.textContent = state.ctxZerosExpanded ? t('session.dual.zerosHide') : t('session.dual.zerosBtn', { n: zeroList.length });
          zBtn.addEventListener('click', () => {
            state.ctxZerosExpanded = !state.ctxZerosExpanded;
            renderSessionBentoSections();
          });
          compLegendEl.appendChild(zBtn);
        }
      }
    }

    // 3. Row 2 Right: 耗时并发图表
    renderTimingSummaryCardVisual(tl);

    // 4. Row 3 Left: 选中步骤详情与前一轮/前一步比较
    const stepCardTitleEl = el('latest-call-card-title');
    if (stepCardTitleEl) {
      stepCardTitleEl.textContent = isPinned ? t('session.stepCard.titlePinned') : t('session.stepCard.titleLatest');
    }
    setPillActive(el('btn-ctx-cmp-step'), state.ctxCompareBase !== 'prev_turn');
    setPillActive(el('btn-ctx-cmp-turn'), state.ctxCompareBase === 'prev_turn');
    const cmpSummaryEl = el('ctx-step-compare-summary');
    if (cmpSummaryEl) {
      if (activeCall && baseCall) {
        const aCtx = activeCall.contextWindowTokens ?? activeCall.totalInputTokens ?? null;
        const bCtx = baseCall.contextWindowTokens ?? baseCall.totalInputTokens ?? null;
        const ctxDelta = (aCtx != null && bCtx != null) ? aCtx - bCtx : null;
        const outDelta = (activeCall.outputTokens != null && baseCall.outputTokens != null) ? (activeCall.outputTokens - baseCall.outputTokens) : null;
        const baseTag = baseCall.stepIndex != null ? `S${baseCall.stepIndex}` : (baseCall.turnIndex != null ? `T${baseCall.turnIndex}` : '#');
        const parts = [`vs ${baseTag}`];
        if (ctxDelta !== null) parts.push(`ΔCtx ${ctxDelta > 0 ? '+' : ''}${short(ctxDelta)}`);
        if (outDelta !== null) parts.push(`ΔOut ${outDelta > 0 ? '+' : ''}${short(outDelta)}`);
        if (activeCall.cacheReadPct != null && baseCall.cacheReadPct != null) {
          const cDiff = Math.round((activeCall.cacheReadPct - baseCall.cacheReadPct) * 10) / 10;
          parts.push(`ΔCache ${cDiff > 0 ? '+' : ''}${cDiff}%`);
        }
        cmpSummaryEl.hidden = false;
        cmpSummaryEl.textContent = parts.join(' · ');
      } else {
        cmpSummaryEl.hidden = true;
        cmpSummaryEl.textContent = '';
      }
    }

    // 5. Row 3 Right: 上下文解剖台（分类树 / 顺序切片视图 / 搜索排序 / 附件视觉审计）
    if (typeof renderContextInspectorView === 'function') {
      renderContextInspectorView(breakdown, { tl, activeCall, unaccTok, usedDenom, targetStepIndex });
    } else {
      setPillActive(el('ctx-tree-mode-full'), state.ctxTreeMode !== 'delta');
      setPillActive(el('ctx-tree-mode-delta'), state.ctxTreeMode === 'delta');
    }

    // 6. Row 4 审计工作台快速胶囊、统一 6 Tab 与模块三深度分析卡片同步
    renderAuditQuickPills(tl);
    syncCockpitAuditTabUi();
    if (typeof renderExecutionTraceWidget === 'function') renderExecutionTraceWidget(tl);
    if (typeof renderAgentCollabHubWidget === 'function') renderAgentCollabHubWidget(tl);
    if (typeof renderAuditWidgetsSection === 'function') renderAuditWidgetsSection(tl, breakdown, activeCall);
    lastRenderedContextSessionUiSig = computeContextSessionUiSignature();
  }

  function syncCockpitAuditTabUi() {
    const activeTab = state.ctxCockpitTab || 'tree';
    const tabsWrap = el('ctx-cockpit-audit-tabs');
    if (tabsWrap) {
      for (const btn of Array.from(tabsWrap.querySelectorAll?.('[data-cockpit-tab]') || [])) {
        const isAct = btn.getAttribute('data-cockpit-tab') === activeTab;
        btn.classList?.toggle?.('active', isAct);
        btn.setAttribute?.('aria-selected', isAct ? 'true' : 'false');
      }
    }
    const treePanel = el('ctx-composition-tree-card');
    const treeControls = el('ctx-tree-mode-controls');
    const auditPanel = el('ctx-audit-workbench');
    const isTree = activeTab === 'tree';
    if (treePanel) treePanel.hidden = !isTree;
    if (treeControls) treeControls.hidden = !isTree;
    if (auditPanel) auditPanel.hidden = isTree;
  }

  function switchCockpitAuditTab(tabName) {
    const valid = ['tree', 'turns', 'timing', 'files', 'commands', 'fleet'];
    const next = valid.includes(tabName) ? tabName : 'tree';
    state.ctxCockpitTab = next;
    const pContext = el('panel');
    const prevScrollTop = (pContext && typeof pContext.scrollTop === 'number') ? pContext.scrollTop : 0;
    syncCockpitAuditTabUi();
    if (next !== 'tree') {
      state.historyDrawerOpen = true;
      state.timelineInsightTab = next;
      renderSessionTimeline();
      if (state.route && !state.sessionTimeline && !state.timelineLoading && typeof fetchSessionTimeline === 'function') {
        void fetchSessionTimeline(state.route, { force: !state.sessionTimeline });
      }
    }
    if (pContext && prevScrollTop > 0 && Math.abs((pContext.scrollTop || 0) - prevScrollTop) > 2) {
      pContext.scrollTop = prevScrollTop;
    }
    positionFloatingPanels();
  }

  function formatTrendInspectText(pt) {
    if (!pt) return t('session.trend.inspectHint');
    const deltaStr = pt.deltaTokens != null
      ? `${pt.deltaTokens > 0 ? '+' : ''}${short(pt.deltaTokens)}`
      : '—';
    const modelStr = pt.modelLabel ? ` · ${pt.modelLabel}` : '';
    const estMark = pt.isEstimated ? ` [${t('session.trend.basisEstimate')}]` : '';
    return t('session.trend.inspectFmt', {
      label: pt.label || `#${(pt.index || 0) + 1}`,
      total: short(pt.totalContextTokens || 0),
      delta: deltaStr,
      inp: short(pt.freshInputTokens || 0),
      cap: short(pt.cacheReadTokens || 0),
      model: `${modelStr}${estMark}`
    });
  }

  function renderContextTrendCard(options = {}) {
    const card = el('ctx-trend-card');
    if (!card) return;
    const pContext = el('panel');
    const isTest = (typeof process !== 'undefined' && Boolean(process.env?.NODE_TEST_CONTEXT)) ||
      Boolean(state.forceRenderForTest);
    if (!options?.force && !isTest && (!pContext || pContext.hidden || activeContextTab !== 'session' || isContextSettingsView)) return;
    // 禁止在 display:none 或 0x0 状态下初始化图表后不再重算：标记延迟等待 ResizeObserver 非零尺寸唤醒
    const isRealDomCard = typeof HTMLElement !== 'undefined' && pContext instanceof HTMLElement;
    if (!isTest && isRealDomCard && (Number(pContext.clientWidth) === 0 || Number(pContext.clientHeight) === 0)) {
      card.setAttribute?.('data-om-deferred-chart', 'true');
      syncContextPanelContainerWidthTier();
      return;
    }
    card.removeAttribute?.('data-om-deferred-chart');
    syncTrendControlButtons();
    const svg = el('ctx-trend-svg');
    const emptyEl = el('ctx-trend-empty');
    const badgeEl = el('ctx-trend-basis-badge');
    const truncEl = el('ctx-trend-trunc-note');
    const legendEl = el('ctx-trend-legend');
    const inspectEl = el('ctx-trend-inspect');

    const timelineSrc = resolveTrendTimelineSource();
    const fallbackEst = (state.latest?.actual == null && Number(state.latest?.estimate) > 0)
      ? Number(state.latest.estimate)
      : (state.scan?.session?.total?.low > 0 && state.latest?.actual == null ? Number(state.scan.session.total.low) : null);
    const series = typeof buildContextTrendSeries === 'function'
      ? buildContextTrendSeries(timelineSrc, {
        mode: state.contextTrendMode,
        granularity: state.contextTrendGranularity,
        compressAll: Boolean(state.trendCompressAll),
        contextChangeEvents: timelineSrc?.contextChangeEvents || [],
        maxPoints: 40,
        fallbackEstimateTokens: fallbackEst,
        fallbackModelLabel: state.latest?.model || ''
      })
      : { points: [], totalPoints: 0, truncatedCount: 0, basis: 'empty', maxTotalTokens: 0, maxAbsDeltaTokens: 0 };
    state.lastTrendSeries = series;

    if (badgeEl) {
      badgeEl.setAttribute?.('data-basis', series.basis || 'empty');
      if (series.basis === 'local_estimate') badgeEl.textContent = t('session.trend.basisEstimate');
      else if (series.basis === 'mixed') badgeEl.textContent = t('session.trend.basisMixed');
      else if (series.basis === 'server_usage') badgeEl.textContent = t('session.trend.basisServer');
      else badgeEl.textContent = '—';
    }
    if (truncEl) {
      if (series.truncatedCount > 0) {
        truncEl.hidden = false;
        truncEl.textContent = t('session.trend.truncatedNote', { shown: series.points.length, total: series.totalPoints });
      } else {
        truncEl.hidden = true;
        truncEl.textContent = '';
      }
    }
    if (legendEl) {
      legendEl.replaceChildren?.();
      const addLegend = (color, labelText) => {
        const span = document.createElement('span');
        const dot = document.createElement('span');
        dot.className = 'ctx-trend-legend-dot';
        dot.style.background = color;
        span.appendChild(dot);
        const lblSpan = document.createElement('span');
        lblSpan.textContent = labelText;
        span.appendChild(lblSpan);
        legendEl.appendChild(span);
      };
      if (series.mode === 'delta') {
        addLegend('#10B981', t('session.trend.legendDeltaPos'));
        addLegend('#FB923C', t('session.trend.legendDeltaNeg'));
      } else {
        addLegend('#10B981', t('session.trend.legendInput'));
        addLegend('#FB923C', t('session.trend.legendCache'));
      }
    }

    const pillEl = el('ctx-trend-pill');
    const pts = Array.isArray(series.points) ? series.points : [];
    if (!pts.length) {
      if (emptyEl) emptyEl.hidden = false;
      if (pillEl) pillEl.hidden = true;
      if (svg) {
        if (typeof svg.replaceChildren === 'function') svg.replaceChildren();
        else svg.innerHTML = '';
        svg.style.display = 'none';
      }
      if (inspectEl) inspectEl.textContent = t('session.trend.inspectHint');
      if (typeof renderTrendPulseExtras === 'function') renderTrendPulseExtras(series, pts, svg, timelineSrc, { displayPt: null });
      return;
    }

    if (emptyEl) emptyEl.hidden = true;
    if (svg) svg.style.display = 'block';

    let selectedPt = null;
    if (state.selectedTrendCallId) {
      selectedPt = pts.find(p => (p.callId && p.callId === state.selectedTrendCallId) || (p.stepIndex != null && `step:${p.stepIndex}` === state.selectedTrendCallId) || String(p.index) === String(state.selectedTrendCallId)) || null;
    }
    if (!selectedPt && state.pinnedCallRecord) {
      const pCid = state.pinnedCallRecord.callId;
      const pStep = state.pinnedCallRecord.stepIndex;
      selectedPt = pts.find(p => (pCid && p.callId === pCid) || (pStep != null && p.stepIndex === pStep)) || null;
    }
    const displayPt = selectedPt || pts[pts.length - 1];
    if (inspectEl) {
      inspectEl.textContent = formatTrendInspectText(displayPt);
    }
    if (pillEl) {
      const pillDelta = displayPt?.deltaTokens != null ? ` · Δ${displayPt.deltaTokens > 0 ? '+' : ''}${short(displayPt.deltaTokens)}` : '';
      pillEl.hidden = false;
      pillEl.textContent = `${displayPt?.label || `#${(displayPt?.index || 0) + 1}`} · ${short(displayPt?.totalContextTokens || 0)}${pillDelta}`;
    }
    if (!svg) return;

    const panelWrapW = el('ctx-trend-chart-wrap')?.clientWidth || 0;
    const tierDefaultW = state.ctxWidthTier === 'wide' ? 620 : (state.ctxWidthTier === 'medium' ? 480 : 360);
    const width = Math.max(320, Math.min(760, panelWrapW > 180 ? panelWrapW : tierDefaultW));
    const height = state.ctxWidthTier === 'wide' ? 128 : 114;
    const padL = 40;
    const padR = 12;
    const padT = 14;
    const padB = 20;
    const plotW = width - padL - padR;
    const plotH = height - padT - padB;
    svg.setAttribute?.('viewBox', `0 0 ${width} ${height}`);

    const nodes = [];
    const slotW = plotW / Math.max(1, pts.length);
    const barW = Math.max(3, Math.min(20, slotW * 0.66));

    const bindTrendPointEvents = (node, pt) => {
      if (!node) return;
      const onPick = () => {
        state.selectedTrendCallId = pt.callId || (pt.stepIndex != null ? `step:${pt.stepIndex}` : String(pt.index));
        if (inspectEl) inspectEl.textContent = formatTrendInspectText(pt);
        const matched = findMatchingCallForTrendPoint(timelineSrc, pt);
        if (matched) {
          state.pinnedCallRecord = matched;
          state.latestCallDetailOpen = true;
          renderLatestCallCard({ fromUserAction: true, skipAnim: true });
          renderSessionTimeline();
        }
        renderContextTrendCard();
        renderSessionBentoSections();
      };
      node.addEventListener?.('click', onPick);
      node.addEventListener?.('mouseenter', () => {
        if (typeof handleTrendPointHover === 'function') handleTrendPointHover(pt, timelineSrc);
        else if (inspectEl) inspectEl.textContent = formatTrendInspectText(pt);
      });
    };

    if (series.mode === 'delta') {
      const posMax = Math.max(0, ...pts.map(p => (p.deltaTokens != null && p.deltaTokens > 0) ? p.deltaTokens : 0));
      const negMax = Math.max(0, ...pts.map(p => (p.deltaTokens != null && p.deltaTokens < 0) ? Math.abs(p.deltaTokens) : 0));
      const span = Math.max(1000, posMax + negMax);
      let zeroY = padT + plotH;
      if (posMax > 0 && negMax > 0) {
        zeroY = Math.max(padT + 14, Math.min(padT + plotH - 14, padT + (posMax / span) * plotH));
      } else if (negMax > 0 && posMax === 0) {
        zeroY = padT + 6;
      }
      const zeroLine = createSvgEl('line', {
        x1: padL, y1: zeroY.toFixed(1), x2: width - padR, y2: zeroY.toFixed(1),
        stroke: 'rgba(148,163,184,0.45)', 'stroke-width': 1, 'stroke-dasharray': '3 2'
      });
      const zeroLbl = createSvgEl('text', {
        x: padL - 4, y: (zeroY + 3).toFixed(1), 'text-anchor': 'end',
        fill: 'var(--ag-text-muted, #8a8a94)', 'font-size': '9'
      });
      if (zeroLbl) zeroLbl.textContent = '0';
      if (posMax > 0) {
        const topLbl = createSvgEl('text', {
          x: padL - 4, y: (padT + 7).toFixed(1), 'text-anchor': 'end',
          fill: '#34d399', 'font-size': '9'
        });
        if (topLbl) topLbl.textContent = `+${short(posMax)}`;
        if (topLbl) nodes.push(topLbl);
      }
      if (negMax > 0) {
        const botLbl = createSvgEl('text', {
          x: padL - 4, y: (padT + plotH).toFixed(1), 'text-anchor': 'end',
          fill: '#f59e0b', 'font-size': '9'
        });
        if (botLbl) botLbl.textContent = `-${short(negMax)}`;
        if (botLbl) nodes.push(botLbl);
      }
      if (zeroLine) nodes.push(zeroLine);
      if (zeroLbl) nodes.push(zeroLbl);

      pts.forEach((pt, i) => {
        const cx = padL + (i + 0.5) * slotW;
        const bx = cx - barW / 2;
        const dVal = pt.deltaTokens;
        const upH = zeroY - padT;
        const dnH = (padT + plotH) - zeroY;
        let by = zeroY - 2;
        let bh = 2;
        let fill = 'rgba(148,163,184,0.45)';
        if (dVal != null && dVal > 0 && posMax > 0) {
          bh = Math.max(2, (dVal / posMax) * upH);
          by = zeroY - bh;
          fill = pt.isEstimated ? '#fbbf24' : (pt.isMaxJump ? '#22c55e' : '#34d399');
        } else if (dVal != null && dVal < 0 && negMax > 0) {
          bh = Math.max(2, (Math.abs(dVal) / negMax) * dnH);
          by = zeroY;
          fill = '#f59e0b';
        }
        const isSel = selectedPt === pt;
        const bar = createSvgEl('rect', {
          x: bx.toFixed(1), y: by.toFixed(1), width: barW.toFixed(1), height: bh.toFixed(1), rx: 1.5,
          fill,
          stroke: (isSel || pt.isMaxJump) ? '#ffffff' : 'none',
          'stroke-width': isSel ? 1.4 : (pt.isMaxJump ? 0.9 : 0),
          'data-trend-index': String(pt.index),
          'data-step-index': pt.stepIndex != null ? String(pt.stepIndex) : '',
          class: 'ctx-trend-bar'
        });
        const hit = createSvgEl('rect', {
          x: (padL + i * slotW).toFixed(1), y: padT, width: slotW.toFixed(1), height: plotH,
          fill: 'transparent', style: 'cursor:pointer',
          'data-trend-index': String(pt.index),
          'data-step-index': pt.stepIndex != null ? String(pt.stepIndex) : ''
        });
        bindTrendPointEvents(hit, pt);
        bindTrendPointEvents(bar, pt);
        if (bar) nodes.push(bar);
        if (hit) nodes.push(hit);
      });
    } else {
      const maxVal = Math.max(1000, series.maxTotalTokens || 0);
      [0, 0.5, 1].forEach(r => {
        const y = padT + plotH * (1 - r);
        const grid = createSvgEl('line', {
          x1: padL, y1: y.toFixed(1), x2: width - padR, y2: y.toFixed(1),
          stroke: 'rgba(148,163,184,0.18)', 'stroke-width': 1
        });
        if (grid) nodes.push(grid);
        if (r === 0 || r === 1) {
          const lbl = createSvgEl('text', {
            x: padL - 4, y: (y + 3).toFixed(1), 'text-anchor': 'end',
            fill: 'var(--ag-text-muted, #8a8a94)', 'font-size': '9'
          });
          if (lbl) {
            lbl.textContent = r === 0 ? '0' : short(maxVal);
            nodes.push(lbl);
          }
        }
      });

      const linePts = [];
      let selectedX = null;
      const baseBottomY = padT + plotH;
      const defs = createSvgEl('defs', {});
      const gradId = 'ctx-mint-area-grad';
      const grad = createSvgEl('linearGradient', { id: gradId, x1: '0', y1: '0', x2: '0', y2: '1' });
      const stop1 = createSvgEl('stop', { offset: '0%', 'stop-color': '#10B981', 'stop-opacity': '0.26' });
      const stop2 = createSvgEl('stop', { offset: '100%', 'stop-color': '#10B981', 'stop-opacity': '0.02' });
      if (grad && stop1 && stop2 && defs) {
        grad.appendChild?.(stop1);
        grad.appendChild?.(stop2);
        defs.appendChild?.(grad);
        nodes.push(defs);
      }

      pts.forEach((pt, i) => {
        const cx = padL + (i + 0.5) * slotW;
        const bx = cx - Math.max(3, barW * 0.55) / 2;
        const totalH = Math.max(1.5, (pt.totalContextTokens / maxVal) * plotH);
        const topY = baseBottomY - totalH;
        const isSel = displayPt === pt;
        if (isSel) selectedX = cx;
        linePts.push({ x: cx, y: topY, pt, isSel });

        // 甜瓜橙增量/新输入伴随柱
        const incH = pt.deltaTokens > 0
          ? Math.min(totalH, Math.max(2, (pt.deltaTokens / maxVal) * plotH))
          : (pt.freshInputTokens > 0 ? Math.min(totalH, Math.max(2, (pt.freshInputTokens / maxVal) * plotH)) : 0);
        if (incH > 0.5) {
          const rDelta = createSvgEl('rect', {
            x: bx.toFixed(1), y: (baseBottomY - incH).toFixed(1), width: Math.max(3, barW * 0.55).toFixed(1), height: incH.toFixed(1), rx: 1.5,
            fill: pt.isEstimated ? 'rgba(250, 204, 21, 0.45)' : 'rgba(251, 146, 60, 0.58)',
            'data-trend-index': String(pt.index),
            'data-step-index': pt.stepIndex != null ? String(pt.stepIndex) : '',
            class: 'ctx-trend-bar'
          });
          bindTrendPointEvents(rDelta, pt);
          if (rDelta) nodes.push(rDelta);
        }
      });

      if (linePts.length >= 1) {
        // 阶梯状薄荷绿折线与柔和面积填充
        let stepD = `M ${linePts[0].x.toFixed(1)} ${linePts[0].y.toFixed(1)}`;
        for (let idx = 1; idx < linePts.length; idx++) {
          const prev = linePts[idx - 1];
          const cur = linePts[idx];
          stepD += ` H ${cur.x.toFixed(1)} V ${cur.y.toFixed(1)}`;
        }
        if (linePts.length >= 2) {
          const areaD = `${stepD} L ${linePts[linePts.length - 1].x.toFixed(1)} ${baseBottomY.toFixed(1)} L ${linePts[0].x.toFixed(1)} ${baseBottomY.toFixed(1)} Z`;
          const trendArea = createSvgEl('path', {
            d: areaD, fill: `url(#${gradId})`, style: 'pointer-events:none'
          });
          if (trendArea) nodes.push(trendArea);
          const trendLine = createSvgEl('path', {
            d: stepD, fill: 'none', stroke: '#10B981', 'stroke-width': 2, style: 'pointer-events:none'
          });
          if (trendLine) nodes.push(trendLine);
        }
        // 数据点圆点 & 选中点狂欢洋红游标线
        if (selectedX != null) {
          const cursorLine = createSvgEl('line', {
            x1: selectedX.toFixed(1), y1: padT, x2: selectedX.toFixed(1), y2: baseBottomY.toFixed(1),
            stroke: '#E11D74', 'stroke-width': 1.5, 'stroke-dasharray': '3 2', style: 'pointer-events:none'
          });
          if (cursorLine) nodes.push(cursorLine);
        }
        linePts.forEach((lp, i) => {
          const pt = lp.pt;
          const dot = createSvgEl('circle', {
            cx: lp.x.toFixed(1), cy: lp.y.toFixed(1), r: lp.isSel ? '3.8' : '2.2',
            fill: lp.isSel ? '#E11D74' : '#10B981',
            stroke: lp.isSel ? '#ffffff' : 'none',
            'stroke-width': lp.isSel ? '1.3' : '0',
            'data-trend-index': String(pt.index),
            'data-step-index': pt.stepIndex != null ? String(pt.stepIndex) : '',
            class: 'ctx-trend-bar'
          });
          const hit = createSvgEl('rect', {
            x: (padL + i * slotW).toFixed(1), y: padT, width: slotW.toFixed(1), height: plotH,
            fill: 'transparent', style: 'cursor:pointer',
            'data-trend-index': String(pt.index),
            'data-step-index': pt.stepIndex != null ? String(pt.stepIndex) : ''
          });
          bindTrendPointEvents(hit, pt);
          bindTrendPointEvents(dot, pt);
          if (dot) nodes.push(dot);
          if (hit) nodes.push(hit);
        });
      }
    }

    // 仅在有证据的上下文变化事件对应步骤位置绘制金合欢黄事件菱形标点 (支持点击追踪)
    const evList = Array.isArray(timelineSrc?.contextChangeEvents) ? timelineSrc.contextChangeEvents : [];
    if (evList.length > 0 && pts.length > 0) {
      const evColorMap = {
        compaction: '#FACC15',
        prune: '#22E09B',
        inject: '#F472B6',
        model: '#10B981',
        mode: '#3B82F6',
        unknown_drop: '#FB923C'
      };
      for (const ev of evList) {
        const ptIdx = pts.findIndex(p =>
          (ev.callId && p.callId === ev.callId)
          || (ev.stepIndex != null && Number(p.stepIndex) === Number(ev.stepIndex))
          || (ev.turnIndex != null && Number(p.turnIndex) === Number(ev.turnIndex))
        );
        if (ptIdx < 0) continue;
        const cx = padL + (ptIdx + 0.5) * slotW;
        const evDot = createSvgEl('circle', {
          cx: cx.toFixed(1), cy: '7', r: '3.2',
          fill: evColorMap[ev.type] || '#FACC15',
          stroke: 'var(--ctx-ck-card, #151517)', 'stroke-width': '1',
          style: 'cursor:pointer', 'data-event-type': ev.type
        });
        if (evDot) {
          evDot.addEventListener?.('click', () => jumpToStepOrTurn({ stepIndex: ev.stepIndex, turnIndex: ev.turnIndex, callId: ev.callId }));
          nodes.push(evDot);
        }
      }
    }

    const firstX = createSvgEl('text', { x: padL, y: height - 5, fill: 'var(--ag-text-muted, #8a8a94)', 'font-size': '9' });
    if (firstX) {
      firstX.textContent = pts[0].label || '#1';
      nodes.push(firstX);
    }
    if (pts.length > 1) {
      const lastX = createSvgEl('text', { x: width - padR, y: height - 5, 'text-anchor': 'end', fill: 'var(--ag-text-muted, #8a8a94)', 'font-size': '9' });
      if (lastX) {
        lastX.textContent = pts[pts.length - 1].label || `#${pts.length}`;
        nodes.push(lastX);
      }
    }

    if (typeof svg.replaceChildren === 'function') svg.replaceChildren(...nodes);
    else {
      svg.innerHTML = '';
      nodes.forEach(n => svg.appendChild?.(n));
    }
    if (typeof renderTrendPulseExtras === 'function') {
      renderTrendPulseExtras(series, pts, svg, timelineSrc, { width, height, padL, padR, padT, padB, plotW, plotH, slotW, displayPt });
    }
  }

  function renderSessionTimeline() {
    const drawer = el('session-timeline-drawer');
    const toggleBtn = el('btn-session-history-toggle');
    if (toggleBtn) {
      toggleBtn.textContent = state.historyDrawerOpen ? t('session.timeline.hideHistory') : t('session.timeline.viewHistory');
      toggleBtn.setAttribute?.('aria-expanded', state.historyDrawerOpen ? 'true' : 'false');
    }
    if (!drawer) return;
    drawer.style.display = state.historyDrawerOpen ? 'flex' : 'none';
    if (!state.historyDrawerOpen) return;

    const sumEl = el('session-timeline-summary');
    const listEl = el('session-timeline-list');
    const insightBodyEl = el('session-timeline-insight-body');
    const insightBarEl = el('timeline-insight-bar');
    const unlinkedEl = el('session-timeline-unlinked');
    const moreWrap = el('session-timeline-more-wrap');
    const moreBtn = el('btn-timeline-load-more');

    syncTimelineSortAndDeltaUi();
    if (insightBarEl) {
      insightBarEl.querySelectorAll?.('.tl-tab-btn').forEach(btn => {
        const isAct = btn.getAttribute('data-tl-tab') === (state.timelineInsightTab || 'turns');
        btn.classList.toggle('active', isAct);
        btn.setAttribute?.('aria-selected', isAct ? 'true' : 'false');
      });
    }

    if (state.timelineLoading && !state.sessionTimeline) {
      if (sumEl) sumEl.textContent = t('session.timeline.loading');
      if (listEl) { listEl.hidden = false; listEl.replaceChildren(); }
      if (insightBodyEl) { insightBodyEl.hidden = true; insightBodyEl.replaceChildren(); }
      if (unlinkedEl) unlinkedEl.hidden = true;
      if (moreWrap) moreWrap.hidden = true;
      return;
    }

    const tl = state.sessionTimeline;
    const eventsEl = el('session-timeline-events');
    if (!tl || (!tl.turns?.length && !tl.unlinkedSubagentCalls?.length && !tl.contextChangeEvents?.length)) {
      if (sumEl) sumEl.textContent = state.timelineError ? translateBackendText(state.timelineError) : t('session.timeline.empty');
      if (eventsEl) { eventsEl.hidden = true; eventsEl.replaceChildren(); }
      if (listEl) { listEl.hidden = false; listEl.replaceChildren(); }
      if (insightBodyEl) { insightBodyEl.hidden = true; insightBodyEl.replaceChildren(); }
      if (unlinkedEl) unlinkedEl.hidden = true;
      if (moreWrap) moreWrap.hidden = true;
      return;
    }

    const ctxEvents = Array.isArray(tl.contextChangeEvents) ? tl.contextChangeEvents : [];
    if (eventsEl) {
      eventsEl.replaceChildren();
      if (ctxEvents.length > 0) {
        eventsEl.hidden = false;
        const evTitle = document.createElement('div');
        evTitle.className = 'timeline-context-events-title';
        evTitle.textContent = t('session.timeline.eventsTitle', { n: ctxEvents.length });
        const evList = document.createElement('div');
        evList.className = 'timeline-context-events-list';
        for (const ev of ctxEvents) {
          const evRow = document.createElement('div');
          evRow.className = 'timeline-event-row is-clickable';
          const leftBox = document.createElement('div');
          leftBox.className = 'timeline-event-left';
          const badge = document.createElement('span');
          const safeType = ['compaction', 'prune', 'inject', 'model', 'mode', 'unknown_drop'].includes(ev.type) ? ev.type : 'inject';
          badge.className = `timeline-event-badge is-${safeType}`;
          badge.textContent = t(`session.timeline.event.${safeType}`);
          const detailEl = document.createElement('span');
          detailEl.className = 'timeline-event-detail';
          const turnPart = ev.turnIndex != null ? `T${ev.turnIndex} ` : '';
          const stepPart = Number.isInteger(ev.stepIndex) && ev.stepIndex >= 0 ? `#${ev.stepIndex} ` : '';
          const srcPart = ev.source ? ` [${ev.source}]` : '';
          const rawDesc = ev.type === 'unknown_drop' ? t('session.timeline.event.unknown_drop') : (ev.detail || '');
          detailEl.textContent = `${turnPart}${stepPart}${rawDesc}${srcPart}`.trim() || badge.textContent;
          leftBox.appendChild(badge);
          leftBox.appendChild(detailEl);

          const tokEl = document.createElement('span');
          tokEl.className = 'timeline-event-tokens';
          const bTxt = ev.beforeTokens != null ? short(ev.beforeTokens) : '—';
          const aTxt = ev.afterTokens != null ? short(ev.afterTokens) : '—';
          const dTxt = ev.deltaTokens != null ? ` (${ev.deltaTokens > 0 ? '+' : ''}${short(ev.deltaTokens)})` : '';
          tokEl.textContent = `${bTxt} → ${aTxt}${dTxt}`;

          evRow.appendChild(leftBox);
          evRow.appendChild(tokEl);
          evRow.addEventListener('click', () => jumpToStepOrTurn({ stepIndex: ev.stepIndex, turnIndex: ev.turnIndex, callId: ev.callId, timelineTab: 'turns' }));
          evList.appendChild(evRow);
        }
        eventsEl.appendChild(evTitle);
        eventsEl.appendChild(evList);
      } else {
        eventsEl.hidden = true;
      }
    }

    const turns = Array.isArray(tl.turns) ? tl.turns : [];
    const cacheText = tl.cacheSummary && tl.cacheSummary.cacheStatus !== 'missing'
      ? (tl.cacheSummary.cacheStatus === 'zero_input' ? t('session.latestCall.naVal') : `${tl.cacheSummary.cacheReadPct}%`)
      : t('session.latestCall.unknownVal');
    if (sumEl) {
      sumEl.replaceChildren();
      const sLine = document.createElement('div');
      sLine.textContent = t('session.timeline.summary', {
        turns: turns.length,
        calls: tl.totalCalls || 0,
        main: tl.mainCallsCount || 0,
        sub: tl.subagentCallsCount || 0,
        cache: cacheText
      });
      sumEl.appendChild(sLine);
      if (tl.cliReportedUsage) {
        const cliLine = document.createElement('div');
        cliLine.style.marginTop = '2px';
        cliLine.textContent = t('session.timeline.cliReportedUsage', {
          total: Number(tl.cliReportedUsage.totalTokens || 0).toLocaleString(),
          cache: Number(tl.cliReportedUsage.cacheReadTokens || 0).toLocaleString()
        });
        sumEl.appendChild(cliLine);
      }
      if (tl.contextDeltaSummary?.latestContextTokens != null) {
        const dSum = tl.contextDeltaSummary;
        const netTxt = dSum.netDeltaTokens != null
          ? `${dSum.netDeltaTokens > 0 ? '+' : ''}${short(dSum.netDeltaTokens)}`
          : '—';
        const dLine = document.createElement('div');
        dLine.style.marginTop = '2px';
        dLine.textContent = t('session.timeline.deltaSummary', {
          net: netTxt,
          init: short(dSum.initialContextTokens || 0),
          latest: short(dSum.latestContextTokens || 0)
        });
        sumEl.appendChild(dLine);
      }
      const noteLine = document.createElement('div');
      noteLine.style.marginTop = '2px';
      noteLine.textContent = t('session.timeline.windowNote');
      sumEl.appendChild(noteLine);
      if (Array.isArray(tl.modelBreakdown) && tl.modelBreakdown.length > 0) {
        const mbWrap = document.createElement('div');
        mbWrap.className = 'timeline-model-breakdown';
        const mbHdr = document.createElement('div');
        mbHdr.className = 'timeline-model-hdr';
        mbHdr.textContent = t('session.timeline.modelBreakdownTitle');
        mbWrap.appendChild(mbHdr);
        for (const mItem of tl.modelBreakdown) {
          const mRow = document.createElement('div');
          mRow.className = 'timeline-model-row';
          const mName = document.createElement('span');
          mName.className = `timeline-model-name${mItem.isUnknown ? ' is-unknown' : ''}`;
          mName.textContent = mItem.isUnknown && !mItem.rawModelId
            ? t('session.timeline.unknownModel')
            : (mItem.modelLabel || mItem.modelKey || t('session.timeline.unknownModel'));
          if (mItem.rawModelId) mName.title = String(mItem.rawModelId);
          const mVal = document.createElement('span');
          mVal.className = 'timeline-model-val';
          mVal.textContent = `${mItem.callCount} · ${short(mItem.totalTokens || 0)} (${mItem.pct ?? 0}%)`;
          mRow.appendChild(mName);
          mRow.appendChild(mVal);
          mbWrap.appendChild(mRow);
        }
        if (tl.sessionTokenTotals) {
          const st = tl.sessionTokenTotals;
          const totLine = document.createElement('div');
          totLine.className = 'timeline-turn-meta';
          totLine.textContent = t(tl.cliReportedUsage ? 'session.timeline.processedTotalsLine' : 'session.timeline.modelTotalsLine', {
            calls: st.callCount || 0,
            total: short(st.totalTokens || 0),
            inp: short(st.inputTokens || 0),
            cap: short(st.cacheReadTokens || 0),
            out: short(st.outputTokens || 0)
          });
          mbWrap.appendChild(totLine);
        }
        sumEl.appendChild(mbWrap);
      }
      if (tl.subagentNote) {
        const dbNoteLine = document.createElement('div');
        dbNoteLine.style.marginTop = '2px';
        dbNoteLine.textContent = t('session.timeline.dbMissingNote', { reason: tl.subagentNote });
        sumEl.appendChild(dbNoteLine);
      }
    }

    const activeInsightTab = state.timelineInsightTab || 'turns';
    if (activeInsightTab !== 'turns') {
      if (listEl) listEl.hidden = true;
      if (moreWrap) moreWrap.hidden = true;
      if (unlinkedEl) unlinkedEl.hidden = true;
      if (insightBodyEl) {
        insightBodyEl.hidden = false;
        renderTimelineInsightTabBody(tl, insightBodyEl);
      }
      return;
    }

    if (insightBodyEl) insightBodyEl.hidden = true;
    if (listEl) {
      listEl.hidden = false;
      const curRouteKey = state.route || '';
      const sameTimelineRoute = state.timelineRenderedRoute === curRouteKey;
      const prevScrollTop = sameTimelineRoute ? Number(listEl.scrollTop || 0) : 0;
      listEl.replaceChildren();
      state.timelineRenderedRoute = curRouteKey;
      const resolveTurnKey = (tObj) => tObj?.turnKey || `turn-${tObj?.turnIndex ?? 'x'}-${tObj?.stepIndex ?? 'na'}`;
      const sortOrder = state.timelineSortOrder || 'newest';
      let descTurns;
      if (sortOrder === 'oldest') {
        descTurns = [...turns];
      } else if (sortOrder === 'delta_desc') {
        const resolveTurnMaxJump = (tObj) => {
          const turnDelta = tObj?.deltaFromPrevTurn != null ? Math.abs(Number(tObj.deltaFromPrevTurn)) : 0;
          const calls = Array.isArray(tObj?.calls) ? tObj.calls : [];
          let callMax = 0;
          for (const c of calls) {
            if (c?.deltaFromPrevStep != null && Number.isFinite(Number(c.deltaFromPrevStep))) {
              const absD = Math.abs(Number(c.deltaFromPrevStep));
              if (absD > callMax) callMax = absD;
            }
          }
          return Math.max(turnDelta, callMax);
        };
        descTurns = [...turns].sort((a, b) => resolveTurnMaxJump(b) - resolveTurnMaxJump(a));
      } else {
        descTurns = [...turns].reverse();
      }
      if (descTurns.length > 0 && state.timelineAutoExpandedRoute !== curRouteKey) {
        state.timelineAutoExpandedRoute = curRouteKey;
        if (state.expandedTurnKeys.size === 0) {
          state.expandedTurnKeys.add(resolveTurnKey(descTurns[0]));
        }
      }
      const limit = Math.max(5, Number(state.timelinePageLimit) || 10);
      const visibleTurns = descTurns.slice(0, limit);

      const createCallRow = (call) => {
        const row = document.createElement('div');
        const isSelected = state.pinnedCallRecord && state.pinnedCallRecord.callId === call.callId;
        row.className = `timeline-call-row${call.agentRole === 'subagent' ? ' is-subagent' : ''}${isSelected ? ' is-selected' : ''}`;
        row.setAttribute('role', 'button');
        row.setAttribute('tabindex', '0');

        const main = document.createElement('div');
        main.className = 'timeline-call-main';
        const roleBadge = document.createElement('span');
        roleBadge.className = `call-agent-badge${call.agentRole === 'subagent' ? ' is-subagent' : (call.attributionConfidence === 'unidentified' ? ' is-unknown' : '')}`;
        roleBadge.textContent = call.agentRole === 'subagent'
          ? (call.subagentType ? `${t('session.latestCall.agentSub')}·${call.subagentType}` : t('session.latestCall.agentSub'))
          : (call.attributionConfidence === 'unidentified' ? t('session.latestCall.agentUnknown') : t('session.latestCall.agentMain'));
        const mName = document.createElement('span');
        mName.className = 'timeline-turn-prompt';
        const baseModelTitle = formatCallModelTitle(call);
        const effortText = call.effort ? String(call.effort).trim() : '';
        const hasEffortParen = effortText && baseModelTitle.trim().toLowerCase().endsWith(`(${effortText.toLowerCase()})`);
        mName.textContent = (effortText && !hasEffortParen) ? `${baseModelTitle} (${effortText})` : baseModelTitle;
        mName.title = mName.textContent;
        main.appendChild(roleBadge);
        main.appendChild(mName);
        const deltaBadge = createDeltaBadgeEl(call.deltaFromPrevStep, Boolean(call.isMaxContextJump));
        if (deltaBadge) main.appendChild(deltaBadge);

        const stats = document.createElement('div');
        stats.className = 'timeline-call-stats';
        const st = resolveCallStatusDisplay(call);
        if (state.timelineDeltaOnly && call.contextWindowTokens != null) {
          const dVal = call.deltaFromPrevStep;
          const dStr = dVal != null ? `${dVal > 0 ? '+' : ''}${short(dVal)}` : '—';
          stats.textContent = `${formatCallTimeStr(call)} · Δ ${dStr} → ${short(call.contextWindowTokens)} · ${st.text}`;
        } else {
          const inpTxt = call.hasInputCacheFields ? short(call.totalInputTokens) : t('session.latestCall.unknownVal');
          const eTag = (call.eScore != null && call.eGrade)
            ? (currentPanelLanguage === 'en' ? ` · ${call.eScore}pt(${call.eGrade})` : ` · ${call.eScore}分(${call.eGrade})`)
            : '';
          if (currentPanelLanguage === 'en') {
            stats.textContent = `${formatCallTimeStr(call)} · In ${inpTxt}/Out ${short(call.outputTokens || 0)} · Cache ${formatCallCachePctText(call)}${eTag} · ${st.text}`;
          } else if (currentPanelLanguage === 'zh-TW') {
            stats.textContent = `${formatCallTimeStr(call)} · 入${inpTxt}/出${short(call.outputTokens || 0)} · 緩${formatCallCachePctText(call)}${eTag} · ${st.text}`;
          } else {
            stats.textContent = `${formatCallTimeStr(call)} · 入${inpTxt}/出${short(call.outputTokens || 0)} · 缓${formatCallCachePctText(call)}${eTag} · ${st.text}`;
          }
        }

        row.appendChild(main);
        row.appendChild(stats);
        const inspectCall = () => {
          state.pinnedCallRecord = call;
          state.latestCallDetailOpen = true;
          renderLatestCallCard({ fromUserAction: true, skipAnim: false });
          renderSessionTimeline();
        };
        row.addEventListener('click', inspectCall);
        row.addEventListener('keydown', (e) => {
          if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); inspectCall(); }
        });
        return row;
      };

      for (const turn of visibleTurns) {
        const turnKey = resolveTurnKey(turn);
        const isOpen = state.expandedTurnKeys.has(turnKey);
        const cardEl = document.createElement('div');
        cardEl.className = 'timeline-turn-card';

        const hdrBtn = document.createElement('button');
        hdrBtn.type = 'button';
        hdrBtn.className = 'timeline-turn-hdr';
        hdrBtn.setAttribute('aria-expanded', isOpen ? 'true' : 'false');

        const left = document.createElement('div');
        left.className = 'timeline-turn-left';
        const idxEl = document.createElement('span');
        idxEl.className = 'timeline-turn-idx';
        idxEl.textContent = t('session.timeline.turnLabel', { n: turn.turnIndex });
        const rawTurnPrompt = turn.preview || turn.userPromptPreview || '';
        const promptText = typeof sanitizeTurnPreviewText === 'function' ? sanitizeTurnPreviewText(rawTurnPrompt, 120) : rawTurnPrompt;
        const promptEl = document.createElement('span');
        promptEl.className = 'timeline-turn-prompt';
        promptEl.textContent = promptText || t('session.timeline.turnNoPrompt');
        if (rawTurnPrompt || promptText) promptEl.title = String(rawTurnPrompt || promptText);
        left.appendChild(idxEl);
        left.appendChild(promptEl);
        const turnDeltaBadge = createDeltaBadgeEl(turn.deltaFromPrevTurn, false);
        if (turnDeltaBadge) left.appendChild(turnDeltaBadge);

        const metaEl = document.createElement('span');
        metaEl.className = 'timeline-turn-meta';
        if (state.timelineDeltaOnly && turn.lastContextTokens != null) {
          const td = turn.deltaFromPrevTurn;
          metaEl.textContent = `${turn.calls?.length || 0} · ${td != null ? `Δ${td > 0 ? '+' : ''}${short(td)} ` : ''}→ ${short(turn.lastContextTokens)}`;
        } else {
          metaEl.textContent = t('session.timeline.turnSummary', {
            calls: turn.calls?.length || 0,
            inp: short(turn.inputTokens || 0),
            cap: short(turn.cacheReadTokens || 0),
            out: short(turn.outputTokens || 0)
          });
        }

        hdrBtn.appendChild(left);
        hdrBtn.appendChild(metaEl);
        hdrBtn.addEventListener('click', () => {
          if (state.expandedTurnKeys.has(turnKey)) state.expandedTurnKeys.delete(turnKey);
          else state.expandedTurnKeys.add(turnKey);
          renderSessionTimeline();
        });
        cardEl.appendChild(hdrBtn);

        if (isOpen && Array.isArray(turn.calls)) {
          const bodyEl = document.createElement('div');
          bodyEl.className = 'timeline-turn-body';
          for (const call of turn.calls) {
            bodyEl.appendChild(createCallRow(call));
          }
          cardEl.appendChild(bodyEl);
        }
        listEl.appendChild(cardEl);
      }

      if (moreWrap && moreBtn) {
        const remaining = descTurns.length - visibleTurns.length;
        if (remaining > 0) {
          moreWrap.hidden = false;
          moreBtn.textContent = t('session.timeline.loadMore', { n: remaining });
        } else {
          moreWrap.hidden = true;
        }
      }

      if (unlinkedEl) {
        const unlinked = Array.isArray(tl.unlinkedSubagentCalls) ? tl.unlinkedSubagentCalls : [];
        if (unlinked.length > 0) {
          unlinkedEl.hidden = false;
          unlinkedEl.replaceChildren();
          const uTitle = document.createElement('div');
          uTitle.className = 'session-timeline-unlinked-title';
          uTitle.textContent = t('session.timeline.unlinkedTitle', { n: unlinked.length });
          unlinkedEl.appendChild(uTitle);
          for (const uCall of unlinked) {
            unlinkedEl.appendChild(createCallRow(uCall));
          }
        } else {
          unlinkedEl.hidden = true;
          unlinkedEl.replaceChildren();
        }
      }
      if (prevScrollTop > 0) {
        const maxScroll = Math.max(0, (listEl.scrollHeight || 0) - (listEl.clientHeight || 0));
        listEl.scrollTop = maxScroll > 0 ? Math.min(prevScrollTop, maxScroll) : prevScrollTop;
      }
    }
  }

  async function fetchSessionTimeline(id, { force = false } = {}) {
    if (!id || state.disposed || id !== state.route) return null;
    if (!force && state.timelineLoading) return null;
    const seq = ++timelineFetchSeq;
    const gen = state.generation;
    state.timelineLoading = true;
    state.timelineError = '';
    if (state.historyDrawerOpen) renderSessionTimeline();

    try {
      if (timelineFetchController) {
        try { timelineFetchController.abort(); } catch { }
      }
      timelineFetchController = typeof AbortController === 'function' ? new AbortController() : null;
      const liveCalls = Array.isArray(state.sessionCalls) ? state.sessionCalls : [];
      const configs = state.cascadeModelConfigs || state.scan?.cascadeModelConfigs || [];
      const hasIpc = typeof window !== 'undefined' && typeof window.contextMeterAPI?.getSessionTimeline === 'function';
      let timelineData = null;

      if (hasIpc || hasLiveHttpBridge()) {
        const out = await callBackendWithPriority({
          ipcCall: hasIpc ? () => window.contextMeterAPI.getSessionTimeline(id, { force, liveCalls, cascadeModelConfigs: configs }) : null,
          liveRoute: '/session-timeline',
          liveBody: { id, force, liveCalls, cascadeModelConfigs: configs },
          liveFetchOpts: timelineFetchController ? { signal: timelineFetchController.signal } : {}
        });
        const res = out?.result;
        if (res?.ok && res.data) {
          timelineData = res.data;
        } else if (res && !res.ok) {
          state.timelineError = res.error || '';
        }
      } else if (typeof groupSessionCallsByTurns === 'function') {
        timelineData = groupSessionCallsByTurns([], liveCalls, { cascadeId: id, cascadeModelConfigs: configs });
      }

      if (gen !== state.generation || seq !== timelineFetchSeq || state.disposed || !sameRouteId(id, state.route)) return null;
      if (timelineData) {
        if (timelineData.cascadeId && UUID_STRICT_RE.test(String(timelineData.cascadeId)) && !sameRouteId(timelineData.cascadeId, state.route)) return null;
        state.sessionTimeline = timelineData;
        state.lastTimelineFetchAt = Date.now();
      }
    } catch (e) {
      if (e?.name !== 'AbortError' && gen === state.generation && !state.disposed && sameRouteId(id, state.route)) {
        state.timelineError = e?.message || String(e || '');
      }
    } finally {
      if (seq === timelineFetchSeq && !state.disposed && sameRouteId(id, state.route)) {
        state.timelineLoading = false;
        if (typeof renderContextTrendCard === 'function') renderContextTrendCard();
        if (typeof renderSessionBentoSections === 'function') renderSessionBentoSections();
        if (state.historyDrawerOpen) renderSessionTimeline();
        renderComposerStatusBar();
        renderTurnFooterStats();
        syncOverflowMenuMetrics?.();
      }
    }
    return state.sessionTimeline;
  }

  function scheduleLatestCallRefresh({ allowTimelineRefresh = false } = {}) {
    if (state.disposed) return;
    if (allowTimelineRefresh && state.historyDrawerOpen && state.route) {
      const latest = resolveLatestSessionCallRecord();
      const sig = buildCallDisplaySignature(latest);
      if (sig && sig !== state.lastTimelineCallSig && Date.now() - state.lastTimelineFetchAt > 1200) {
        state.lastTimelineCallSig = sig;
        void fetchSessionTimeline(state.route);
      }
    }
    renderLatestCallCard();
  }

  // 渲染上下文与全局状态（无论在主页 / 还是会话页 /c/<id>，始终保持插件栏挂载与可用）
  function render() {
    host.hidden = false;
    host.setAttribute('data-has-session', state.route ? 'true' : 'false');
    enforceMarketplaceAvoidance();
    ensureHostDocked();
    renderConversationScopeUI();
    if (!state.route) {
      host.setAttribute('data-compacting', 'false');
      hideContextTooltip();
      const barFill = el('bar-fill');
      if (barFill) barFill.style.width = '0%';
      const badgePctVal = el('badge-pct-val');
      if (badgePctVal) badgePctVal.textContent = '--%';
      const amountEl0 = el('amount');
      if (amountEl0) amountEl0.textContent = t('badge.noSession');
      setHoverExtra(t('badge.clickOpenCli'));
      syncSpeedBadgeText();
      const badgeTokEl0 = el('badge-tokens');
      if (badgeTokEl0) badgeTokEl0.title = t('badge.tokensTitle');
      syncContextModelSelectionFromState();
      renderLatestCallCard({ skipAnim: true });
      renderSessionBentoSections();
      renderSessionTimeline();
      renderComposerStatusBar();
      renderTurnFooterStats();
      return;
    }
    renderSessionCost();

    const d = state.latest, session = state.scan?.session;
    const disp = resolveDisplayStatus(d, session);
    const stale = state.requestError || state.requestAt && Date.now() - state.requestAt > 20000;
    const incomplete = session?.unknownFiles > 0;
    const danger = disp.isError || d?.exceeded;

    let pct = null;
    if (d?.exceeded) {
      pct = 100;
    } else if (d?.percent != null && !danger && !stale) {
      pct = Math.min(100, Math.max(0, d.percent));
    } else if (d?.actual != null && d?.budget && !danger && !stale) {
      pct = Math.min(100, Math.max(0, (d.actual / d.budget) * 100));
    }

    const { warnThreshold, dangerThreshold } = getContextUsageThresholds();
    // 顶栏进度条与总览 #ctx-ov-pct-summary 共用同一分档来源，颜色严格由分档推导
    const topbarTier = computeContextUsageTier(pct, { warnThreshold, dangerThreshold }, {
      exceeded: Boolean(danger),
      limitValid: pct != null
    });
    const barColor = (topbarTier === 'full' || topbarTier === 'danger') ? '#ff4d4f'
      : (topbarTier === 'warn' || stale || incomplete) ? '#faad14' : '#69c0ff';
    const tone = danger ? '#ff9292' : stale || incomplete || (d?.estimated && !d?.compacted) ? '#f2c46d' : '#b7c1ff';
    host.style.setProperty('--tone', tone);
    host.style.setProperty('--bar-color', barColor);

    const barFill = el('bar-fill');
    if (barFill) barFill.style.width = pct != null ? `${pct}%` : (d?.exceeded ? '100%' : '0%');
    const isCompactingNow = Boolean(state.compacting && state.compacting.cascadeId === state.route && !disp.isError);

    updateRingAndBubble(d, session, pct, danger, stale, incomplete, disp, isCompactingNow);

    syncContextModelSelectionFromState();

    // 若观测到的上下文预算变化且抽屉已展开或尚未读取状态，触发一次轻量同步（不再据此判定真实请求已验证）
    if (d?.budget && d.budget !== lastAutoObservedBudget && d.budget > 256000) {
      lastAutoObservedBudget = d.budget;
      if (currentUnlockStatus || (unlockDrawerBody && unlockDrawerBody.style.display === 'block')) {
        void refreshUnlockStatus();
      }
    }

    host.setAttribute('data-compacting', isCompactingNow ? 'true' : 'false');
    const status = disp.isError || disp.kind === 'canceled'
      ? disp.statusText
      : isCompactingNow ? t('badge.status.compacting')
        : stale ? t('badge.status.stale')
          : state.scanError ? t('badge.status.scanErr', { err: translateBackendText(state.scanError) })
            : incomplete ? t('badge.status.incomplete', { count: session.unknownFiles })
              : d?.compacted ? t('badge.status.compacted')
                : d?.estimated ? t('badge.status.estimated')
                  : t('badge.status.normal');
    el('status').textContent = status;

    const corpus = session?.total
      ? t('badge.corpus.range', { range: range(session.total), inc: incomplete ? t('badge.corpus.incPlus') : '' })
      : state.scanBusy ? t('badge.corpus.scanning') : t('badge.corpus.pending');

    const badgePctVal = el('badge-pct-val');
    const amountEl = el('amount');
    if (disp.isError || disp.kind === 'canceled') {
      if (amountEl) amountEl.textContent = disp.amountText;
      if (badgePctVal) badgePctVal.textContent = disp.badgeText;
      setHoverExtra(disp.hoverExtra);
    } else if (isCompactingNow) {
      const curTok = d?.actual != null ? d.actual : (d?.postCompactEstimate ?? null);
      if (amountEl) amountEl.textContent = curTok != null ? `${short(curTok)} (${t('badge.pct.compacting')})` : t('badge.pct.compacting');
      if (badgePctVal) badgePctVal.textContent = t('badge.pct.compacting');
      const budgetStr = d?.budget ? ` / ${short(d.budget)}` : '';
      setHoverExtra(`${budgetStr} · ${corpus}`);
    } else if (stale) {
      if (amountEl) amountEl.textContent = t('badge.delayed');
      if (badgePctVal) badgePctVal.textContent = pct != null ? `${pct.toFixed(0)}%` : '--%';
      setHoverExtra(` · ${corpus}`);
    } else if (d?.compacted && d?.postCompactEstimate != null) {
      const pctRound = pct != null ? (pct > 0 && pct < 1 ? 1 : Math.round(pct)) : null;
      const pctStr = pctRound != null ? ` (${pctRound}%)` : '';
      if (amountEl) amountEl.textContent = `~${short(d.postCompactEstimate)}${pctStr}`;
      if (badgePctVal) badgePctVal.textContent = pctRound != null ? `~${pctRound}%` : '--%';
      const budgetStr = d?.budget ? ` / ${short(d.budget)}` : '';
      setHoverExtra(`${budgetStr} · ${corpus}`);
    } else if (d?.actual != null) {
      const pctStr = pct != null ? ` (${pct.toFixed(0)}%)` : '';
      if (amountEl) amountEl.textContent = `${short(d.actual)}${pctStr}`;
      if (badgePctVal) badgePctVal.textContent = pct != null ? `${pct.toFixed(0)}%` : '--%';
      const budgetStr = d?.budget ? ` / ${short(d.budget)}` : '';
      setHoverExtra(`${budgetStr} · ${corpus}`);
    } else {
      if (amountEl) amountEl.textContent = t('badge.actualUnknown');
      if (badgePctVal) badgePctVal.textContent = '--%';
      setHoverExtra(` · ${corpus}`);
    }

    const badgeTokEl = el('badge-tokens');
    if (badgeTokEl) badgeTokEl.title = t('badge.tokensTitle');

    // 渲染输出速度 (顶栏显示当前会话平均速度, 统一使用 tok/s)
    const sp = d?.speed;
    const speedBadge = el('badge-speed');
    const speedHoverExtra = el('speed-hover-extra');
    syncSpeedBadgeText();
    const avgSpForRender = getSessionAverageSpeed(state.lastSpeedEval || null);
    if (speedBadge) {
      if (sp?.tps != null) {
        if (speedHoverExtra) {
          speedHoverExtra.textContent = `${sp.duration ? ` · ${sp.duration}s` : ''}${sp.outputTokens ? ` · ${short(sp.outputTokens)} tok` : ''}`;
        }
      } else if (avgSpForRender?.avgTps != null) {
        if (speedHoverExtra) {
          speedHoverExtra.textContent = `${avgSpForRender.totalDurationSec ? ` · ${avgSpForRender.totalDurationSec}s` : ''}${avgSpForRender.totalOutputTokens ? ` · ${short(avgSpForRender.totalOutputTokens)} tok` : ''}`;
        }
      } else if (state.requestBusy) {
        if (speedHoverExtra) speedHoverExtra.textContent = '';
      } else {
        if (speedHoverExtra) speedHoverExtra.textContent = t('badge.speedHoverIdle');
      }
      updateSpeedBadgeHoverTitle(state.lastSpeedEval || null, avgSpForRender);
    }

    if (el('key-summary')) {
      const keyBar = el('key-bar-fill');
      const keyBadge = el('key-badge');
      const keyUsed = el('key-used');
      const keyLimit = el('key-limit');
      const keyRemaining = el('key-remaining');
      const keyTakeaway = el('key-takeaway');

      if (keyBar) keyBar.style.width = pct != null ? `${pct}%` : (d?.exceeded ? '100%' : '0%');

      if (disp.isError || disp.kind === 'canceled') {
        if (keyBadge) {
          keyBadge.textContent = disp.keyBadgeText;
          keyBadge.className = disp.pillClass;
        }

        const usedTokenCount = d?.actual != null ? d.actual : (d?.used != null ? d.used : (d?.estimate != null ? d.estimate : (session?.total?.low ?? null)));
        const budgetTokenCount = d?.budget || (d?.serviceLimit ? d.serviceLimit : 983040);

        if (disp.isOverflow) {
          if (keyUsed) keyUsed.textContent = d.serviceLimit ? `>${short(d.serviceLimit)}` : t('key.overflowUsed');
          if (keyLimit) keyLimit.textContent = d.serviceLimit ? short(d.serviceLimit) : short(budgetTokenCount);
          if (keyRemaining) keyRemaining.textContent = t('key.overflowRem');
        } else {
          // 非超限错误：保留已有上下文用量，标明其状态，不归零、不清空
          if (keyUsed) {
            keyUsed.textContent = usedTokenCount != null ? (d?.actual != null ? `${short(usedTokenCount)}${pct != null ? ` (${pct.toFixed(1)}%)` : ''}` : t('key.estShort', { val: short(usedTokenCount) })) : '—';
          }
          if (keyLimit) keyLimit.textContent = budgetTokenCount ? short(budgetTokenCount) : '—';
          if (keyRemaining) {
            if (usedTokenCount != null && budgetTokenCount) {
              const rem = Math.max(0, budgetTokenCount - usedTokenCount);
              const remP = Math.max(0, 100 - (pct || ((usedTokenCount / budgetTokenCount) * 100)));
              keyRemaining.textContent = `${short(rem)} (${remP.toFixed(1)}%)`;
            } else {
              keyRemaining.textContent = t('key.pending');
            }
          }
        }
        if (keyTakeaway) {
          keyTakeaway.textContent = disp.keyTakeaway;
          const showErrTakeaway = Boolean(disp.isError);
          keyTakeaway.hidden = !showErrTakeaway;
          keyTakeaway.style.display = showErrTakeaway ? '' : 'none';
        }
      } else if (isCompactingNow) {
        if (keyBadge) {
          keyBadge.textContent = t('key.pill.compacting');
          keyBadge.className = 'key-pill pill-info';
        }
        const curUsed = d?.actual != null ? d.actual : (d?.postCompactEstimate ?? d?.estimate ?? null);
        if (keyUsed) {
          keyUsed.textContent = curUsed != null
            ? `${d?.actual != null ? '' : '~'}${short(curUsed)}${pct != null ? ` (${pct.toFixed(1)}%)` : ''}`
            : '—';
        }
        if (keyLimit) keyLimit.textContent = d?.budget ? short(d.budget) : '—';
        if (keyRemaining) {
          if (curUsed != null && d?.budget && pct != null) {
            const rem = Math.max(0, d.budget - curUsed);
            const remPct = Math.max(0, 100 - pct);
            keyRemaining.textContent = `${short(rem)} (${remPct.toFixed(1)}%)`;
          } else {
            keyRemaining.textContent = t('key.pending');
          }
        }
        if (keyTakeaway) {
          keyTakeaway.textContent = t('key.takeaway.compacting');
          keyTakeaway.hidden = false;
          keyTakeaway.style.display = '';
        }
      } else if (d?.compacted && d?.postCompactEstimate != null) {
        if (pct != null) {
          const limitVal = d.budget || 256000;
          const remainVal = Math.max(0, limitVal - d.postCompactEstimate);
          const remainPct = Math.max(0, 100 - pct);
          if (keyBadge) {
            keyBadge.textContent = t('key.pill.compacted');
            keyBadge.className = pct >= 90 ? 'key-pill pill-danger' : (pct >= 75 ? 'key-pill pill-warn' : 'key-pill pill-good');
          }
          if (keyUsed) keyUsed.textContent = `~${short(d.postCompactEstimate)} (${pct.toFixed(1)}%)`;
          if (keyLimit) keyLimit.textContent = short(limitVal);
          if (keyRemaining) keyRemaining.textContent = `~${short(remainVal)} (${remainPct.toFixed(1)}%)`;
          if (keyTakeaway) {
            keyTakeaway.textContent = t('key.takeaway.compacted', { pct: pct.toFixed(1), rem: short(remainVal) });
            keyTakeaway.hidden = false;
            keyTakeaway.style.display = '';
          }
        } else {
          if (keyBadge) {
            keyBadge.textContent = t('key.pill.compacted');
            keyBadge.className = 'key-pill pill-good';
          }
          if (keyUsed) keyUsed.textContent = `~${short(d.postCompactEstimate)}`;
          if (keyLimit) keyLimit.textContent = d?.budget ? short(d.budget) : '—';
          if (keyRemaining) keyRemaining.textContent = t('key.pending');
          if (keyTakeaway) {
            keyTakeaway.textContent = t('badge.status.compacted');
            keyTakeaway.hidden = false;
            keyTakeaway.style.display = '';
          }
        }
      } else if (d?.actual != null && pct != null) {
        const limitVal = d.budget || 256000;
        const remainVal = Math.max(0, limitVal - d.actual);
        const remainPct = Math.max(0, 100 - pct);

        if (keyBadge) {
          if (pct >= 90) { keyBadge.textContent = t('key.pill.tight'); keyBadge.className = 'key-pill pill-danger'; }
          else if (pct >= 75) { keyBadge.textContent = t('key.pill.elevated'); keyBadge.className = 'key-pill pill-warn'; }
          else { keyBadge.textContent = t('key.pill.normal'); keyBadge.className = 'key-pill pill-good'; }
        }
        if (keyUsed) keyUsed.textContent = `${short(d.actual)} (${pct.toFixed(1)}%)`;
        if (keyLimit) keyLimit.textContent = short(limitVal);
        if (keyRemaining) keyRemaining.textContent = `${short(remainVal)} (${remainPct.toFixed(1)}%)`;
        if (keyTakeaway) {
          if (pct >= 90) {
            keyTakeaway.textContent = t('key.takeaway.90', { pct: pct.toFixed(1), rem: short(remainVal) });
            keyTakeaway.hidden = false;
            keyTakeaway.style.display = '';
          } else if (pct >= 75) {
            keyTakeaway.textContent = t('key.takeaway.75', { pct: pct.toFixed(1), rem: short(remainVal) });
            keyTakeaway.hidden = false;
            keyTakeaway.style.display = '';
          } else {
            keyTakeaway.textContent = t('key.takeaway.ok', { pct: pct.toFixed(1), rem: short(remainVal) });
            keyTakeaway.hidden = true;
            keyTakeaway.style.display = 'none';
          }
        }
      } else {
        if (keyBadge) { keyBadge.textContent = d?.estimated ? t('key.pill.est') : t('key.pill.reading'); keyBadge.className = 'key-pill pill-muted'; }
        if (keyUsed) keyUsed.textContent = d?.estimate ? t('key.estPrefix', { val: short(d.estimate) }) : (session?.total ? short(session.total.low) : '—');
        if (keyLimit) keyLimit.textContent = d?.budget ? short(d.budget) : '—';
        if (keyRemaining) keyRemaining.textContent = t('key.pending');
        if (keyTakeaway) {
          keyTakeaway.textContent = t('key.takeaway.est');
          keyTakeaway.hidden = true;
          keyTakeaway.style.display = 'none';
        }
      }
    }

    if (el('speed-summary')) {
      if (typeof evaluateGenerationExperience === 'function') {
        const evalRes = state.lastSpeedEval || evaluateGenerationExperience(resolveSpeedEvaluationInput(), currentPanelLanguage);
        renderSpeedExperienceInPlace(evalRes);
      } else {
        const spBadge = el('speed-badge');
        const spAvgVal = el('speed-avg-val');
        const spVal = el('speed-val');
        const spDur = el('speed-duration');
        const spTtft = el('speed-ttft');
        const spTokens = el('speed-tokens');
        const spTakeaway = el('speed-takeaway');
        if (spAvgVal) {
          spAvgVal.textContent = avgSpForRender?.avgTps != null ? `${avgSpForRender.avgTps} tok/s` : '—';
        }

        if (sp?.tps != null) {
          if (spBadge) {
            if (sp.tps >= 80) { spBadge.textContent = t('speed.pill.fast'); spBadge.className = 'key-pill pill-good'; }
            else if (sp.tps >= 35) { spBadge.textContent = t('speed.pill.smooth'); spBadge.className = 'key-pill pill-good'; }
            else if (sp.tps >= 15) { spBadge.textContent = t('speed.pill.good'); spBadge.className = 'key-pill pill-warn'; }
            else { spBadge.textContent = t('speed.pill.slow'); spBadge.className = 'key-pill pill-danger'; }
          }
          if (spVal) spVal.textContent = `${sp.tps} tok/s`;
          if (spDur) spDur.textContent = sp.duration ? `${sp.duration}s` : '—';
          if (spTtft) spTtft.textContent = sp.ttft ? `${sp.ttft}s` : '—';
          if (spTokens) spTokens.textContent = `${fmt(sp.outputTokens)} tok`;
          if (spTakeaway) {
            const modelStr = d?.model ? `（${d.model}）` : '';
            const streamInfo = sp.streamingTps ? t('speed.streamPart', { tps: sp.streamingTps }) : '';
            const avgPart = avgSpForRender?.avgTps != null
              ? t('speed.avgPart', {
                avgTps: avgSpForRender.avgTps,
                count: avgSpForRender.count,
                totalTok: fmt(avgSpForRender.totalOutputTokens),
                totalDur: avgSpForRender.totalDurationSec ?? '—'
              })
              : '';
            spTakeaway.textContent = t('speed.takeaway.ok', {
              tone: sp.tps >= 35 ? t('speed.tone.smooth') : t('speed.tone.steady'),
              tps: sp.tps,
              stream: streamInfo,
              dur: sp.duration,
              tok: fmt(sp.outputTokens),
              model: modelStr,
              avgPart
            });
          }
        } else {
          if (spBadge) { spBadge.textContent = state.requestBusy ? t('speed.pill.calc') : t('speed.pill.idle'); spBadge.className = 'key-pill pill-muted'; }
          if (spVal) spVal.textContent = '—';
          if (spDur) spDur.textContent = '—';
          if (spTtft) spTtft.textContent = '—';
          if (spTokens) spTokens.textContent = '—';
          if (spTakeaway) spTakeaway.textContent = t('speed.takeaway.idle');
        }
      }
    }

    el('model').textContent = d?.model?.startsWith('MODEL_PLACEHOLDER') ? t('tech.modelPlaceholder', { id: d.model }) : d?.model || t('tech.modelMissing');
    el('request-status').textContent = d?.exceeded ? t('tech.req.exceeded') : d?.network ? t('tech.req.network') : d?.error ? t('tech.req.failed') : isCompactingNow ? t('tech.req.compacting') : d?.compacted ? t('tech.req.compacted') : d?.status === 'reported' ? t('tech.req.reported') : d?.status === 'estimated' ? t('tech.req.estimated') : t('tech.req.waiting');
    el('actual').textContent = d?.actual != null ? token(d.actual) : d?.exceeded ? t('tech.actual.exceeded', { val: fmt(d.serviceLimit || 0) }) : d?.compacted ? t('tech.actual.compacted') : t('tech.actual.unknown');
    if (d?.exceeded && !d.serviceLimit) el('actual').textContent = t('tech.actual.exceededNoLim');
    el('estimate').textContent = d?.estimate ? t('tech.est.val', { val: fmt(d.estimate), note: d.exceeded ? t('tech.est.under') : (d.compacted ? t('tech.est.compacted') : t('tech.est.ref')) }) : t('tech.est.none');
    el('budget').textContent = token(d?.budget);
    el('service-limit').textContent = d?.serviceLimit ? t('tech.svcLim.val', { val: fmt(d.serviceLimit) }) : t('tech.svcLim.none');
    el('percent').textContent = d?.percent != null && !danger && !stale
      ? (d.compacted ? t('tech.pct.compactedVal', { pct: d.percent.toFixed(1) }) : t('tech.pct.val', { pct: d.percent.toFixed(1) }))
      : t('tech.pct.none');
    el('session-total').textContent = session?.total ? range(session.total) + (incomplete ? t('tech.plusUnknown') : '') : state.scanError ? t('tech.scanIncomplete') : t('tech.scanning');
    el('characters').textContent = session?.total ? fmt(session.total.chars) : '—';
    for (const name of ['user', 'assistant', 'thinking', 'tools', 'summaries']) {
      if (name === 'summaries' && session?.groups?.summaries && Number(session.checkpointCount) > 0 && Number.isInteger(session.lastCheckpointIndex) && session.lastCheckpointIndex >= 0) {
        el(name).textContent = t('tech.summaries.withCheckpoints', {
          range: range(session.groups.summaries),
          count: session.checkpointCount,
          step: session.lastCheckpointIndex
        });
      } else {
        el(name).textContent = session?.groups ? range(session.groups[name]) : '—';
      }
    }
    el('system').textContent = session?.groups ? range({ low: (session.groups.system?.low || 0) + (session.groups.definitions?.low || 0), high: (session.groups.system?.high || 0) + (session.groups.definitions?.high || 0) }) : '—';
    const subGrp = session?.compositionSubgroups;
    if (el('injections')) {
      el('injections').textContent = (subGrp && Number(subGrp.injectionCount) > 0)
        ? t('session.tech.subCount', { range: range(subGrp.injections), count: subGrp.injectionCount })
        : '—';
    }
    if (el('skills')) {
      el('skills').textContent = (subGrp && Number(subGrp.skillCount) > 0)
        ? t('session.tech.subCount', { range: range(subGrp.skills), count: subGrp.skillCount })
        : '—';
    }
    if (el('composition-gap')) {
      const comp = (session && typeof buildSessionCompositionBreakdown === 'function')
        ? buildSessionCompositionBreakdown(session, d)
        : null;
      if (comp && comp.actualTokens != null && comp.estimatedTotalMedian > 0) {
        const diffSign = comp.diffTokens > 0 ? '+' : (comp.diffTokens < 0 ? '-' : '');
        el('composition-gap').textContent = t('session.tech.gapVal', {
          actual: short(comp.actualTokens),
          est: short(comp.estimatedTotalMedian),
          diff: `${diffSign}${short(Math.abs(comp.diffTokens || 0))}`
        });
      } else {
        el('composition-gap').textContent = '—';
      }
    }
    el('attachment-total').textContent = session?.attachmentTotal ? range(session.attachmentTotal) + (incomplete ? t('tech.plusUnknownShort') : '') : '—';
    el('steps').textContent = session?.steps != null ? t('tech.stepsVal', { steps: fmt(session.steps), user: session.userMessages, assistant: session.assistantMessages }) : t('tech.stepsNone');
    el('coverage').textContent = Array.isArray(session?.attachments)
      ? t('tech.coverageVal', {
        total: session.attachments.length,
        user: session.attachments.filter(f => f.source === 'user').length,
        assistant: session.attachments.filter(f => f.source === 'assistant').length,
        read: session.attachments.filter(f => f.chars > 0).length,
        unknown: session.unknownFiles,
        rescan: state.scanBusy ? t('tech.coverageRescan') : '',
        err: state.scanError ? t('tech.coverageErr', { err: translateBackendText(state.scanError) }) : ''
      })
      : (state.scanError ? translateBackendText(state.scanError) : t('tech.coverageScanning'));
    el('updated').textContent = t('tech.updatedVal', {
      req: state.requestAt ? new Date(state.requestAt).toLocaleTimeString() : t('tech.unread'),
      scan: state.scan ? new Date(state.scan.scannedAt).toLocaleTimeString() : t('tech.unfinished')
    });
    el('refresh').disabled = state.scanBusy;
    scheduleLatestCallRefresh({ allowTimelineRefresh: false });
    if (typeof syncContextPanelContainerWidthTier === 'function') syncContextPanelContainerWidthTier();
    if (typeof renderContextTrendCard === 'function') renderContextTrendCard();
    if (typeof renderSessionBentoSections === 'function') renderSessionBentoSections();
    if (state.historyDrawerOpen) renderSessionTimeline();
    renderComposerStatusBar();
    renderTurnFooterStats();
    if (typeof syncAuxQuickSwitchAndMorphToolbar === 'function') syncAuxQuickSwitchAndMorphToolbar();
    syncOverflowMenuMetrics?.();
  }

  const MAX_FLUSH_BATCH_CALLS = 500;
  const MAX_FLUSH_BATCH_BYTES = 900 * 1024;
  const MAX_LIVE_RECORD_BODY_BYTES = 1024 * 1024;
  const utf8Encoder = typeof TextEncoder === 'function' ? new TextEncoder() : null;

  function getUtf8ByteLength(str) {
    const s = String(str ?? '');
    if (utf8Encoder) return utf8Encoder.encode(s).length;
    if (typeof Buffer !== 'undefined' && typeof Buffer.byteLength === 'function') return Buffer.byteLength(s, 'utf8');
    let bytes = 0;
    for (let i = 0; i < s.length; i++) {
      const code = s.charCodeAt(i);
      if (code < 0x80) bytes += 1;
      else if (code < 0x800) bytes += 2;
      else if (code >= 0xd800 && code <= 0xdbff && i + 1 < s.length) {
        const next = s.charCodeAt(i + 1);
        if (next >= 0xdc00 && next <= 0xdfff) { bytes += 4; i++; }
        else bytes += 3;
      } else bytes += 3;
    }
    return bytes;
  }

  const getSingleCallBodyBytes = call => 12 + getUtf8ByteLength(JSON.stringify(call));

  const getModelRank = (model, modelKey) => {
    const s = String(model || '').trim();
    if (!s) return 0;
    if (/^model_placeholder_/i.test(s)) return modelKey ? 2 : 1;
    return modelKey ? 3 : 2;
  };

  const getDateRank = call => {
    if (!call) return 0;
    const hasDate = Boolean(call.date && /^\d{4}-\d{2}-\d{2}/.test(String(call.date)));
    const isProv = call.dateIsProvisional === true || call.dateSource === 'provisional';
    if (isProv) return hasDate ? 1 : 0;
    let hasValidCreatedAt = false;
    if (call.created_at) {
      const dt = new Date(call.created_at);
      hasValidCreatedAt = !Number.isNaN(dt.getTime());
    }
    if (call.dateSource === 'transcript' && (hasDate || hasValidCreatedAt)) return 4;
    if (hasValidCreatedAt) return 3;
    if (hasDate) return 2;
    return 0;
  };

  const resolveWatermarkDate = call => {
    if (!call) return '';
    const isProv = call.dateIsProvisional === true || call.dateSource === 'provisional';
    if (!isProv && call.created_at) {
      const dt = new Date(call.created_at);
      if (!Number.isNaN(dt.getTime())) return formatLocalYmd(dt);
    }
    return (call.date && /^\d{4}-\d{2}-\d{2}/.test(String(call.date))) ? String(call.date).slice(0, 10) : '';
  };

  function rawRevIsPresent(val) {
    return val !== null && val !== '';
  }

  const extractSourceRevision = row => {
    if (!row || typeof row !== 'object') return null;
    const raw = row.sourceRevision ?? row.revision ?? row.metadataRevision;
    if (raw !== undefined && rawRevIsPresent(raw)) {
      const num = Number(raw);
      if (Number.isFinite(num)) return num;
    }
    const rawUpdated = row.updated_at ?? row.sourceUpdatedAt;
    if (rawUpdated !== undefined && rawRevIsPresent(rawUpdated)) {
      const ts = typeof rawUpdated === 'number' ? rawUpdated : Date.parse(String(rawUpdated));
      if (Number.isFinite(ts)) return ts;
    }
    return null;
  };

  const compareSourceRevision = (incRev, baseRev) => {
    const a = typeof incRev === 'number' && Number.isFinite(incRev) ? incRev : null;
    const b = typeof baseRev === 'number' && Number.isFinite(baseRev) ? baseRev : null;
    if (a === null && b === null) return 0;
    if (a !== null && b === null) return 1;
    if (a === null && b !== null) return -1;
    if (a === b) return 0;
    return a > b ? 1 : -1;
  };

  const compareWatermarkUsage = (a, b) => {
    const totDiff = (a?.tot || 0) - (b?.tot || 0);
    if (totDiff !== 0) return totDiff;
    return (a?.out || 0) - (b?.out || 0);
  };

  const canAdoptNextDate = (nextWm, prevWm) => {
    if (!prevWm) return Boolean(nextWm?.date);
    const nextDateRank = nextWm?.dateRank || 0;
    const prevDateRank = prevWm?.dateRank || 0;
    if (nextDateRank > prevDateRank) return Boolean(nextWm?.date);
    if (nextDateRank < prevDateRank) return false;
    if (!nextWm?.date) return false;
    if (!prevWm?.date) return true;
    const usageCmp = compareWatermarkUsage(nextWm, prevWm);
    const revCmp = compareSourceRevision(nextWm.sourceRevision, prevWm.sourceRevision);
    if (nextDateRank >= 2) {
      if (revCmp > 0 && usageCmp >= 0) return true;
      if (usageCmp > 0 && revCmp >= 0) return true;
      return nextWm.date === prevWm.date && (nextWm.createdAt || '') === (prevWm.createdAt || '') && revCmp >= 0 && usageCmp >= 0;
    }
    return nextWm.date < prevWm.date;
  };

  const getFinalCallWatermark = call => ({
    inp: call?.inputTokens || 0,
    cap: call?.cacheTokens || 0,
    tot: (call?.inputTokens || 0) + (call?.cacheTokens || 0) + (call?.outputTokens || 0),
    out: call?.outputTokens || 0,
    model: String(call?.model || '').trim(),
    modelKey: String(call?.modelKey || '').trim(),
    isPriced: Boolean(call?.isPriced),
    costUSD: Number(call?.costUSD || 0),
    date: resolveWatermarkDate(call),
    createdAt: call?.created_at ? String(call.created_at) : '',
    dateSource: call?.dateSource ? String(call.dateSource) : '',
    dateRank: getDateRank(call),
    sourceRevision: extractSourceRevision(call)
  });

  function hasWatermarkProgressed(nextWm, prevWm) {
    if (!prevWm) return true;
    const usageCmp = compareWatermarkUsage(nextWm, prevWm);
    if (usageCmp > 0) return true;
    if (getModelRank(nextWm.model, nextWm.modelKey) > getModelRank(prevWm.model, prevWm.modelKey)) return true;
    if (!prevWm.modelKey && Boolean(nextWm.modelKey)) return true;
    if (!prevWm.isPriced && Boolean(nextWm.isPriced)) return true;
    const nextDateRank = nextWm.dateRank || 0;
    const prevDateRank = prevWm.dateRank || 0;
    if (nextDateRank > prevDateRank) return true;
    const usageRegressed = usageCmp < 0;
    const revCmp = compareSourceRevision(nextWm.sourceRevision, prevWm.sourceRevision);
    if (!usageRegressed && revCmp > 0) return true;
    const takeNextDate = canAdoptNextDate(nextWm, prevWm);
    if (
      takeNextDate &&
      nextDateRank >= 2 &&
      nextDateRank === prevDateRank &&
      Boolean(nextWm.date) &&
      (
        nextWm.date !== prevWm.date ||
        (nextDateRank >= 3 && Boolean(nextWm.createdAt) && nextWm.createdAt !== (prevWm.createdAt || ''))
      )
    ) {
      return true;
    }
    const hasUnacceptedDate = Boolean(prevWm.date) && Boolean(nextWm.date) && nextWm.date !== prevWm.date && !takeNextDate;
    if (!usageRegressed && revCmp >= 0 && !hasUnacceptedDate && nextWm.isPriced && !(prevWm.costUSD > 0) && nextWm.costUSD > 0) return true;
    return false;
  }

  function mergeWatermarks(prevWm, nextWm) {
    if (!prevWm) return { ...nextWm };
    const nextRank = getModelRank(nextWm.model, nextWm.modelKey);
    const prevRank = getModelRank(prevWm.model, prevWm.modelKey);
    const nextDateRank = nextWm.dateRank || 0;
    const prevDateRank = prevWm.dateRank || 0;
    const usageCmp = compareWatermarkUsage(nextWm, prevWm);
    const usageRegressed = usageCmp < 0;
    const revCmp = compareSourceRevision(nextWm.sourceRevision, prevWm.sourceRevision);
    const takeNextUsage = usageCmp > 0 || (usageCmp === 0 && revCmp >= 0);
    const takeNextDate = canAdoptNextDate(nextWm, prevWm);
    const mergedSourceRevision = revCmp >= 0
      ? (nextWm.sourceRevision ?? prevWm.sourceRevision ?? null)
      : (prevWm.sourceRevision ?? null);
    let mergedCost = Math.max(prevWm.isPriced ? (prevWm.costUSD || 0) : 0, nextWm.isPriced ? (nextWm.costUSD || 0) : 0);
    if (!usageRegressed && revCmp >= 0 && nextWm.isPriced && (takeNextDate || nextWm.date === prevWm.date || !prevWm.date)) {
      mergedCost = nextWm.costUSD || 0;
    }
    return {
      inp: takeNextUsage ? (nextWm.inp ?? 0) : (prevWm.inp ?? 0),
      cap: takeNextUsage ? (nextWm.cap ?? 0) : (prevWm.cap ?? 0),
      tot: takeNextUsage ? nextWm.tot : prevWm.tot,
      out: takeNextUsage ? nextWm.out : prevWm.out,
      model: nextRank >= prevRank && nextWm.model ? nextWm.model : prevWm.model,
      modelKey: nextWm.modelKey || prevWm.modelKey || '',
      isPriced: Boolean(prevWm.isPriced || nextWm.isPriced),
      costUSD: mergedCost,
      date: takeNextDate ? nextWm.date : (prevWm.date || nextWm.date || ''),
      createdAt: takeNextDate ? (nextWm.createdAt || '') : (prevWm.createdAt || ''),
      dateSource: takeNextDate ? (nextWm.dateSource || '') : (prevWm.dateSource || ''),
      dateRank: Math.max(prevDateRank, nextDateRank),
      sourceRevision: mergedSourceRevision
    };
  }

  function mergePendingCallData(prevCall, nextCall) {
    if (!prevCall) return nextCall;
    const prevWm = getFinalCallWatermark(prevCall);
    const nextWm = getFinalCallWatermark(nextCall);
    const merged = { ...nextCall };
    const usageCmp = compareWatermarkUsage(nextWm, prevWm);
    const revCmp = compareSourceRevision(nextWm.sourceRevision, prevWm.sourceRevision);
    const takePrevUsage = usageCmp < 0 || (usageCmp === 0 && revCmp < 0);
    if (takePrevUsage) {
      merged.inputTokens = prevCall.inputTokens;
      merged.cacheTokens = prevCall.cacheTokens;
      merged.cacheReadTokens = prevCall.cacheReadTokens;
      merged.outputTokens = prevCall.outputTokens;
      merged.thinkingTokens = prevCall.thinkingTokens;
      merged.responseTokens = prevCall.responseTokens;
      merged.totalTokens = prevCall.totalTokens;
    }
    const takeNextDate = canAdoptNextDate(nextWm, prevWm);
    const takePrevDate = !takeNextDate && Boolean(prevWm.date || (prevWm.dateRank || 0) > (nextWm.dateRank || 0));
    if (takePrevDate) {
      merged.date = prevCall.date;
      merged.created_at = prevCall.created_at;
      if (prevCall.dateSource !== undefined) merged.dateSource = prevCall.dateSource;
      else delete merged.dateSource;
      merged.dateIsProvisional = prevCall.dateIsProvisional;
      if (prevCall.timestamp !== undefined) merged.timestamp = prevCall.timestamp;
    }
    if (revCmp < 0 && prevWm.sourceRevision !== null) {
      merged.sourceRevision = prevWm.sourceRevision;
    } else if (nextWm.sourceRevision !== null) {
      merged.sourceRevision = nextWm.sourceRevision;
    } else {
      delete merged.sourceRevision;
    }
    if (getModelRank(prevWm.model, prevWm.modelKey) > getModelRank(nextWm.model, nextWm.modelKey)) {
      merged.model = prevCall.model;
    }
    if (!merged.requestedModel && prevCall.requestedModel) {
      merged.requestedModel = prevCall.requestedModel;
    }
    if (!merged.requestedModelRaw && prevCall.requestedModelRaw) {
      merged.requestedModelRaw = prevCall.requestedModelRaw;
    }
    if (!nextWm.modelKey && prevWm.modelKey) {
      merged.modelKey = prevCall.modelKey;
    }
    if (typeof calculateRequestApiCost === 'function' && (merged.model || merged.modelKey)) {
      const recalc = calculateRequestApiCost(merged);
      if (recalc.isPriced) {
        merged.modelKey = recalc.modelKey;
        merged.isPriced = true;
        merged.costUSD = recalc.costUSD ?? 0;
      }
    } else if (!nextWm.isPriced && prevWm.isPriced) {
      merged.isPriced = prevCall.isPriced;
      merged.costUSD = prevCall.costUSD;
    } else if (nextWm.isPriced && prevWm.isPriced && (takePrevUsage || takePrevDate) && (prevWm.costUSD || 0) > (nextWm.costUSD || 0)) {
      merged.costUSD = prevCall.costUSD;
    }
    return merged;
  }

  function takeNextPendingBatch(pendingMap) {
    const chunk = [];
    const snap = [];
    let totalBytes = 12; // '{"calls":[]}'
    for (const call of pendingMap.values()) {
      if (chunk.length >= MAX_FLUSH_BATCH_CALLS) break;
      const itemBytes = getUtf8ByteLength(JSON.stringify(call));
      if (12 + itemBytes > MAX_FLUSH_BATCH_BYTES) continue;
      const addedBytes = (chunk.length > 0 ? 1 : 0) + itemBytes;
      if (chunk.length > 0 && totalBytes + addedBytes > MAX_FLUSH_BATCH_BYTES) break;
      chunk.push(call);
      snap.push({ callId: call.callId, wm: getFinalCallWatermark(call) });
      totalBytes += addedBytes;
    }
    return { chunk, snap };
  }

  function commitConfirmedEntries(entries) {
    for (const entry of entries) {
      state.quarantinedOversizeMap?.delete(entry.callId);
      const curSynced = state.syncedFinalMap.get(entry.callId);
      const nextSynced = mergeWatermarks(curSynced, entry.wm);
      state.syncedFinalMap.set(entry.callId, nextSynced);
      const curPending = state.pendingFinalCalls.get(entry.callId);
      if (curPending && !hasWatermarkProgressed(getFinalCallWatermark(curPending), nextSynced)) {
        state.pendingFinalCalls.delete(entry.callId);
      }
    }
  }

  const EXPLICIT_OVERSIZE_RE = /\b413\b|payload\s+too\s+large|entity\s+too\s+large|body\s+too\s+large|(?:payload|body|size|record|message|batch|bytes?)\b.*(?:exceeds?|exceeded|over)\b|(?:exceeds?|exceeded|over)\b.*(?:\d+\s*(?:kib|mib|kb|mb|bytes?)|(?:size|payload|body)\s*(?:limit|max))|传输体积超限|体积超限|超出上限|超过.*上限/i;

  function isExplicitOversizeError(recRes) {
    if (!recRes || typeof recRes !== 'object') return false;
    if (recRes.status === 413) return true;
    if (recRes.code === 'PAYLOAD_TOO_LARGE' || recRes.code === 'OVERSIZE' || recRes.phase === 'oversize_guard') return true;
    return EXPLICIT_OVERSIZE_RE.test(String(recRes.error || ''));
  }

  function quarantineOversizedEntry(callId, wm) {
    if (!state.quarantinedOversizeMap) state.quarantinedOversizeMap = new Map();
    const prevQuarantined = state.quarantinedOversizeMap.get(callId);
    state.quarantinedOversizeMap.set(callId, mergeWatermarks(prevQuarantined, wm));
    const curPending = state.pendingFinalCalls.get(callId);
    if (curPending && !hasWatermarkProgressed(getFinalCallWatermark(curPending), wm) && getSingleCallBodyBytes(curPending) > MAX_FLUSH_BATCH_BYTES) {
      state.pendingFinalCalls.delete(callId);
    }
  }

  async function flushPendingFinalCalls(triggerSyncEvenIfUnchanged) {
    if (triggerSyncEvenIfUnchanged && state.flushFinalsBusy) {
      state.pendingFlushForceSync = true;
    }
    if (state.flushFinalsBusy || state.disposed || !state.pendingFinalCalls?.size) return;
    if (Date.now() < (state.nextFlushRetryAt || 0)) return;
    state.flushFinalsBusy = true;
    let anySucceeded = false;
    let anyChanged = false;
    let failedDuringLoop = false;
    try {
      while (!state.disposed && state.pendingFinalCalls.size > 0) {
        if (Date.now() < (state.nextFlushRetryAt || 0)) break;
        const { chunk, snap } = takeNextPendingBatch(state.pendingFinalCalls);
        if (!chunk.length) break;
        const recRes = await recordModelCallsRemote(chunk);
        if (state.disposed) break;
        if (recRes?.ok === true) {
          anySucceeded = true;
          if (recRes.changed) anyChanged = true;
          commitConfirmedEntries(snap);
        } else {
          failedDuringLoop = true;
          state.nextFlushRetryAt = Date.now() + (document.hidden ? 15000 : 3000);
          break;
        }
      }
      if (!state.disposed && !failedDuringLoop && state.pendingFinalCalls.size > 0 && Date.now() >= (state.nextOversizeRetryAt || 0)) {
        const oversizedItems = [];
        for (const call of state.pendingFinalCalls.values()) {
          const singleBytes = getSingleCallBodyBytes(call);
          if (singleBytes > MAX_FLUSH_BATCH_BYTES) {
            oversizedItems.push({ call, singleBytes, wm: getFinalCallWatermark(call) });
          }
        }
        for (const item of oversizedItems) {
          if (state.disposed) break;
          if (!state.pendingFinalCalls.has(item.call.callId)) continue;
          const isLiveHttpMode = (typeof window !== 'undefined' && typeof window.contextMeterAPI?.recordCalls !== 'function' && hasLiveHttpBridge())
            || shouldPreferLiveHost(typeof window?.contextMeterAPI?.recordCalls === 'function', '/record-calls');
          if (isLiveHttpMode && item.singleBytes > MAX_LIVE_RECORD_BODY_BYTES) {
            quarantineOversizedEntry(item.call.callId, item.wm);
            console.warn(`Context Meter: 单条调用记录超过实时通道 1MiB 上限 (${item.singleBytes} bytes)，已隔离跳过: ${item.call.callId}`);
            continue;
          }
          const recRes = await recordModelCallsRemote([item.call]);
          if (state.disposed) break;
          if (recRes?.ok === true) {
            anySucceeded = true;
            if (recRes.changed) anyChanged = true;
            state.nextOversizeRetryAt = 0;
            commitConfirmedEntries([{ callId: item.call.callId, wm: item.wm }]);
          } else if ((isLiveHttpMode && (item.singleBytes > MAX_LIVE_RECORD_BODY_BYTES || recRes?.status === 413)) || isExplicitOversizeError(recRes)) {
            quarantineOversizedEntry(item.call.callId, item.wm);
            console.warn(`Context Meter: 超大调用记录入账被拒绝，已隔离跳过: ${item.call.callId}`);
          } else {
            failedDuringLoop = true;
            const retryAt = Date.now() + (document.hidden ? 15000 : 3000);
            state.nextOversizeRetryAt = retryAt;
            state.nextFlushRetryAt = retryAt;
            break;
          }
        }
      }
      if (!state.disposed && !failedDuringLoop && state.pendingFinalCalls.size > 0 && (state.nextOversizeRetryAt || 0) > Date.now()) {
        const { chunk: remainingNormal } = takeNextPendingBatch(state.pendingFinalCalls);
        if (!remainingNormal.length) {
          state.nextFlushRetryAt = state.nextOversizeRetryAt;
        }
      }
      if (!state.disposed && anySucceeded) {
        if (!failedDuringLoop && state.pendingFinalCalls.size === 0) {
          state.nextFlushRetryAt = 0;
          state.nextOversizeRetryAt = 0;
        }
        if (triggerSyncEvenIfUnchanged || state.pendingFlushForceSync || anyChanged) {
          state.pendingFlushForceSync = false;
          automaticHistorySyncPending = true;
          syncPendingAutomaticHistory();
        }
        if (typeof scheduleQuotaPostTurnRefresh === 'function') {
          scheduleQuotaPostTurnRefresh();
        }
      }
    } finally {
      state.flushFinalsBusy = false;
      if (anySucceeded && !state.disposed && state.pendingFinalCalls.size > 0 && Date.now() >= (state.nextFlushRetryAt || 0)) {
        void flushPendingFinalCalls(true);
      }
    }
  }

  function getRendererCsrfToken() {
    const direct = typeof window !== 'undefined' ? window.__APP_CONFIG__?.csrfToken : null;
    if (typeof direct === 'string' && direct.trim()) return direct.trim();
    try {
      const stored = typeof window !== 'undefined' ? (window.localStorage?.getItem?.('agy_session_csrf_token') || window.sessionStorage?.getItem?.('agy_session_csrf_token')) : null;
      if (typeof stored === 'string' && stored.trim()) return stored.trim();
    } catch { }
    return '';
  }

  function resolveDefaultBudgetFallbackForCompaction(baseLatest) {
    if (baseLatest?.budget && baseLatest.budget > 0) return baseLatest.budget;
    if (state.scan?.preCompactLatest?.budget && state.scan.preCompactLatest.budget > 0) {
      return state.scan.preCompactLatest.budget;
    }
    if (state.latest?.budget && state.latest.budget > 0) return state.latest.budget;
    return null;
  }

  function resolveEffectiveLatestWithCompaction(candidateLatest, candidateMeta = null, candidateGenIndex = -1) {
    const scanSession = state.scan?.session || null;
    const scanCpIdx = Number.isInteger(scanSession?.lastCheckpointIndex) ? scanSession.lastCheckpointIndex : -1;
    const scanGenCount = Number.isFinite(Number(state.scan?.generatorCount)) ? Number(state.scan.generatorCount) : -1;
    const hCwu = (state.hostContextWindowUsage && state.hostContextWindowUsage.cascadeId === state.route)
      ? state.hostContextWindowUsage
      : null;
    const hostCpActive = Boolean(hCwu?.estimatedAfterCompaction);
    const hostStepIdx = Number.isInteger(hCwu?.lastStepIndex) ? hCwu.lastStepIndex : -1;
    const hostGenIdx = Number.isInteger(hCwu?.generatorMetadataIndex) ? hCwu.generatorMetadataIndex : -1;

    const effectiveCpIdx = Math.max(scanCpIdx, hostCpActive ? Math.max(0, hostStepIdx) : -1);
    if (effectiveCpIdx < 0 && !hostCpActive) {
      return withStepError(candidateLatest, candidateMeta);
    }

    if (candidateLatest && !candidateLatest.compacted) {
      const rowMaxStep = typeof extractGeneratorMaxStep === 'function'
        ? extractGeneratorMaxStep(candidateMeta)
        : -1;
      const hasOutcome = candidateLatest.actual !== null || Boolean(candidateLatest.error);
      if (rowMaxStep >= 0) {
        if (rowMaxStep > effectiveCpIdx && hasOutcome) {
          if (hCwu && hCwu.estimatedAfterCompaction && (hostStepIdx < 0 || rowMaxStep > hostStepIdx)) {
            hCwu.estimatedAfterCompaction = false;
          }
          return withStepError(candidateLatest, candidateMeta);
        }
      } else if (hasOutcome) {
        const lastModelStep = Number.isInteger(scanSession?.lastModelStepAt)
          ? scanSession.lastModelStepAt
          : (Number.isInteger(scanSession?.lastAssistantAt) ? scanSession.lastAssistantAt : -1);
        // 若旧检查点之后已存在真实模型/工具步，证明 scanCpIdx 是早先已被超越的历史检查点（二次压缩期间亦应保持压缩前真实用量，避免误拿旧检查点重算）
        const scanAlreadyHasPostModelStep = scanCpIdx >= 0 && lastModelStep > scanCpIdx && !hostCpActive;
        const isCompactingCurrentRoute = Boolean(state.compacting && state.compacting.cascadeId === state.route);
        const genAdvancedPastScan = !isCompactingCurrentRoute && scanCpIdx >= 0 && scanGenCount > 0 && candidateGenIndex >= scanGenCount && !hostCpActive;
        const genAdvancedPastHost = !isCompactingCurrentRoute && hostCpActive && hostGenIdx >= 0 && candidateGenIndex > hostGenIdx;
        if (scanAlreadyHasPostModelStep || genAdvancedPastScan || genAdvancedPastHost) {
          if (hCwu && hCwu.estimatedAfterCompaction) {
            hCwu.estimatedAfterCompaction = false;
          }
          return withStepError(candidateLatest, candidateMeta);
        }
      }
    }

    if (typeof buildPostCompactSummary === 'function') {
      const baseRef = (candidateLatest && !candidateLatest.compacted)
        ? {
          ...(state.scan?.preCompactLatest || state.latest || {}),
          ...candidateLatest,
          budget: candidateLatest.budget || resolveDefaultBudgetFallbackForCompaction(candidateLatest),
          model: candidateLatest.model || state.scan?.preCompactLatest?.model || state.latest?.model || '',
          modelId: candidateLatest.modelId || state.scan?.preCompactLatest?.modelId || state.latest?.modelId || null,
          modelRaw: candidateLatest.modelRaw || state.scan?.preCompactLatest?.modelRaw || state.latest?.modelRaw || '',
          speed: candidateLatest.speed || state.latest?.speed || state.scan?.preCompactLatest?.speed || null
        }
        : (state.scan?.preCompactLatest || candidateLatest || state.latest || null);
      const compactedObj = buildPostCompactSummary({
        session: scanSession,
        postCheckpointAttachmentTotal: scanSession?.postCheckpointAttachmentTotal,
        system: scanSession?.groups?.system,
        definitions: scanSession?.groups?.definitions,
        previousLatest: baseRef,
        hostContextWindowUsage: hCwu,
        defaultBudgetFallback: resolveDefaultBudgetFallbackForCompaction(baseRef)
      });
      return withStepError(compactedObj, null);
    }

    return withStepError(candidateLatest, candidateMeta);
  }

  async function requestPoll(generation, id) {
    state.requestBusy = true;
    const controller = new AbortController(); state.controllers.add(controller);
    const timeout = setTimeout(() => controller.abort(), 12000);
    try {
      const csrf = getRendererCsrfToken(); if (!csrf) throw new Error('后台尚未就绪');
      const fromCache = Boolean(state.restoredFromCache);
      const prevCount = state.count || 0;
      let offset = Math.max(0, prevCount - 3);
      const fetchMeta = off => fetch('/exa.language_server_pb.LanguageServerService/GetCascadeTrajectoryGeneratorMetadata', { method: 'POST', headers: { 'Content-Type': 'application/json', 'Connect-Protocol-Version': '1', 'x-codeium-csrf-token': csrf }, body: JSON.stringify({ cascadeId: id, generatorMetadataOffset: off, includeMessages: false }), signal: controller.signal });
      let response = await fetchMeta(offset);
      if (!response.ok) throw new Error(`HTTP ${response.status}`);
      let data = await response.json(); if (generation !== state.generation || state.disposed || !sameRouteId(id, state.route)) return;
      let rows = data.generatorMetadata || [];
      if (fromCache && offset > 0 && (!rows.length || offset + rows.length < prevCount)) {
        offset = 0;
        response = await fetchMeta(0);
        if (!response.ok) throw new Error(`HTTP ${response.status}`);
        data = await response.json(); if (generation !== state.generation || state.disposed || !sameRouteId(id, state.route)) return;
        rows = data.generatorMetadata || [];
      }
      state.restoredFromCache = false;
      const nextCount = rows.length ? offset + rows.length : 0;
      if (fromCache && nextCount < prevCount) {
        sessionSnapshotCache.delete(id);
        state.sessionCallsMap?.clear();
        if (!nextCount) Object.assign(state, { latest: null, displayedCallRecord: null, displayedCallSig: '', lastSpeedEval: null });
      }
      state.count = nextCount;
      if (!state.sessionCallsMap) state.sessionCallsMap = new Map();
      if (!state.syncedFinalMap) state.syncedFinalMap = new Map();
      if (!state.pendingFinalCalls) state.pendingFinalCalls = new Map();
      if (!state.quarantinedOversizeMap) state.quarantinedOversizeMap = new Map();
      const wasHydrated = Boolean(state.callsHydrated);
      let hasNewOrProgressedPending = false;
      const modelConfigsList = state.cascadeModelConfigs || state.scan?.cascadeModelConfigs || [];
      for (let i = 0; i < rows.length; i++) {
        const call = parseGeneratorCall ? parseGeneratorCall(rows[i], id, 'desktop', { cascadeModelConfigs: modelConfigsList }) : null;
        if (call && call.callId) {
          const prevSessionCall = state.sessionCallsMap.get(call.callId);
          const prevSynced = state.syncedFinalMap.get(call.callId);
          const prevPending = state.pendingFinalCalls.get(call.callId);
          const prevQuarantined = state.quarantinedOversizeMap.get(call.callId);
          let effectiveCall = (prevSessionCall && call.status === 'final' && prevSessionCall.status === 'final')
            ? mergePendingCallData(prevSessionCall, call)
            : call;
          const isNewLiveObservation = Boolean(
            (wasHydrated && !prevSessionCall) ||
            prevSessionCall?.liveRealtimeConfirmed === true ||
            (state.livePendingRequest && state.livePendingRequest.cascadeId === id && call.callId !== state.livePendingRequest.baselineCallId)
          );
          if (isNewLiveObservation) {
            const trackedReq = state.lastRequestedModelByCascade?.get?.(id);
            const useTrackedReq = !effectiveCall.requestedModel && trackedReq && (Date.now() - (trackedReq.ts || 0) < 300000);
            effectiveCall = {
              ...effectiveCall,
              ...(useTrackedReq ? {
                requestedModel: trackedReq.requestedModel,
                ...(trackedReq.requestedModelRaw ? { requestedModelRaw: trackedReq.requestedModelRaw } : {})
              } : {}),
              liveRealtimeConfirmed: true,
              liveObservedAtMs: prevSessionCall?.liveObservedAtMs || Date.now()
            };
          }
          if (prevPending && effectiveCall.status === 'final' && prevPending.status === 'final') {
            effectiveCall = mergePendingCallData(prevPending, effectiveCall);
          }
          if (effectiveCall.status === 'final') {
            if (prevSynced) {
              const effWm0 = getFinalCallWatermark(effectiveCall);
              const uCmp0 = compareWatermarkUsage(effWm0, prevSynced);
              const rCmp0 = compareSourceRevision(effWm0.sourceRevision, prevSynced.sourceRevision);
              const restoreSyncedUsage = (uCmp0 < 0 || (uCmp0 === 0 && rCmp0 < 0)) && prevSynced.inp !== undefined;
              const restoreSyncedDate = (prevSynced.dateRank || 0) >= 2 && Boolean(prevSynced.date) && !canAdoptNextDate(effWm0, prevSynced);
              const restoreSyncedRev = rCmp0 < 0 && prevSynced.sourceRevision !== null && prevSynced.sourceRevision !== undefined;
              if (restoreSyncedUsage || restoreSyncedDate || restoreSyncedRev) {
                effectiveCall = {
                  ...effectiveCall,
                  ...(restoreSyncedUsage ? {
                    inputTokens: prevSynced.inp,
                    cacheTokens: prevSynced.cap,
                    cacheReadTokens: prevSynced.cap,
                    outputTokens: prevSynced.out,
                    totalTokens: prevSynced.tot
                  } : {}),
                  ...(restoreSyncedDate ? {
                    date: prevSynced.date,
                    created_at: prevSynced.createdAt || null,
                    ...(prevSynced.dateSource ? { dateSource: prevSynced.dateSource } : {}),
                    dateIsProvisional: false
                  } : {}),
                  ...(restoreSyncedRev ? { sourceRevision: prevSynced.sourceRevision } : {})
                };
                if (restoreSyncedDate && !prevSynced.dateSource) delete effectiveCall.dateSource;
                if (typeof calculateRequestApiCost === 'function' && (effectiveCall.model || effectiveCall.modelKey)) {
                  const recalc = calculateRequestApiCost(effectiveCall);
                  if (recalc.isPriced) {
                    effectiveCall.modelKey = recalc.modelKey;
                    effectiveCall.isPriced = true;
                    effectiveCall.costUSD = recalc.costUSD ?? 0;
                  }
                }
              }
            }
            if (getDateRank(effectiveCall) === 1) {
              let earliestProvDate = effectiveCall.date ? String(effectiveCall.date).slice(0, 10) : '';
              for (const ref of [prevPending, prevSynced, prevQuarantined]) {
                const refRank = ref ? (ref.dateRank !== undefined ? ref.dateRank : getDateRank(ref)) : 0;
                const refDate = ref?.date ? String(ref.date).slice(0, 10) : '';
                if (refRank === 1 && refDate && (!earliestProvDate || refDate < earliestProvDate)) {
                  earliestProvDate = refDate;
                }
              }
              if (earliestProvDate && earliestProvDate !== String(effectiveCall.date || '').slice(0, 10)) {
                effectiveCall = { ...effectiveCall, date: earliestProvDate, created_at: null, dateSource: 'provisional', dateIsProvisional: true };
                if (typeof calculateRequestApiCost === 'function' && (effectiveCall.model || effectiveCall.modelKey)) {
                  const recalc = calculateRequestApiCost(effectiveCall);
                  if (recalc.isPriced) {
                    effectiveCall.modelKey = recalc.modelKey;
                    effectiveCall.isPriced = true;
                    effectiveCall.costUSD = recalc.costUSD ?? 0;
                  }
                }
              }
            }
          }
          state.sessionCallsMap.set(call.callId, effectiveCall);
          if (effectiveCall.status === 'final') {
            const wm = getFinalCallWatermark(effectiveCall);
            if (hasWatermarkProgressed(wm, prevSynced)) {
              if (prevQuarantined && !hasWatermarkProgressed(wm, prevQuarantined) && getSingleCallBodyBytes(effectiveCall) > MAX_FLUSH_BATCH_BYTES) {
                continue;
              }
              const prevPendingWm = prevPending ? getFinalCallWatermark(prevPending) : null;
              const progressedVsPending = hasWatermarkProgressed(wm, prevPendingWm);
              if (progressedVsPending) {
                hasNewOrProgressedPending = true;
                if (getSingleCallBodyBytes(effectiveCall) > MAX_FLUSH_BATCH_BYTES) {
                  state.nextOversizeRetryAt = 0;
                }
              }
              const notRegressedVsPending = !prevPendingWm || (
                compareWatermarkUsage(wm, prevPendingWm) >= 0 &&
                compareSourceRevision(wm.sourceRevision, prevPendingWm.sourceRevision) >= 0 &&
                canAdoptNextDate(wm, prevPendingWm) &&
                getModelRank(wm.model, wm.modelKey) >= getModelRank(prevPendingWm.model, prevPendingWm.modelKey) &&
                (wm.dateRank || 0) >= (prevPendingWm.dateRank || 0) &&
                (!prevPendingWm.modelKey || Boolean(wm.modelKey)) &&
                (!prevPendingWm.isPriced || Boolean(wm.isPriced))
              );
              if (progressedVsPending || notRegressedVsPending) {
                const nextPendingCall = prevPending ? mergePendingCallData(prevPending, effectiveCall) : effectiveCall;
                state.pendingFinalCalls.set(call.callId, nextPendingCall);
              }
            }
          }
        }
      }
      state.callsHydrated = true;
      state.sessionCalls = Array.from(state.sessionCallsMap.values());
      state.sessionCostTotal = state.sessionCalls.reduce((sum, c) => sum + (c.isPriced ? (c.costUSD || 0) : 0), 0);

      // 清除等待首字计时器与排队->调度状态流转（禁止用轮询时间戳伪造分块间隔）
      const newestPollCall = state.sessionCalls.length ? state.sessionCalls[state.sessionCalls.length - 1] : null;
      if (newestPollCall) {
        if (state.livePendingRequest && state.livePendingRequest.cascadeId === id) {
          const isNewCall = newestPollCall.callId !== state.livePendingRequest.baselineCallId;
          const gotFirstToken = (newestPollCall.outputTokens || 0) > 0 || newestPollCall.ttftSec != null || newestPollCall.status === 'final';
          if (state.livePendingRequest.stage === 'queued') {
            const baselineCall = state.livePendingRequest.baselineCallId
              ? state.sessionCallsMap?.get?.(state.livePendingRequest.baselineCallId)
              : null;
            if ((isNewCall && gotFirstToken) || (state.count > (state.livePendingRequest.baselineCount || 0) && gotFirstToken) || (isNewCall && newestPollCall.error)) {
              state.livePendingRequest.stage = 'first_token';
              state.livePendingRequest.firstTokenAtMs = Date.now();
              clearLivePendingRequestWait();
            } else if (isNewCall || (state.count > (state.livePendingRequest.baselineCount || 0))) {
              promoteQueuedPendingRequestToDispatched(id, newestPollCall.timestamp || Date.now());
            } else if (baselineCall && baselineCall.status === 'final' && !state.livePendingRequest.queuedFromComposerDom) {
              promoteQueuedPendingRequestToDispatched(id, Date.now());
            }
          } else if ((isNewCall && gotFirstToken) || (state.count > (state.livePendingRequest.baselineCount || 0) && gotFirstToken) || newestPollCall.error) {
            state.livePendingRequest.stage = 'first_token';
            state.livePendingRequest.firstTokenAtMs = Date.now();
            clearLivePendingRequestWait();
          }
        }
      }

      if (hasNewOrProgressedPending) {
        state.nextFlushRetryAt = 0;
      }
      if (state.pendingFinalCalls.size > 0) {
        void flushPendingFinalCalls(wasHydrated);
      }
      let matchedPollRow = false;
      for (let i = rows.length - 1; i >= 0; i--) {
        const value = summarize(rows[i], { cascadeModelConfigs: state.cascadeModelConfigs || state.scan?.cascadeModelConfigs || [] });
        if (value) {
          matchedPollRow = true;
          state.latest = resolveEffectiveLatestWithCompaction(value, rows[i], offset + i);
          const callInfo = parseGeneratorCall ? parseGeneratorCall(rows[i], id, 'desktop', { cascadeModelConfigs: modelConfigsList }) : null;
          updateLiveSpeedTracker(id, rows[i], state.latest, callInfo);
          if (!state.latest?.compacted || state.latest?.postCompactSource === 'host_context_window_usage') {
            recordObservationFromSummary(state.latest, id, {
              callId: state.latest?.compacted ? null : (callInfo?.callId || null),
              stepCount: state.count,
              ts: Date.now()
            });
          }
          break;
        }
      }
      if (!matchedPollRow && state.latest?.compacted) {
        state.latest = resolveEffectiveLatestWithCompaction(state.latest, null, -1);
      }
      if (rows.some(r => r && !r.chatModel) && !state.scanBusy && Date.now() - (state.lastCompactForceScanAt || 0) > 1500) {
        triggerImmediateCompactScan(id);
      }
      state.requestAt = Date.now(); state.requestError = '';
      if (typeof reconcileCompactionCompletion === 'function') {
        reconcileCompactionCompletion(id, {
          afterTokens: state.latest?.actual ?? state.latest?.postCompactEstimate ?? null,
          budget: state.latest?.budget ?? state.latest?.serviceLimit ?? null,
          latestCompacted: Boolean(state.latest?.compacted),
          hasNewTurnActivity: Boolean(newestPollCall && newestPollCall.status === 'streaming')
        });
      }
      const latestSessionRecForNp = newestPollCall || (Array.isArray(state.sessionCalls) && state.sessionCalls.length ? state.sessionCalls[state.sessionCalls.length - 1] : null);
      if (nextPromptEnabled && !state.compacting && id === state.route
        && latestSessionRecForNp && latestSessionRecForNp.status === 'final'
        && !state.livePendingRequest && typeof maybeRequestNextPromptPrediction === 'function') {
        void maybeRequestNextPromptPrediction({ routeId: id });
      }
      if (state.historyDrawerOpen) scheduleLatestCallRefresh({ allowTimelineRefresh: true });
    } catch (e) { if (generation === state.generation && !state.disposed) state.requestError = e.name === 'AbortError' ? '读取超时' : e.message; }
    finally {
      clearTimeout(timeout);
      state.controllers.delete(controller);
      if (generation === state.generation && !state.disposed) {
        state.requestBusy = false;
        const latestRecNow = resolveLatestSessionCallRecord();
        const isStreamingNow = Boolean((latestRecNow && latestRecNow.status === 'streaming') || state.compacting);
        const nextDelay = document.hidden ? 15000 : (isStreamingNow ? 1000 : 3000);
        state.requestNext = Date.now() + nextDelay;
        render();
      }
    }
  }

  async function scan(generation, id, force = false) {
    const myScanSeq = ++activeScanSeq;
    const scanStartedAtMs = Date.now();
    state.scanBusy = true; render();
    try {
      let result;
      const hasIpcScan = typeof window !== 'undefined' && typeof window.contextMeterAPI?.scan === 'function';
      if (!hasIpcScan && !hasLiveHttpBridge()) {
        throw new Error('完整重启 Antigravity 后启用附件扫描');
      }
      const controller = new AbortController();
      activeScanController = controller;
      state.controllers.add(controller);
      const timeout = setTimeout(() => controller.abort(), 180000);
      try {
        const out = await callBackendWithPriority({
          ipcCall: hasIpcScan ? () => window.contextMeterAPI.scan(id, force) : null,
          liveRoute: '/scan',
          liveBody: { id, force, ...((typeof getRendererCsrfToken === 'function' && getRendererCsrfToken()) ? { csrfToken: getRendererCsrfToken() } : {}) },
          liveFetchOpts: { signal: controller.signal }
        });
        result = out.result;
      } finally {
        clearTimeout(timeout);
        state.controllers.delete(controller);
        if (activeScanController === controller) activeScanController = null;
      }
      if (generation !== state.generation || state.disposed || myScanSeq !== activeScanSeq || !sameRouteId(id, state.route)) return;
      if (result?.data?.abortedStale) return;
      if (result?.data?.conversation && UUID_STRICT_RE.test(String(result.data.conversation)) && !sameRouteId(result.data.conversation, state.route)) return;
      if (!result?.ok) throw new Error(result?.error || '扫描未返回有效结果');
      state.scan = result.data; state.scanError = '';
      const scannedCpIdx = Number.isInteger(result.data.session?.lastCheckpointIndex)
        ? result.data.session.lastCheckpointIndex
        : -1;
      const scannedInProgressCpIdx = Number.isInteger(result.data.session?.inProgressCheckpointIndex)
        ? result.data.session.inProgressCheckpointIndex
        : -1;
      if (scannedInProgressCpIdx >= 0 && !state.compacting && id === state.route) {
        beginCompactingTransition(id);
      }
      if (state.compacting && state.compacting.cascadeId === id) {
        if (!state.compacting.baselineHydrated) {
          const firstScanAlreadyCompacted = scannedCpIdx >= 0
            && Boolean(result.data.latest?.compacted)
            && !state.lastDomCompactingActive
            && scannedInProgressCpIdx < 0;
          if (firstScanAlreadyCompacted) {
            clearCompactingTransition('completed');
          } else {
            state.compacting.baselineCheckpointIndex = scannedCpIdx;
            state.compacting.baselineHydrated = true;
          }
        } else if (scannedCpIdx > state.compacting.baselineCheckpointIndex && scannedInProgressCpIdx < 0) {
          updateCompactionProgress(id, {
            phase: 'checkpoint_ready',
            checkpointIndexAfter: scannedCpIdx,
            afterTokens: result.data.latest?.actual ?? result.data.latest?.postCompactEstimate ?? null,
            budget: result.data.latest?.budget ?? state.latest?.budget ?? null
          }, t('compactProgress.stage.checkpoint_ready'));
          clearCompactingTransition('completed');
        } else if (state.compacting.domEndedAtMs > 0 && scanStartedAtMs >= state.compacting.domEndedAtMs) {
          state.compacting.postDomEndScans = (state.compacting.postDomEndScans || 0) + 1;
        }
      }
      if (result.data.modelCapabilitiesById && typeof result.data.modelCapabilitiesById === 'object') {
        mergeCapabilitiesMapClient(result.data.modelCapabilitiesById);
      }
      if (Array.isArray(result.data.cascadeModelConfigs) && result.data.cascadeModelConfigs.length) {
        state.cascadeModelConfigs = result.data.cascadeModelConfigs;
      }
      if (result.data.scannedAt >= state.requestAt && result.data.latest) {
        state.latest = result.data.latest;
        state.requestAt = result.data.scannedAt;
        const genSteps = Number(result.data.generatorCount);
        const msgSteps = Number(result.data.session?.userMessages || 0) + Number(result.data.session?.assistantMessages || 0);
        const resolvedStepCount = Number.isFinite(genSteps) && genSteps >= 0 ? genSteps : (msgSteps > 0 ? msgSteps : state.count);
        if (!state.latest?.compacted) {
          recordObservationFromSummary(state.latest, id, {
            callId: result.data.latestCallId || null,
            stepCount: resolvedStepCount,
            ts: Number(result.data.scannedAt || Date.now())
          });
        }
      }
      state.latest = resolveEffectiveLatestWithCompaction(
        state.latest || result.data.latest || null,
        null,
        state.count > 0 ? state.count - 1 : -1
      );
      if (state.latest?.compacted && !state.requestAt) {
        state.requestAt = Number(result.data.scannedAt || Date.now());
      }
      if (typeof reconcileCompactionCompletion === 'function') {
        reconcileCompactionCompletion(id, {
          scannedCpIdx,
          inProgressCpIdx: scannedInProgressCpIdx,
          afterTokens: state.latest?.actual ?? state.latest?.postCompactEstimate ?? null,
          budget: state.latest?.budget ?? state.latest?.serviceLimit ?? null,
          latestCompacted: Boolean(state.latest?.compacted || result.data.latest?.compacted),
          skipRender: true
        });
      }
      renderFiles(result.data.session);
      if (state.historyDrawerOpen) scheduleLatestCallRefresh({ allowTimelineRefresh: true });
    } catch (e) {
      if (generation === state.generation && !state.disposed && myScanSeq === activeScanSeq) {
        state.scanError = e.message;
      }
    }
    finally {
      if (generation === state.generation && !state.disposed && myScanSeq === activeScanSeq) {
        state.scanBusy = false;
        if (state.pendingCompactForceScan && id === state.route) {
          state.pendingCompactForceScan = false;
          state.lastCompactForceScanAt = Date.now();
          void scan(state.generation, id, true);
          return;
        }
        if (
          state.compacting
          && state.compacting.cascadeId === id
          && state.compacting.domEndedAtMs > 0
          && (state.compacting.postDomEndScans || 0) >= 1
          && (state.compacting.postDomEndScans || 0) <= 3
          && !compactThrottleTimer
        ) {
          compactThrottleTimer = setTimeout(() => {
            compactThrottleTimer = null;
            if (!state.disposed && state.compacting && state.compacting.cascadeId === id && state.route === id && !state.scanBusy) {
              triggerImmediateCompactScan(id);
            }
          }, 350);
        }
        state.scanNext = Date.now() + (document.hidden ? 60000 : 20000);
        render();
        if (nextPromptEnabled && !state.compacting && id === state.route && typeof maybeRequestNextPromptPrediction === 'function') {
          void maybeRequestNextPromptPrediction({ routeId: id });
        }
      }
    }
  }

  let lastAvailableModelsSync = 0;
  let availableModelsFetchInFlight = false;
  async function fetchAvailableModelsIfNeeded() {
    if (availableModelsFetchInFlight) return;
    if (typeof fetch !== 'function') return;
    const csrf = getRendererCsrfToken();
    if (!csrf) return;
    if (Date.now() - lastAvailableModelsSync < 300000 && state.modelCapabilitiesById && Object.keys(state.modelCapabilitiesById).length > 0) {
      return;
    }
    availableModelsFetchInFlight = true;
    try {
      const response = await fetch('/exa.language_server_pb.LanguageServerService/GetAvailableModels', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', 'Connect-Protocol-Version': '1', 'x-codeium-csrf-token': csrf },
        body: JSON.stringify({ forceRefresh: false })
      });
      if (!response.ok) return;
      const data = await response.json();
      const modelsObj = data?.response?.models || data?.models;
      if (!modelsObj || typeof modelsObj !== 'object') return;
      const entries = Array.isArray(modelsObj)
        ? modelsObj.map(item => [item?.model || item?.modelId || '', item])
        : Object.entries(modelsObj);
      const nextCaps = {};
      for (const [entryKey, d] of entries) {
        if (!d || typeof d !== 'object') continue;
        const rawId = String(d.model || d.modelId || entryKey || '').trim();
        if (!rawId) continue;
        const normKey = rawId.toLowerCase().replace(/^model_/, '');
        const maxTokens = Number.isSafeInteger(Number(d.maxTokens)) && Number(d.maxTokens) > 0 ? Number(d.maxTokens) : null;
        const maxOutputTokens = d.maxOutputTokens != null && Number.isSafeInteger(Number(d.maxOutputTokens)) && Number(d.maxOutputTokens) >= 0
          ? Number(d.maxOutputTokens)
          : null;
        const rec = {
          modelId: rawId,
          displayName: d.displayName || null,
          maxTokens,
          maxOutputTokens,
          thinkingBudget: d.thinkingBudget ?? null,
          minThinkingBudget: d.minThinkingBudget ?? null,
          thinkingLevel: d.thinkingLevel || null,
          supportsModelInfoOverride: typeof d.supportsModelInfoOverride === 'boolean' ? d.supportsModelInfoOverride : null,
          capabilitySource: 'get_available_models'
        };
        if (normKey) nextCaps[normKey] = rec;
        if (entryKey) nextCaps[String(entryKey).trim().toLowerCase().replace(/^model_/, '')] = rec;
      }
      if (Object.keys(nextCaps).length > 0) {
        mergeCapabilitiesMapClient(nextCaps);
        lastAvailableModelsSync = Date.now();
        if (!isContextSettingsView && activeContextTab === 'models') {
          renderModelSettingsTab();
          renderPresetSelectionUI();
        }
      }
    } catch { }
    finally {
      availableModelsFetchInFlight = false;
    }
  }

  // =========================================================================
  // 模块 5: 模型额度看板（ELV-34）—— 顶栏圆环入口、共享池归组、多状态机与定时刷新
  // =========================================================================
  const QUOTA_REFRESH_FG_MS = 60000;
  const QUOTA_REFRESH_BG_MS = 180000;
  const QUOTA_STALE_MS = 180000;
  const QUOTA_ANIM_DURATION_MS = 220;
  const QUOTA_CAL_STORAGE_PREFIX = 'ag_quota_token_cal_v2_';
  const quotaState = {
    accountScopeKey: null,
    collectorVersion: null,
    snapshot: null,
    rawInput: null,
    browsePoolKey: null,
    busy: false,
    lastFetchedAtMs: null,
    lastSuccessAtMs: null,
    nextRefreshAtMs: null,
    error: null,
    errorKind: null,
    dataFreshness: null,
    consecutiveErrors: 0,
    lastResetRequeryKey: null,
    autoPaused: false
  };
  quotaStateInitialized = true;
  let quotaAutoTimer = null;
  let quotaResetTimer = null;
  let quotaPostTurnTimer = null;
  let quotaFeedbackTimer = null;
  let quotaInFlightPromise = null;
  let quotaInFlightManual = false;
  let quotaInFlightEntry = null;
  let quotaAbortController = null;
  let quotaRequestGeneration = 0;
  let quotaCommittedGeneration = 0;
  let quotaAccountEpoch = 0;
  const QUOTA_MIN_FETCH_SCAN_MS = 240;
  const QUOTA_COMMIT_PREP_MS = 90;
  const QUOTA_CELL_POWER_ON_MS = 180;
  const QUOTA_REFRESH_DONE_HOLD_MS = 900;
  const QUOTA_BAR_CHARGE_DURATION_MS = 720;
  let quotaRefreshPhase = 'idle';
  let quotaRefreshBtnState = 'idle';
  let quotaRefreshSpinAnim = null;
  let quotaBarChargeTimer = null;
  let quotaRefreshDoneTimer = null;
  let quotaBarChargePlaying = false;
  let quotaLastChargeDetail = null;
  let quotaLastRefreshTimeline = [];
  let quotaBoardCtrl = null;
  let quotaBoardColorMode = 'uniform';
  let quotaActiveBoardRunId = 0;
  try {
    const savedColorMode = typeof localStorage !== 'undefined' ? localStorage.getItem('ag_quota_color_mode') : null;
    if (savedColorMode === 'progressive' || savedColorMode === 'uniform') {
      quotaBoardColorMode = savedColorMode;
    }
  } catch { }

  function syncQuotaColorModeButtonsUi() {
    const btnUni = el('quota-color-mode-uniform');
    const btnProg = el('quota-color-mode-progressive');
    if (btnUni?.classList) {
      const isUni = quotaBoardColorMode === 'uniform';
      if (isUni) btnUni.classList.add('active');
      else btnUni.classList.remove('active');
      btnUni.classList.remove('is-active');
      btnUni.setAttribute?.('aria-pressed', isUni ? 'true' : 'false');
    }
    if (btnProg?.classList) {
      const isProg = quotaBoardColorMode === 'progressive';
      if (isProg) btnProg.classList.add('active');
      else btnProg.classList.remove('active');
      btnProg.classList.remove('is-active');
      btnProg.setAttribute?.('aria-pressed', isProg ? 'true' : 'false');
    }
  }

  function syncQuotaBoardSurfaceTheme() {
    try {
      quotaBoardCtrl?.refreshTheme?.();
    } catch { }
  }

  function ensureQuotaBoardController() {
    if (quotaBoardCtrl) return quotaBoardCtrl;
    const boardEl = el('quota-main-board');
    if (!boardEl || typeof createQuotaBoardController !== 'function') return null;
    quotaBoardCtrl = createQuotaBoardController(boardEl, {
      isReducedMotion: () => isQuotaReducedMotion(),
      onRefreshIconSpin: (spinning) => {
        const iconEl = el('quota-refresh-icon-svg');
        if (iconEl?.classList) {
          if (spinning && !isQuotaReducedMotion()) iconEl.classList.add('is-spinning');
          else iconEl.classList.remove('is-spinning');
        }
      },
      onHeaderSoftened: (softened) => {
        const metaEl = el('quota-updated-meta');
        if (metaEl?.classList) {
          if (softened) metaEl.classList.add('is-softened');
          else metaEl.classList.remove('is-softened');
        }
      }
    });
    quotaBoardCtrl.setColorMode(quotaBoardColorMode);
    syncQuotaColorModeButtonsUi();
    return quotaBoardCtrl;
  }

  function applyQuotaBoardColorMode(mode) {
    quotaBoardColorMode = mode === 'progressive' ? 'progressive' : 'uniform';
    try {
      if (typeof localStorage !== 'undefined') localStorage.setItem('ag_quota_color_mode', quotaBoardColorMode);
    } catch { }
    const ctrl = ensureQuotaBoardController();
    ctrl?.setColorMode?.(quotaBoardColorMode);
    syncQuotaColorModeButtonsUi();
    return quotaBoardColorMode;
  }

  const quotaAnimRafs = new Set();
  const quotaActiveChargeRefs = new Set();
  const quotaActiveCompactFills = new Set();
  const quotaPrevCellsByBarKey = new Map();
  const quotaNumAnimState = new WeakMap();
  const quotaNodeRefsMap = new WeakMap();
  let quotaCalibrationScope = null;
  let quotaCalibrationMap = {};
  let quotaLastEstComputeSig = '';
  let quotaCachedEstByKey = null;
  let quotaLastSnapshotSig = null;
  let quotaPendingSmoothAnim = false;
  let quotaBadgeLastHasFraction = false;

  function recordQuotaTimelineEvent(stage, extra = null) {
    const entry = { stage, ts: Date.now(), ...(extra && typeof extra === 'object' ? extra : {}) };
    quotaLastRefreshTimeline.push(entry);
    if (quotaLastRefreshTimeline.length > 40) quotaLastRefreshTimeline.shift();
    return entry;
  }

  function isQuotaReducedMotion() {
    try {
      return Boolean(typeof window !== 'undefined' && window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches);
    } catch {
      return false;
    }
  }

  function setQuotaBadgeSyncingAttr(syncing) {
    const bQuota = el('badge-quota');
    if (!bQuota) return;
    if (syncing) setQuotaAttrIfChanged(bQuota, 'data-quota-syncing', 'true');
    else removeQuotaAttrIfPresent(bQuota, 'data-quota-syncing');
  }

  function setQuotaRefreshUiPhase(phase, btnState = null) {
    quotaRefreshPhase = phase || 'idle';
    const panelQuotaEl = el('panel-quota');
    if (panelQuotaEl) {
      if (quotaRefreshPhase === 'idle') removeQuotaAttrIfPresent(panelQuotaEl, 'data-refresh-phase');
      else setQuotaAttrIfChanged(panelQuotaEl, 'data-refresh-phase', quotaRefreshPhase);
    }
    if (btnState !== null) {
      quotaRefreshBtnState = btnState;
      const btnRefresh = el('btn-quota-refresh');
      const txtRefresh = el('quota-refresh-text');
      if (btnRefresh) {
        setQuotaAttrIfChanged(btnRefresh, 'data-refresh-state', btnState);
        setQuotaAttrIfChanged(btnRefresh, 'data-busy', btnState === 'loading' ? 'true' : 'false');
        setQuotaAttrIfChanged(btnRefresh, 'aria-busy', btnState === 'loading' ? 'true' : 'false');
        const nextDisabled = btnState === 'loading';
        if (Boolean(btnRefresh.disabled) !== nextDisabled) btnRefresh.disabled = nextDisabled;
      }
      if (txtRefresh) {
        if (btnState === 'done') setQuotaTextIfChanged(txtRefresh, t('quota.refresh.done'));
        else if (btnState === 'fallback') setQuotaTextIfChanged(txtRefresh, t('quota.refresh.cached'));
        else if (btnState === 'error') setQuotaTextIfChanged(txtRefresh, t('quota.refresh.failed'));
        else setQuotaTextIfChanged(txtRefresh, t('quota.refresh.btn'));
      }
    }
  }

  function capturePreRefreshQuotaCellsSnapshot() {
    quotaPrevCellsByBarKey.clear();
    const curView = lastComputedQuotaView;
    if (!curView || !Array.isArray(curView.pools)) return;
    const EPS = 1e-9;
    for (const p of curView.pools) {
      for (const b of (p.buckets || [])) {
        const key = `${p.poolKey}::${b.bucketId || b.windowKey || ''}`;
        if (b.remainingFraction == null || !Number.isFinite(Number(b.remainingFraction))) {
          quotaPrevCellsByBarKey.set(key, { activeCells: 0, fraction: null });
          continue;
        }
        const frac = Math.max(0, Math.min(1, Number(b.remainingFraction)));
        const fullBlocks = Math.min(20, Math.floor(frac * 20 + EPS));
        const partialRaw = fullBlocks >= 20 ? 0 : Math.max(0, frac * 20 - fullBlocks);
        const partialFrac = partialRaw < EPS ? 0 : partialRaw;
        const activeCells = frac <= 0 ? 0 : Math.min(20, fullBlocks + (partialFrac > 0 ? 1 : 0));
        quotaPrevCellsByBarKey.set(key, { activeCells, fraction: frac });
      }
    }
  }

  function clearQuotaBarChargeAnimations(opts = {}) {
    if (quotaBarChargeTimer) {
      clearTimeout(quotaBarChargeTimer);
      quotaBarChargeTimer = null;
    }
    if (quotaRefreshDoneTimer && opts.keepDoneTimer !== true) {
      clearTimeout(quotaRefreshDoneTimer);
      quotaRefreshDoneTimer = null;
    }
    quotaBarChargePlaying = false;
    for (const ref of quotaActiveChargeRefs) {
      if (ref?.track) {
        removeQuotaAttrIfPresent(ref.track, 'data-charging');
        ref.track.style?.removeProperty?.('--charge-step');
      }
      if (ref?.chargeStage) setQuotaHiddenIfChanged(ref.chargeStage, true);
      if (Array.isArray(ref?.segFills)) {
        for (const sf of ref.segFills) {
          if (!sf) continue;
          removeQuotaAttrIfPresent(sf, 'data-cell-pulse');
          removeQuotaAttrIfPresent(sf, 'data-cell-diff');
          sf.style?.removeProperty?.('--quota-cell-delay');
          sf.style?.removeProperty?.('--cell-target-opacity');
        }
      }
    }
    quotaActiveChargeRefs.clear();
    for (const cf of quotaActiveCompactFills) {
      if (cf) removeQuotaAttrIfPresent(cf, 'data-compact-refill');
    }
    quotaActiveCompactFills.clear();
    if (opts.keepBoardAnim !== true) {
      quotaActiveBoardRunId = 0;
      quotaBoardCtrl?.abortManualRefreshCycle?.();
    }
    if (opts.resetPhase !== false) {
      setQuotaRefreshUiPhase('idle', opts.resetBtn !== false ? 'idle' : null);
    }
  }

  function enterQuotaFetchingPhase() {
    if (quotaRefreshDoneTimer) {
      clearTimeout(quotaRefreshDoneTimer);
      quotaRefreshDoneTimer = null;
    }
    if (quotaBarChargeTimer) {
      clearTimeout(quotaBarChargeTimer);
      quotaBarChargeTimer = null;
    }
    quotaBarChargePlaying = false;
    hideQuotaRefreshFeedback();
    capturePreRefreshQuotaCellsSnapshot();
    const panelQuotaEl = el('panel-quota');
    const panelVisible = Boolean(panelQuotaEl && !panelQuotaEl.hidden);
    if (panelVisible && !isQuotaReducedMotion()) {
      setQuotaRefreshUiPhase('fetching', 'loading');
    } else {
      setQuotaRefreshUiPhase('idle', 'loading');
    }
    recordQuotaTimelineEvent('fetching_start', { panelVisible });
  }

  function scheduleQuotaDoneToIdle(showUpToDate = false) {
    if (quotaRefreshDoneTimer) {
      clearTimeout(quotaRefreshDoneTimer);
      quotaRefreshDoneTimer = null;
    }
    setQuotaRefreshUiPhase('idle', 'done');
    if (showUpToDate) {
      showQuotaUpToDateFeedback();
    }
    recordQuotaTimelineEvent('done_shown');
    quotaRefreshDoneTimer = setTimeout(() => {
      quotaRefreshDoneTimer = null;
      if (state.disposed) return;
      if (!quotaState.busy && quotaRefreshPhase === 'idle') {
        setQuotaRefreshUiPhase('idle', 'idle');
        recordQuotaTimelineEvent('idle_restored');
      }
    }, QUOTA_REFRESH_DONE_HOLD_MS);
  }

  function finishQuotaRefreshWithError() {
    clearQuotaBarChargeAnimations({ resetPhase: true, resetBtn: false });
    hideQuotaRefreshFeedback();
    setQuotaRefreshUiPhase('idle', 'error');
    recordQuotaTimelineEvent('error_restored');
    if (quotaRefreshDoneTimer) clearTimeout(quotaRefreshDoneTimer);
    quotaRefreshDoneTimer = setTimeout(() => {
      quotaRefreshDoneTimer = null;
      if (!state.disposed && !quotaState.busy && quotaRefreshPhase === 'idle') {
        setQuotaRefreshUiPhase('idle', 'idle');
      }
    }, QUOTA_REFRESH_DONE_HOLD_MS);
  }

  function finishQuotaRefreshWithFallback(hasUsableCache = true) {
    clearQuotaBarChargeAnimations({ resetPhase: true, resetBtn: false });
    hideQuotaRefreshFeedback();
    if (hasUsableCache) {
      setQuotaRefreshUiPhase('idle', 'fallback');
      showQuotaFallbackFeedback();
      recordQuotaTimelineEvent('fallback_cached_shown');
    } else {
      setQuotaRefreshUiPhase('idle', 'error');
      recordQuotaTimelineEvent('fallback_no_data_error');
    }
    if (quotaRefreshDoneTimer) clearTimeout(quotaRefreshDoneTimer);
    quotaRefreshDoneTimer = setTimeout(() => {
      quotaRefreshDoneTimer = null;
      if (!state.disposed && !quotaState.busy && quotaRefreshPhase === 'idle') {
        setQuotaRefreshUiPhase('idle', 'idle');
      }
    }, QUOTA_REFRESH_DONE_HOLD_MS);
  }

  function triggerQuotaBarsChargeAnimation(targets, opts = {}) {
    const showUpToDateOnFinish = Boolean(opts.showUpToDate);
    // 动画进行中不堆积或重启多轮播放
    if (quotaBarChargePlaying) return false;
    const panelQuotaEl = el('panel-quota');
    if (!panelQuotaEl || panelQuotaEl.hidden) {
      scheduleQuotaDoneToIdle(showUpToDateOnFinish);
      return false;
    }
    if (isQuotaReducedMotion()) {
      clearQuotaBarChargeAnimations({ resetPhase: true, resetBtn: false });
      scheduleQuotaDoneToIdle(true);
      return false;
    }

    const validRefs = [];
    for (const ref of (Array.isArray(targets) ? targets : [])) {
      if (ref && ref.chargeEligible && ref.track && Number(ref.activeCells) > 0) {
        validRefs.push(ref);
      }
    }
    const compactFills = Array.isArray(opts.compactFills) ? opts.compactFills.filter(Boolean) : [];
    if (!validRefs.length) {
      clearQuotaBarChargeAnimations({ resetPhase: true, resetBtn: false });
      scheduleQuotaDoneToIdle(showUpToDateOnFinish);
      return false;
    }

    const details = [];
    let maxBarDoneMs = QUOTA_COMMIT_PREP_MS + QUOTA_CELL_POWER_ON_MS;
    for (const ref of validRefs) {
      removeQuotaAttrIfPresent(ref.track, 'data-charging');
      // 20 格模式下彻底禁用连续绿带与反光层
      if (ref.chargeStage) setQuotaHiddenIfChanged(ref.chargeStage, true);
      const activeCells = Number.isInteger(ref.activeCells) ? ref.activeCells : 0;
      const segFills = Array.isArray(ref.segFills) ? ref.segFills : [];
      const prevInfo = ref.barKey ? quotaPrevCellsByBarKey.get(ref.barKey) : null;
      const prevActiveCells = prevInfo && Number.isInteger(prevInfo.activeCells) ? prevInfo.activeCells : null;
      if (activeCells > 0 && segFills.length === 20) {
        const stepMs = Math.max(20, Math.min(44, Math.round(380 / activeCells)));
        ref.track.style?.setProperty?.('--charge-step', `${stepMs}ms`);
        let pulseCount = 0;
        let staticEmptyCount = 0;
        let gainCount = 0;
        let dropCount = 0;
        for (let idx = 0; idx < 20; idx++) {
          const sf = segFills[idx];
          if (!sf) continue;
          if (idx < activeCells) {
            const targetOp = sf.style?.getPropertyValue?.('--seg-opacity') || sf.style?.opacity || '1';
            setQuotaAttrIfChanged(sf, 'data-cell-pulse', 'true');
            sf.style?.setProperty?.('--cell-idx', String(idx));
            sf.style?.setProperty?.('--cell-target-opacity', String(targetOp));
            sf.style?.setProperty?.('--quota-cell-delay', `${QUOTA_COMMIT_PREP_MS + idx * stepMs}ms`);
            if (prevActiveCells !== null && idx >= prevActiveCells) {
              setQuotaAttrIfChanged(sf, 'data-cell-diff', 'gain');
              gainCount++;
            } else {
              removeQuotaAttrIfPresent(sf, 'data-cell-diff');
            }
            pulseCount++;
          } else if (prevActiveCells !== null && idx < prevActiveCells) {
            removeQuotaAttrIfPresent(sf, 'data-cell-pulse');
            setQuotaAttrIfChanged(sf, 'data-cell-diff', 'drop');
            sf.style?.removeProperty?.('--quota-cell-delay');
            sf.style?.removeProperty?.('--cell-target-opacity');
            dropCount++;
          } else {
            removeQuotaAttrIfPresent(sf, 'data-cell-pulse');
            removeQuotaAttrIfPresent(sf, 'data-cell-diff');
            sf.style?.removeProperty?.('--quota-cell-delay');
            sf.style?.removeProperty?.('--cell-target-opacity');
            staticEmptyCount++;
          }
        }
        const firstCellMs = QUOTA_COMMIT_PREP_MS;
        const lastCellStartMs = QUOTA_COMMIT_PREP_MS + (activeCells - 1) * stepMs;
        const barDoneMs = lastCellStartMs + QUOTA_CELL_POWER_ON_MS;
        if (barDoneMs > maxBarDoneMs) maxBarDoneMs = barDoneMs;
        details.push({
          barKey: ref.barKey || null,
          activeCells,
          prevActiveCells,
          stepMs,
          firstCellMs,
          lastCellStartMs,
          barDoneMs,
          pulseCount,
          gainCount,
          dropCount,
          staticEmptyCount
        });
      }
      quotaActiveChargeRefs.add(ref);
    }

    for (const cf of compactFills) {
      setQuotaAttrIfChanged(cf, 'data-compact-refill', 'true');
      quotaActiveCompactFills.add(cf);
    }

    quotaLastChargeDetail = {
      phase: 'committing',
      prepMs: QUOTA_COMMIT_PREP_MS,
      cellDurationMs: QUOTA_CELL_POWER_ON_MS,
      totalCommitMs: maxBarDoneMs,
      doneHoldMs: QUOTA_REFRESH_DONE_HOLD_MS,
      targetCount: validRefs.length,
      compactRefillCount: compactFills.length,
      bars: details
    };

    setQuotaRefreshUiPhase('committing', 'loading');
    // 单次强制提交布局，确保 0-90ms 清空预备与逐格上电同步起播
    if (typeof panelQuotaEl.offsetHeight === 'number') void panelQuotaEl.offsetHeight;
    for (const ref of validRefs) {
      setQuotaAttrIfChanged(ref.track, 'data-charging', 'true');
    }
    recordQuotaTimelineEvent('committing_start', { totalCommitMs: maxBarDoneMs, bars: details.length });

    quotaBarChargePlaying = true;
    quotaBarChargeTimer = setTimeout(() => {
      quotaBarChargeTimer = null;
      if (state.disposed) return;
      clearQuotaBarChargeAnimations({ resetPhase: false, resetBtn: false, keepDoneTimer: true });
      recordQuotaTimelineEvent('committing_complete');
      scheduleQuotaDoneToIdle(showUpToDateOnFinish);
    }, maxBarDoneMs);
    return true;
  }

  function triggerQuotaRefreshIconSpin() {
    // 加载态旋转已由 data-refresh-state="loading" 纯 CSS 驱动，此处保留兼容空操作以防外部测试调用报错
    return;
  }

  function clearQuotaAnimations() {
    for (const rafId of quotaAnimRafs) {
      if (typeof cancelAnimationFrame === 'function') cancelAnimationFrame(rafId);
    }
    quotaAnimRafs.clear();
    clearQuotaBarChargeAnimations();
    setQuotaBadgeSyncingAttr(false);
    if (quotaRefreshSpinAnim) {
      try { quotaRefreshSpinAnim.cancel(); } catch { }
      quotaRefreshSpinAnim = null;
    }
  }

  function clearQuotaTimers() {
    if (quotaAutoTimer) { clearTimeout(quotaAutoTimer); quotaAutoTimer = null; }
    if (quotaResetTimer) { clearTimeout(quotaResetTimer); quotaResetTimer = null; }
    if (quotaPostTurnTimer) { clearTimeout(quotaPostTurnTimer); quotaPostTurnTimer = null; }
    if (quotaFeedbackTimer) { clearTimeout(quotaFeedbackTimer); quotaFeedbackTimer = null; }
    if (quotaScanFloorTimer) { clearTimeout(quotaScanFloorTimer); quotaScanFloorTimer = null; }
    if (quotaRefreshDoneTimer) { clearTimeout(quotaRefreshDoneTimer); quotaRefreshDoneTimer = null; }
    // PR #83：看板滚动恢复属于额度看板生命周期内任务，销毁与切页时必须一并清理
    try { clearQuotaScrollRestoreTimers(); } catch { }
    try { quotaBoardCtrl?.destroy?.(); } catch { }
    quotaBoardCtrl = null;
    clearQuotaAnimations();
    try { quotaAbortController?.abort?.(); } catch { }
    quotaAbortController = null;
  }

  function loadQuotaCalibrationForScope(scopeKey) {
    const clean = scopeKey ? String(scopeKey).trim() : 'anonymous';
    if (quotaCalibrationScope === clean) return quotaCalibrationMap;
    quotaCalibrationScope = clean;
    quotaCalibrationMap = {};
    try {
      if (typeof localStorage !== 'undefined') {
        const raw = localStorage.getItem(`${QUOTA_CAL_STORAGE_PREFIX}${clean}`);
        if (raw) {
          const parsed = JSON.parse(raw);
          if (parsed && typeof parsed === 'object') quotaCalibrationMap = parsed;
        }
      }
    } catch { }
    return quotaCalibrationMap;
  }

  function saveQuotaCalibrationForScope(scopeKey, nextMap) {
    const clean = scopeKey ? String(scopeKey).trim() : 'anonymous';
    quotaCalibrationScope = clean;
    quotaCalibrationMap = nextMap && typeof nextMap === 'object' ? nextMap : {};
    try {
      if (typeof localStorage !== 'undefined') {
        localStorage.setItem(`${QUOTA_CAL_STORAGE_PREFIX}${clean}`, JSON.stringify(quotaCalibrationMap));
      }
    } catch { }
  }

  // 仅在值实际改变时写入 DOM，避免重复替换 Text 节点或重设属性引发重排与闪烁
  function setQuotaTextIfChanged(node, text) {
    if (!node) return;
    const next = text == null ? '' : String(text);
    if (node.textContent !== next) node.textContent = next;
  }

  function setQuotaHiddenIfChanged(node, hidden) {
    if (!node) return;
    const next = Boolean(hidden);
    if (Boolean(node.hidden) !== next) node.hidden = next;
  }

  function setQuotaAttrIfChanged(node, name, val) {
    if (!node) return;
    const next = String(val);
    if (getChildAttr(node, name) !== next) node.setAttribute(name, next);
  }

  function removeQuotaAttrIfPresent(node, name) {
    if (!node) return;
    if (getChildAttr(node, name) !== null) node.removeAttribute?.(name);
  }

  function setQuotaClassIfChanged(node, cls) {
    if (!node) return;
    const next = String(cls || '');
    if (node.className !== next) node.className = next;
  }

  function hideQuotaRefreshFeedback() {
    if (quotaFeedbackTimer) { clearTimeout(quotaFeedbackTimer); quotaFeedbackTimer = null; }
    const fb = el('quota-refresh-feedback');
    if (fb) {
      removeQuotaAttrIfPresent(fb, 'data-tone');
      setQuotaHiddenIfChanged(fb, true);
    }
  }

  function showQuotaUpToDateFeedback() {
    const fb = el('quota-refresh-feedback');
    if (!fb) return;
    if (quotaFeedbackTimer) { clearTimeout(quotaFeedbackTimer); quotaFeedbackTimer = null; }
    removeQuotaAttrIfPresent(fb, 'data-tone');
    setQuotaTextIfChanged(fb, t('quota.refresh.upToDate'));
    setQuotaHiddenIfChanged(fb, false);
    quotaFeedbackTimer = setTimeout(() => {
      quotaFeedbackTimer = null;
      if (!state.disposed && el('quota-refresh-feedback')) {
        setQuotaHiddenIfChanged(el('quota-refresh-feedback'), true);
      }
    }, 1800);
  }

  function showQuotaFallbackFeedback() {
    const fb = el('quota-refresh-feedback');
    if (!fb) return;
    if (quotaFeedbackTimer) { clearTimeout(quotaFeedbackTimer); quotaFeedbackTimer = null; }
    setQuotaAttrIfChanged(fb, 'data-tone', 'warn');
    setQuotaTextIfChanged(fb, t('quota.refresh.fallbackTip'));
    setQuotaHiddenIfChanged(fb, false);
    quotaFeedbackTimer = setTimeout(() => {
      quotaFeedbackTimer = null;
      if (!state.disposed && el('quota-refresh-feedback')) {
        removeQuotaAttrIfPresent(el('quota-refresh-feedback'), 'data-tone');
        setQuotaHiddenIfChanged(el('quota-refresh-feedback'), true);
      }
    }, 2600);
  }

  function computeQuotaVisualSignature(view) {
    if (!view || !Array.isArray(view.pools)) return 'empty';
    const parts = [
      quotaBadgeWindowMode || 'auto',
      view.currentModel?.productKey || '',
      view.activeStatus || '',
      view.badge?.fraction == null ? 'null' : view.badge.fraction.toFixed(4)
    ];
    for (const p of view.pools) {
      const bStr = (p.buckets || []).map(b => `${b.bucketId}:${b.remainingFraction == null ? 'null' : b.remainingFraction.toFixed(4)}:${b.resetAtMs || ''}`).join(',');
      parts.push(`${p.poolKey}=${p.status}=${bStr}`);
    }
    return parts.join('|');
  }

  function formatQuotaNumPctValue(pctVal) {
    if (!Number.isFinite(pctVal)) return '';
    const clamped = Math.max(0, Math.min(100, pctVal));
    if (clamped === 0) return '0%';
    if (clamped > 0 && clamped < 0.1) return '<0.1%';
    if (clamped < 1) return `${clamped.toFixed(1)}%`;
    return `${Math.round(clamped)}%`;
  }

  function animateQuotaPercentNode(node, targetFrac, animate, fallbackText = '') {
    if (!node) return;
    const prevState = quotaNumAnimState.get(node) || { rafId: 0, currentPct: null, targetPct: null };
    if (targetFrac == null || !Number.isFinite(Number(targetFrac))) {
      if (prevState.rafId && typeof cancelAnimationFrame === 'function') {
        cancelAnimationFrame(prevState.rafId);
        quotaAnimRafs.delete(prevState.rafId);
      }
      quotaNumAnimState.set(node, { rafId: 0, currentPct: null, targetPct: null });
      setQuotaTextIfChanged(node, fallbackText);
      return;
    }

    const targetPct = Math.max(0, Math.min(100, Number(targetFrac) * 100));
    const canAnimate = Boolean(
      animate &&
      !isQuotaReducedMotion() &&
      typeof requestAnimationFrame === 'function' &&
      prevState.currentPct !== null &&
      Math.abs(targetPct - prevState.currentPct) >= 0.05
    );

    if (!canAnimate) {
      if (prevState.rafId && prevState.targetPct !== null && Math.abs(prevState.targetPct - targetPct) < 0.05) {
        return;
      }
      if (prevState.rafId && typeof cancelAnimationFrame === 'function') {
        cancelAnimationFrame(prevState.rafId);
        quotaAnimRafs.delete(prevState.rafId);
      }
      quotaNumAnimState.set(node, { rafId: 0, currentPct: targetPct, targetPct });
      setQuotaTextIfChanged(node, formatQuotaNumPctValue(targetPct));
      return;
    }

    if (prevState.rafId && prevState.targetPct !== null && Math.abs(prevState.targetPct - targetPct) < 0.05) {
      return;
    }

    if (prevState.rafId && typeof cancelAnimationFrame === 'function') {
      cancelAnimationFrame(prevState.rafId);
      quotaAnimRafs.delete(prevState.rafId);
    }

    const startPct = prevState.currentPct;
    const startTs = (typeof performance !== 'undefined' && performance.now) ? performance.now() : Date.now();
    const animObj = { rafId: 0, currentPct: startPct, targetPct };
    quotaNumAnimState.set(node, animObj);

    const step = (nowTs) => {
      if (state.disposed) {
        quotaAnimRafs.delete(animObj.rafId);
        animObj.rafId = 0;
        return;
      }
      const curNow = (typeof performance !== 'undefined' && performance.now) ? performance.now() : Date.now();
      const rawT = Math.min(1, Math.max(0, (curNow - startTs) / QUOTA_ANIM_DURATION_MS));
      const eased = 1 - Math.pow(1 - rawT, 3);
      const val = startPct + (targetPct - startPct) * eased;
      animObj.currentPct = val;
      setQuotaTextIfChanged(node, formatQuotaNumPctValue(val));
      if (rawT < 1) {
        animObj.rafId = requestAnimationFrame(step);
        quotaAnimRafs.add(animObj.rafId);
      } else {
        quotaAnimRafs.delete(animObj.rafId);
        animObj.rafId = 0;
        animObj.currentPct = targetPct;
        setQuotaTextIfChanged(node, formatQuotaNumPctValue(targetPct));
      }
    };
    animObj.rafId = requestAnimationFrame(step);
    quotaAnimRafs.add(animObj.rafId);
  }

  function resetQuotaState(opts = {}) {
    clearQuotaTimers();
    if (opts.clearAccountScope !== false) {
      quotaAccountEpoch += 1;
      sessionSnapshotCache.clear();
      quotaState.accountScopeKey = null;
      quotaCalibrationScope = null;
      quotaCalibrationMap = {};
    }
    quotaLastEstComputeSig = '';
    quotaCachedEstByKey = null;
    quotaLastSnapshotSig = null;
    quotaPendingSmoothAnim = false;
    quotaBadgeLastHasFraction = false;
    quotaExpandedPoolKeys.clear();
    quotaPrevCellsByBarKey.clear();
    lastComputedQuotaView = null;
    quotaState.snapshot = null;
    quotaState.rawInput = null;
    quotaState.browsePoolKey = null;
    quotaState.busy = false;
    quotaState.lastFetchedAtMs = null;
    quotaState.lastSuccessAtMs = null;
    quotaState.nextRefreshAtMs = null;
    quotaState.error = null;
    quotaState.errorKind = null;
    quotaState.dataFreshness = null;
    quotaState.consecutiveErrors = 0;
    quotaState.lastResetRequeryKey = null;
    quotaInFlightPromise = null;
    quotaInFlightEntry = null;
    quotaInFlightManual = false;
    renderQuotaBoard();
  }

  function refreshQuotaTokenEstimates() {
    quotaLastEstComputeSig = '';
    quotaCachedEstByKey = null;
    if (!state.disposed && (quotaState.snapshot || quotaState.rawInput)) {
      renderQuotaBoard(Date.now(), { animate: false });
    }
  }

  function handleQuotaAccountSwitch(nextScopeKey, opts = {}) {
    const cleanNext = nextScopeKey ? String(nextScopeKey).trim() : null;
    const prev = quotaState.accountScopeKey;
    const changed = Boolean(cleanNext && prev && cleanNext !== prev);
    if (changed || opts.forceRefresh) {
      resetQuotaState({ clearAccountScope: true });
      if (cleanNext) quotaState.accountScopeKey = cleanNext;
      if (!state.disposed) void syncQuotaFromHost(true);
      return true;
    }
    if (cleanNext && !prev) {
      quotaState.accountScopeKey = cleanNext;
    }
    return false;
  }

  function getQuotaStatusLabelText(statusKey) {
    const keyMap = {
      available: 'quota.state.available',
      low: 'quota.state.low',
      exhausted: 'quota.state.exhausted',
      no_permission: 'quota.state.no_permission',
      stale: 'quota.state.stale',
      error: 'quota.state.error',
      unknown: 'quota.state.unknown'
    };
    return t(keyMap[statusKey] || 'quota.state.unknown');
  }

  function getQuotaShortBadgeText(statusKey) {
    const keyMap = {
      exhausted: 'quota.short.exhausted',
      no_permission: 'quota.short.no_permission',
      error: 'quota.short.error',
      stale: 'quota.short.stale',
      unknown: 'quota.short.unknown'
    };
    return keyMap[statusKey] ? t(keyMap[statusKey]) : '';
  }

  function getQuotaPillClass(statusKey) {
    if (statusKey === 'available') return 'pill-good';
    if (statusKey === 'low' || statusKey === 'stale') return 'pill-warn';
    if (statusKey === 'exhausted' || statusKey === 'error') return 'pill-danger';
    if (statusKey === 'no_permission') return 'pill-info';
    return 'pill-muted';
  }

  function formatQuotaDateTime(ms) {
    if (!Number.isFinite(Number(ms)) || Number(ms) <= 0) return t('quota.time.unknown');
    const d = new Date(Number(ms));
    const mo = String(d.getMonth() + 1).padStart(2, '0');
    const da = String(d.getDate()).padStart(2, '0');
    const hh = String(d.getHours()).padStart(2, '0');
    const mi = String(d.getMinutes()).padStart(2, '0');
    const ss = String(d.getSeconds()).padStart(2, '0');
    return `${mo}-${da} ${hh}:${mi}:${ss}`;
  }

  function formatCountdownMsCompact(ms) {
    if (!Number.isFinite(Number(ms))) return t('quota.time.unknown');
    if (ms <= 0) return '0s';
    const isEn = currentPanelLanguage === 'en';
    const hrUnit = currentPanelLanguage === 'zh-TW' ? '小時' : '小时';
    if (ms >= 60000) {
      // 与 Antigravity 官方客户端倒计时保持一致：>= 60s 时按分钟向下取整
      const totalMins = Math.floor(ms / 60000);
      const d = Math.floor(totalMins / 1440);
      const h = Math.floor((totalMins % 1440) / 60);
      const m = totalMins % 60;
      if (isEn) {
        if (d > 0) return `${d}d ${h}h`;
        if (h > 0) return `${h}h ${m}m`;
        return `${m}m`;
      }
      if (d > 0) return `${d}天${h}${hrUnit}`;
      if (h > 0) return `${h}${hrUnit}${m}分`;
      return `${m}分`;
    }
    const s = Math.max(1, Math.ceil(ms / 1000));
    return isEn ? `${s}s` : `${s}秒`;
  }

  function formatQuotaDialExactDuration(remainingMs) {
    const safeMs = Math.max(0, Number(remainingMs) || 0);
    const isEn = currentPanelLanguage === 'en';
    const hrUnit = currentPanelLanguage === 'zh-TW' ? '小時' : '小时';
    if (safeMs <= 0) return isEn ? '0m' : '0分';
    if (safeMs < 60000) {
      const sec = Math.max(1, Math.ceil(safeMs / 1000));
      return isEn ? `${sec}s` : `${sec}秒`;
    }
    const totalMins = Math.floor(safeMs / 60000);
    const totalHours = Math.floor(totalMins / 60);
    const remMins = totalMins % 60;
    const pad2 = v => String(Math.max(0, Math.floor(v))).padStart(2, '0');
    if (totalHours >= 1) {
      return isEn ? `${totalHours}h ${pad2(remMins)}m` : `${totalHours}${hrUnit}${pad2(remMins)}分`;
    }
    return isEn ? `${remMins}m` : `${remMins}分`;
  }

  function formatQuotaDialDisplay(remainingMs, windowKey) {
    const safeMs = Math.max(0, Number(remainingMs) || 0);
    const sec = Math.floor(safeMs / 1000);
    const pad2 = v => String(Math.max(0, Math.floor(v))).padStart(2, '0');
    if (windowKey === 'weekly' || sec >= 86400) {
      if (safeMs <= 0) {
        return {
          mode: 'hours',
          partA: '0',
          colon: '',
          partB: 'm',
          unit: 'm',
          text: '0m',
          isWide: false,
          isExpired: true
        };
      }
      const totalHours = Math.floor(safeMs / 3600000);
      if (totalHours >= 1) {
        const left = String(totalHours);
        return {
          mode: 'hours',
          partA: left,
          colon: '',
          partB: 'h',
          unit: 'h',
          text: `${left}h`,
          isWide: left.length >= 3,
          isExpired: false
        };
      }
      const mins = safeMs >= 60000 ? Math.floor(safeMs / 60000) : 1;
      const left = String(mins);
      return {
        mode: 'hours',
        partA: left,
        colon: '',
        partB: 'm',
        unit: 'm',
        text: `${left}m`,
        isWide: false,
        isExpired: false
      };
    }
    if (sec < 60) {
      const pB = pad2(sec);
      return {
        mode: 'clock',
        partA: '00',
        colon: ':',
        partB: pB,
        unit: '',
        text: `00:${pB}`,
        isWide: false,
        isExpired: safeMs <= 0
      };
    }
    const hours = Math.floor(sec / 3600);
    const mins = Math.floor((sec % 3600) / 60);
    const pA = pad2(hours);
    const pB = pad2(mins);
    return {
      mode: 'clock',
      partA: pA,
      colon: ':',
      partB: pB,
      unit: '',
      text: `${pA}:${pB}`,
      isWide: false,
      isExpired: false
    };
  }

  function formatQuotaDialParts(remainingSec, windowKey) {
    const info = formatQuotaDialDisplay((Number(remainingSec) || 0) * 1000, windowKey);
    return [info.partA, info.partB];
  }

  function formatQuotaWindowTitle(bucket) {
    if (!bucket) return '';
    if (currentPanelLanguage === 'en') {
      if (bucket.windowKey === '5h') return '5h Window';
      if (bucket.windowKey === 'weekly') return 'Weekly Window';
      if (bucket.windowKey === 'daily') return 'Daily Window';
      return 'Primary Quota';
    }
    if (currentPanelLanguage === 'zh-TW') {
      if (bucket.windowKey === '5h') return '5小時限額';
      if (bucket.windowKey === 'weekly') return '每週限額';
      if (bucket.windowKey === 'daily') return '每日限額';
      return '目前主限額';
    }
    return bucket.windowLabel || '周期限额';
  }

  function getActiveQuotaModelInput() {
    if (activeSessionModelConfirmed && (activeSessionModelKey || activeSessionProductKey)) {
      if (activeSessionModelUnknown) {
        return {
          modelId: activeSessionModelKey || '',
          label: activeSessionModelLabel || activeSessionModelKey || activeSessionProductKey,
          productKey: activeSessionProductKey || '',
          role: activeSessionModelRole || undefined,
          isUnknownModel: true
        };
      }
      const cfgList = state.cascadeModelConfigs || state.scan?.cascadeModelConfigs || [];
      const activeKeyLower = String(activeSessionModelKey || '').trim().toLowerCase();
      const matched = activeKeyLower ? cfgList.find(c =>
        String(c?.modelId || '').trim().toLowerCase() === activeKeyLower ||
        String(c?.modelOrAlias?.model || '').trim().toLowerCase() === activeKeyLower
      ) : null;
      if (matched) return matched;
      return {
        modelId: activeSessionModelKey || '',
        label: activeSessionModelLabel || state.latest?.model || activeSessionModelKey || activeSessionProductKey,
        productKey: activeSessionProductKey || '',
        role: activeSessionModelRole || undefined
      };
    }
    if (state.latest?.modelId || state.latest?.model) {
      return {
        modelId: state.latest.modelId || state.latest.model,
        label: state.latest.model || state.latest.modelId
      };
    }
    return null;
  }

  function attachTokenEstimatesToQuotaView(view, nowMs) {
    const core = typeof __AGContextMeterCore !== 'undefined' ? __AGContextMeterCore : null;
    if (!view || !Array.isArray(view.pools) || !core?.applyQuotaTokenEstimates) return view;
    const scopeKey = quotaState.accountScopeKey || view.accountScopeKey || 'anonymous';
    const historyLoaded = Array.isArray(ANTIGRAVITY_TOKEN_DATA.recentModelUsage);
    const usageEvents = historyLoaded ? ANTIGRAVITY_TOKEN_DATA.recentModelUsage : [];
    const coverageStartMs = ANTIGRAVITY_TOKEN_DATA.quotaUsageCoverageStartMs ?? null;
    let maxEvTs = 0;
    let sumEvTokens = 0;
    for (let i = 0; i < usageEvents.length; i++) {
      const ev = usageEvents[i];
      const evTs = Number(ev?.ts ?? ev?.timestamp ?? 0);
      if (Number.isFinite(evTs) && evTs > maxEvTs) maxEvTs = evTs;
      const evTok = Number(ev?.totalTokens ?? ev?.tok ?? 0);
      if (Number.isFinite(evTok) && evTok > 0) sumEvTokens += evTok;
    }
    const poolSig = view.pools.map(p => `${p.poolKey}:${(p.buckets || []).map(b => `${b.bucketId}=${b.remainingFraction ?? 'n'}`).join(',')}`).join(';');
    const computeSig = `${scopeKey}|${historyLoaded ? 1 : 0}|${view.fetchedAtMs || 0}|${coverageStartMs ?? 'null'}|${usageEvents.length}|${maxEvTs}|${Math.round(sumEvTokens)}|${poolSig}`;

    if (quotaLastEstComputeSig === computeSig && quotaCachedEstByKey) {
      const enrichedPools = view.pools.map(p => {
        const nextBuckets = (p.buckets || []).map(b => {
          const bKey = `${p.poolKey}::${b.bucketId || b.windowKey}`;
          return quotaCachedEstByKey[bKey] ? { ...b, tokenEstimate: quotaCachedEstByKey[bKey] } : b;
        });
        const pb = p.primaryBucket ? (nextBuckets.find(b => b.bucketId === p.primaryBucket.bucketId) || nextBuckets[0] || p.primaryBucket) : (nextBuckets[0] || null);
        return { ...p, buckets: nextBuckets, primaryBucket: pb, tokenEstimate: pb?.tokenEstimate || p.tokenEstimate || null };
      });
      return { ...view, pools: enrichedPools };
    }

    const calMap = loadQuotaCalibrationForScope(scopeKey);
    const applied = core.applyQuotaTokenEstimates(view, {
      accountScopeKey: scopeKey,
      usageEvents,
      historyCoverageStartMs: coverageStartMs,
      historyLoaded,
      calibrationMap: calMap,
      nowMs: view.fetchedAtMs || nowMs
    });
    // 历史用量首次扫描尚未落盘时只读推算，不向 localStorage 持久化外部消耗锁定状态，防止冷启动竞态污染整个周期
    if (historyLoaded && applied?.nextCalibrationMap) {
      saveQuotaCalibrationForScope(scopeKey, applied.nextCalibrationMap);
    }
    const cacheObj = {};
    for (const p of (applied?.snapshot?.pools || [])) {
      for (const b of (p.buckets || [])) {
        cacheObj[`${p.poolKey}::${b.bucketId || b.windowKey}`] = b.tokenEstimate || null;
      }
    }
    quotaLastEstComputeSig = computeSig;
    quotaCachedEstByKey = cacheObj;
    return applied?.snapshot || view;
  }

  function applyQuotaBadgeWindowModeToView(view, core) {
    if (!view || !Array.isArray(view.pools) || !view.pools.length) return view;
    const mode = VALID_QUOTA_WINDOW_MODES.includes(quotaBadgeWindowMode) ? quotaBadgeWindowMode : 'auto';
    const hasUnmatchedCurrent = Boolean(view.currentModel && !view.currentModel.poolKey) || Boolean(view.currentModel?.isUnknownModel);
    if (hasUnmatchedCurrent) {
      return {
        ...view,
        badge: {
          ...(view.badge || {}),
          windowMode: mode,
          dualBuckets: null,
          fraction: null,
          status: 'unknown',
          statusLabel: view.badge?.statusLabel || getQuotaStatusLabelText('unknown'),
          text: view.badge?.text || t('quota.short.unknown'),
          tag: '',
          pace: null
        },
        activeReset: {
          hasResetTime: false,
          resetTimeIso: null,
          resetAtMs: null,
          resetTimeText: null,
          countdownText: null,
          isResetPassed: false
        }
      };
    }
    const targetPool = (view.currentModel?.poolKey
      ? view.pools.find(p => p.poolKey === view.currentModel.poolKey)
      : null) || view.pools[0] || null;
    if (!targetPool || !Array.isArray(targetPool.buckets) || !targetPool.buckets.length) {
      return { ...view, badge: { ...(view.badge || {}), windowMode: mode, dualBuckets: null } };
    }
    const selFn = typeof selectPrimaryQuotaBucket === 'function' ? selectPrimaryQuotaBucket : core?.selectPrimaryQuotaBucket;
    const pickMode = mode === 'both' ? 'auto' : mode;
    const sel = selFn ? selFn(targetPool.buckets, pickMode) : null;
    const pb = sel?.primaryBucket || targetPool.primaryBucket || targetPool.buckets[0] || null;
    if (pb) {
      targetPool.primaryBucket = pb;
      targetPool.selectionReason = sel?.selectionReason || targetPool.selectionReason;
    }

    const fmtPct = f => (core?.formatQuotaPercentText ? core.formatQuotaPercentText(f) : `${Math.round(Number(f) * 100)}%`);
    let dualBuckets = null;
    const pairFn = typeof resolveQuotaWindowBucketPair === 'function' ? resolveQuotaWindowBucketPair : core?.resolveQuotaWindowBucketPair;
    if (mode === 'both' && pairFn && view.activeStatus !== 'error' && view.activeStatus !== 'no_permission') {
      const pair = pairFn(targetPool.buckets);
      if (pair?.bucket5h && pair?.bucket7d && pair.bucket5h.remainingFraction != null && pair.bucket7d.remainingFraction != null) {
        dualBuckets = [
          { key: '5h', text: `5h ${fmtPct(pair.bucket5h.remainingFraction)}` },
          { key: '7d', text: `7d ${fmtPct(pair.bucket7d.remainingFraction)}` }
        ];
      }
    }

    const nextBadge = { ...(view.badge || {}), windowMode: mode, dualBuckets };
    let nextActiveReset = view.activeReset;
    if (pb && pb.remainingFraction != null && view.activeStatus !== 'error' && view.activeStatus !== 'no_permission') {
      nextBadge.fraction = pb.remainingFraction;
      if (pb.isExhausted || pb.remainingFraction === 0) {
        nextBadge.text = t('quota.short.exhausted');
      } else {
        nextBadge.text = fmtPct(pb.remainingFraction);
      }
      nextBadge.tag = view.syncState === 'stale' ? t('quota.short.stale') : (pb.windowShort || '');
      nextBadge.pace = (pb.pace && pb.pace.available && view.syncState !== 'stale') ? pb.pace : null;
      nextActiveReset = {
        hasResetTime: Boolean(pb.hasResetTime),
        resetTimeIso: pb.resetTimeIso ?? null,
        resetAtMs: pb.resetAtMs ?? null,
        resetTimeText: pb.resetTimeText ?? null,
        countdownText: pb.countdownText ?? null,
        isResetPassed: Boolean(pb.isResetPassed)
      };
    }

    return {
      ...view,
      badge: nextBadge,
      activeReset: nextActiveReset
    };
  }

  function computeEffectiveQuotaView(nowMs = Date.now()) {
    const core = typeof __AGContextMeterCore !== 'undefined' ? __AGContextMeterCore : null;
    const currentModelInput = getActiveQuotaModelInput();

    // 1. 优先复用 rawInput 通过 buildModelQuotaSnapshot 完整演算（支持测试注入原始响应或本地配置变更）
    if (quotaState.rawInput && core?.buildModelQuotaSnapshot) {
      const built = core.buildModelQuotaSnapshot({
        ...quotaState.rawInput,
        currentModel: currentModelInput,
        browsePoolKey: quotaState.browsePoolKey,
        fetchMeta: {
          fetchedAtMs: quotaState.lastSuccessAtMs ?? quotaState.lastFetchedAtMs,
          nextRefreshAtMs: quotaState.nextRefreshAtMs,
          staleThresholdMs: QUOTA_STALE_MS,
          error: quotaState.error,
          errorKind: quotaState.errorKind
        },
        nowMs
      });
      return applyQuotaBadgeWindowModeToView(attachTokenEstimatesToQuotaView(built, nowMs), core);
    }

    // 2. 基于主进程返回的标准化 snapshot 重新结合当前会话模型与实时 nowMs 刷新视图状态
    const base = quotaState.snapshot;
    if (!base) {
      const hasErr = Boolean(quotaState.error);
      return {
        schemaVersion: 1,
        syncState: hasErr ? 'error' : 'unknown',
        fetchedAtMs: quotaState.lastSuccessAtMs ?? quotaState.lastFetchedAtMs,
        nextRefreshAtMs: quotaState.nextRefreshAtMs,
        staleThresholdMs: QUOTA_STALE_MS,
        lastError: quotaState.error,
        errorKind: quotaState.errorKind,
        currentModel: currentModelInput ? { productLabel: String(currentModelInput.label || currentModelInput.modelId) } : null,
        activeStatus: hasErr ? 'error' : 'unknown',
        activeStatusLabel: getQuotaStatusLabelText(hasErr ? 'error' : 'unknown'),
        badge: {
          text: getQuotaShortBadgeText(hasErr ? 'error' : 'unknown'),
          tag: hasErr ? t('quota.retry') : '',
          fraction: null,
          status: hasErr ? 'error' : 'unknown',
          statusLabel: getQuotaStatusLabelText(hasErr ? 'error' : 'unknown')
        },
        activeReset: { hasResetTime: false, resetTimeText: null, countdownText: null, isResetPassed: false },
        browsePoolKey: quotaState.browsePoolKey,
        planTierName: ANTIGRAVITY_TOKEN_DATA.planStatus?.tierName || null,
        pools: []
      };
    }

    const updatedPools = (base.pools || []).map(p => {
      const nextBuckets = (p.buckets || []).map(b => {
        if (!b.resetTimeIso || !core?.formatQuotaResetMeta) return { ...b };
        const rm = core.formatQuotaResetMeta(b.resetTimeIso, nowMs);
        return {
          ...b,
          hasResetTime: rm.hasResetTime,
          resetAtMs: rm.resetAtMs,
          resetTimeText: rm.resetTimeText,
          countdownText: rm.countdownText,
          isResetPassed: rm.isResetPassed
        };
      });
      const pickMode = quotaBadgeWindowMode === 'both' ? 'auto' : quotaBadgeWindowMode;
      const sel = (typeof selectPrimaryQuotaBucket === 'function')
        ? selectPrimaryQuotaBucket(nextBuckets, pickMode)
        : (() => {
          const priced = nextBuckets.filter(b => b.remainingFraction !== null).sort((a, b) => a.remainingFraction - b.remainingFraction);
          return { primaryBucket: priced[0] || nextBuckets[0] || null, selectionReason: priced.length <= 1 ? 'single_window' : 'tighter_window' };
        })();
      const pb = sel.primaryBucket || p.primaryBucket || nextBuckets[0] || null;
      const pbFrac = pb?.remainingFraction ?? p.remainingFraction ?? null;
      const pbExhausted = pb ? Boolean(pb.isExhausted || pb.remainingFraction === 0) : Boolean(p.isExhausted);
      const nextStatus = p.noPermission
        ? 'no_permission'
        : (pbFrac == null
          ? (p.status || 'unknown')
          : (pbExhausted ? 'exhausted' : (pbFrac <= 0.2 ? 'low' : 'available')));
      return {
        ...p,
        buckets: nextBuckets,
        primaryBucket: pb,
        selectionReason: sel.selectionReason || p.selectionReason || 'single_window',
        status: nextStatus,
        remainingFraction: pbFrac,
        percentText: pb?.percentText ?? p.percentText ?? null,
        isExhausted: pbExhausted,
        hasResetTime: Boolean(pb?.hasResetTime ?? p.hasResetTime),
        resetTimeIso: pb?.resetTimeIso ?? p.resetTimeIso ?? null,
        resetAtMs: pb?.resetAtMs ?? p.resetAtMs ?? null,
        resetTimeText: pb?.resetTimeText ?? p.resetTimeText ?? null,
        countdownText: pb?.countdownText ?? p.countdownText ?? null,
        isResetPassed: Boolean(pb?.isResetPassed ?? p.isResetPassed)
      };
    });

    // 针对实时切换后的会话模型重新匹配池与模型
    const targetCandidates = currentModelInput
      ? (typeof currentModelInput === 'object'
        ? [currentModelInput.modelId, currentModelInput.modelOrAlias?.model, currentModelInput.label, currentModelInput.model]
        : [String(currentModelInput)]
      ).filter(v => typeof v === 'string' && v.trim())
      : [];
    const targetLowers = targetCandidates.map(v => v.trim().toLowerCase());
    const targetStripped = targetLowers.map(v => v.replace(/^model_/, ''));
    const normFn = core?.normalizeModelLookupName;
    const targetNorms = normFn
      ? [...new Set(targetCandidates.map(v => normFn(v)).filter(Boolean))]
      : [];
    let matchedPool = null;
    let matchedModel = null;
    if (!currentModelInput?.isUnknownModel && (targetLowers.length > 0 || currentModelInput?.productKey)) {
      for (const p of updatedPools) {
        for (const m of (p.models || [])) {
          const allIds = [...(m.modelIds || []), ...(m.aliases || [])].map(x => String(x).toLowerCase());
          if (allIds.some(id => targetLowers.includes(id) || targetStripped.includes(id.replace(/^model_/, '')))) {
            matchedPool = p;
            matchedModel = m;
            break;
          }
        }
        if (matchedPool) break;
      }
      if (!matchedPool && currentModelInput?.productKey) {
        for (const p of updatedPools) {
          for (const m of (p.models || [])) {
            if (m.productKey && m.productKey === currentModelInput.productKey) {
              matchedPool = p;
              matchedModel = m;
              break;
            }
          }
          if (matchedPool) break;
        }
      }
      if (!matchedPool) {
        for (const p of updatedPools) {
          for (const m of (p.models || [])) {
            if (m.productLabel && targetLowers.includes(m.productLabel.toLowerCase())) {
              matchedPool = p;
              matchedModel = m;
              break;
            }
            if (normFn && m.productLabel) {
              const mNorm = normFn(m.productLabel);
              if (mNorm && targetNorms.includes(mNorm)) {
                matchedPool = p;
                matchedModel = m;
                break;
              }
            }
          }
          if (matchedPool) break;
        }
      }
      if (!matchedPool && core?.getSharedQuotaGroupKey) {
        const gKey = core.getSharedQuotaGroupKey(currentModelInput);
        matchedPool = updatedPools.find(p => p.poolKey === gKey) || null;
        if (matchedPool) matchedModel = matchedPool.models?.[0] || null;
      }
    }

    const lastOkMs = quotaState.lastSuccessAtMs ?? base.fetchedAtMs ?? null;
    const ageExpired = lastOkMs !== null && (nowMs - lastOkMs > QUOTA_STALE_MS);
    const anyResetPassed = updatedPools.some(p => p.isResetPassed && p.remainingFraction === 0);
    const hasAnyPool = updatedPools.some(p => p.remainingFraction !== null || p.noPermission);
    let syncState = 'unknown';
    if (!hasAnyPool && quotaState.error) syncState = 'error';
    else if (hasAnyPool && (quotaState.error || ageExpired || anyResetPassed)) syncState = 'stale';
    else if (hasAnyPool) syncState = 'fresh';

    const paceFn = typeof evaluateQuotaPace === 'function' ? evaluateQuotaPace : core?.evaluateQuotaPace;
    if (paceFn) {
      for (const p of updatedPools) {
        const paceStatus = p.noPermission
          ? 'no_permission'
          : (syncState === 'error' || syncState === 'stale' ? syncState : p.status);
        for (const b of (p.buckets || [])) {
          b.pace = paceFn(b, nowMs, { status: paceStatus });
        }
        if (p.primaryBucket) {
          const matchedBucket = (p.buckets || []).find(x => x === p.primaryBucket || (p.primaryBucket.bucketId && x.bucketId === p.primaryBucket.bucketId));
          if (matchedBucket && matchedBucket.pace) p.primaryBucket.pace = matchedBucket.pace;
          else p.primaryBucket.pace = paceFn(p.primaryBucket, nowMs, { status: paceStatus });
        }
      }
    }

    let activeStatus = 'unknown';
    let badgeText = t('quota.short.unknown');
    let badgeTag = '';
    let activeFraction = null;
    let activeReset = { hasResetTime: false, resetTimeText: null, countdownText: null, isResetPassed: false };

    if (syncState === 'error') {
      activeStatus = 'error';
      badgeText = t('quota.short.error');
      badgeTag = t('quota.retry');
    } else if (matchedModel?.noPermission || matchedPool?.noPermission) {
      activeStatus = 'no_permission';
      badgeText = t('quota.short.no_permission');
    } else if (matchedPool) {
      activeFraction = matchedPool.remainingFraction;
      activeReset = {
        hasResetTime: matchedPool.hasResetTime,
        resetTimeIso: matchedPool.resetTimeIso,
        resetAtMs: matchedPool.resetAtMs,
        resetTimeText: matchedPool.resetTimeText,
        countdownText: matchedPool.countdownText,
        isResetPassed: matchedPool.isResetPassed
      };
      if (matchedPool.remainingFraction === null) {
        activeStatus = syncState === 'stale' ? 'stale' : 'unknown';
        badgeText = t(syncState === 'stale' ? 'quota.short.stale' : 'quota.short.unknown');
      } else if (matchedPool.isExhausted || matchedPool.remainingFraction === 0) {
        activeStatus = syncState === 'stale' ? 'stale' : 'exhausted';
        badgeText = t('quota.short.exhausted');
        badgeTag = matchedPool.primaryBucket?.windowShort || '';
      } else {
        activeStatus = syncState === 'stale' ? 'stale' : (matchedPool.remainingFraction <= 0.2 ? 'low' : 'available');
        badgeText = core?.formatQuotaPercentText ? core.formatQuotaPercentText(matchedPool.remainingFraction) : matchedPool.percentText;
        badgeTag = syncState === 'stale' ? t('quota.short.stale') : (matchedPool.primaryBucket?.windowShort || '');
      }
    } else if (!currentModelInput?.isUnknownModel && syncState === 'stale') {
      activeStatus = 'stale';
      badgeText = t('quota.short.stale');
    }

    const baseOut = attachTokenEstimatesToQuotaView({
      ...base,
      syncState,
      fetchedAtMs: lastOkMs,
      nextRefreshAtMs: quotaState.nextRefreshAtMs,
      lastError: quotaState.error,
      errorKind: quotaState.errorKind,
      currentModel: matchedModel
        ? {
          productKey: matchedModel.productKey,
          productLabel: matchedModel.productLabel,
          poolKey: matchedPool.poolKey,
          poolTitle: matchedPool.title,
          noPermission: matchedModel.noPermission,
          unavailabilityReason: matchedModel.unavailabilityReason,
          noticeText: matchedModel.noticeText
        }
        : (currentModelInput
          ? {
            productLabel: String(currentModelInput.label || currentModelInput.modelId),
            poolKey: null,
            poolTitle: null,
            isUnknownModel: Boolean(currentModelInput.isUnknownModel)
          }
          : base.currentModel),
      activeStatus,
      activeStatusLabel: getQuotaStatusLabelText(activeStatus),
      badge: {
        text: badgeText,
        tag: badgeTag,
        fraction: activeFraction,
        status: activeStatus,
        statusLabel: getQuotaStatusLabelText(activeStatus)
      },
      activeReset,
      browsePoolKey: quotaState.browsePoolKey || matchedPool?.poolKey || updatedPools[0]?.poolKey || null,
      pools: updatedPools
    }, nowMs);
    return applyQuotaBadgeWindowModeToView(baseOut, core);
  }

  /**
   * 判定估算样本是否涉及跨厂商模型混用（严禁仅凭模型数量给单厂商 Gemini 池误标「同池混用模型」）
   */
  function isCrossVendorMixedPoolEstimate(est, poolCtx = null) {
    if (!est || !est.mixedPoolModels) return false;
    const poolKey = String(poolCtx?.poolKey || poolCtx?.pool?.poolKey || '').toLowerCase();
    const resolveVendor = (modelKey) => {
      const s = String(modelKey || '').toLowerCase();
      if (!s || s === 'unknown') return '';
      if (s.includes('gemini') || s.includes('google') || s.includes('orchestrator')) return 'google';
      if (s.includes('claude') || s.includes('anthropic') || s.includes('opus') || s.includes('sonnet') || s.includes('haiku')) return 'anthropic';
      if (s.includes('gpt') || s.includes('openai') || s.includes('o1') || s.includes('o3') || s.includes('o4')) return 'openai';
      return s.split(/[-_:]/)[0] || s;
    };
    const usedModels = Array.isArray(est.poolModelsUsed) ? est.poolModelsUsed.filter(Boolean) : [];
    if (usedModels.length > 0) {
      const vendors = new Set(usedModels.map(resolveVendor).filter(Boolean));
      if (vendors.size > 1) return true;
      if (vendors.size === 1) return false;
    }
    if (poolKey === 'shared_gemini_main' || poolKey.includes('gemini')) return false;
    if (poolKey === 'shared_3p_pool' || poolKey.includes('3p')) return true;
    const poolModels = Array.isArray(poolCtx?.pool?.models) ? poolCtx.pool.models : [];
    if (poolModels.length > 0) {
      const poolVendors = new Set(poolModels.map(m => resolveVendor(m?.vendor || m?.productKey || m?.productLabel)).filter(Boolean));
      if (poolVendors.size > 1) return true;
      if (poolVendors.size === 1) return false;
    }
    return false;
  }

  function formatBucketTokenEstimateLine(est, poolCtx = null) {
    if (!est || est.estSource === 'unavailable' || est.estSource === 'unknown') return '';
    if (est.estBasis === 'exhausted' || est.estSource === 'exhausted' || est.estRemainingTokens === 0) {
      return t('quota.est.exhausted');
    }
    if (est.estBasis === 'incomplete_samples' || est.estSource === 'incomplete') {
      return t('quota.est.incomplete');
    }
    if (est.estBasis === 'calibration_expired' || est.estSource === 'expired') {
      return t('quota.est.expired');
    }
    if (est.estBasis === 'coverage_incomplete') {
      return t('quota.est.coverageIncomplete');
    }
    if (est.estRemainingTokens != null && est.estRemainingShort) {
      let basisKey = 'quota.est.basisCached';
      if (est.estBasis === 'stale_with_divergence' || est.estSource === 'unreliable_cached') {
        basisKey = 'quota.est.basisStaleDivergence';
      } else if (est.estBasis === 'delta_calibrated' && est.estSource === 'delta') {
        basisKey = 'quota.est.basisDelta';
      } else if (est.estBasis === 'cycle_estimated' && est.estSource === 'cycle') {
        basisKey = 'quota.est.basisCycle';
      }
      const parts = [
        t('quota.est.approx', { tokens: est.estRemainingShort }),
        t(basisKey)
      ];
      if (isCrossVendorMixedPoolEstimate(est, poolCtx)) {
        parts.push(t('quota.est.mixedModels'));
      }
      const core = typeof __AGContextMeterCore !== 'undefined' ? __AGContextMeterCore : null;
      const usedShort = est.cycleTokensUsed > 0 && core?.formatApproxTokensShort
        ? core.formatApproxTokensShort(est.cycleTokensUsed)
        : null;
      if (usedShort) {
        parts.push(t('quota.est.cycleUsed', { used: usedShort }));
      }
      return parts.join(' · ');
    }
    return t('quota.est.waiting');
  }

  function getChildAttr(node, name) {
    if (!node) return null;
    if (typeof node.getAttribute === 'function') return node.getAttribute(name);
    return node.attributes?.[name] ?? null;
  }

  function reconcileQuotaChildOrder(container, desiredNodes) {
    const cur = Array.from(container.children || []);
    const sameOrder = cur.length === desiredNodes.length && cur.every((n, idx) => n === desiredNodes[idx]);
    if (sameOrder) return;
    if (typeof container.removeChild === 'function' && typeof container.insertBefore === 'function') {
      const wantSet = new Set(desiredNodes);
      for (const ch of cur) {
        if (!wantSet.has(ch)) container.removeChild(ch);
      }
      for (let i = 0; i < desiredNodes.length; i++) {
        const node = desiredNodes[i];
        const atIdx = container.children[i] || null;
        if (atIdx !== node) {
          container.insertBefore(node, atIdx);
        }
      }
      return;
    }
    if (typeof container.replaceChildren === 'function') {
      container.replaceChildren(...desiredNodes);
    } else {
      if (Array.isArray(container.children)) container.children.length = 0;
      for (const n of desiredNodes) container.appendChild?.(n);
    }
  }

  function getQuotaPaceTierLabel(pace) {
    if (!pace || !pace.tierKey) return '';
    if (pace.tierKey === 'surplus') return t('quota.pace.surplus');
    if (pace.tierKey === 'balanced') return t('quota.pace.balanced');
    if (pace.tierKey === 'fast') return t('quota.pace.fast');
    return t('quota.pace.overburn');
  }

  function formatQuotaPaceDeltaText(pace) {
    if (!pace || !pace.available) return '';
    const label = getQuotaPaceTierLabel(pace);
    if (pace.isExhausted) return `${label} · ${t('quota.pace.exhaustedTag')}`;
    if (pace.tier === 2 && pace.deltaPct === 0) return label;
    const sign = pace.deltaPct >= 0 ? '+' : '';
    return `${label} ${sign}${pace.deltaPct}%`;
  }

  function computePaceRingDotCoords(cx, cy, radius, timeRemaining) {
    const tFrac = Math.max(0, Math.min(1, Number(timeRemaining) || 0));
    const angle = -Math.PI / 2 + 2 * Math.PI * tFrac;
    return {
      x: Number((cx + radius * Math.cos(angle)).toFixed(2)),
      y: Number((cy + radius * Math.sin(angle)).toFixed(2))
    };
  }

  function renderQuotaBucketsContainer(container, buckets, statusOverride = null, opts = {}) {
    if (!container) return;
    const list = Array.isArray(buckets) ? buckets : [];
    const animate = Boolean(opts.animate);
    const nowMs = Number.isFinite(Number(opts.nowMs)) ? Number(opts.nowMs) : Date.now();
    if (!list.length) {
      reconcileQuotaChildOrder(container, []);
      return;
    }

    const MINI_RING_C = 2 * Math.PI * 5.5;
    const existingRows = new Map();
    for (const child of Array.from(container.children || [])) {
      const bKey = getChildAttr(child, 'data-bucket-key');
      if (bKey) existingRows.set(bKey, child);
    }

    const desiredRows = [];
    for (let i = 0; i < list.length; i++) {
      const b = list[i];
      const bKey = String(b.bucketId || b.windowKey || `b-${i}`);

      let row = existingRows.get(bKey);
      let refs = row ? quotaNodeRefsMap.get(row) : null;

      if (!row || !refs) {
        row = document.createElement('div');
        row.className = 'quota-bucket-row';
        row.setAttribute('data-bucket-key', bKey);

        const meta = document.createElement('div');
        meta.className = 'quota-bucket-meta';

        const leftBox = document.createElement('span');
        leftBox.className = 'quota-bucket-left';

        const miniSvg = createQuotaSvgEl('svg');
        let miniFill = null;
        let miniDot = null;
        if (miniSvg) {
          miniSvg.setAttribute('class', 'quota-mini-ring-svg');
          miniSvg.setAttribute('width', '15');
          miniSvg.setAttribute('height', '15');
          miniSvg.setAttribute('viewBox', '0 0 16 16');
          miniSvg.setAttribute('aria-hidden', 'true');
          const miniTrack = createQuotaSvgEl('circle');
          miniFill = createQuotaSvgEl('circle');
          miniDot = createQuotaSvgEl('circle');
          if (miniTrack) {
            miniTrack.setAttribute('class', 'quota-mini-ring-track');
            miniTrack.setAttribute('cx', '8');
            miniTrack.setAttribute('cy', '8');
            miniTrack.setAttribute('r', '5.5');
            miniTrack.setAttribute('fill', 'none');
            miniTrack.setAttribute('stroke-width', '2');
            miniSvg.appendChild(miniTrack);
          }
          if (miniFill) {
            miniFill.setAttribute('class', 'quota-mini-ring-fill');
            miniFill.setAttribute('cx', '8');
            miniFill.setAttribute('cy', '8');
            miniFill.setAttribute('r', '5.5');
            miniFill.setAttribute('fill', 'none');
            miniFill.setAttribute('stroke-width', '2');
            miniFill.setAttribute('stroke-linecap', 'round');
            miniFill.setAttribute('transform', 'rotate(-90 8 8)');
            miniFill.setAttribute('stroke-dasharray', `${MINI_RING_C.toFixed(2)} ${MINI_RING_C.toFixed(2)}`);
            miniFill.setAttribute('stroke-dashoffset', MINI_RING_C.toFixed(2));
            miniSvg.appendChild(miniFill);
          }
          if (miniDot) {
            miniDot.setAttribute('class', 'quota-mini-pace-dot');
            miniDot.setAttribute('cx', '8');
            miniDot.setAttribute('cy', '2.5');
            miniDot.setAttribute('r', '1.35');
            miniDot.hidden = true;
            miniSvg.appendChild(miniDot);
          }
          leftBox.appendChild(miniSvg);
        }

        const nameEl = document.createElement('span');
        nameEl.className = 'quota-bucket-name';
        leftBox.appendChild(nameEl);

        const winBadges = document.createElement('span');
        winBadges.className = 'quota-window-badges';
        leftBox.appendChild(winBadges);

        const valEl = document.createElement('span');
        valEl.className = 'quota-bucket-val';
        const pctEl = document.createElement('span');
        pctEl.className = 'quota-pct-num';
        const resetEl = document.createElement('span');
        resetEl.className = 'quota-reset-span';
        valEl.appendChild(pctEl);
        valEl.appendChild(resetEl);

        meta.appendChild(leftBox);
        meta.appendChild(valEl);

        const track = document.createElement('div');
        track.className = 'quota-bar-track';
        const fillEl = document.createElement('div');
        fillEl.className = 'quota-bar-fill';
        track.appendChild(fillEl);

        // 保留隐藏的兼容层在 track.children[1]，20 格模式下彻底禁用连续绿带与反光
        const chargeStage = document.createElement('div');
        chargeStage.className = 'quota-bar-charge-stage';
        chargeStage.hidden = true;
        const chargeFill = document.createElement('div');
        chargeFill.className = 'quota-bar-charge-fill';
        const chargeSheen = document.createElement('div');
        chargeSheen.className = 'quota-bar-charge-sheen';
        chargeStage.appendChild(chargeFill);
        chargeStage.appendChild(chargeSheen);
        track.appendChild(chargeStage);

        // 20 格离散分段上轨层：保留在 track.children[2]，原地复用不重建
        const segsWrap = document.createElement('div');
        segsWrap.className = 'quota-bar-segments';
        const segFills = [];
        for (let sIdx = 0; sIdx < 20; sIdx++) {
          const seg = document.createElement('span');
          seg.className = 'quota-seg';
          const segFill = document.createElement('span');
          segFill.className = 'quota-seg-fill';
          seg.appendChild(segFill);
          segsWrap.appendChild(seg);
          segFills.push(segFill);
        }
        track.appendChild(segsWrap);

        // 时间基准与消耗节奏下轨：原地复用于 row.children[2]
        const paceWrap = document.createElement('div');
        paceWrap.className = 'quota-pace-wrap';
        paceWrap.hidden = true;

        const paceTrack = document.createElement('div');
        paceTrack.className = 'quota-pace-track';
        const paceTimeFill = document.createElement('div');
        paceTimeFill.className = 'quota-pace-time-fill';
        const paceGap = document.createElement('div');
        paceGap.className = 'quota-pace-gap';
        paceGap.hidden = true;
        const paceTick = document.createElement('div');
        paceTick.className = 'quota-pace-tick';
        paceTrack.appendChild(paceTimeFill);
        paceTrack.appendChild(paceGap);
        paceTrack.appendChild(paceTick);

        const paceMeta = document.createElement('div');
        paceMeta.className = 'quota-pace-meta';
        const paceTimeText = document.createElement('span');
        paceTimeText.className = 'quota-pace-time-text';
        const paceTierPill = document.createElement('span');
        paceTierPill.className = 'quota-pace-tier-pill';
        paceMeta.appendChild(paceTimeText);
        paceMeta.appendChild(paceTierPill);

        paceWrap.appendChild(paceTrack);
        paceWrap.appendChild(paceMeta);

        const estEl = document.createElement('div');
        estEl.className = 'quota-bucket-est';
        estEl.hidden = true;

        // 右侧独立圆形重置倒计时表盘：附加在 row.children[4]，不影响 0..3 既有索引
        const dialWrap = document.createElement('div');
        dialWrap.className = 'quota-reset-dial';
        dialWrap.setAttribute('tabindex', '0');
        const DIAL_R = 21;
        const DIAL_C = 2 * Math.PI * DIAL_R;
        const dialSvg = createQuotaSvgEl('svg');
        let dialArc = null;
        let dialTip = null;
        if (dialSvg) {
          dialSvg.setAttribute('class', 'quota-dial-svg');
          dialSvg.setAttribute('viewBox', '0 0 56 56');
          dialSvg.setAttribute('aria-hidden', 'true');
          for (let ti = 0; ti < 24; ti++) {
            const ang = (ti * 15 - 90) * (Math.PI / 180);
            const isMajor = ti % 6 === 0;
            const rIn = isMajor ? 24.4 : 25.1;
            const rOut = 26.8;
            const tick = createQuotaSvgEl('line');
            if (tick) {
              tick.setAttribute('class', isMajor ? 'quota-dial-tick quota-dial-tick--major' : 'quota-dial-tick');
              tick.setAttribute('x1', (28 + rIn * Math.cos(ang)).toFixed(2));
              tick.setAttribute('y1', (28 + rIn * Math.sin(ang)).toFixed(2));
              tick.setAttribute('x2', (28 + rOut * Math.cos(ang)).toFixed(2));
              tick.setAttribute('y2', (28 + rOut * Math.sin(ang)).toFixed(2));
              dialSvg.appendChild(tick);
            }
          }
          const dTrack = createQuotaSvgEl('circle');
          if (dTrack) {
            dTrack.setAttribute('class', 'quota-dial-track');
            dTrack.setAttribute('cx', '28');
            dTrack.setAttribute('cy', '28');
            dTrack.setAttribute('r', String(DIAL_R));
            dialSvg.appendChild(dTrack);
          }
          dialArc = createQuotaSvgEl('circle');
          if (dialArc) {
            dialArc.setAttribute('class', 'quota-dial-arc');
            dialArc.setAttribute('cx', '28');
            dialArc.setAttribute('cy', '28');
            dialArc.setAttribute('r', String(DIAL_R));
            dialArc.setAttribute('stroke-dasharray', DIAL_C.toFixed(2));
            dialArc.setAttribute('stroke-dashoffset', DIAL_C.toFixed(2));
            dialSvg.appendChild(dialArc);
          }
          dialTip = createQuotaSvgEl('circle');
          if (dialTip) {
            dialTip.setAttribute('class', 'quota-dial-tip');
            dialTip.setAttribute('cx', '28');
            dialTip.setAttribute('cy', String(28 - DIAL_R));
            dialTip.setAttribute('r', '2');
            dialSvg.appendChild(dialTip);
          }
          dialWrap.appendChild(dialSvg);
        }
        const dialCenter = document.createElement('div');
        dialCenter.className = 'quota-dial-center';
        const dialPartA = document.createElement('span');
        dialPartA.className = 'quota-dial-part';
        dialPartA.textContent = '--';
        const dialColon = document.createElement('span');
        dialColon.className = 'quota-dial-colon';
        dialColon.textContent = ':';
        const dialPartB = document.createElement('span');
        dialPartB.className = 'quota-dial-part';
        dialPartB.textContent = '--';
        dialCenter.appendChild(dialPartA);
        dialCenter.appendChild(dialColon);
        dialCenter.appendChild(dialPartB);
        dialWrap.appendChild(dialCenter);

        row.appendChild(meta);
        row.appendChild(track);
        row.appendChild(paceWrap);
        row.appendChild(estEl);
        row.appendChild(dialWrap);
        refs = {
          nameEl,
          winBadges,
          miniSvg,
          miniFill,
          miniDot,
          pctEl,
          resetEl,
          track,
          fillEl,
          chargeStage,
          chargeFill,
          chargeSheen,
          chargeRef: { track, chargeStage, segFills, activeCells: 0, chargeEligible: false, barKey: `${opts.poolKey || ''}::${bKey}` },
          segsWrap,
          segFills,
          paceWrap,
          paceTimeFill,
          paceGap,
          paceTick,
          paceTimeText,
          paceTierPill,
          estEl,
          dialWrap,
          dialArc,
          dialTip,
          dialPartA,
          dialColon,
          dialPartB,
          dialCircumference: DIAL_C,
          dialRadius: DIAL_R
        };
        quotaNodeRefsMap.set(row, refs);
      }

      const {
        nameEl, winBadges, miniSvg, miniFill, miniDot, pctEl, resetEl, track, fillEl,
        chargeStage, chargeRef, segsWrap, segFills,
        paceWrap, paceTimeFill, paceGap, paceTick, paceTimeText, paceTierPill, estEl,
        dialWrap, dialArc, dialTip, dialPartA, dialColon, dialPartB, dialCircumference, dialRadius
      } = refs;
      if (chargeRef) chargeRef.barKey = `${opts.poolKey || ''}::${bKey}`;
      if (nameEl) setQuotaTextIfChanged(nameEl, formatQuotaWindowTitle(b));

      if (winBadges) {
        const wShortTag = b.windowShort || (b.windowKey === '5h' ? '5h' : (b.windowKey === 'weekly' ? '7d' : (b.windowKey === 'daily' ? '24h' : '')));
        const badgeSig = `${wShortTag}`;
        if (getChildAttr(winBadges, 'data-badge-sig') !== badgeSig) {
          winBadges.setAttribute('data-badge-sig', badgeSig);
          const bNodes = [];
          if (wShortTag) {
            const wEl = document.createElement('span');
            wEl.className = 'quota-win-badge';
            wEl.textContent = wShortTag;
            bNodes.push(wEl);
          }
          reconcileQuotaChildOrder(winBadges, bNodes);
        }
      }

      const pace = (statusOverride === 'no_permission' || opts.paceSuppressed)
        ? null
        : (b.pace && b.pace.available ? b.pace : null);

      if (pace) {
        setQuotaAttrIfChanged(row, 'data-pace-tier', String(pace.tier));
      } else {
        removeQuotaAttrIfPresent(row, 'data-pace-tier');
      }

      if (pctEl) {
        if (statusOverride === 'no_permission') {
          animateQuotaPercentNode(pctEl, null, false, t('quota.short.no_permission'));
        } else if (b.remainingFraction == null) {
          animateQuotaPercentNode(pctEl, null, false, t('quota.time.unknown'));
        } else {
          animateQuotaPercentNode(pctEl, b.remainingFraction, animate, b.percentText);
        }
      }

      if (resetEl) {
        const resetSuffix = b.hasResetTime
          ? ` · ${b.resetTimeText}${b.countdownText ? ` · ${b.isResetPassed ? b.countdownText : formatCountdownMsCompact((b.resetAtMs || 0) - nowMs)}` : ''}`
          : ` · ${t('quota.time.reset')} ${t('quota.time.unknown')}`;
        setQuotaTextIfChanged(resetEl, resetSuffix);
      }

      const bStatus = statusOverride || (b.remainingFraction == null
        ? 'unknown'
        : (b.isExhausted || b.remainingFraction === 0 ? 'exhausted' : (b.remainingFraction <= 0.2 ? 'low' : 'available')));
      const hasValidFrac = b.remainingFraction != null && Number.isFinite(Number(b.remainingFraction)) && statusOverride !== 'no_permission';
      const scaleVal = b.remainingFraction == null ? 0 : Math.max(0, Math.min(1, b.remainingFraction));
      const scaleStr = scaleVal.toFixed(4);
      const stageWidthStr = `${(scaleVal * 100).toFixed(2)}%`;

      if (miniSvg && miniFill) {
        if (!hasValidFrac) {
          setQuotaAttrIfChanged(miniFill, 'stroke-dashoffset', MINI_RING_C.toFixed(2));
          if (miniDot) setQuotaHiddenIfChanged(miniDot, true);
        } else {
          const offsetStr = (MINI_RING_C * (1 - scaleVal)).toFixed(2);
          setQuotaAttrIfChanged(miniFill, 'stroke-dashoffset', offsetStr);
          if (miniDot) {
            if (pace) {
              const pos = computePaceRingDotCoords(8, 8, 5.5, pace.timeRemaining);
              setQuotaAttrIfChanged(miniDot, 'cx', String(pos.x));
              setQuotaAttrIfChanged(miniDot, 'cy', String(pos.y));
              setQuotaHiddenIfChanged(miniDot, false);
            } else {
              setQuotaHiddenIfChanged(miniDot, true);
            }
          }
        }
      }

      // 更新右侧圆形重置倒计时表盘（共用真实 resetAtMs 与周期时长，缺数据明确标待识别）
      if (dialWrap) {
        const showDial = statusOverride !== 'no_permission';
        setQuotaHiddenIfChanged(dialWrap, !showDial);
        row.classList?.toggle?.('has-dial', showDial);
        if (showDial) {
          const coreRef = typeof __AGContextMeterCore !== 'undefined' ? __AGContextMeterCore : null;
          const totalDurationMs = coreRef?.inferQuotaWindowDurationMs
            ? coreRef.inferQuotaWindowDurationMs(b.windowKey, b.bucketId)
            : (b.windowKey === '5h' ? 5 * 3600000 : (b.windowKey === 'weekly' ? 7 * 86400000 : null));
          const hasValidReset = Boolean(b.hasResetTime && Number.isFinite(Number(b.resetAtMs)));
          if (hasValidReset && totalDurationMs && totalDurationMs > 0) {
            const remMs = Math.max(0, Number(b.resetAtMs) - nowMs);
            const ratio = Math.max(0, Math.min(1, remMs / totalDurationMs));
            const isSoon = ratio <= 0.25;
            removeQuotaAttrIfPresent(dialWrap, 'data-dial-pending');
            setQuotaAttrIfChanged(dialWrap, 'data-dial-soon', isSoon ? 'true' : 'false');
            const dialInfo = formatQuotaDialDisplay(remMs, b.windowKey);
            setQuotaAttrIfChanged(dialWrap, 'data-dial-format', dialInfo.mode);
            if (dialInfo.isWide) setQuotaAttrIfChanged(dialWrap, 'data-dial-wide', 'true');
            else removeQuotaAttrIfPresent(dialWrap, 'data-dial-wide');
            if (dialInfo.isExpired) setQuotaAttrIfChanged(dialWrap, 'data-dial-expired', 'true');
            else removeQuotaAttrIfPresent(dialWrap, 'data-dial-expired');
            if (dialPartA) setQuotaTextIfChanged(dialPartA, dialInfo.partA);
            if (dialColon) {
              setQuotaHiddenIfChanged(dialColon, dialInfo.mode === 'hours');
              setQuotaTextIfChanged(dialColon, dialInfo.colon);
            }
            if (dialPartB) {
              setQuotaTextIfChanged(dialPartB, dialInfo.partB);
              dialPartB.classList?.toggle?.('quota-dial-part--unit', dialInfo.mode === 'hours');
            }
            if (dialArc) {
              const offset = (dialCircumference * (1 - ratio)).toFixed(2);
              setQuotaAttrIfChanged(dialArc, 'stroke-dashoffset', offset);
            }
            if (dialTip) {
              const ang = -Math.PI / 2 + ratio * Math.PI * 2;
              setQuotaAttrIfChanged(dialTip, 'cx', (28 + dialRadius * Math.cos(ang)).toFixed(2));
              setQuotaAttrIfChanged(dialTip, 'cy', (28 + dialRadius * Math.sin(ang)).toFixed(2));
              if (dialTip.style) dialTip.style.opacity = ratio <= 0.005 ? '0' : '1';
            }
            const remainPct = Math.round(ratio * 100);
            const elapsedPct = 100 - remainPct;
            const tipStr = t('quota.dial.tooltip', {
              elapsed: elapsedPct,
              remain: remainPct,
              exact: formatQuotaDialExactDuration(remMs),
              reset: b.resetTimeText || t('quota.time.unknown')
            });
            if (dialWrap.title !== tipStr) dialWrap.title = tipStr;
            setQuotaAttrIfChanged(dialWrap, 'aria-label', `${t('quota.dial.aria', { time: dialInfo.text })} · ${tipStr}`);
          } else {
            setQuotaAttrIfChanged(dialWrap, 'data-dial-pending', 'true');
            setQuotaAttrIfChanged(dialWrap, 'data-dial-soon', 'false');
            removeQuotaAttrIfPresent(dialWrap, 'data-dial-format');
            removeQuotaAttrIfPresent(dialWrap, 'data-dial-wide');
            removeQuotaAttrIfPresent(dialWrap, 'data-dial-expired');
            if (dialPartA) setQuotaTextIfChanged(dialPartA, '--');
            if (dialColon) {
              setQuotaHiddenIfChanged(dialColon, false);
              setQuotaTextIfChanged(dialColon, ':');
            }
            if (dialPartB) {
              setQuotaTextIfChanged(dialPartB, '--');
              dialPartB.classList?.toggle?.('quota-dial-part--unit', false);
            }
            if (dialArc) setQuotaAttrIfChanged(dialArc, 'stroke-dashoffset', dialCircumference.toFixed(2));
            if (dialTip?.style) dialTip.style.opacity = '0';
            const pendingTip = t('quota.dial.pending');
            if (dialWrap.title !== pendingTip) dialWrap.title = pendingTip;
            setQuotaAttrIfChanged(dialWrap, 'aria-label', pendingTip);
          }
        }
      }

      if (fillEl) {
        setQuotaAttrIfChanged(fillEl, 'data-status', bStatus);
        if (getChildAttr(fillEl, 'data-fraction') !== scaleStr) {
          fillEl.setAttribute('data-fraction', scaleStr);
          if (typeof fillEl.style?.setProperty === 'function') {
            fillEl.style.setProperty('--quota-scale', scaleStr);
          }
          if (fillEl.style) {
            fillEl.style.transform = `scaleX(${scaleStr})`;
          }
        }
        let activeCells = 0;
        if (segsWrap && Array.isArray(segFills) && segFills.length === 20) {
          setQuotaAttrIfChanged(segsWrap, 'data-status', bStatus);
          if (hasValidFrac) {
            setQuotaHiddenIfChanged(segsWrap, false);
            const EPS = 1e-9;
            const fullBlocks = pace
              ? pace.fullBlocks
              : Math.min(20, Math.floor(scaleVal * 20 + EPS));
            const partialRaw = pace
              ? pace.partialBlockFrac
              : (fullBlocks >= 20 ? 0 : Math.max(0, scaleVal * 20 - fullBlocks));
            const partialFrac = partialRaw < EPS ? 0 : partialRaw;
            const minVis = pace
              ? pace.hasMinVisibleBlock
              : (scaleVal > 0 && fullBlocks === 0 && partialFrac > 0);
            const minOpacity = pace
              ? pace.partialVisualOpacity
              : (minVis && partialFrac < 0.25 ? 0.25 : partialFrac);
            activeCells = scaleVal <= 0 ? 0 : Math.min(20, fullBlocks + (partialFrac > 0 ? 1 : 0));

            for (let sIdx = 0; sIdx < 20; sIdx++) {
              const sf = segFills[sIdx];
              if (!sf?.style) continue;
              if (sIdx < fullBlocks) {
                if (sf.style.width !== '100%') sf.style.width = '100%';
                if (sf.style.opacity !== '1') sf.style.opacity = '1';
                sf.style.setProperty?.('--seg-opacity', '1');
                sf.style.setProperty?.('--cell-idx', String(sIdx));
                sf.style.setProperty?.('--cell-target-opacity', '1');
                setQuotaAttrIfChanged(sf, 'data-cell-active', 'true');
              } else if (sIdx === fullBlocks && partialFrac > 0) {
                if (minVis && partialFrac < 0.25) {
                  if (sf.style.width !== '100%') sf.style.width = '100%';
                  const opStr = String(minOpacity);
                  if (sf.style.opacity !== opStr) sf.style.opacity = opStr;
                  sf.style.setProperty?.('--seg-opacity', opStr);
                  sf.style.setProperty?.('--cell-idx', String(sIdx));
                  sf.style.setProperty?.('--cell-target-opacity', opStr);
                  setQuotaAttrIfChanged(sf, 'data-cell-active', 'true');
                } else {
                  const wStr = `${(partialFrac * 100).toFixed(1)}%`;
                  if (sf.style.width !== wStr) sf.style.width = wStr;
                  if (sf.style.opacity !== '0.85') sf.style.opacity = '0.85';
                  sf.style.setProperty?.('--seg-opacity', '0.85');
                  sf.style.setProperty?.('--cell-idx', String(sIdx));
                  sf.style.setProperty?.('--cell-target-opacity', '0.85');
                  setQuotaAttrIfChanged(sf, 'data-cell-active', 'true');
                }
              } else {
                if (sf.style.width !== '0%') sf.style.width = '0%';
                if (sf.style.opacity !== '0') sf.style.opacity = '0';
                sf.style.setProperty?.('--seg-opacity', '0');
                removeQuotaAttrIfPresent(sf, 'data-cell-active');
                removeQuotaAttrIfPresent(sf, 'data-cell-pulse');
                sf.style?.removeProperty?.('--quota-cell-delay');
                sf.style?.removeProperty?.('--cell-target-opacity');
              }
            }
          } else {
            setQuotaHiddenIfChanged(segsWrap, true);
          }
        }

        const chargeEligible = Boolean(
          statusOverride !== 'no_permission' &&
          bStatus !== 'no_permission' &&
          bStatus !== 'unknown' &&
          b.remainingFraction != null &&
          Number.isFinite(Number(b.remainingFraction)) &&
          scaleVal > 0 &&
          activeCells > 0
        );
        if (chargeStage) {
          setQuotaAttrIfChanged(chargeStage, 'data-status', bStatus);
          if (getChildAttr(chargeStage, 'data-fraction') !== scaleStr) {
            chargeStage.setAttribute('data-fraction', scaleStr);
            if (chargeStage.style) {
              chargeStage.style.width = stageWidthStr;
            }
          }
          // 20 格模式彻底隐藏连续绿带与反光层
          setQuotaHiddenIfChanged(chargeStage, true);
        }
        if (track) {
          setQuotaAttrIfChanged(track, 'data-charge-eligible', chargeEligible ? 'true' : 'false');
          setQuotaAttrIfChanged(track, 'data-segmented', hasValidFrac ? 'true' : 'false');
          if (!chargeEligible) {
            removeQuotaAttrIfPresent(track, 'data-charging');
            if (chargeStage) setQuotaHiddenIfChanged(chargeStage, true);
            if (chargeRef) quotaActiveChargeRefs.delete(chargeRef);
          }
        }
        if (chargeRef) {
          chargeRef.activeCells = activeCells;
          chargeRef.chargeEligible = chargeEligible;
          if (chargeEligible && Array.isArray(opts.chargeTargets)) {
            opts.chargeTargets.push(chargeRef);
          }
        }
      }

      if (paceWrap) {
        if (pace) {
          setQuotaHiddenIfChanged(paceWrap, false);
          setQuotaAttrIfChanged(paceWrap, 'data-pace-tier', String(pace.tier));
          const timeLeftPctStr = `${(pace.timeRemaining * 100).toFixed(2)}%`;
          if (paceTimeFill?.style && paceTimeFill.style.width !== timeLeftPctStr) {
            paceTimeFill.style.width = timeLeftPctStr;
          }
          if (paceTick?.style && paceTick.style.left !== timeLeftPctStr) {
            paceTick.style.left = timeLeftPctStr;
          }
          if (paceGap) {
            if (pace.hasGap && pace.gapWidthPct > 0) {
              setQuotaHiddenIfChanged(paceGap, false);
              setQuotaAttrIfChanged(paceGap, 'data-pace-tier', String(pace.tier));
              if (paceGap.style) {
                const lStr = `${pace.gapLeftPct.toFixed(2)}%`;
                const wStr = `${pace.gapWidthPct.toFixed(2)}%`;
                if (paceGap.style.left !== lStr) paceGap.style.left = lStr;
                if (paceGap.style.width !== wStr) paceGap.style.width = wStr;
              }
            } else {
              setQuotaHiddenIfChanged(paceGap, true);
            }
          }
          const countdownStr = formatCountdownMsCompact(pace.remainingTimeMs);
          if (paceTimeText) {
            setQuotaTextIfChanged(paceTimeText, t('quota.pace.resetIn', { countdown: countdownStr, pct: pace.timePct }));
          }
          const pillLabel = formatQuotaPaceDeltaText(pace);
          if (paceTierPill) {
            setQuotaAttrIfChanged(paceTierPill, 'data-pace-tier', String(pace.tier));
            setQuotaTextIfChanged(paceTierPill, pillLabel);
          }
          const deltaSign = pace.deltaPct >= 0 ? '+' : '';
          const tipLines = [
            t('quota.pace.tooltip', {
              quotaPct: pace.quotaPct,
              timePct: pace.timePct,
              countdown: countdownStr,
              window: formatQuotaWindowTitle(b),
              deltaStr: `${deltaSign}${pace.deltaPct}%`,
              tierLabel: getQuotaPaceTierLabel(pace)
            })
          ];
          if (pace.estRunoutMs) {
            tipLines.push(t('quota.pace.estRunout', { eta: formatCountdownMsCompact(pace.estRunoutMs) }));
          }
          const tipText = tipLines.join('\n');
          if (paceWrap.title !== tipText) paceWrap.title = tipText;
        } else {
          setQuotaHiddenIfChanged(paceWrap, true);
          removeQuotaAttrIfPresent(paceWrap, 'data-pace-tier');
          if (paceGap) setQuotaHiddenIfChanged(paceGap, true);
        }
      }

      if (estEl) {
        const estText = statusOverride === 'no_permission' ? '' : formatBucketTokenEstimateLine(b.tokenEstimate);
        if (estText) {
          setQuotaHiddenIfChanged(estEl, false);
          setQuotaTextIfChanged(estEl, estText);
        } else {
          setQuotaHiddenIfChanged(estEl, true);
          setQuotaTextIfChanged(estEl, '');
        }
      }
      desiredRows.push(row);
    }

    reconcileQuotaChildOrder(container, desiredRows);
  }

  function renderPoolCompactList(compactBox, pool, paceSuppressed = false, compactFills = null) {
    if (!compactBox) return;
    const list = Array.isArray(pool?.buckets) ? pool.buckets : [];
    if (pool?.noPermission || !list.length) {
      setQuotaHiddenIfChanged(compactBox, true);
      reconcileQuotaChildOrder(compactBox, []);
      return;
    }
    setQuotaHiddenIfChanged(compactBox, false);

    const existingRows = new Map();
    for (const ch of Array.from(compactBox.children || [])) {
      const bk = getChildAttr(ch, 'data-bucket-key');
      if (bk) existingRows.set(bk, ch);
    }

    const desiredRows = [];
    for (let i = 0; i < list.length; i++) {
      const b = list[i];
      const bKey = String(b.bucketId || b.windowKey || `b-${i}`);
      let cRow = existingRows.get(bKey);
      let cRefs = cRow ? quotaNodeRefsMap.get(cRow) : null;

      if (!cRow || !cRefs) {
        cRow = document.createElement('div');
        cRow.className = 'quota-pool-compact-row';
        cRow.setAttribute('data-bucket-key', bKey);

        const winEl = document.createElement('span');
        winEl.className = 'quota-compact-win';

        const barEl = document.createElement('div');
        barEl.className = 'quota-compact-bar';
        const cFill = document.createElement('div');
        cFill.className = 'quota-compact-fill';
        const cGap = document.createElement('div');
        cGap.className = 'quota-compact-gap';
        cGap.hidden = true;
        const cTick = document.createElement('div');
        cTick.className = 'quota-compact-tick';
        cTick.hidden = true;
        barEl.appendChild(cFill);
        barEl.appendChild(cGap);
        barEl.appendChild(cTick);

        const cVal = document.createElement('span');
        cVal.className = 'quota-compact-val';
        const cTier = document.createElement('span');
        cTier.className = 'quota-compact-tier';
        cTier.hidden = true;

        cRow.appendChild(winEl);
        cRow.appendChild(barEl);
        cRow.appendChild(cVal);
        cRow.appendChild(cTier);

        cRefs = { winEl, cFill, cGap, cTick, cVal, cTier };
        quotaNodeRefsMap.set(cRow, cRefs);
      }

      const { winEl, cFill, cGap, cTick, cVal, cTier } = cRefs;
      const wShort = b.windowShort || (b.windowKey === '5h' ? '5h' : (b.windowKey === 'weekly' ? '7d' : (b.windowKey === 'daily' ? '24h' : '—')));
      setQuotaTextIfChanged(winEl, wShort);

      const pace = !paceSuppressed && b.pace && b.pace.available ? b.pace : null;
      const frac = b.remainingFraction == null ? null : Math.max(0, Math.min(1, Number(b.remainingFraction)));
      const bStatus = frac == null
        ? 'unknown'
        : (b.isExhausted || frac === 0 ? 'exhausted' : (frac <= 0.2 ? 'low' : 'available'));

      if (pace) {
        setQuotaAttrIfChanged(cRow, 'data-pace-tier', String(pace.tier));
      } else {
        removeQuotaAttrIfPresent(cRow, 'data-pace-tier');
      }

      if (cFill) {
        setQuotaAttrIfChanged(cFill, 'data-status', bStatus);
        const isZeroFill = frac == null || frac === 0 || b.isExhausted === true;
        if (isZeroFill) {
          setQuotaAttrIfChanged(cFill, 'data-empty', 'true');
          if (cFill.style && cFill.style.width !== '0%') cFill.style.width = '0%';
        } else {
          removeQuotaAttrIfPresent(cFill, 'data-empty');
          const wPct = `${(frac * 100).toFixed(1)}%`;
          if (cFill.style && cFill.style.width !== wPct) cFill.style.width = wPct;
          if (Array.isArray(compactFills)) compactFills.push(cFill);
        }
      }
      if (cGap) {
        if (pace && pace.hasGap && pace.gapWidthPct > 0) {
          setQuotaHiddenIfChanged(cGap, false);
          setQuotaAttrIfChanged(cGap, 'data-pace-tier', String(pace.tier));
          if (cGap.style) {
            const lStr = `${pace.gapLeftPct.toFixed(2)}%`;
            const wStr = `${pace.gapWidthPct.toFixed(2)}%`;
            if (cGap.style.left !== lStr) cGap.style.left = lStr;
            if (cGap.style.width !== wStr) cGap.style.width = wStr;
          }
        } else {
          setQuotaHiddenIfChanged(cGap, true);
        }
      }
      if (cTick) {
        if (pace) {
          setQuotaHiddenIfChanged(cTick, false);
          const tStr = `${(pace.timeRemaining * 100).toFixed(2)}%`;
          if (cTick.style && cTick.style.left !== tStr) cTick.style.left = tStr;
        } else {
          setQuotaHiddenIfChanged(cTick, true);
        }
      }
      if (cVal) {
        setQuotaTextIfChanged(cVal, frac == null ? t('quota.time.unknown') : (b.percentText || `${Math.round(frac * 100)}%`));
      }
      if (cTier) {
        if (pace) {
          setQuotaHiddenIfChanged(cTier, false);
          setQuotaTextIfChanged(cTier, getQuotaPaceTierLabel(pace));
        } else {
          setQuotaHiddenIfChanged(cTier, true);
          setQuotaTextIfChanged(cTier, '');
        }
      }
      desiredRows.push(cRow);
    }
    reconcileQuotaChildOrder(compactBox, desiredRows);
  }

  function syncComposerStatusBarWidth() {
    const csbBar = el('composer-status-bar');
    if (!csbBar) return 'normal';
    let hostWidth = 0;
    try {
      const parentRect = csbBar.parentElement?.getBoundingClientRect?.();
      if (parentRect && Number.isFinite(parentRect.width) && parentRect.width > 0) {
        hostWidth = parentRect.width;
      }
    } catch { }
    if (!hostWidth && typeof window !== 'undefined' && Number.isFinite(Number(window.innerWidth)) && Number(window.innerWidth) > 0) {
      hostWidth = Number(window.innerWidth);
    }
    const mode = hostWidth > 0 && hostWidth < 500
      ? 'tight'
      : (hostWidth > 0 && hostWidth < 680 ? 'narrow' : 'normal');
    setQuotaAttrIfChanged(csbBar, 'data-csb-width', mode);
    return mode;
  }

  function renderComposerQuotaSummary(view = lastComputedQuotaView, nowMs = Date.now()) {
    const group = el('csb-group-quota');
    if (!group) return;
    syncComposerStatusBarWidth();
    if (!showComposerQuotaSummary || !view || !Array.isArray(view.pools) || !view.pools.length) {
      setQuotaHiddenIfChanged(group, true);
      return;
    }

    const hasUnmatchedCurrentModel = Boolean(view.currentModel && !view.currentModel.poolKey) || Boolean(view.currentModel?.isUnknownModel);
    const pool = hasUnmatchedCurrentModel
      ? null
      : ((view.currentModel?.poolKey
        ? view.pools.find(p => p.poolKey === view.currentModel.poolKey)
        : null) || view.pools[0] || null);
    if (!pool) {
      setQuotaHiddenIfChanged(group, true);
      return;
    }

    const core = typeof __AGContextMeterCore !== 'undefined' ? __AGContextMeterCore : (globalThis.__AGContextMeterCore || null);
    const fmtPct = f => (core?.formatQuotaPercentText ? core.formatQuotaPercentText(f) : `${Math.round(Number(f) * 100)}%`);
    const CSB_RING_C = 2 * Math.PI * 5.5;
    const paceSuppressed = Boolean(pool.noPermission || view.syncState === 'stale' || view.syncState === 'error' || view.activeStatus === 'stale' || view.activeStatus === 'error');

    const applyWin = (winId, ringId, dotId, textId, prefix, bucket, statusOverride, isSecondary) => {
      const winEl = el(winId);
      const ringEl = el(ringId);
      const dotEl = el(dotId);
      const textEl = el(textId);
      if (!winEl) return;
      if (!bucket && statusOverride !== 'no_permission') {
        setQuotaHiddenIfChanged(winEl, true);
        return;
      }
      setQuotaHiddenIfChanged(winEl, false);
      setQuotaAttrIfChanged(winEl, 'data-secondary', isSecondary ? 'true' : 'false');

      const frac = bucket?.remainingFraction ?? null;
      const validFrac = statusOverride !== 'no_permission' && frac != null && Number.isFinite(Number(frac));
      const bStatus = statusOverride || (!validFrac
        ? 'unknown'
        : (bucket.isExhausted || frac === 0 ? 'exhausted' : (frac <= 0.2 ? 'low' : 'available')));
      const pace = !paceSuppressed && bucket?.pace && bucket.pace.available ? bucket.pace : null;

      setQuotaAttrIfChanged(winEl, 'data-quota-state', bStatus);
      if (pace && (bStatus === 'available' || bStatus === 'low' || bStatus === 'exhausted')) {
        setQuotaAttrIfChanged(winEl, 'data-pace-tier', String(pace.tier));
      } else {
        removeQuotaAttrIfPresent(winEl, 'data-pace-tier');
      }

      if (ringEl) {
        const dashOffset = validFrac ? (CSB_RING_C * (1 - Math.max(0, Math.min(1, Number(frac))))).toFixed(2) : CSB_RING_C.toFixed(2);
        setQuotaAttrIfChanged(ringEl, 'stroke-dashoffset', dashOffset);
      }
      if (dotEl) {
        if (pace && validFrac) {
          const pos = computePaceRingDotCoords(8, 8, 5.5, pace.timeRemaining);
          setQuotaAttrIfChanged(dotEl, 'cx', String(pos.x));
          setQuotaAttrIfChanged(dotEl, 'cy', String(pos.y));
          setQuotaHiddenIfChanged(dotEl, false);
        } else {
          setQuotaHiddenIfChanged(dotEl, true);
        }
      }
      if (textEl) {
        const valText = statusOverride === 'no_permission'
          ? t('quota.short.no_permission')
          : (validFrac ? fmtPct(frac) : t('quota.short.unknown'));
        setQuotaTextIfChanged(textEl, prefix ? `${prefix} ${valText}` : valText);
      }
    };

    const altWarnEl = el('csb-quota-alt-warn');
    const moreEl = el('csb-quota-more');

    if (pool.noPermission) {
      applyWin('csb-quota-5h', 'csb-quota-ring-5h', 'csb-quota-dot-5h', 'csb-quota-text-5h', '', null, null, true);
      applyWin('csb-quota-7d', 'csb-quota-ring-7d', 'csb-quota-dot-7d', 'csb-quota-text-7d', '', null, null, true);
      applyWin('csb-quota-single', 'csb-quota-ring-single', 'csb-quota-dot-single', 'csb-quota-text-single', '', null, 'no_permission', false);
      if (altWarnEl) setQuotaHiddenIfChanged(altWarnEl, true);
    } else {
      const pairFn = typeof resolveQuotaWindowBucketPair === 'function' ? resolveQuotaWindowBucketPair : core?.resolveQuotaWindowBucketPair;
      const pair = pairFn ? pairFn(pool.buckets || []) : { bucket5h: null, bucket7d: null };
      const b5h = pair?.bucket5h || null;
      const b7d = pair?.bucket7d || null;

      if (b5h && b7d) {
        const pb = pool.primaryBucket || null;
        const primaryIs7d = Boolean(pb && (pb === b7d || pb.windowKey === 'weekly' || pb.windowShort === '7d'));
        applyWin('csb-quota-5h', 'csb-quota-ring-5h', 'csb-quota-dot-5h', 'csb-quota-text-5h', '5H', b5h, null, primaryIs7d);
        applyWin('csb-quota-7d', 'csb-quota-ring-7d', 'csb-quota-dot-7d', 'csb-quota-text-7d', '7D', b7d, null, !primaryIs7d);
        applyWin('csb-quota-single', 'csb-quota-ring-single', 'csb-quota-dot-single', 'csb-quota-text-single', '', null, null, true);

        const altBucket = primaryIs7d ? b5h : b7d;
        const altShort = primaryIs7d ? '5H' : '7D';
        const altPace = !paceSuppressed && altBucket?.pace?.available ? altBucket.pace : null;
        const altLowOrExhausted = Boolean(altBucket && (altBucket.isExhausted || (altBucket.remainingFraction != null && altBucket.remainingFraction <= 0.2)));
        const altPaceWarn = Boolean(altPace && (altPace.tier === 3 || altPace.tier === 4));
        if (altWarnEl && (altPaceWarn || altLowOrExhausted)) {
          const warnTier = altPace ? (altPace.tier >= 3 ? altPace.tier : (altBucket.isExhausted ? 4 : 3)) : (altBucket.isExhausted ? 4 : 3);
          const warnLabel = altBucket.isExhausted
            ? t('quota.short.exhausted')
            : (altPaceWarn ? getQuotaPaceTierLabel(altPace) : t('quota.pace.fast'));
          setQuotaHiddenIfChanged(altWarnEl, false);
          setQuotaAttrIfChanged(altWarnEl, 'data-pace-tier', String(warnTier));
          setQuotaTextIfChanged(altWarnEl, `${altShort} ${warnLabel}`);
        } else if (altWarnEl) {
          setQuotaHiddenIfChanged(altWarnEl, true);
        }
      } else if (b5h || b7d) {
        applyWin('csb-quota-5h', 'csb-quota-ring-5h', 'csb-quota-dot-5h', 'csb-quota-text-5h', '5H', b5h, null, false);
        applyWin('csb-quota-7d', 'csb-quota-ring-7d', 'csb-quota-dot-7d', 'csb-quota-text-7d', '7D', b7d, null, false);
        applyWin('csb-quota-single', 'csb-quota-ring-single', 'csb-quota-dot-single', 'csb-quota-text-single', '', null, null, true);
        if (altWarnEl) setQuotaHiddenIfChanged(altWarnEl, true);
      } else {
        applyWin('csb-quota-5h', 'csb-quota-ring-5h', 'csb-quota-dot-5h', 'csb-quota-text-5h', '', null, null, true);
        applyWin('csb-quota-7d', 'csb-quota-ring-7d', 'csb-quota-dot-7d', 'csb-quota-text-7d', '', null, null, true);
        const sb = pool.primaryBucket || pool.buckets?.[0] || null;
        const sbTag = typeof window?.__AGContextMeterCore?.formatQuotaWindowDisplayTag === 'function' ? window.__AGContextMeterCore.formatQuotaWindowDisplayTag(sb?.windowShort || '') : String(sb?.windowShort || '').toUpperCase();
        applyWin('csb-quota-single', 'csb-quota-ring-single', 'csb-quota-dot-single', 'csb-quota-text-single', sbTag, sb, sb ? null : (view.activeStatus || 'unknown'), false);
        if (altWarnEl) setQuotaHiddenIfChanged(altWarnEl, true);
      }
    }

    const otherPools = view.pools.filter(p => p.poolKey !== pool.poolKey);
    // 07 规格：移除底栏其他额度池 +N 徽标，保持 5H/7D 简洁常驻与详情入口可达
    if (typeof window !== 'undefined' && typeof window.AGMorphIndicatorToolbar?.stripComposerQuotaMoreBadge === 'function') {
      try { window.AGMorphIndicatorToolbar.stripComposerQuotaMoreBadge(el('composer-status-bar') || group); } catch { }
    }
    if (moreEl) {
      setQuotaHiddenIfChanged(moreEl, true);
      setQuotaTextIfChanged(moreEl, '');
    }

    const poolLines = (pool.buckets || []).map(b => {
      const wTag = b.windowShort || formatQuotaWindowTitle(b);
      const paceText = (!paceSuppressed && b.pace?.available) ? ` · ${formatQuotaPaceDeltaText(b.pace)}` : '';
      return `${wTag}: ${b.percentText || t('quota.time.unknown')}${paceText}`;
    });
    const otherText = otherPools.length
      ? `${t('quota.pace.otherPoolsMore', { count: otherPools.length })}: ${otherPools.map(p => `${p.title} (${p.percentText})`).join(' / ')}`
      : '';
    const tipTitle = [`${pool.title}`, poolLines.join(' | '), otherText].filter(Boolean).join('\n');
    if (group.title !== tipTitle) group.title = tipTitle;
    setQuotaHiddenIfChanged(group, false);
  }

  // =========================================================================
  // PR #83：额度看板双层滚动恢复（支持重绘、内容缩短夹紧与用户主动归顶，桥接 __AGQuotaScrollGuard）
  // =========================================================================
  const QUOTA_SCROLL_RESTORE_STEPS_MS = [0, 400, 1200, 2200];
  const QUOTA_SCROLL_KEYS = new Set(['PageUp', 'PageDown', 'Home', 'End', 'ArrowUp', 'ArrowDown', ' ', 'Spacebar']);
  var quotaScrollRestoreTimers = [];
  let quotaScrollUserIntentAt = 0;
  let quotaScrollProgrammatic = false;
  const quotaScrollAnchorById = new Map();

  function ensureQuotaScrollGuardController() {
    try {
      if (!quotaScrollGuardCtrl && typeof window !== 'undefined' && typeof window.__AGQuotaScrollGuard?.createQuotaScrollGuard === 'function') {
        quotaScrollGuardCtrl = window.__AGQuotaScrollGuard.createQuotaScrollGuard({
          resolveContainers: () => ['view-quota', 'panel-quota', 'panel']
            .map(id => ({ id, node: el(id) }))
            .filter(item => item.node && typeof item.node.scrollTop === 'number'),
          isPanelVisible: () => {
            if (state.disposed) return false;
            const panelEl = el('panel-quota');
            return Boolean(panelEl && !panelEl.hidden);
          },
          restoreStepsMs: QUOTA_SCROLL_RESTORE_STEPS_MS
        });
        const cleanup = () => { try { quotaScrollGuardCtrl?.destroy?.(); } catch { } quotaScrollGuardCtrl = null; };
        activeDisposers.add(cleanup);
        earlyDisposeHooks.push(cleanup);
      }
    } catch { }
    return quotaScrollGuardCtrl;
  }

  function clearQuotaScrollRestoreTimers() {
    try { quotaScrollGuardCtrl?.cancelRestore?.(); } catch { }
    if (!Array.isArray(quotaScrollRestoreTimers)) {
      quotaScrollRestoreTimers = [];
      return;
    }
    for (const timer of quotaScrollRestoreTimers) clearTimeout(timer);
    quotaScrollRestoreTimers = [];
  }

  function cancelQuotaScrollRestore() {
    let cancelled = false;
    try {
      if (quotaScrollGuardCtrl?.cancelRestore?.()) cancelled = true;
    } catch { }
    if (Array.isArray(quotaScrollRestoreTimers) && quotaScrollRestoreTimers.length) {
      clearQuotaScrollRestoreTimers();
      cancelled = true;
    }
    return cancelled;
  }

  function clampQuotaScrollTarget(node, desiredTop) {
    if (typeof window !== 'undefined' && typeof window.__AGQuotaScrollGuard?.clampScrollTop === 'function') {
      return window.__AGQuotaScrollGuard.clampScrollTop(node, desiredTop);
    }
    const raw = Math.max(0, Number(desiredTop) || 0);
    const sh = Number(node?.scrollHeight);
    const ch = Number(node?.clientHeight);
    if (Number.isFinite(sh) && Number.isFinite(ch) && sh > 0 && ch > 0) {
      const maxTop = Math.max(0, sh - ch);
      return Math.min(raw, maxTop);
    }
    return raw;
  }

  function applyQuotaScrollPositions(entries) {
    // 用户刚主动滚过就绝不再抢回去
    if (Date.now() - quotaScrollUserIntentAt < 200) return;
    quotaScrollProgrammatic = true;
    try {
      for (const [node, top] of entries) {
        if (!node || typeof top !== 'number') continue;
        const clampedTop = clampQuotaScrollTarget(node, top);
        if (Math.abs(Number(node.scrollTop) - clampedTop) > 1) node.scrollTop = clampedTop;
      }
    } finally {
      quotaScrollProgrammatic = false;
    }
  }

  function armPanelScrollRestoreTimers(entries) {
    clearQuotaScrollRestoreTimers();
    if (!entries || !entries.length) return;
    const guard = ensureQuotaScrollGuardController();
    if (guard && typeof guard.armRestoreAfterRedraw === 'function') {
      const mapped = entries
        .filter(item => Array.isArray(item) && item[0] && typeof item[1] === 'number')
        .map(([node, scrollTop], idx) => ({ id: node.id || `quota-scroll-${idx}`, node, scrollTop, stickBottom: false }));
      if (mapped.length) guard.armRestoreAfterRedraw(mapped, 'panel_redraw');
    }
    for (const delay of QUOTA_SCROLL_RESTORE_STEPS_MS) {
      if (delay === 0) {
        applyQuotaScrollPositions(entries);
        continue;
      }
      quotaScrollRestoreTimers.push(setTimeout(() => {
        if (state.disposed) return;
        const panelEl = el('panel-quota');
        if (!panelEl || panelEl.hidden) return;
        applyQuotaScrollPositions(entries);
      }, delay));
    }
  }

  let quotaScrollIntentBound = false;
  function bindQuotaScrollUserIntentOnce() {
    if (quotaScrollIntentBound) return;
    quotaScrollIntentBound = true;
    bindQuotaScrollUserIntent();
  }

  function bindQuotaScrollUserIntent() {
    try { ensureQuotaScrollGuardController()?.bindContainers?.(); } catch { }
    for (const nodeId of ['view-quota', 'panel-quota', 'panel']) {
      const node = el(nodeId);
      if (!node?.addEventListener) continue;
      for (const evt of ['wheel', 'touchstart', 'mousedown']) {
        node.addEventListener(evt, () => {
          quotaScrollUserIntentAt = Date.now();
          cancelQuotaScrollRestore();
          if (typeof node.scrollTop === 'number') quotaScrollAnchorById.set(nodeId, node.scrollTop);
        }, { passive: true });
      }
      node.addEventListener('scroll', () => {
        if (quotaScrollProgrammatic) return;
        quotaScrollUserIntentAt = Date.now();
        if (typeof node.scrollTop === 'number') quotaScrollAnchorById.set(nodeId, node.scrollTop);
      }, { passive: true });
      node.addEventListener('keydown', (e) => {
        if (e && QUOTA_SCROLL_KEYS.has(e.key)) {
          quotaScrollUserIntentAt = Date.now();
          cancelQuotaScrollRestore();
        }
      });
    }
    if (typeof activeDisposers !== 'undefined') {
      activeDisposers.add(() => { clearQuotaScrollRestoreTimers(); });
      activeDisposers.add(() => { quotaScrollAnchorById.clear(); });
    }
  }

  function renderQuotaBoard(nowMs = Date.now(), renderOpts = {}) {
    bindQuotaScrollUserIntentOnce();
    const panel = el('panel-quota');
    const scrollPositions = !state.disposed && panel && !panel.hidden
      ? ['view-quota', 'panel-quota', 'panel'].map(nodeId => {
        const node = el(nodeId);
        if (!node || node.hidden) return null;
        const curTop = Number(node.scrollTop) || 0;
        const remembered = quotaScrollAnchorById.get(nodeId);
        // 若当前已滚动则以当前值为准；仅当非用户主动归顶却被重绘归零时使用记忆锚点
        const userRecentlyActed = (Date.now() - quotaScrollUserIntentAt) < 1200;
        const targetTop = curTop > 0 ? curTop : ((!userRecentlyActed && remembered > 0) ? remembered : 0);
        if (curTop > 0 || userRecentlyActed) quotaScrollAnchorById.set(nodeId, curTop);
        return [node, targetTop];
      }).filter(Boolean)
      : [];
    const viewQuotaBody = el('view-quota');
    const view = computeEffectiveQuotaView(nowMs);
    lastComputedQuotaView = view;
    const currentSig = computeQuotaVisualSignature(view);
    const chargeBarTargets = renderOpts.chargeBars ? [] : null;
    const compactFillTargets = renderOpts.chargeBars ? [] : null;
    const shouldAnimate = Boolean(
      renderOpts.animate !== undefined
        ? renderOpts.animate
        : (quotaPendingSmoothAnim && quotaLastSnapshotSig !== null && currentSig !== quotaLastSnapshotSig)
    );
    if (renderOpts.consumeAnim !== false && quotaPendingSmoothAnim) {
      quotaPendingSmoothAnim = false;
    }
    quotaLastSnapshotSig = currentSig;

    // 1. 渲染顶栏圆环入口与窄屏溢出菜单项（不只靠颜色，必含数值/状态短文本与时间刻点）
    const bQuota = el('badge-quota');
    const qFill = el('quota-ring-fill');
    const qPaceDot = el('quota-ring-pace-dot');
    const qVal = el('quota-badge-val');
    const qTag = el('quota-badge-tag');
    const qDual = el('quota-badge-dual');
    const oQuotaVal = el('overflow-quota-val');
    const matchedPoolObjTop = (view.pools || []).find(p => p.poolKey === view.currentModel?.poolKey) || null;
    const topPaceAllowed = view.activeStatus === 'available' || view.activeStatus === 'low';
    const topPace = topPaceAllowed
      ? ((view.badge?.pace && view.badge.pace.available ? view.badge.pace : null)
        || (matchedPoolObjTop?.primaryBucket?.pace && matchedPoolObjTop.primaryBucket.pace.available ? matchedPoolObjTop.primaryBucket.pace : null))
      : null;

    if (bQuota) {
      setQuotaAttrIfChanged(bQuota, 'data-quota-state', view.activeStatus || 'unknown');
      if (topPace) {
        setQuotaAttrIfChanged(bQuota, 'data-quota-pace-tier', String(topPace.tier));
      } else {
        removeQuotaAttrIfPresent(bQuota, 'data-quota-pace-tier');
      }
      const tipModel = view.currentModel?.productLabel || t('quota.current.unmatched');
      const matchedPoolObj = matchedPoolObjTop;
      const reasonMap = {
        tighter_window: currentPanelLanguage === 'en' ? 'tightest window' : (currentPanelLanguage === 'zh-TW' ? '最緊縮視窗優先' : '最紧缩窗口优先'),
        tie_window: currentPanelLanguage === 'en' ? '5h priority on tie' : (currentPanelLanguage === 'zh-TW' ? '同餘量優先短視窗' : '同余量优先短窗口'),
        single_window: currentPanelLanguage === 'en' ? 'single window' : (currentPanelLanguage === 'zh-TW' ? '單一限額視窗' : '单一限额窗口'),
        user_5h: t('quota.modeTag.5h'),
        user_weekly: t('quota.modeTag.weekly')
      };
      const winLines = (matchedPoolObj?.buckets || []).map(b => {
        const wTag = b.windowShort || formatQuotaWindowTitle(b);
        const cleanRt = typeof qbNormalizeResetTimeText === 'function' ? qbNormalizeResetTimeText(b.resetTimeText) : (b.resetTimeText || '');
        const cdTxt = b.hasResetTime ? formatCountdownMsCompact((b.resetAtMs || 0) - nowMs) : '';
        const wReset = b.hasResetTime ? ([cleanRt, cdTxt].filter(Boolean).join(' · ') || t('quota.dial.pending')) : t('quota.dial.pending');
        const paceNote = (b.pace && b.pace.available && topPaceAllowed) ? ` · ${formatQuotaPaceDeltaText(b.pace)}` : '';
        return `${wTag}: ${b.percentText || t('quota.time.unknown')} · ${wReset}${paceNote}`;
      });
      const selNote = matchedPoolObj?.primaryBucket
        ? `${matchedPoolObj.primaryBucket.windowShort || formatQuotaWindowTitle(matchedPoolObj.primaryBucket)} · ${reasonMap[matchedPoolObj.selectionReason] || ''}`
        : '';
      const modeTag = t(`quota.modeTag.${quotaBadgeWindowMode}`);
      const updatedStr = view.fetchedAtMs ? new Date(view.fetchedAtMs).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' }) : t('quota.time.unknown');
      const poolHeader = matchedPoolObj?.title ? ` · ${matchedPoolObj.title}` : '';
      const activeCleanRt = typeof qbNormalizeResetTimeText === 'function' ? qbNormalizeResetTimeText(view.activeReset?.resetTimeText) : (view.activeReset?.resetTimeText || '');
      const tipReset = view.activeReset?.hasResetTime
        ? ([activeCleanRt, formatCountdownMsCompact((view.activeReset.resetAtMs || 0) - nowMs)].filter(Boolean).join(' · ') || t('quota.dial.pending'))
        : t('quota.dial.pending');
      const nextTitle = [
        `${tipModel}${poolHeader} · ${view.activeStatusLabel} · ${view.badge.text}${selNote ? ` · ${selNote}` : ''} · ${modeTag}`,
        winLines.length ? winLines.join(' | ') : `${t('quota.time.reset')}: ${tipReset}`,
        `${currentPanelLanguage === 'en' ? 'Updated' : '更新'}: ${updatedStr}`,
        t('settings.quotaBadgeMode.desc')
      ].filter(Boolean).join('\n');
      if (bQuota.title !== nextTitle) bQuota.title = nextTitle;
      setQuotaAttrIfChanged(bQuota, 'aria-label', `${t('badge.quota.aria')}: ${view.badge.text} · ${view.activeStatusLabel}`);
    }
    if (qPaceDot) {
      if (topPace) {
        const dotPos = computePaceRingDotCoords(9, 9, RING_RADIUS, topPace.timeRemaining);
        setQuotaAttrIfChanged(qPaceDot, 'cx', String(dotPos.x));
        setQuotaAttrIfChanged(qPaceDot, 'cy', String(dotPos.y));
        setQuotaHiddenIfChanged(qPaceDot, false);
      } else {
        setQuotaHiddenIfChanged(qPaceDot, true);
      }
    }
    if (qFill) {
      if (view.badge.fraction == null) {
        const nextDash = view.activeStatus === 'unknown' ? '10 30.84' : `0 ${RING_CIRCUMFERENCE.toFixed(2)}`;
        setQuotaAttrIfChanged(qFill, 'stroke-dasharray', nextDash);
        setQuotaAttrIfChanged(qFill, 'stroke-dashoffset', '0');
        quotaBadgeLastHasFraction = false;
      } else {
        const clampedFrac = Math.max(0, Math.min(1, view.badge.fraction));
        const offsetStr = (RING_CIRCUMFERENCE * (1 - clampedFrac)).toFixed(2);
        const dashStr = `${RING_CIRCUMFERENCE.toFixed(2)} ${RING_CIRCUMFERENCE.toFixed(2)}`;
        if (!quotaBadgeLastHasFraction && qFill.style && typeof qFill.getBoundingClientRect === 'function') {
          qFill.style.transition = 'none';
          qFill.setAttribute('stroke-dasharray', dashStr);
          qFill.setAttribute('stroke-dashoffset', offsetStr);
          qFill.getBoundingClientRect();
          qFill.style.transition = '';
        } else {
          setQuotaAttrIfChanged(qFill, 'stroke-dasharray', dashStr);
          setQuotaAttrIfChanged(qFill, 'stroke-dashoffset', offsetStr);
        }
        quotaBadgeLastHasFraction = true;
      }
    }
    const useDualDisplay = quotaBadgeWindowMode === 'both'
      && state.layoutMode !== 'compact'
      && Array.isArray(view.badge.dualBuckets)
      && view.badge.dualBuckets.length === 2;
    if (bQuota) {
      if (useDualDisplay) bQuota.setAttribute?.('data-quota-dual', 'true');
      else bQuota.removeAttribute?.('data-quota-dual');
    }
    if (useDualDisplay && qDual) {
      if (qVal) setQuotaHiddenIfChanged(qVal, true);
      if (qTag) setQuotaHiddenIfChanged(qTag, true);
      setQuotaHiddenIfChanged(qDual, false);
      const line0 = qDual.children?.[0] || document.createElement('span');
      line0.className = 'quota-dual-line';
      line0.textContent = view.badge.dualBuckets[0].text;
      const line1 = qDual.children?.[1] || document.createElement('span');
      line1.className = 'quota-dual-line is-secondary';
      line1.textContent = view.badge.dualBuckets[1].text;
      if (qDual.children?.length !== 2) {
        qDual.replaceChildren?.();
        qDual.appendChild?.(line0);
        qDual.appendChild?.(line1);
      }
    } else {
      if (qDual) setQuotaHiddenIfChanged(qDual, true);
      if (qVal) {
        setQuotaHiddenIfChanged(qVal, false);
        const hasNumericPct = view.activeStatus !== 'exhausted' && view.activeStatus !== 'no_permission' && view.activeStatus !== 'error' && view.badge.fraction != null;
        if (hasNumericPct) {
          animateQuotaPercentNode(qVal, view.badge.fraction, shouldAnimate, view.badge.text);
          if (!shouldAnimate) {
            setQuotaTextIfChanged(qVal, view.badge.text);
          }
        } else {
          let dispVal = view.badge.text;
          if (view.activeStatus === 'exhausted') dispVal = t('quota.short.exhausted');
          else if (view.activeStatus === 'no_permission') dispVal = t('quota.short.no_permission');
          else if (view.activeStatus === 'error') dispVal = t('quota.short.error');
          else if (view.activeStatus === 'unknown' || view.badge.fraction == null) {
            dispVal = view.activeStatus === 'stale' ? t('quota.short.stale') : (view.badge.text || t('quota.short.unknown'));
          }
          animateQuotaPercentNode(qVal, null, false, dispVal);
          setQuotaTextIfChanged(qVal, dispVal);
        }
      }
      if (qTag) {
        let dispTag = view.badge.tag;
        if (view.activeStatus === 'error') dispTag = t('quota.retry');
        else if (view.activeStatus === 'stale' && view.badge.fraction != null) dispTag = t('quota.short.stale');
        if (dispTag) {
          setQuotaHiddenIfChanged(qTag, false);
          setQuotaTextIfChanged(qTag, dispTag);
        } else {
          setQuotaHiddenIfChanged(qTag, true);
          setQuotaTextIfChanged(qTag, '');
        }
      }
    }
    if (oQuotaVal) {
      const dispTxt = useDualDisplay
        ? view.badge.dualBuckets.map(b => b.text).join(' / ')
        : (view.badge.fraction != null && view.activeStatus !== 'exhausted' && view.activeStatus !== 'no_permission' && view.activeStatus !== 'error'
          ? view.badge.text
          : (qVal ? qVal.textContent : view.badge.text));
      const dispTag = (!useDualDisplay && qTag && !qTag.hidden) ? qTag.textContent : '';
      const cleanDispTag = (dispTag && dispTag !== dispTxt) ? dispTag : '';
      setQuotaTextIfChanged(oQuotaVal, cleanDispTag ? `${dispTxt} · ${cleanDispTag}` : dispTxt);
    }
    if (typeof syncFloatingOrbState === 'function') syncFloatingOrbState();

    // 2. 刷新按钮与横幅渲染（保护 fetching / committing / done / fallback / error 态不被常规重绘打断）
    const btnRefresh = el('btn-quota-refresh');
    const txtRefresh = el('quota-refresh-text');
    const isAnimOrTerminalBtn = quotaRefreshPhase !== 'idle' || quotaRefreshBtnState === 'done' || quotaRefreshBtnState === 'fallback' || quotaRefreshBtnState === 'error';
    if (btnRefresh && !isAnimOrTerminalBtn) {
      if (Boolean(btnRefresh.disabled) !== Boolean(quotaState.busy)) {
        btnRefresh.disabled = Boolean(quotaState.busy);
      }
      setQuotaAttrIfChanged(btnRefresh, 'data-busy', quotaState.busy ? 'true' : 'false');
      setQuotaAttrIfChanged(btnRefresh, 'data-refresh-state', quotaState.busy ? 'loading' : 'idle');
      setQuotaAttrIfChanged(btnRefresh, 'aria-busy', quotaState.busy ? 'true' : 'false');
    }
    if (txtRefresh && !isAnimOrTerminalBtn) {
      setQuotaTextIfChanged(txtRefresh, t('quota.refresh.btn'));
    }

    const tierPill = el('quota-plan-tier-pill');
    if (tierPill) {
      const planPs = ANTIGRAVITY_TOKEN_DATA.planStatus || null;
      const hasTrustedPlanStatus = Boolean(planPs && (planPs.status === 'identified' || planPs.sources?.tier === 'custom') && planPs.tierName && planPs.tierName !== '未知');
      const knownCachedTier = (!view.planTierName && !hasTrustedPlanStatus) ? loadKnownAccountTierLabel(quotaState.accountScopeKey) : null;
      const tierTxt = (view.planTierName && view.planTierName !== '未知')
        ? view.planTierName
        : (hasTrustedPlanStatus ? planPs.tierName : (knownCachedTier || ''));
      setQuotaHiddenIfChanged(tierPill, false);
      setQuotaTextIfChanged(tierPill, tierTxt || t('plan.tier.pending'));
    }

    const bannerEl = el('quota-banner');
    const bannerTextEl = el('quota-banner-text');
    const bannerRetryBtn = el('btn-quota-banner-retry');
    const bannerRestartBtn = el('btn-quota-banner-restart');
    if (bannerEl && bannerTextEl) {
      const currentVer = METER_RENDERER_VERSION;
      const isBridgeMissing = quotaState.errorKind === 'bridge_unavailable';
      const observedBackendVer = backendStatus.backendVersion || quotaState.collectorVersion || null;
      const isStaleCollectorAfterUpdate = Boolean(
        pendingUpdateRestart &&
        (!quotaState.collectorVersion || quotaState.collectorVersion !== currentVer) &&
        (Boolean(quotaState.error) || view.activeStatus === 'no_permission' || view.activeStatus === 'unknown')
      );
      const isExplicitBackendMismatch = Boolean(
        !isBridgeMissing &&
        !isStaleCollectorAfterUpdate &&
        observedBackendVer &&
        observedBackendVer !== currentVer &&
        (backendStatus.hotReloadFallback || pendingUpdateRestart || backendStatus.backendVersionMismatch)
      );
      const needsRestartAction = isBridgeMissing || isStaleCollectorAfterUpdate || isExplicitBackendMismatch;
      if (bannerRestartBtn) {
        setQuotaHiddenIfChanged(bannerRestartBtn, !(needsRestartAction && hostSupportsRestart));
      }
      if (bannerRetryBtn) {
        setQuotaHiddenIfChanged(bannerRetryBtn, isBridgeMissing);
      }

      if (isBridgeMissing) {
        setQuotaHiddenIfChanged(bannerEl, false);
        setQuotaAttrIfChanged(bannerEl, 'data-tone', 'warn');
        const msg = hostSupportsRestart
          ? t('quota.bridgeMissing')
          : `${t('quota.bridgeMissing')} ${t('client.restart.hostNotSupported')}`;
        setQuotaTextIfChanged(bannerTextEl, msg);
      } else if (isStaleCollectorAfterUpdate) {
        setQuotaHiddenIfChanged(bannerEl, false);
        setQuotaAttrIfChanged(bannerEl, 'data-tone', 'warn');
        const msg = hostSupportsRestart
          ? t('quota.pendingRestartBanner')
          : `${t('quota.pendingRestartBanner')} ${t('client.restart.hostNotSupported')}`;
        setQuotaTextIfChanged(bannerTextEl, msg);
      } else if (isExplicitBackendMismatch) {
        setQuotaHiddenIfChanged(bannerEl, false);
        setQuotaAttrIfChanged(bannerEl, 'data-tone', 'warn');
        const baseMsg = t('quota.backendMismatchBanner', {
          uiVer: currentVer,
          backendVer: `v${observedBackendVer}`,
          source: backendStatus.backendSource || 'host'
        });
        const msg = hostSupportsRestart ? baseMsg : `${baseMsg} ${t('client.restart.hostNotSupported')}`;
        setQuotaTextIfChanged(bannerTextEl, msg);
      } else if (quotaState.errorKind === 'force_refresh_unsupported' && view.syncState === 'error') {
        setQuotaHiddenIfChanged(bannerEl, false);
        setQuotaAttrIfChanged(bannerEl, 'data-tone', 'error');
        setQuotaTextIfChanged(bannerTextEl, t('quota.fallback.noDataBanner'));
      } else if (quotaState.errorKind === 'force_refresh_unsupported' && view.syncState === 'stale') {
        setQuotaHiddenIfChanged(bannerEl, false);
        setQuotaAttrIfChanged(bannerEl, 'data-tone', 'warn');
        setQuotaTextIfChanged(bannerTextEl, t('quota.fallback.banner'));
      } else if (view.syncState === 'error' && view.lastError) {
        setQuotaHiddenIfChanged(bannerEl, false);
        setQuotaAttrIfChanged(bannerEl, 'data-tone', 'error');
        setQuotaTextIfChanged(bannerTextEl, t('quota.errorBanner', { reason: view.lastError }));
      } else if (view.syncState === 'stale') {
        setQuotaHiddenIfChanged(bannerEl, false);
        setQuotaAttrIfChanged(bannerEl, 'data-tone', 'warn');
        const staleReason = view.lastError
          || (view.pools.some(p => p.isResetPassed && p.remainingFraction === 0) ? t('quota.resetPassReason') : t('quota.ageExpiredReason'));
        setQuotaTextIfChanged(bannerTextEl, t('quota.staleBanner', { reason: staleReason }));
      } else {
        setQuotaHiddenIfChanged(bannerEl, true);
      }
    }

    // 三时间分列渲染：数据更新时间 / 下次自动刷新 / 当前额度重置
    const tUpd = el('quota-time-updated');
    const tNext = el('quota-time-next');
    const tReset = el('quota-time-reset');
    if (tUpd) {
      const updStr = formatQuotaDateTime(view.fetchedAtMs);
      setQuotaTextIfChanged(tUpd, updStr);
      if (tUpd.title !== updStr) tUpd.title = updStr;
    }
    if (tNext) {
      const prevNextText = String(tNext.textContent || '').trim();
      const hasValidNextText = Boolean(prevNextText && prevNextText !== '—' && prevNextText !== t('quota.time.unknown') && prevNextText !== t('quota.refresh.busy'));
      let nextStr = null;
      if (quotaState.busy) {
        if (!hasValidNextText) nextStr = t('quota.refresh.busy');
      } else if (quotaState.autoPaused) {
        nextStr = t('quota.time.paused');
      } else if (Number.isFinite(Number(quotaState.nextRefreshAtMs))) {
        const nextDiff = quotaState.nextRefreshAtMs - nowMs;
        if (nextDiff > 0) {
          nextStr = `${formatQuotaDateTime(quotaState.nextRefreshAtMs).slice(6)} · ${formatCountdownMsCompact(nextDiff)}`;
        } else if (!hasValidNextText) {
          nextStr = t('quota.refresh.busy');
        }
      } else {
        nextStr = t('quota.time.unknown');
      }
      if (nextStr !== null) {
        setQuotaTextIfChanged(tNext, nextStr);
        if (tNext.title !== nextStr) tNext.title = nextStr;
      }
    }
    if (tReset) {
      let resetStr = t('quota.dial.pending');
      if (view.activeReset?.hasResetTime) {
        const cleanResetTxt = typeof qbNormalizeResetTimeText === 'function'
          ? qbNormalizeResetTimeText(view.activeReset.resetTimeText)
          : String(view.activeReset.resetTimeText || '').trim();
        const diffText = view.activeReset.isResetPassed
          ? t('quota.resetPassReason')
          : formatCountdownMsCompact((view.activeReset.resetAtMs || 0) - nowMs);
        resetStr = [cleanResetTxt, diffText].filter(Boolean).join(' · ') || t('quota.dial.pending');
      }
      setQuotaTextIfChanged(tReset, resetStr);
      if (tReset.title !== resetStr) tReset.title = resetStr;
    }

    // 当前会话模型概览卡片（唯一主池双轨与所属模型芯片）
    const renderQuotaModelChips = (chipsBox, modelsList, currentProductKey) => {
      if (!chipsBox) return;
      const list = Array.isArray(modelsList) ? modelsList : [];
      if (!list.length) {
        setQuotaHiddenIfChanged(chipsBox, true);
        return;
      }
      setQuotaHiddenIfChanged(chipsBox, false);
      const chipsSig = list.map(m => `${m.productKey}:${m.productLabel}:${(m.efforts || []).join('/')}:${m.noPermission ? 1 : 0}:${m.noticeText || ''}:${m.decorativeBadgeTag || ''}:${currentProductKey === m.productKey ? 1 : 0}:${t('quota.short.no_permission')}`).join(';');
      if (getChildAttr(chipsBox, 'data-chips-sig') === chipsSig) return;
      chipsBox.setAttribute('data-chips-sig', chipsSig);
      const chipNodes = [];
      for (const m of list) {
        const chip = document.createElement('span');
        chip.className = 'quota-model-chip';
        if (currentProductKey && m.productKey === currentProductKey) {
          chip.setAttribute('data-current-model', 'true');
        }
        const lbl = document.createElement('span');
        lbl.textContent = m.productLabel;
        chip.appendChild(lbl);
        if (m.efforts && m.efforts.length) {
          const ef = document.createElement('span');
          ef.className = 'quota-chip-efforts';
          ef.textContent = `· ${m.efforts.join(' / ')}`;
          chip.appendChild(ef);
        }
        if (m.decorativeBadgeTag) {
          const deco = document.createElement('span');
          deco.className = 'quota-chip-deco';
          deco.textContent = m.decorativeBadgeTag;
          chip.appendChild(deco);
        }
        if (m.noPermission) {
          const np = document.createElement('span');
          np.className = 'quota-chip-noperm';
          np.textContent = t('quota.short.no_permission');
          chip.appendChild(np);
        } else if (m.noticeText) {
          const nt = document.createElement('span');
          nt.className = 'quota-chip-notice';
          nt.title = m.noticeText;
          nt.textContent = m.noticeTitle || 'Notice';
          chip.appendChild(nt);
        }
        chipNodes.push(chip);
      }
      reconcileQuotaChildOrder(chipsBox, chipNodes);
    };

    const curModelEl = el('quota-cur-model');
    const curStatusEl = el('quota-cur-status');
    const curAlertEl = el('quota-cur-alert');

    const paceSuppressedGlobal = view.syncState === 'stale' || view.syncState === 'error';

    if (curModelEl) {
      setQuotaTextIfChanged(curModelEl, view.currentModel?.productLabel || t('quota.current.unmatched'));
    }
    if (curStatusEl) {
      setQuotaClassIfChanged(curStatusEl, `key-pill ${getQuotaPillClass(view.activeStatus)}`);
      setQuotaTextIfChanged(curStatusEl, getQuotaStatusLabelText(view.activeStatus));
    }
    if (curAlertEl) {
      if (view.currentModel?.noPermission && view.currentModel?.unavailabilityReason) {
        setQuotaHiddenIfChanged(curAlertEl, false);
        setQuotaAttrIfChanged(curAlertEl, 'data-kind', 'noperm');
        setQuotaTextIfChanged(curAlertEl, view.currentModel.unavailabilityReason);
      } else if (
        view.currentModel?.noticeText &&
        !/^(?:new|beta|preview|updated|notice|recommended)$/i.test(String(view.currentModel.noticeText).trim())
      ) {
        setQuotaHiddenIfChanged(curAlertEl, false);
        setQuotaAttrIfChanged(curAlertEl, 'data-kind', 'notice');
        setQuotaTextIfChanged(curAlertEl, `Notice: ${view.currentModel.noticeText}`);
      } else {
        setQuotaHiddenIfChanged(curAlertEl, true);
      }
    }

    // 10.html 主配额看板渲染 (唯一 20 格纯平电池条双池四行主界面，彻底取代旧竞争主卡片)
    const boardCtrl = ensureQuotaBoardController();
    if (boardCtrl && typeof buildQuotaBoardItemsFromView === 'function') {
      const boardSpec = buildQuotaBoardItemsFromView(view, nowMs, {
        paceSuppressed: paceSuppressedGlobal
      });
      boardCtrl.syncStatic(boardSpec.items, { forceStatic: Boolean(renderOpts.forceStatic) });
      syncQuotaColorModeButtonsUi();
    }

    if (!state.disposed && panel && !panel.hidden) {
      // PR #83：把恢复绑定到真实 DOM 更新点（覆盖约 2.2s 的历史回填），
      // 且不再冻结用户滚动 —— 用户一旦主动滚动立即取消待恢复任务
      armPanelScrollRestoreTimers(scrollPositions);
    }

    syncModelListQuotaIndicators(view, nowMs);
    renderComposerQuotaSummary(view, nowMs);
    scheduleQuotaResetConfirmIfNeeded(view, nowMs);
    renderAccountsTabPoolsSection(view, nowMs, { shouldAnimate, renderQuotaModelChips });
  }

  function renderAccountPoolWindowSummary(container, pool, opts = {}) {
    if (!container) return;
    const nowMs = Number.isFinite(Number(opts.nowMs)) ? Number(opts.nowMs) : Date.now();
    if (!pool || pool.noPermission) {
      container.replaceChildren();
      return;
    }
    const rawBuckets = Array.isArray(pool.buckets) ? pool.buckets.filter(Boolean) : [];
    const seenWin = new Set();
    const deduped = [];
    for (const b of rawBuckets) {
      const rawKey = String(b.windowKey || b.windowShort || b.bucketId || '').trim().toLowerCase();
      const normWinKey = (rawKey === 'weekly' || rawKey === '7d') ? '7d' : (rawKey || String(deduped.length));
      if (seenWin.has(normWinKey)) continue;
      seenWin.add(normWinKey);
      deduped.push({ bucket: b, normWinKey });
    }
    if (!deduped.length) {
      container.replaceChildren();
      return;
    }
    container.replaceChildren();
    for (const { bucket: b, normWinKey } of deduped) {
      const row = document.createElement('div');
      row.className = 'ctx-pool-summary-row';
      row.setAttribute('data-window-key', normWinKey);
      const winEl = document.createElement('span');
      winEl.className = 'ctx-pool-summary-win';
      winEl.textContent = formatQuotaWindowTitle(b);

      const valEl = document.createElement('span');
      valEl.className = 'ctx-pool-summary-val';
      const pctEl = document.createElement('span');
      pctEl.className = 'ctx-pool-summary-pct';
      const resolvedFrac = b.remainingFraction != null
        ? Number(b.remainingFraction)
        : (Number.isFinite(Number(b.remainingPct)) ? Number(b.remainingPct) / 100 : null);
      if (b.percentText && b.percentText !== '未知') {
        pctEl.textContent = b.percentText;
      } else if (resolvedFrac != null && Number.isFinite(resolvedFrac)) {
        pctEl.textContent = `${Math.round(resolvedFrac * 100)}%`;
      } else {
        pctEl.textContent = t('quota.time.unknown');
      }
      const resetEl = document.createElement('span');
      resetEl.className = 'ctx-pool-summary-reset';
      if (b.hasResetTime) {
        const cdStr = b.countdownText
          ? (b.isResetPassed ? b.countdownText : formatCountdownMsCompact((b.resetAtMs || 0) - nowMs))
          : '';
        resetEl.textContent = cdStr ? `${b.resetTimeText} · ${cdStr}` : String(b.resetTimeText || '');
      } else if (b.resetText) {
        resetEl.textContent = String(b.resetText);
      } else {
        resetEl.textContent = `${t('quota.time.reset')}: ${t('quota.time.unknown')}`;
      }
      valEl.appendChild(pctEl);
      valEl.appendChild(resetEl);
      row.appendChild(winEl);
      row.appendChild(valEl);
      container.appendChild(row);
    }
  }

  function renderAccountsTabPoolsSection(view, nowMs = Date.now(), opts = {}) {
    const sec = el('ctx-shared-pools-section');
    if (!sec) return;
    const ov = accountsUiState?.overview || {};
    const activeEmailLabel = ov.activeAccountEmail
      || (Array.isArray(ov.accounts) ? (ov.accounts.find(a => a?.isActive)?.maskedEmail || ov.accounts.find(a => a?.isActive)?.email) : '')
      || ANTIGRAVITY_TOKEN_DATA.planStatus?.email
      || '';
    const acctTag = el('ctx-pools-account-tag');
    if (acctTag) {
      const activeAccObj = Array.isArray(ov.accounts) ? ov.accounts.find(a => a?.isActive) : null;
      const dispEmail = activeAccObj?.maskedEmail || activeEmailLabel || t('quota.state.unknown');
      setQuotaTextIfChanged(acctTag, dispEmail);
    }
    const updEl = el('ctx-pools-updated-at');
    if (updEl) {
      setQuotaTextIfChanged(updEl, formatQuotaDateTime(view.fetchedAtMs));
    }

    const banner = el('ctx-pools-banner');
    const bannerTxt = el('ctx-pools-banner-text');
    const hasNoPermPool = (view.pools || []).some(p => p && p.noPermission);
    if (banner && bannerTxt) {
      if (view.syncState === 'error' && view.lastError) {
        setQuotaHiddenIfChanged(banner, false);
        setQuotaAttrIfChanged(banner, 'data-tone', 'error');
        setQuotaTextIfChanged(bannerTxt, t('quota.errorBanner', { reason: view.lastError }));
      } else if (view.syncState === 'stale') {
        setQuotaHiddenIfChanged(banner, false);
        setQuotaAttrIfChanged(banner, 'data-tone', 'warn');
        const staleReason = view.lastError
          || (view.pools.some(p => p.isResetPassed && p.remainingFraction === 0) ? t('quota.resetPassReason') : t('quota.ageExpiredReason'));
        setQuotaTextIfChanged(bannerTxt, t('quota.staleBanner', { reason: staleReason }));
      } else if (!view.pools.length) {
        setQuotaHiddenIfChanged(banner, false);
        setQuotaAttrIfChanged(banner, 'data-tone', 'warn');
        setQuotaTextIfChanged(bannerTxt, t('quota.pools.empty'));
      } else if (hasNoPermPool) {
        setQuotaHiddenIfChanged(banner, false);
        setQuotaAttrIfChanged(banner, 'data-tone', 'warn');
        setQuotaTextIfChanged(bannerTxt, t('accountsTab.noPermissionBanner'));
      } else {
        setQuotaHiddenIfChanged(banner, true);
      }
    }

    const matchedPoolObj = (view.pools || []).find(p => p.poolKey === view.currentModel?.poolKey) || (view.pools || [])[0] || null;
    const curModelEl = el('ctx-pools-cur-model');
    const curPoolEl = el('ctx-pools-cur-pool');
    const curStatusEl = el('ctx-pools-cur-status');
    const curAlertEl = el('ctx-pools-cur-alert');
    const curBucketsEl = el('ctx-pools-cur-buckets');
    const curChipsEl = el('ctx-pools-cur-models-chips');

    if (curModelEl) {
      setQuotaTextIfChanged(curModelEl, view.currentModel?.productLabel || matchedPoolObj?.title || t('quota.current.unmatched'));
    }
    if (curPoolEl) {
      setQuotaTextIfChanged(curPoolEl, matchedPoolObj?.title || '');
    }
    if (curStatusEl) {
      const st = matchedPoolObj?.noPermission ? 'no_permission' : (matchedPoolObj?.status || view.activeStatus || 'unknown');
      setQuotaClassIfChanged(curStatusEl, `key-pill ${getQuotaPillClass(st)}`);
      const pctText = !matchedPoolObj?.noPermission && matchedPoolObj?.percentText && matchedPoolObj.percentText !== '未知'
        ? ` · ${matchedPoolObj.percentText}`
        : '';
      setQuotaTextIfChanged(curStatusEl, `${getQuotaStatusLabelText(st)}${pctText}`);
    }
    if (curAlertEl) {
      if (matchedPoolObj?.noPermission && (matchedPoolObj?.unavailabilityReason || view.currentModel?.unavailabilityReason)) {
        setQuotaHiddenIfChanged(curAlertEl, false);
        setQuotaAttrIfChanged(curAlertEl, 'data-kind', 'noperm');
        setQuotaTextIfChanged(curAlertEl, matchedPoolObj.unavailabilityReason || view.currentModel.unavailabilityReason);
      } else {
        setQuotaHiddenIfChanged(curAlertEl, true);
      }
    }
    if (curBucketsEl) {
      renderAccountPoolWindowSummary(curBucketsEl, matchedPoolObj, { nowMs });
    }
    if (curChipsEl) {
      setQuotaHiddenIfChanged(curChipsEl, true);
    }

    const othersHeadingEl = el('ctx-pools-others-heading');
    const othersListEl = el('ctx-pools-others-list');
    if (othersListEl) {
      const hasMain = Boolean(matchedPoolObj);
      if (othersHeadingEl) {
        setQuotaTextIfChanged(othersHeadingEl, t(hasMain ? 'quota.pools.othersHeading' : 'quota.pools.heading'));
      }
      const otherPools = (view.pools || []).filter(p => p && (!matchedPoolObj || p.poolKey !== matchedPoolObj.poolKey));
      if (!otherPools.length) {
        othersListEl.replaceChildren();
        if (!view.pools.length) {
          const emptyEl = document.createElement('div');
          emptyEl.className = 'quota-pools-empty-state';
          if (emptyEl.style) emptyEl.style.cssText = 'font-size:11px;color:var(--ag-text-muted);padding:10px;text-align:center;border:1px dashed var(--ag-border-subcard);border-radius:7px';
          emptyEl.textContent = t('quota.pools.empty');
          othersListEl.appendChild(emptyEl);
          setQuotaHiddenIfChanged(othersListEl, false);
        } else {
          setQuotaHiddenIfChanged(othersListEl, true);
        }
        return;
      }

      setQuotaHiddenIfChanged(othersListEl, false);
      othersListEl.replaceChildren();
      for (const pool of otherPools) {
        const card = document.createElement('div');
        card.className = 'quota-pool-card ctx-pool-summary-card';
        card.setAttribute('data-pool-key', pool.poolKey);

        const top = document.createElement('div');
        top.className = 'quota-pool-top';
        const titleEl = document.createElement('div');
        titleEl.className = 'quota-pool-title';
        titleEl.textContent = pool.title || pool.poolKey;
        const tagsEl = document.createElement('div');
        tagsEl.className = 'quota-pool-tags';
        const stPill = document.createElement('span');
        const pStatus = pool.noPermission ? 'no_permission' : (pool.status || 'unknown');
        stPill.className = `key-pill quota-pool-status-pill ${getQuotaPillClass(pStatus)}`;
        const pctStr = !pool.noPermission && pool.percentText && pool.percentText !== '未知' ? ` · ${pool.percentText}` : '';
        stPill.textContent = `${getQuotaStatusLabelText(pStatus)}${pctStr}`;
        tagsEl.appendChild(stPill);
        top.appendChild(titleEl);
        top.appendChild(tagsEl);
        card.appendChild(top);

        if (pool.noPermission && pool.unavailabilityReason) {
          const reasonEl = document.createElement('div');
          reasonEl.className = 'quota-pool-reason';
          if (reasonEl.style) reasonEl.style.cssText = 'font-size:10.5px;color:var(--ag-text-muted);margin-bottom:4px';
          reasonEl.textContent = pool.unavailabilityReason;
          card.appendChild(reasonEl);
        } else if (pool.buckets && pool.buckets.length) {
          const summaryBox = document.createElement('div');
          summaryBox.className = 'ctx-pool-summary-list';
          renderAccountPoolWindowSummary(summaryBox, pool, { nowMs });
          card.appendChild(summaryBox);
        }
        othersListEl.appendChild(card);
      }
    }
  }

  function scheduleQuotaResetConfirmIfNeeded(view, nowMs = Date.now()) {
    if (state.disposed) return;
    if (quotaResetTimer) { clearTimeout(quotaResetTimer); quotaResetTimer = null; }
    // 找到未来最近的 resetAtMs 并设定到点 +2s 自动刷新；若刚过 reset 且尚未确认重拉则安排一次即时确认
    let soonestFutureMs = null;
    let passedKey = null;
    for (const p of (view.pools || [])) {
      for (const b of (p.buckets || [])) {
        if (!b.hasResetTime || !Number.isFinite(b.resetAtMs)) continue;
        if (b.resetAtMs > nowMs) {
          if (soonestFutureMs === null || b.resetAtMs < soonestFutureMs) soonestFutureMs = b.resetAtMs;
        } else if (b.remainingFraction === 0) {
          const rKey = `${p.poolKey}:${b.bucketId}:${b.resetTimeIso}`;
          if (quotaState.lastResetRequeryKey !== rKey) {
            passedKey = rKey;
          }
        }
      }
    }
    if (passedKey && !quotaState.busy) {
      quotaState.lastResetRequeryKey = passedKey;
      quotaResetTimer = setTimeout(() => { void syncQuotaFromHost(true); }, 1500);
      return;
    }
    if (soonestFutureMs !== null) {
      const waitMs = Math.min(2147483000, Math.max(2000, soonestFutureMs - nowMs + 2000));
      quotaResetTimer = setTimeout(() => { void syncQuotaFromHost(true); }, waitMs);
    }
  }

  function scheduleQuotaAutoRefresh(delayMs = null) {
    if (state.disposed || !rendererBootCompleted || !quotaStateInitialized) return;
    if (quotaAutoTimer) { clearTimeout(quotaAutoTimer); quotaAutoTimer = null; }
    const isWindowActive = host.getAttribute('data-window-active') !== 'false' && (typeof document === 'undefined' || !document.hidden);
    let interval = delayMs;
    if (!Number.isFinite(interval) || interval <= 0) {
      if (quotaState.consecutiveErrors > 0) {
        interval = Math.min(180000, 30000 * Math.pow(2, Math.min(2, quotaState.consecutiveErrors - 1)));
      } else {
        interval = isWindowActive ? QUOTA_REFRESH_FG_MS : QUOTA_REFRESH_BG_MS;
      }
    }
    quotaState.nextRefreshAtMs = Date.now() + interval;
    quotaAutoTimer = setTimeout(() => {
      quotaAutoTimer = null;
      if (!state.disposed) void syncQuotaFromHost(false, { silent: true });
    }, interval);
  }

  function onQuotaWindowFocus() {
    if (state.disposed || !rendererBootCompleted || !quotaStateInitialized) return;
    quotaState.autoPaused = false;
    const elapsed = quotaState.lastFetchedAtMs ? (Date.now() - quotaState.lastFetchedAtMs) : Infinity;
    if (elapsed >= 20000 && !quotaState.busy) {
      void syncQuotaFromHost(false, { silent: true });
    } else {
      scheduleQuotaAutoRefresh();
    }
  }

  function onQuotaWindowBlur() {
    if (state.disposed || !rendererBootCompleted || !quotaStateInitialized) return;
    scheduleQuotaAutoRefresh(QUOTA_REFRESH_BG_MS);
  }

  function scheduleQuotaPostTurnRefresh() {
    if (state.disposed) return;
    if (quotaPostTurnTimer) clearTimeout(quotaPostTurnTimer);
    quotaPostTurnTimer = setTimeout(() => {
      quotaPostTurnTimer = null;
      const elapsed = quotaState.lastFetchedAtMs ? (Date.now() - quotaState.lastFetchedAtMs) : Infinity;
      if (!state.disposed && !quotaState.busy && elapsed > 5000) {
        void syncQuotaFromHost(true);
      }
    }, 1500);
  }

  async function maybeRefreshQuotaOnOpen() {
    const elapsed = quotaState.lastFetchedAtMs ? (Date.now() - quotaState.lastFetchedAtMs) : Infinity;
    if (!quotaState.snapshot || elapsed > 15000) {
      await syncQuotaFromHost(false);
    }
  }

  function mergeQuotaConfigsPreservingCapabilities(prevConfigs, nextConfigs) {
    if (!Array.isArray(nextConfigs) || !nextConfigs.length) return Array.isArray(prevConfigs) ? prevConfigs : [];
    const prevById = new Map();
    if (Array.isArray(prevConfigs)) {
      for (const item of prevConfigs) {
        const key = String(item?.model || item?.modelId || item?.modelOrAlias?.model || '').trim().toLowerCase();
        if (key) prevById.set(key, item);
      }
    }
    return nextConfigs.map(cfg => {
      if (!cfg || typeof cfg !== 'object') return cfg;
      const key = String(cfg.model || cfg.modelId || cfg.modelOrAlias?.model || '').trim().toLowerCase();
      const prev = key ? prevById.get(key) : null;
      if (!prev) return cfg;
      const merged = { ...cfg };
      for (const field of ['maxTokens', 'maxOutputTokens', 'thinkingBudget', 'minThinkingBudget', 'thinkingLevel', 'supportsModelInfoOverride', 'capabilitySource']) {
        if ((merged[field] == null || merged[field] === '') && prev[field] != null && prev[field] !== '') {
          merged[field] = prev[field];
        }
      }
      return merged;
    });
  }

  const QUOTA_KNOWN_TIER_STORAGE_PREFIX = 'ag_quota_known_tier_v1_';
  let quotaScanFloorTimer = null;

  function loadKnownAccountTierLabel(scopeKey) {
    const clean = typeof scopeKey === 'string' ? scopeKey.trim() : '';
    if (!clean || clean === 'anonymous') return null;
    try {
      if (typeof localStorage !== 'undefined') {
        const val = localStorage.getItem(`${QUOTA_KNOWN_TIER_STORAGE_PREFIX}${clean}`);
        if (val && val.trim() && val.trim() !== '未知') return val.trim();
      }
    } catch { }
    return null;
  }

  function saveKnownAccountTierLabel(scopeKey, tierName) {
    const clean = typeof scopeKey === 'string' ? scopeKey.trim() : '';
    const cleanTier = typeof tierName === 'string' ? tierName.trim() : '';
    if (!clean || clean === 'anonymous' || !cleanTier || cleanTier === '未知') return;
    try {
      if (typeof localStorage !== 'undefined') {
        localStorage.setItem(`${QUOTA_KNOWN_TIER_STORAGE_PREFIX}${clean}`, cleanTier);
      }
    } catch { }
  }

  function syncPlanStatusFromQuotaPayload(payload) {
    if (!payload || payload.ok === false) return;
    const summary = payload.planTierSummary && typeof payload.planTierSummary === 'object' ? payload.planTierSummary : null;
    const snapTierName = payload.snapshot?.planTierName || null;
    const hasIdentifiedSummary = Boolean(summary && summary.status === 'identified' && summary.tierName && summary.tierName !== '未知');
    const resolvedTierName = hasIdentifiedSummary
      ? summary.tierName
      : (snapTierName && snapTierName !== '未知' ? snapTierName : null);
    if (!resolvedTierName) return;

    const scopeKey = payload.accountScopeKey || quotaState.accountScopeKey || null;
    if (scopeKey) saveKnownAccountTierLabel(scopeKey, resolvedTierName);

    const prevPs = ANTIGRAVITY_TOKEN_DATA.planStatus && typeof ANTIGRAVITY_TOKEN_DATA.planStatus === 'object'
      ? ANTIGRAVITY_TOKEN_DATA.planStatus
      : {};
    const livePs = {
      ...prevPs,
      status: 'identified',
      tierKey: summary?.tierKey || payload.snapshot?.planTierKey || prevPs.tierKey || 'unknown',
      tierId: summary?.tierId ?? payload.snapshot?.planTierId ?? prevPs.tierId ?? null,
      teamsTier: summary?.teamsTier ?? payload.snapshot?.planTeamsTier ?? prevPs.teamsTier ?? null,
      tierName: resolvedTierName,
      planName: summary?.planName || resolvedTierName,
      email: payload.email || summary?.email || prevPs.email || null,
      multiplier: summary?.multiplier ?? prevPs.multiplier ?? null,
      officialPriceMonthly: summary?.officialPriceMonthly ?? prevPs.officialPriceMonthly ?? null
    };
    let nextPs = livePs;
    const core = typeof __AGContextMeterCore !== 'undefined' ? __AGContextMeterCore : null;
    if (core?.resolveEffectivePlanStatus) {
      const email = livePs.email || 'default';
      let customObj = lastSavedCustomPlan || null;
      if (!customObj && typeof window !== 'undefined' && window.__AGContextMeterSettings?.customPlan) {
        customObj = window.__AGContextMeterSettings.customPlan;
      }
      try {
        if (!customObj && typeof localStorage !== 'undefined') {
          const savedRaw = localStorage.getItem('ag_custom_plan_' + String(email).toLowerCase()) || localStorage.getItem('ag_custom_plan_default');
          if (savedRaw) customObj = JSON.parse(savedRaw);
        }
      } catch { }
      nextPs = core.resolveEffectivePlanStatus(livePs, customObj, { currentEmail: email });
    }
    ANTIGRAVITY_TOKEN_DATA.rawPlanStatus = livePs;
    ANTIGRAVITY_TOKEN_DATA.planStatus = nextPs;
    if (typeof renderPlanDetail === 'function') {
      try { renderPlanDetail(nextPs); } catch { }
    }
  }

  async function syncQuotaFromHost(force = false, meta = {}) {
    if (state.disposed) return null;
    const isManual = Boolean(meta.manual);
    const isForce = Boolean(force || isManual);
    const reqSource = typeof meta.source === 'string' && meta.source.trim()
      ? meta.source.trim()
      : (isManual ? 'panel_manual_refresh' : (isForce ? 'forced_refresh' : 'auto_poll'));

    // 1. 在途请求去重与强刷升级逻辑：
    //    - 1 秒内连点顶栏 3 次、或面板手动刷新与顶栏强刷并发时，若同账号同强刷在途则共享同一 RPC，避免并发堆叠；
    //    - 若在途的是旧的非强刷后台轮询，新强刷绝不复用它，直接分配新 generation 穿透拉新，旧后台回包将被丢弃防倒灌。
    if (quotaInFlightEntry && quotaInFlightEntry.promise) {
      const sameEpoch = quotaInFlightEntry.accountEpoch === quotaAccountEpoch;
      if (!isForce && sameEpoch) {
        return quotaInFlightEntry.promise;
      }
      if (isForce && quotaInFlightEntry.force && sameEpoch) {
        if (isManual && !quotaInFlightEntry.manual) {
          quotaInFlightEntry.manual = true;
          quotaInFlightManual = true;
          enterQuotaFetchingPhase();
          const panelNow = el('panel-quota');
          if (panelNow && !panelNow.hidden) {
            const bCtrl = ensureQuotaBoardController();
            if (bCtrl) {
              const curView = computeEffectiveQuotaView(Date.now());
              const preSpec = buildQuotaBoardItemsFromView(curView, Date.now(), { paceSuppressed: curView.syncState === 'stale' || curView.syncState === 'error' });
              quotaInFlightEntry.boardRunId = bCtrl.beginManualRefreshCycle(quotaInFlightEntry.generation, preSpec.items);
              quotaActiveBoardRunId = quotaInFlightEntry.boardRunId;
            }
          }
        }
        return quotaInFlightEntry.promise;
      }
    }

    const isSilent = Boolean(meta.silent) && !isManual;
    const myGen = ++quotaRequestGeneration;
    const myAccountEpoch = quotaAccountEpoch;
    const expectedAccountScopeKey = quotaState.accountScopeKey || null;

    if (quotaScanFloorTimer) {
      clearTimeout(quotaScanFloorTimer);
      quotaScanFloorTimer = null;
    }

    let initialBoardRunId = 0;
    if (isManual) {
      quotaLastRefreshTimeline = [];
      enterQuotaFetchingPhase();
      const panelNow = el('panel-quota');
      if (panelNow && !panelNow.hidden) {
        const bCtrl = ensureQuotaBoardController();
        if (bCtrl) {
          const curView = computeEffectiveQuotaView(Date.now());
          const preSpec = buildQuotaBoardItemsFromView(curView, Date.now(), { paceSuppressed: curView.syncState === 'stale' || curView.syncState === 'error' });
          initialBoardRunId = bCtrl.beginManualRefreshCycle(myGen, preSpec.items);
          quotaActiveBoardRunId = initialBoardRunId;
        }
      }
    }
    if (isForce) {
      setQuotaBadgeSyncingAttr(true);
    }

    const entry = {
      promise: null,
      force: isForce,
      manual: isManual,
      source: reqSource,
      generation: myGen,
      accountEpoch: myAccountEpoch,
      startedAtMs: Date.now(),
      boardRunId: initialBoardRunId
    };

    const runner = (async () => {
      const prevSig = computeQuotaVisualSignature(computeEffectiveQuotaView(Date.now()));
      quotaState.busy = true;
      renderQuotaBoard(Date.now(), { animate: false, consumeAnim: false });
      let payload = null;
      let rpcErr = null;
      let missingBridge = false;
      let usedBackendSource = null;
      let wasAborted = false;
      const reqStartMs = Date.now();
      const myAbortController = typeof AbortController !== 'undefined' ? new AbortController() : null;
      quotaAbortController = myAbortController;

      try {
        const hasIpcGetQuota = typeof window !== 'undefined' && typeof window.contextMeterAPI?.getQuota === 'function';
        const hasLivePort = hasLiveHttpBridge() && hasLiveRouteCapability('/quota');
        if (!hasIpcGetQuota && !hasLivePort) {
          missingBridge = true;
          rpcErr = t('quota.bridgeMissing');
        } else {
          const isGeneratingNow = hasActiveCompactionOrGeneration();
          const hasDraftNow = Boolean(autoSwitchDraftDirty || accountsUiState.autoSwitchDraft?.dirty || hasUnsavedChatComposerDraft());
          const reqOpts = {
            force: isForce,
            source: reqSource,
            ...(expectedAccountScopeKey ? { expectedAccountScopeKey } : {}),
            isGenerating: isGeneratingNow,
            hasUnsavedDraft: hasDraftNow
          };
          const out = await callBackendWithPriority({
            ipcCall: hasIpcGetQuota ? () => window.contextMeterAPI.getQuota(reqOpts) : null,
            liveRoute: '/quota',
            liveBody: {
              ...reqOpts,
              origin: typeof window !== 'undefined' ? (window.location?.origin || undefined) : undefined,
              ...((typeof getRendererCsrfToken === 'function' && getRendererCsrfToken()) ? { csrfToken: getRendererCsrfToken() } : {})
            },
            liveFetchOpts: { signal: myAbortController?.signal }
          });
          usedBackendSource = out.source;
          const resObj = out.result;
          if (resObj?.ok && resObj.data) {
            payload = resObj.data;
          } else if (resObj?.error) {
            rpcErr = resObj.error;
          }
          const incomingSyncedOverview = resObj?.accountsOverview || resObj?.accountSyncResult?.overview || null;
          if (incomingSyncedOverview) {
            accountsUiState.overview = incomingSyncedOverview;
            renderAccountsOverviewSection();
          }
          if (resObj?.accountSyncResult) {
            const sr = resObj.accountSyncResult;
            if (sr.action === 'restart_pending') {
              autoSwitchWaitingIdle = false;
              accountsUiState.feedback = sr.switchResult?.message || '已触发自动切号，正在重启客户端';
              accountsUiState.feedbackTone = 'info';
            } else if (sr.action === 'switch_failed_halted') {
              autoSwitchWaitingIdle = false;
              accountsUiState.feedback = sr.error || '自动切号失败，已停止自动切换';
              accountsUiState.feedbackTone = 'error';
            } else if (sr.action === 'pending_debounce') {
              autoSwitchWaitingIdle = false;
              if (autoSwitchDebounceTimer) clearTimeout(autoSwitchDebounceTimer);
              const waitMs = Math.max(1500, Math.min(35000, ((Number(sr.retryInSec) || 15) * 1000) + 500));
              autoSwitchDebounceTimer = setTimeout(() => {
                autoSwitchDebounceTimer = null;
                if (!state.disposed && !quotaInFlightEntry) {
                  void syncQuotaFromHost(true, { silent: true, source: 'autoswitch_debounce' });
                }
              }, waitMs);
            } else if (sr.action === 'waiting_idle' && sr.reason === 'generation_in_progress') {
              autoSwitchWaitingIdle = true;
            } else if (sr.action === 'switched' || sr.action === 'ok_above_threshold' || sr.action === 'noop' || sr.action === 'no_candidates' || sr.action === 'all_candidates_exhausted') {
              autoSwitchWaitingIdle = false;
            }
          }
        }
      } catch (e) {
        if (e?.name === 'AbortError' || myAbortController?.signal?.aborted) {
          wasAborted = true;
        } else {
          rpcErr = e?.message || '请求模型额度失败';
        }
      } finally {
        if (quotaAbortController === myAbortController) quotaAbortController = null;
      }

      if (state.disposed) return null;

      // 竞态防倒灌：切号前旧请求、被更新 generation 抢先提交的旧后台响应、或已取消请求，一律不得覆盖新状态
      if (wasAborted || myAccountEpoch !== quotaAccountEpoch || myGen < quotaCommittedGeneration || payload?.staleDiscarded) {
        if (quotaInFlightEntry === entry) {
          quotaState.busy = false;
          setQuotaBadgeSyncingAttr(false);
          if (entry.manual) {
            clearQuotaBarChargeAnimations({ resetPhase: true, resetBtn: true });
          }
        }
        return quotaState.snapshot;
      }

      const isHostCacheFallbackPayload = (p) => Boolean(
        p && (
          p.forceRefreshFallback === true ||
          p.dataFreshness === 'host_cache_fallback' ||
          p.errorKind === 'force_refresh_unsupported' ||
          (p.forceRefreshSent === true && p.forceRefreshApplied === false && !p.errorKind)
        )
      );
      const isIdentityRejectedPayload = (p) => Boolean(
        p && (
          p.accountIdentityMismatch === true ||
          p.identityVerified === false ||
          p.errorKind === 'account_mismatch' ||
          p.errorKind === 'unverified_account'
        )
      );
      const isHostCacheFallback = isHostCacheFallbackPayload(payload);
      const isIdentityRejected = isIdentityRejectedPayload(payload);

      const nowMs = Date.now();
      const quotaDurationMs = nowMs - reqStartMs;
      const effectiveManual = Boolean(entry.manual);
      recordQuotaTimelineEvent('rpc_resolved', {
        ok: Boolean(payload && payload.ok !== false && !isHostCacheFallback && !isIdentityRejected && !rpcErr),
        hostCacheFallback: isHostCacheFallback,
        durationMs: quotaDurationMs
      });

      const commitResolvedPayload = () => {
        if (state.disposed) return quotaState.snapshot;
        if (myAccountEpoch !== quotaAccountEpoch || myGen < quotaCommittedGeneration) {
          return quotaState.snapshot;
        }
        const commitNowMs = Date.now();
        quotaCommittedGeneration = myGen;
        quotaState.busy = false;
        quotaState.lastFetchedAtMs = commitNowMs;
        setQuotaBadgeSyncingAttr(false);

        let fallbackHasUsableCache = false;
        if (payload) {
          const canUpdateAccountScope = Boolean(
            !isIdentityRejected &&
            payload.accountScopeKey &&
            payload.accountScopeKey !== 'anonymous' &&
            (payload.ok !== false || isHostCacheFallback)
          );
          if (
            canUpdateAccountScope &&
            (payload.accountSwitched || (quotaState.accountScopeKey && payload.accountScopeKey !== quotaState.accountScopeKey))
          ) {
            clearQuotaBarChargeAnimations({ resetPhase: false, resetBtn: false, keepBoardAnim: Boolean(entry.boardRunId) });
            quotaState.snapshot = null;
            quotaState.rawInput = null;
            quotaState.browsePoolKey = null;
            quotaState.lastSuccessAtMs = null;
            quotaState.lastResetRequeryKey = null;
            quotaLastEstComputeSig = '';
            quotaCachedEstByKey = null;
            quotaPrevCellsByBarKey.clear();
          }
          if (canUpdateAccountScope) quotaState.accountScopeKey = payload.accountScopeKey;
          if (payload.collectorVersion) quotaState.collectorVersion = payload.collectorVersion;
          if (usedBackendSource) {
            syncObservedBackendMeta(usedBackendSource, payload, quotaDurationMs);
            if (backendStatus.backendVersion === METER_RENDERER_VERSION && !backendStatus.backendVersionMismatch) {
              pendingUpdateRestart = false;
            }
          }

          if (isHostCacheFallback) {
            // 旧宿主协议不支持 forceRefresh 时的 {} 缓存回退：
            // 保留同账号有用缓存，但绝不当作新采样成功、绝不推进 lastSuccessAtMs、绝不播成功充能
            const incomingPools = Array.isArray(payload.snapshot?.pools) ? payload.snapshot.pools : [];
            const incomingHasValidPools = incomingPools.some(p => p && (p.remainingFraction !== null || p.noPermission));
            const existingPools = Array.isArray(quotaState.snapshot?.pools) ? quotaState.snapshot.pools : [];
            const existingHasValidPools = existingPools.some(p => p && (p.remainingFraction !== null || p.noPermission));
            fallbackHasUsableCache = incomingHasValidPools || existingHasValidPools;
            if (incomingHasValidPools) {
              quotaState.snapshot = { ...payload.snapshot, syncState: 'stale' };
              quotaState.rawInput = null;
            }
            if (!quotaState.lastSuccessAtMs && Number.isFinite(Number(payload.lastSuccessAtMs)) && Number(payload.lastSuccessAtMs) > 0) {
              quotaState.lastSuccessAtMs = Number(payload.lastSuccessAtMs);
            }
            quotaState.dataFreshness = 'host_cache_fallback';
            quotaState.errorKind = 'force_refresh_unsupported';
            quotaState.error = fallbackHasUsableCache ? t('quota.fallback.banner') : t('quota.fallback.noDataBanner');
            if (payload.planTierSummary && fallbackHasUsableCache) {
              syncPlanStatusFromQuotaPayload({ ...payload, ok: true });
            }
          } else if (payload.ok !== false && !isIdentityRejected) {
            // 原子提交：套餐、所有适用模型池额度与绝对重置点同时写入真实状态
            quotaState.snapshot = payload.snapshot || null;
            quotaState.rawInput = null;
            quotaState.lastSuccessAtMs = payload.lastSuccessAtMs || payload.fetchedAtMs || commitNowMs;
            quotaState.dataFreshness = payload.dataFreshness || null;
            quotaState.error = null;
            quotaState.errorKind = null;
            quotaState.consecutiveErrors = 0;
            syncPlanStatusFromQuotaPayload(payload);
            if (typeof ingestRendererQuotaSnapshot === 'function') {
              ingestRendererQuotaSnapshot(payload);
            }
            if (Array.isArray(payload.cascadeModelConfigs) && payload.cascadeModelConfigs.length > 0) {
              state.cascadeModelConfigs = mergeQuotaConfigsPreservingCapabilities(
                payload.accountSwitched ? [] : state.cascadeModelConfigs,
                payload.cascadeModelConfigs
              );
              renderHeaderModelDropdown();
              syncContextModelSelectionFromState();
              if (!isContextSettingsView && activeContextTab === 'models') {
                renderModelSettingsTab();
              }
            }
          } else {
            quotaState.dataFreshness = payload.dataFreshness || null;
            quotaState.error = payload.error || '刷新失败';
            quotaState.errorKind = payload.errorKind || 'network';
            quotaState.consecutiveErrors += 1;
            if (payload.snapshot && !quotaState.snapshot && !isIdentityRejected) {
              quotaState.snapshot = payload.snapshot;
            }
          }
        } else if (rpcErr) {
          quotaState.dataFreshness = null;
          quotaState.error = rpcErr;
          quotaState.errorKind = missingBridge ? 'bridge_unavailable' : 'network';
          quotaState.consecutiveErrors += 1;
        }

        const nextView = computeEffectiveQuotaView(commitNowMs);
        const nextSig = computeQuotaVisualSignature(nextView);
        const hasDataChanged = nextSig !== prevSig;
        const requestSucceeded = Boolean(payload && payload.ok !== false && !isHostCacheFallback && !isIdentityRejected && !rpcErr && !quotaState.error);
        const shouldAnimateChange = Boolean(hasDataChanged && !quotaState.error && prevSig !== 'empty' && !isSilent && !isHostCacheFallback);
        const panelQuotaEl = el('panel-quota');
        const panelVisible = Boolean(panelQuotaEl && !panelQuotaEl.hidden);
        const boardCtrl = ensureQuotaBoardController();
        const hasActiveBoardAnim = Boolean(effectiveManual && panelVisible && boardCtrl && entry.boardRunId);
        quotaPendingSmoothAnim = shouldAnimateChange;

        const applyTerminalUiFeedback = () => {
          if (state.disposed) return;
          if (isHostCacheFallback) {
            if (effectiveManual) {
              finishQuotaRefreshWithFallback(fallbackHasUsableCache);
            } else {
              hideQuotaRefreshFeedback();
            }
          } else if (!requestSucceeded) {
            hideQuotaRefreshFeedback();
            if (effectiveManual) {
              finishQuotaRefreshWithError();
            }
          } else if (effectiveManual) {
            scheduleQuotaDoneToIdle(!hasDataChanged);
          } else if (hasDataChanged) {
            hideQuotaRefreshFeedback();
          }
        };

        if (missingBridge) {
          clearQuotaTimers();
          quotaState.nextRefreshAtMs = null;
        } else {
          scheduleQuotaAutoRefresh();
        }
        // 严禁在每次手动刷新时并发扫荡非活跃账号；若后端未随 /quota 回传 accountsOverview，仅静默读一次本地总览
        if (typeof refreshAccountsOverview === 'function' && !meta.skipAccountsOverviewRefresh && !accountsUiState.overview) {
          void refreshAccountsOverview({ silent: true, refreshAllRemote: false });
        }
        if (
          requestSucceeded &&
          hasDataChanged &&
          !historySyncBusy &&
          (Date.now() - lastHistorySync > 2000) &&
          ((typeof window !== 'undefined' && typeof window.contextMeterAPI?.getTokenHistory === 'function') || hasLiveHttpBridge())
        ) {
          void syncTokenHistoryFromHost(false);
        }

        // 先同步顶栏、悬停菜单、输入区状态条、横幅、套餐与时间摘要（主看板在手动刷新动画中由状态机接管）
        renderQuotaBoard(commitNowMs, {
          animate: shouldAnimateChange,
          forceStatic: !hasActiveBoardAnim
        });

        if (hasActiveBoardAnim) {
          const paceSuppressedNext = nextView.syncState === 'stale' || nextView.syncState === 'error';
          const targetSpec = buildQuotaBoardItemsFromView(nextView, commitNowMs, { paceSuppressed: paceSuppressedNext });
          const finishKind = isHostCacheFallback ? 'fallback' : (requestSucceeded ? 'success' : 'error');
          setQuotaRefreshUiPhase('committing', 'loading');
          quotaBarChargePlaying = true;
          void boardCtrl.completeManualRefreshCycle(entry.boardRunId, targetSpec.items, {
            kind: finishKind,
            skipPause: Boolean(meta.skipScanFloor),
            onSettled: () => {
              quotaBarChargePlaying = false;
              applyTerminalUiFeedback();
            }
          });
        } else {
          applyTerminalUiFeedback();
        }
        return quotaState.snapshot;
      };

      return commitResolvedPayload();
    })();

    entry.promise = runner;
    quotaInFlightEntry = entry;
    quotaInFlightPromise = runner;
    quotaInFlightManual = isManual;
    try {
      return await runner;
    } finally {
      if (quotaInFlightEntry === entry) {
        quotaInFlightEntry = null;
        quotaInFlightPromise = null;
        quotaInFlightManual = false;
      }
    }
  }

